L["hover over a named UI element, then type /cine add and press Enter (or /cine add <FrameName>). Frames without a name can't be added: the Addon Frames settings page lists the addons faded out of the box."] = "이름이 있는 UI 요소에 마우스를 올린 다음 /cine add를 입력하고 Enter를 누르세요 (또는 /cine add <창이름>). 이름이 없는 창은 추가할 수 없습니다. 기본으로 흐려지는 애드온 목록은 애드온 창 설정 페이지에 있습니다."
L["%s is a window, so it isn't faded (it would stay there invisible). Move the mouse off it onto the frame you want, then try again."] = "%s은(는) 창(window)이라 흐리게 하지 않습니다 (보이지 않은 채 남아 있게 됩니다). 마우스를 원하는 창으로 옮긴 뒤 다시 시도하세요."
L["%s is already faded as part of the built-in \"%s\" group."] = "%s은(는) 이미 기본 '%s' 그룹으로 흐려지고 있습니다."
L["now fading %s"] = "이제 %s 흐리게 함"
L["hover over a faded UI element, then type /cine keep and press Enter."] = "흐려진 UI 요소에 마우스를 올린 다음 /cine keep을 입력하고 Enter를 누르세요."
L["%s will always be shown (untick its CineMode box under Custom frames on the Addon Frames options page to undo)."] = "%s은(는) 항상 표시됩니다 (되돌리려면 애드온 창 옵션 페이지의 사용자 지정 창에서 CineMode 칸을 해제하세요)."
L["%s skipped: you set it to always show (untick its CineMode box under Custom frames on the Addon Frames page)."] = "%s 건너뜀: 항상 표시하도록 설정했습니다 (애드온 창 페이지의 사용자 지정 창에서 CineMode 칸을 해제하세요)."
L["found %s"] = "%s 찾음"
L["add mode: hover over the frames to fade. Type /cine add mode again to fade them (or /cine add cancel to drop them). The game's own frames and ones already faded are left out."] = "추가 모드: 흐리게 할 창 위에 마우스를 올리세요. /cine add mode를 다시 입력하면 흐리게 하고, /cine add cancel로 취소합니다. 게임 기본 창과 이미 흐려지는 창은 제외됩니다."
L["add mode off: nothing found to add."] = "추가 모드 꺼짐: 추가할 창을 찾지 못했습니다."
L["add mode off: now fading %d frame."] = "추가 모드 꺼짐: 이제 창 %d개를 흐리게 합니다."
L["add mode off: now fading %d frames."] = "추가 모드 꺼짐: 이제 창 %d개를 흐리게 합니다."
L["add mode isn't on (/cine add mode starts it)."] = "추가 모드가 켜져 있지 않습니다 (/cine add mode로 시작)."
L["add mode canceled: %d frame left as it was."] = "추가 모드 취소: 창 %d개를 그대로 두었습니다."
L["add mode canceled: %d frames left as they were."] = "추가 모드 취소: 창 %d개를 그대로 두었습니다."
L["fading %s"] = "%s 흐리게 함"
L["ignoring %s"] = "%s 무시함"
L["no extra frames."] = "추가된 창이 없습니다."
L["Chat"] = "대화"

-- MinimapButton.lua
L["until logout"] = "로그아웃까지"
L["%d:%02d left"] = "%d:%02d 남음"
L["Tint"] = "색조"
L["Enable Cinematic"] = "Cinematic 사용"
L["Show minimap button"] = "미니맵 버튼 표시"
L["minimap button hidden. Bring it back with /cine button or the \"Show minimap button\" option."] = "미니맵 버튼을 숨겼습니다. /cine button 또는 '미니맵 버튼 표시' 옵션으로 다시 표시할 수 있습니다."
L["Open settings"] = "설정 열기"
L["Off"] = "꺼짐"
L["Paused, %s"] = "일시 정지됨, %s"
L["On"] = "켜짐"
L["Left-click: options"] = "왼쪽 클릭: 옵션"
L["Right-click: settings"] = "오른쪽 클릭: 설정"
L["Drag: move"] = "끌기: 이동"
L["minimap button shown"] = "미니맵 버튼 표시됨"
L["minimap button hidden"] = "미니맵 버튼 숨겨짐"
L["Audio"] = "소리"

-- Options.lua
L["While you're flagged for PvP (not in dungeons or raids, nor on flights), and in battlegrounds and arenas."] = "PvP가 활성화된 동안(던전, 공격대, 비행 중 제외), 그리고 전장과 투기장에서."
L["Put this page's settings back to the profile's own?"] = "이 페이지의 설정을 프로필 값으로 되돌리시겠습니까?"
L["Reset page"] = "페이지 초기화"
L["Put this page's settings back to the active profile's own values (the defaults, or a built-in profile's)."] = "이 페이지의 설정을 현재 프로필의 값(기본값 또는 기본 제공 프로필의 값)으로 되돌립니다."
L["Search Cinematic's settings"] = "Cinematic 설정 검색"
L["Search this page"] = "이 페이지 검색"
L["|cff808080Nothing found|r"] = "|cff808080찾은 항목 없음|r"
L["Scroll for %d more"] = "스크롤하면 %d개 더 있음"
L["Fades the UI and adds letterbox bars between fights. Combat, casting and opening windows like the spellbook bring it back. Typing just shows the chat. The pages under this one cover what shows when (CineMode, Game Frames, Addon Frames, Minimap, Quest tracker, Nameplates, Chat), visual effects and sound, the camera modes and triggers, and keybinds."] = "전투 사이에 UI를 흐리게 하고 레터박스 바를 추가합니다. 전투, 시전, 주문책 같은 창을 열면 UI가 돌아옵니다. 입력할 때는 대화창만 보입니다. 이 아래의 페이지에서 언제 무엇을 보일지(CineMode, 게임 창, 애드온 창, 미니맵, 퀘스트 추적기, 이름표, 대화), 화면 효과와 소리, 카메라 모드와 발동 조건, 단축키를 설정합니다."
L["Also toggled with /cine or the keybind under Key Bindings > AddOns."] = "/cine 또는 단축키 설정 > 애드온의 단축키로도 켜고 끌 수 있습니다."
L["Start in CineMode (fade UI, queue music, etc.)"] = "CineMode로 시작 (UI 흐리기, 음악 재생 등)"
L["Off: the UI stays as it is and the camera's left to you, with just the visual effects over it (as the Visual Effects page says), as in the Subtle profile. Events ticked in the Camera Triggers page's CineMode column still bring CineMode on while their camera runs: standing still or going AFK, say, for a screensaver."] = "끄면: UI는 그대로 두고 카메라도 직접 조작하며, 화면 효과만 위에 덧씌웁니다(화면 효과 페이지 설정대로). 'Subtle' 프로필과 같습니다. 카메라 발동 조건 페이지의 CineMode 열에 체크한 이벤트는 그 카메라가 도는 동안 여전히 CineMode를 켭니다. 예를 들어 가만히 서 있거나 자리를 비울 때 화면 보호기처럼 쓸 수 있습니다."
L["Left-click it for quick options (combat, music, tint), right-click for these settings, drag to move it."] = "왼쪽 클릭은 빠른 옵션(전투, 음악, 색조), 오른쪽 클릭은 이 설정, 끌어서 이동합니다."
L["Language"] = "언어"
L["Game language"] = "게임 언어"
L["The language Cinematic's text is in, for all your characters. Game language follows the game's (English where Cinematic has no translation yet). A change needs a reload."] = "모든 캐릭터에 적용되는 Cinematic의 표시 언어입니다. '게임 언어'는 게임 설정을 따릅니다(Cinematic에 번역이 없으면 영어). 바꾸면 UI를 다시 불러와야 합니다."
L["Turn off in"] = "끄는 곳"
L["Combat"] = "전투"
L["Being in combat brings the UI back. Unticked, CineMode stays on in fights: only the frames ticked under In combat on the Game Frames page show. (Targeting an enemy only ever shows the frames chosen for it there.)"] = "전투에 들어가면 UI가 돌아옵니다. 해제하면 전투 중에도 CineMode가 유지되며, 게임 창 페이지의 '전투 중'에 체크한 창만 보입니다. (적을 대상으로 지정하면 그곳에서 고른 창만 보입니다.)"
L["Open world"] = "필드"
L["Anywhere outside cities, dungeons and raids (inns too), while you're not PvP flagged. Flights still go cinematic."] = "도시, 던전, 공격대(여관 포함) 밖의 모든 곳에서, PvP가 꺼져 있는 동안. 비행은 여전히 시네마틱으로 진행됩니다."
L["Cities"] = "도시"
L["Capital cities, including Dalaran. Flights leaving a city still go cinematic."] = "달라란을 포함한 수도. 도시에서 출발하는 비행은 여전히 시네마틱으로 진행됩니다."
L["Dungeons"] = "던전"
L["Keep the normal UI in dungeons and scenarios."] = "던전과 시나리오에서는 일반 UI를 유지합니다."
L["Raids"] = "공격대"
L["PvP"] = "PvP"
L["Keep the normal UI while you're in a party (but not a raid group)."] = "파티 중(공격대 제외)에는 일반 UI를 유지합니다."
L["Raid group"] = "공격대 그룹"
L["Keep the normal UI while you're in a raid group, wherever you are."] = "공격대 그룹에 있는 동안에는 어디서든 일반 UI를 유지합니다."
L["Moving"] = "이동"
L["Walking or riding about yourself brings the UI back (names too), say to look for an NPC in a city. CineMode comes back once you've stood still, or kept moving, for the time below. Auto-run, RP walking and flights stay in CineMode."] = "직접 걷거나 탈것을 타고 움직이면 UI(이름 포함)가 돌아옵니다. 도시에서 NPC를 찾을 때처럼요. 아래 시간만큼 가만히 서 있거나 계속 움직이면 CineMode가 돌아옵니다. 자동 달리기, RP 걷기, 비행은 CineMode를 유지합니다."
L["Keep VFX on"] = "화면 효과 유지"
L["The visual effects (letterbox, tint and the rest on the Visual Effects page) stay on while moving brings the UI back."] = "움직여서 UI가 돌아오는 동안에도 화면 효과(레터박스, 색조 등 화면 효과 페이지의 항목)를 유지합니다."
L["Back after"] = "복귀 시간"
L["%d sec"] = "%d초"
L["CineMode comes back once you've stood still this long, or kept moving this long without stopping (a long walk or ride)."] = "이 시간만큼 가만히 서 있거나, 멈추지 않고 계속 움직이면(오래 걷거나 달릴 때) CineMode가 돌아옵니다."
L["Reset profile"] = "프로필 초기화"
L["Put the active profile's settings back to how it started (a built-in profile's own values, or the defaults). Frames you added or stopped fading are kept."] = "현재 프로필의 설정을 처음 상태(기본 제공 프로필의 값 또는 기본값)로 되돌립니다. 추가했거나 흐리기를 멈춘 창은 유지됩니다."
L["Profile: |cffff8000none yet|r (pick one on the Profiles page)"] = "프로필: |cffff8000아직 없음|r (프로필 페이지에서 고르세요)"
L["Profile: %s"] = "프로필: %s"
L[" (this character)"] = " (이 캐릭터)"
L["How fast the UI fades, what brings it (or parts of it) back while CineMode is on, and combat text. Fights and targeting are on the Game Frames page, names and nameplates on the Nameplates page, buffs on the Buffs/debuffs page, the minimap on the Minimap page, the quest tracker on the Quest tracker page, chat on the Chat page."] = "UI가 흐려지는 속도, CineMode 중에 UI(또는 그 일부)를 다시 보이게 하는 것, 전투 문자를 설정합니다. 전투와 대상 지정은 게임 창 페이지, 이름과 이름표는 이름표 페이지, 강화 효과는 강화/약화 효과 페이지, 미니맵은 미니맵 페이지, 퀘스트 추적기는 퀘스트 추적기 페이지, 대화는 대화 페이지에 있습니다."
L["Fading"] = "흐리기"
L["Fade in time"] = "나타나는 시간"
L["How long things take to fade in out of combat: targeting something, a mouseover, a window opening. In fights the Combat fade in time is used."] = "전투 밖에서 표시가 나타나는 데 걸리는 시간: 무언가를 대상으로 잡을 때, 마우스를 올릴 때, 창이 열릴 때. 전투 중에는 전투 중 나타나기 시간을 씁니다."
L["%.1f sec"] = "%.1f초"
L["Fade out time"] = "사라지는 시간"
L["How long things take to fade out, in and out of fights: letting go of a target, after a mouseover, and after a fight once the Calm Timer below is over. The mouseover time (Hover groups page) includes it: a time shorter than the fade just fades straight away."] = "전투 중이든 아니든 표시가 사라지는 데 걸리는 시간: 대상을 놓을 때, 마우스를 올린 뒤, 그리고 전투 후 아래 진정 타이머가 끝났을 때. 마우스오버 시간(마우스오버 그룹 페이지)에 포함되며, 사라지기보다 짧으면 곧바로 사라집니다."
L["Combat fade in time"] = "전투 중 나타나는 시간"
L["How long things take to fade in during a fight: the UI coming back as one starts, and anything else that shows mid-fight. Other times use the Fade in time."] = "전투 중에 나타나는 데 걸리는 시간입니다. 전투가 시작될 때 돌아오는 UI와 전투 중에 보이는 다른 모든 것에 적용됩니다. 그 밖에는 '나타나는 시간'을 씁니다."
L["Calm Timer"] = "진정 타이머"
L["Exit Calm Timer when healthy"] = "건강해지면 진정 타이머 종료"
L["as soon as you're healthy"] = "건강해지는 즉시"
L["%d sec after you're healthy"] = "건강해진 뒤 %d초"
L["Include your pet"] = "소환수 포함"
L["The Calm Timer runs out early once your health and power are back to full after a fight (mana, energy and focus refilled; rage, runic power, Insanity and the like drained). The seconds: how long things stay up once you're full, before they fade out at the Fade out time (a little wait keeps them up between pulls when you took no damage). Off: the Calm Timer always runs its full length."] = "전투 후 생명력과 자원이 다시 가득 차면 진정 타이머가 일찍 끝납니다 (마나, 기력, 집중이 다시 차고 분노, 룬 마력, 광기 등은 비워짐). 초: 가득 찬 뒤 표시가 얼마나 더 남아 있다가 사라지기 시간에 맞춰 사라질지 (피해를 받지 않았을 때 잠깐 기다리면 풀 사이에 표시가 유지됩니다). 끔: 진정 타이머가 항상 끝까지 갑니다."
L["With a pet out, the Calm Timer only ends early once its health is back to full as well. No pet, or a dead one: just yours counts."] = "소환수가 있으면 소환수의 생명력도 가득 차야 진정 타이머가 일찍 끝납니다. 소환수가 없거나 죽었으면 내 생명력만 봅니다."
L["%d sec after a fight"] = "전투 후 %d초"
L["How long things take to settle back into CineMode after a fight. Nameplates and names ticked In combat stay up this long (so they don't drop away between pulls), and visual effects that step aside for fights wait this long before fading back in. Your portrait and buffs, if they only show after combat, count a fight as recent for this long too, the RP walk, auto-run and cozy cameras wait this long before starting, and music muted for fights comes back after it. Then things fade out at the Fade out time. 0 settles at once. Exit Calm Timer when healthy, below, can end it early."] = "전투가 끝나고 CineMode로 돌아가기까지 걸리는 시간입니다. '전투 중'에 체크한 이름표와 이름은 이 시간 동안 남아 있고(전투 사이에 사라지지 않도록), 전투 중 비켜나는 화면 효과는 이 시간을 기다린 뒤 다시 나타납니다. 전투 후에만 보이는 초상화와 강화 효과도 이 시간 동안은 최근 전투로 칩니다. RP 걷기, 자동 달리기, 아늑한 카메라는 이 시간을 기다린 뒤 시작하고, 전투 때문에 꺼진 음악도 이 시간 뒤에 돌아옵니다. 그 뒤 사라지기 시간에 맞춰 사라집니다. 0이면 곧바로 진정됩니다. 아래의 '건강해지면 진정 타이머 종료'로 일찍 끝낼 수 있습니다."
L["Combat text"] = "전투 문자"
L["Hide combat text out of combat"] = "비전투 중 전투 문자 숨기기"
L["No floating damage and healing numbers (like \"+10\" from a heal or regen) in cinematic mode while you're out of combat. They come back the moment a fight starts and stay for the Calm Timer after it, and your combat text settings are put back when the UI returns."] = "비전투 중에는 시네마틱 모드에서 떠오르는 피해량과 치유량 숫자(치유나 재생으로 뜨는 '+10' 같은)를 표시하지 않습니다. 전투가 시작되는 순간 돌아와서 전투 후 진정 타이머 동안 남아 있으며, UI가 돌아오면 전투 문자 설정도 원래대로 돌아갑니다."
L["Hide all floating text: XP, damage, healing (restart required)"] = "떠오르는 문자 모두 숨기기: 경험치, 피해, 치유 (재시작 필요)"
L["The game has no way to hide just the XP you gain over your character: it draws that, the damage and healing numbers, misses and the like all in one font. This blanks that font, so they all go, always (not just in CineMode). Takes effect after you fully restart the game; /reload isn't enough."] = "게임에는 캐릭터 위에 뜨는 경험치만 숨기는 방법이 없습니다. 경험치, 피해량과 치유량 숫자, 빗나감 등을 모두 한 글꼴로 그리기 때문입니다. 이 옵션은 그 글꼴을 비워서 모두, 항상(CineMode일 때만이 아니라) 사라지게 합니다. 게임을 완전히 다시 시작해야 적용됩니다. /reload로는 안 됩니다."
L["Floating text changes after you fully restart the game (/reload isn't enough). Exit the game now?"] = "떠오르는 문자는 게임을 완전히 다시 시작해야 바뀝니다 (/reload로는 안 됩니다). 지금 게임을 종료하시겠습니까?"
L["Misc"] = "기타"
L["Frames CineMode brings back while they have something to tell you. Always keeping a frame up, or in fights, is on the Game Frames page."] = "알려 줄 것이 있는 동안 CineMode가 다시 보여 주는 프레임입니다. 프레임을 항상, 또는 전투 중에 띄워 두는 설정은 게임 창 페이지에 있습니다."
L["Show your portrait until health and power are full"] = "생명력과 자원이 가득 찰 때까지 초상화 표시"
L["Keeps your player portrait up while you're recovering. Rage and runic power don't count, so a warrior's portrait hides once their health is full."] = "회복하는 동안 플레이어 초상화를 띄워 둡니다. 분노와 룬 마력은 치지 않으므로 전사의 초상화는 생명력이 가득 차면 숨겨집니다."
L["Only after combat"] = "전투 후에만"
L["Only keep the portrait up if you've been in combat (or taken fall damage) within the Calm Timer (CineMode page), so things like casting a buff in town don't bring it up."] = "진정 타이머(CineMode 페이지) 안에 전투를 했거나(또는 낙하 피해를 입었거나) 했을 때만 초상화를 띄워 둡니다. 마을에서 강화 효과를 거는 것 같은 일로는 뜨지 않습니다."
L["Also after you resurrect"] = "부활한 뒤에도"
L["After you come back to life, keep the portrait up until your health and power are full, however long that takes."] = "되살아난 뒤에는 시간이 얼마나 걸리든 생명력과 자원이 가득 찰 때까지 초상화를 띄워 둡니다."
L["Show the durability figure when gear is damaged"] = "장비가 손상되면 내구도 표시"
L["Keeps the armor figure (by the minimap) up in CineMode, and in fights, while the game shows it: some of your gear is badly damaged (yellow) or broken (red). It goes again once you repair. Off, it fades with the rest of the UI."] = "게임이 내구도 인형을 보여 주는 동안(장비 일부가 심하게 손상(노랑)되었거나 파손(빨강)되었을 때) CineMode와 전투 중에도 미니맵 옆의 방어구 인형을 띄워 둡니다. 수리하면 다시 사라집니다. 끄면 나머지 UI와 함께 흐려집니다."
L["While a camera mode runs (AFK, auto-run, RP walk, flights and the rest), the figure fades with the rest of the UI. It comes back when the camera mode ends."] = "카메라 모드(자리 비움, 자동 달리기, RP 걷기, 비행 등)가 실행되는 동안 인형 표시가 나머지 UI와 함께 사라집니다. 카메라 모드가 끝나면 다시 나타납니다."
L["Show the pet frame when your pet isn't happy"] = "소환수가 행복하지 않을 때 소환수 프레임 표시"
L["Keeps your pet's portrait up in CineMode, and in fights, while its happiness isn't green: content (yellow) or unhappy (red). It goes again once your pet is happy."] = "소환수의 행복도가 녹색이 아닌 동안(만족: 노랑, 불만: 빨강) CineMode와 전투 중에 소환수 초상화를 표시합니다. 소환수가 행복해지면 다시 사라집니다."
L["While a camera mode runs (AFK, auto-run, RP walk, flights and the rest), the pet frame fades with the rest of the UI. It comes back when the camera mode ends."] = "카메라 모드(자리 비움, 자동 달리기, RP 걷기, 비행 등)가 실행되는 동안 소환수 프레임이 나머지 UI와 함께 사라집니다. 카메라 모드가 끝나면 다시 나타납니다."
L["Buffs/debuffs"] = "강화/약화 효과"
L["Buffs/Debuffs"] = "강화/약화 효과"
L["Your buff and debuff icons. They fade with the UI in CineMode; these bring them back."] = "내 강화 효과와 약화 효과 아이콘입니다. CineMode에서는 UI와 함께 흐려지며, 아래 옵션으로 다시 보이게 합니다."
L["Show buffs when you gain or refresh one"] = "강화 효과를 얻거나 갱신하면 표시"
L["Gaining or refreshing a buff briefly shows your buffs and debuffs. Not on flights."] = "강화 효과를 얻거나 갱신하면 강화 및 약화 효과를 잠깐 보여 줍니다. 비행 중에는 제외."
L["On: CineMode fades your buffs and debuffs as this page and their Game Frames row say. Off: it leaves them alone, with no peeks."] = "켜면: 이 페이지와 게임 창 페이지의 해당 줄에 따라 CineMode가 강화 및 약화 효과를 흐리게 합니다. 끄면: 손대지 않으며 잠깐 보여 주지도 않습니다."
L["Only within the Calm Timer after a fight, so buffing up in town doesn't count."] = "전투 후 진정 타이머 안에서만. 마을에서 강화 효과를 받는 것은 치지 않습니다."
L["Not ones you cast on yourself"] = "내가 나에게 건 효과는 제외"
L["Your own buffs on yourself (Power Word: Fortitude, Arcane Intellect, a self-cast shield...) and your pet's don't bring them up; ones from other players and the world still do."] = "내가 나에게 건 강화 효과(신의 권능: 인내, 신비한 지능, 자신에게 거는 보호막...)와 소환수의 효과로는 뜨지 않습니다. 다른 플레이어나 주변에서 받은 효과로는 여전히 뜹니다."
L["Show debuffs when you gain or refresh one"] = "약화 효과를 얻거나 갱신하면 표시"
L["Gaining or refreshing a debuff briefly shows your buffs and debuffs. Not on flights."] = "약화 효과를 얻거나 갱신하면 강화 및 약화 효과를 잠깐 보여 줍니다. 비행 중에는 제외."
L["Only within the Calm Timer after a fight. Off: debuffs like Hunter's Mark show any time."] = "전투 후 진정 타이머 안에서만. 끄면: 사냥꾼의 징표 같은 약화 효과도 언제든 표시합니다."
L["Keep them up until the debuff is gone"] = "약화 효과가 사라질 때까지 유지"
L["A debuff that brings them up keeps them up while you have any debuff (bar the ones listed below), however long that is. Combat still takes over."] = "약화 효과 때문에 떴다면, 약화 효과(아래 목록 제외)가 하나라도 있는 동안은 얼마나 길든 계속 띄워 둡니다. 전투가 되면 전투 설정이 우선합니다."
L["Show buffs for"] = "강화 효과 표시 시간"
L["Show debuffs for"] = "약화 효과 표시 시간"
L["Except for these buffs and debuffs:"] = "다음 강화/약화 효과는 제외:"
L["Remove"] = "제거"
L["Add"] = "추가"
L["Gaining or stacking this doesn't bring your buffs up. Type a spell ID or a name. Names must match your game language; spell IDs work in any language (2479 is Honorless Target, 8326 and 20584 are Ghost)."] = "이 효과를 얻거나 중첩해도 강화 효과를 띄우지 않습니다. 주문 ID나 이름을 입력하세요. 이름은 게임 언어와 일치해야 하며, 주문 ID는 어느 언어에서나 됩니다(2479는 명예 없는 대상, 8326과 20584는 유령)."
L["Camera Modes"] = "카메라 모드"
L["While CineMode is on, the camera comes alive in eight situations: Flight (on flight paths), AFK (once you've stood still a while, or go AFK), Cozy (campfires and emotes), Tele (casting your Hearthstone or a teleport), Vista (/stare), Fish (fishing), RP Walk (auto-walking) and Auto-run. Moving by hand cancels them all. Death Cam turns round your body when you die, and Quest Cam swings behind you at quest givers. The Camera Triggers page picks which camera each emote or event starts. Everything goes back to normal when the UI returns. The settings here apply to all of them."] = "CineMode가 켜져 있으면 카메라가 여덟 가지 상황에서 살아 움직입니다: 비행(비행 경로), 자리 비움(한동안 가만히 서 있거나 자리를 비울 때), 아늑함(모닥불과 감정 표현), 순간이동(귀환석이나 순간이동 시전), 풍경(/stare), 낚시(낚시 중), RP 걷기(자동 걷기), 자동 달리기. 직접 움직이면 모두 취소됩니다. 죽음 카메라는 죽었을 때 시체 주위를 돌고, 퀘스트 카메라는 퀘스트 NPC 앞에서 뒤쪽으로 돌아갑니다. 각 감정 표현이나 이벤트가 어떤 카메라를 시작할지는 카메라 발동 조건 페이지에서 고릅니다. UI가 돌아오면 모두 원래대로 돌아갑니다. 여기 설정은 모든 카메라에 적용됩니다."
L["In the camera modes, the minimap and quest tracker hover holds and the buff and chat peeks use their short default times, so they clear the view quickly."] = "카메라 모드에서는 미니맵과 퀘스트 추적기의 마우스오버 유지 시간, 강화 효과와 대화창을 잠깐 보여 주는 시간이 짧은 기본값을 써서 화면이 금방 깨끗해집니다."
L["Ticked, that camera doesn't start there (and stops if it's running): the UI stays faded, with the camera left to you. With the Death Cam off, dying brings the UI back as usual. To keep the normal UI somewhere instead, use Turn off in on the main page. For flights, Cities means taking off from one, and Open world taking off anywhere else. Calm Timer, on the right: ticked, that camera waits until the Calm Timer (CineMode page) has run out after a fight before it starts."] = "체크하면 그곳에서는 그 카메라가 시작하지 않습니다(돌고 있으면 멈춥니다). UI는 흐려진 채 카메라는 직접 조작합니다. 죽음 카메라가 꺼져 있으면 죽을 때 평소처럼 UI가 돌아옵니다. 대신 일반 UI를 유지하려면 메인 페이지의 '끄는 곳'을 쓰세요. 비행에서 '도시'는 도시에서 출발할 때, '필드'는 그 밖의 곳에서 출발할 때입니다. 오른쪽의 진정 타이머: 체크하면 그 카메라는 전투 후 진정 타이머(CineMode 페이지)가 끝날 때까지 기다렸다가 시작합니다."
L["in capital cities"] = "수도에서"
L["in dungeons, scenarios and raids"] = "던전, 시나리오, 공격대에서"
L["in battlegrounds and arenas"] = "전장과 투기장에서"
L["out in the world (not in a capital city or an instance), inns included"] = "필드에서(수도나 인스턴스가 아닌 곳), 여관 포함"
L["Tick a camera here to turn it off %s."] = "여기서 카메라를 체크하면 %s 끕니다."
L["Tick a camera here to have it wait until the Calm Timer (CineMode page) has run out after a fight before it starts."] = "전투 후 진정 타이머(CineMode 페이지)가 끝날 때까지 기다렸다가 시작하게 하려면 여기 체크하세요."
L["Flights don't start %s."] = "%s 비행 카메라가 시작하지 않습니다."
L["No Flight Cam on flights taking off from a capital city."] = "수도에서 출발하는 비행에서는 비행 카메라를 쓰지 않습니다."
L["No Flight Cam on flights taking off anywhere but a capital city."] = "수도가 아닌 곳에서 출발하는 비행에서는 비행 카메라를 쓰지 않습니다."
L["No %s Cam %s."] = "%s 카메라를 쓰지 않습니다 (%s)."
L["You die in a fight: the Death Cam can't wait for one to be over."] = "죽음은 전투 중에 일어나므로 죽음 카메라는 전투가 끝나기를 기다릴 수 없습니다."
L["The %s Cam waits until the Calm Timer has run out after a fight."] = "%s 카메라는 전투 후 진정 타이머가 끝날 때까지 기다립니다."
L["Depth of field"] = "피사계 심도"
L["Cozy camera"] = "아늑한 카메라"
L["Vista camera"] = "풍경 카메라"
L["Fish camera"] = "낚시 카메라"
L["AFK camera"] = "자리 비움 카메라"
L["No camera"] = "카메라 없음"
L["Flight camera"] = "비행 카메라"
L["RP walk camera"] = "RP 걷기 카메라"
L["Auto-run camera"] = "자동 달리기 카메라"
L["Death camera"] = "죽음 카메라"
L["Quest camera"] = "퀘스트 카메라"
L["Tele camera"] = "순간이동 카메라"
L["Standing or sitting still with any of the buffs listed below (like Welcoming Campfire)."] = "아래 목록의 강화 효과(환영의 모닥불 등)를 받은 채 가만히 서 있거나 앉아 있을 때."
L["Doing the emote (or pressing the sit key). Moving, jumping or another emote ends it."] = "감정 표현을 할 때(또는 앉기 키를 누를 때). 움직이거나, 점프하거나, 다른 감정 표현을 하면 끝납니다."
L["Doing the emote. Moving, jumping or another emote ends it."] = "감정 표현을 할 때. 움직이거나, 점프하거나, 다른 감정 표현을 하면 끝납니다."
L["Right-clicking a seat to sit on it; standing up ends it. Seats are recognized by name, using the words below."] = "의자를 오른쪽 클릭해 앉을 때. 일어서면 끝납니다. 의자는 아래 단어로 이름을 보고 알아봅니다."
L["Unsheathing your weapon with your Sheathe/Unsheathe key out of combat, for a \"hero shot\" (not when it comes out from attacking or casting). Putting it away, running or combat ends it. With the cozy camera it carries on while you auto-walk (the camera swings round in front as you walk, even with Stop on move)."] = "비전투 중에 무기 넣기/꺼내기 키로 무기를 꺼낼 때, '영웅 샷'을 위해(공격이나 시전으로 꺼낼 때는 제외). 무기를 넣거나, 달리거나, 전투에 들어가면 끝납니다. 아늑한 카메라라면 자동 걷기 중에도 계속됩니다(걸어가는 동안 카메라가 앞쪽으로 돌아갑니다. '움직이면 멈춤'이 켜져 있어도)."
L["Casting your Hearthstone (or Astral Recall, or any spell with \"Hearthstone\" in its name). The tele camera swings round in front of you and spins faster and faster as it zooms in, until you go. The cast doesn't bring the UI back or pause the camera."] = "귀환석(또는 영혼의 귀환이나 이름에 '귀환석'이 들어간 주문)을 시전할 때. 순간이동 카메라가 앞쪽으로 돌아가서 확대하며 점점 빠르게 돌다가 이동합니다. 시전해도 UI가 돌아오거나 카메라가 멈추지 않습니다."
L["Casting a teleport (a mage's \"Teleport: Stormwind\" and the like, or a druid's Teleport: Moonglade). The tele camera, as for the Hearthstone."] = "순간이동을 시전할 때(마법사의 '순간이동: 스톰윈드' 등이나 드루이드의 순간이동: 달의 숲). 귀환석과 같은 순간이동 카메라입니다."
L["Logging out or quitting where the game counts down 20 seconds first (out in the world). In an inn or a city, logging out is instant, so there's nothing to see. Moving, jumping, casting or Cancel ends it. It comes before any other event (a Hearthstone or teleport cast calls it off)."] = "게임이 20초를 먼저 세는 곳(필드)에서 로그아웃하거나 게임을 종료할 때. 여관이나 도시에서는 로그아웃이 바로 되므로 볼 것이 없습니다. 움직이거나, 점프하거나, 시전하거나, 취소하면 끝납니다. 다른 모든 이벤트보다 우선합니다(귀환석이나 순간이동 시전은 이를 취소합니다)."
L["Doing the emote while standing still. Moving, jumping or another emote ends it."] = "가만히 서서 감정 표현을 할 때. 움직이거나, 점프하거나, 다른 감정 표현을 하면 끝납니다."
L["Casting Fishing. It carries on after the cast ends (looting, casting again) until you move or jump. The cast doesn't bring the UI back or pause the camera."] = "낚시를 시전할 때. 시전이 끝난 뒤에도(전리품 획득, 다시 시전) 움직이거나 점프할 때까지 계속됩니다. 시전해도 UI가 돌아오거나 카메라가 멈추지 않습니다."
L["Being flagged AFK (/afk, or away long enough). With \"No camera\", Stand still below still applies once you've stood still for its time."] = "자리 비움 상태일 때(/afk 또는 오래 자리를 비움). '카메라 없음'이면 아래의 '가만히 서 있기'가 그 시간만큼 서 있은 뒤에 적용됩니다."
L["Standing still for the time below with nothing else going on (no emote, no other event). \"No camera\": standing still starts nothing, though going AFK and the other events still do."] = "다른 일(감정 표현, 다른 이벤트) 없이 아래 시간만큼 가만히 서 있을 때. '카메라 없음': 가만히 서 있어도 아무것도 시작하지 않지만, 자리 비움과 다른 이벤트는 여전히 시작합니다."
L["Taking off on a flight path. With \"No camera\", the camera is left to you for the whole flight."] = "비행 경로로 출발할 때. '카메라 없음'이면 비행 내내 카메라를 직접 조작합니다."
L["Talking to a quest giver (a quest to pick up or hand in). Works whether or not CineMode is on."] = "퀘스트 NPC와 대화할 때(받거나 완료할 퀘스트가 있을 때). CineMode가 켜져 있든 아니든 작동합니다."
L["Camera Triggers"] = "카메라 발동 조건"
L["What starts the AFK, cozy, vista and fish cameras. Pick a camera for each event; a Hearthstone or teleport cast comes first, then logging out, going AFK, the latest emote, a drawn weapon, a campfire, and standing still last. Taking a flight has the flight camera, talking to a quest giver the quest camera, and auto-walking, auto-running and dying their own."] = "자리 비움, 아늑함, 풍경, 낚시 카메라를 무엇이 시작할지 정합니다. 이벤트마다 카메라를 고르세요. 귀환석이나 순간이동 시전이 가장 먼저이고, 그다음 로그아웃, 자리 비움, 가장 최근의 감정 표현, 꺼낸 무기, 모닥불 순이며, 가만히 서 있기가 마지막입니다. 비행에는 비행 카메라, 퀘스트 NPC와의 대화에는 퀘스트 카메라가 있고, 자동 걷기, 자동 달리기, 죽음에는 각자의 카메라가 있습니다."
L["Event"] = "이벤트"
L["Camera"] = "카메라"
L["Music"] = "음악"
L["Music starts as this event's camera starts, unless the addon started music within the fatigue time (Audio page). Music already playing just carries on. Off: this camera never starts music. Needs \"Allow CineMode to queue Music\" on the Audio page."] = "이 이벤트의 카메라가 시작될 때 음악도 시작합니다. 단, 애드온이 피로 시간(소리 페이지) 안에 음악을 시작했다면 제외합니다. 이미 재생 중인 음악은 그대로 이어집니다. 끄면: 이 카메라는 음악을 시작하지 않습니다. 소리 페이지의 'CineMode가 음악을 재생하도록 허용'이 필요합니다."
L["With \"Start in CineMode\" off (Cinematic's main page), this event's camera starting brings CineMode on (the UI fades, music, visual effects), and it ends with the camera. Tick Stand still and Go AFK for a screensaver: the normal UI while you play, CineMode once you've been idle a while."] = "'CineMode로 시작'이 꺼져 있으면(Cinematic 메인 페이지), 이 이벤트의 카메라가 시작될 때 CineMode가 켜지고(UI 흐리기, 음악, 화면 효과) 카메라와 함께 끝납니다. '가만히 서 있기'와 '자리 비움'에 체크하면 화면 보호기가 됩니다: 플레이하는 동안은 일반 UI, 한동안 가만히 있으면 CineMode."
L[" While you're flagged AFK, whatever the camera. Off also keeps music from coming back after a pause while you're away."] = " 자리 비움 상태인 동안, 카메라와 상관없이. 끄면 자리를 비운 동안 일시 정지 뒤에 음악이 다시 나오지 않습니다."
L[" Off also keeps music from coming back after a pause while you stand still."] = " 끄면 가만히 서 있는 동안 일시 정지 뒤에 음악이 다시 나오지 않습니다."
L["Buff names or spell IDs, separated by commas. Names must match your game language; spell IDs work in any language."] = "강화 효과 이름이나 주문 ID를 쉼표로 구분해 입력합니다. 이름은 게임 언어와 일치해야 하며, 주문 ID는 어느 언어에서나 됩니다."
L["Buffs, separated by commas."] = "강화 효과, 쉼표로 구분."
L["Words that mark a seat when they're in an object's name (\"Wooden Chair\"), separated by commas. Use words in your game language."] = "물체 이름에 들어 있으면 의자로 보는 단어('나무 의자')를 쉼표로 구분해 입력합니다. 게임 언어의 단어를 쓰세요."
L["Seat words, separated by commas."] = "의자 단어, 쉼표로 구분."
L["After standing still for"] = "가만히 서 있은 시간"
L["How long you stand still before this row's camera starts (an event set to the AFK camera, like going AFK, skips the wait). Also used by the other options that mention standing still (tint, tracking, music, tooltips)."] = "이 줄의 카메라가 시작되기 전에 가만히 서 있어야 하는 시간입니다(자리 비움처럼 자리 비움 카메라로 설정한 이벤트는 기다리지 않습니다). 가만히 서 있기를 언급하는 다른 옵션(색조, 추적, 음악, 툴팁)에도 쓰입니다."
L["Auto-walk (RP walk)"] = "자동 걷기 (RP 걷기)"
L["After auto-walking for"] = "자동 걷기 시간"
L["Auto-walking (auto-run in walk mode). The camera's settings are under RP Walk Cam on the Camera Settings page; Camera Modes turns it off in some places."] = "자동 걷기(걷기 모드의 자동 달리기). 카메라 설정은 카메라 설정 페이지의 RP 걷기 카메라에 있으며, 카메라 모드 페이지에서 일부 장소에서는 끌 수 있습니다."
L["After auto-running for"] = "자동 달리기 시간"
L["Auto-running. The camera's settings are under Auto-run Cam on the Camera Settings page; Camera Modes turns it off in some places."] = "자동 달리기. 카메라 설정은 카메라 설정 페이지의 자동 달리기 카메라에 있으며, 카메라 모드 페이지에서 일부 장소에서는 끌 수 있습니다."
L["Die"] = "죽음"
L["Dying, until you release or are resurrected. The camera's settings are under Death Cam on the Camera Settings page; Camera Modes turns it off in some places."] = "죽었을 때, 영혼을 놓아주거나 부활할 때까지. 카메라 설정은 카메라 설정 페이지의 죽음 카메라에 있으며, 카메라 모드 페이지에서 일부 장소에서는 끌 수 있습니다."
L["A song of its own plays while the death camera runs, in place of the zone music (pick the songs under Death Cam on the Camera Settings page). With CineMode music off, only if your game music is on."] = "죽음 카메라가 실행되는 동안 지역 음악 대신 전용 곡이 재생됩니다(곡은 카메라 설정 페이지의 죽음 카메라에서 고릅니다). CineMode 음악이 꺼져 있으면 게임 음악이 켜져 있을 때만 재생됩니다."
L["How long you keep going before this row's camera starts (and CineMode, if its CineMode box is ticked). 0: straight away. Stopping or moving by hand first starts the count over."] = "이 줄의 카메라(와 CineMode 칸에 체크했다면 CineMode)가 시작되기 전에 계속해야 하는 시간입니다. 0: 바로 시작. 그 전에 멈추거나 직접 움직이면 처음부터 다시 셉니다."
L["An event set to the AFK camera starts it without waiting out Stand still's time."] = "자리 비움 카메라로 설정한 이벤트는 '가만히 서 있기' 시간을 기다리지 않고 바로 시작합니다."
L["Strength"] = "강도"
L["%.2f sec"] = "%.2f초"
L["Visual Effects"] = "화면 효과"
L["How the game world looks in CineMode (or over the normal UI, with Start in CineMode off on the main page): letterbox bars, color grading, vignette, inn glow and weather. The UI isn't tinted. Names and nameplates are on the Nameplates page."] = "CineMode에서(또는 메인 페이지의 'CineMode로 시작'이 꺼져 있으면 일반 UI 위에) 게임 세상이 어떻게 보일지 정합니다: 레터박스 바, 색 보정, 비네트, 여관 불빛, 날씨. UI에는 색조가 입혀지지 않습니다. 이름과 이름표는 이름표 페이지에 있습니다."
L["Turns everything on this page on or off at once: the letterbox, tint, time of day, zone tints, vignette, inn glow, weather and depth of field. Each keeps its own settings for when you turn this back on."] = "이 페이지의 모든 것을 한 번에 켜거나 끕니다: 레터박스, 색조, 시간대, 지역 색조, 비네트, 여관 불빛, 날씨, 피사계 심도. 다시 켤 때를 위해 각자의 설정은 유지됩니다."
L["Ticked, that effect doesn't show there. Always: not at all. Combat: it goes for fights, and comes back once the Calm Timer (CineMode page) has run out after. Outside camera modes: it only shows while a camera mode runs (flights, AFK, cozy and the rest)."] = "체크하면 그곳에서는 그 효과가 보이지 않습니다. 항상: 전혀 보이지 않음. 전투: 전투 중에는 사라졌다가, 전투 후 진정 타이머(CineMode 페이지)가 끝나면 돌아옴. 카메라 모드 밖: 카메라 모드(비행, 자리 비움, 아늑함 등)가 도는 동안에만 보임."
L["Letterbox"] = "레터박스"
L["Vignette"] = "비네트"
L["Weather"] = "날씨"
L["letterbox"] = "레터박스"
L["tint"] = "색조"
L["vignette"] = "비네트"
L["weather tint"] = "날씨 색조"
L["Always"] = "항상"
L["No %s at all."] = "%s 전혀 없음."
L["No %s %s."] = "%s 없음 (%s)."
L["The %s goes for fights, and comes back once the Calm Timer (CineMode page) has run out after one."] = "%s: 전투 중에는 사라졌다가, 전투 후 진정 타이머(CineMode 페이지)가 끝나면 돌아옵니다."
L["Outside camera modes"] = "카메라 모드 밖"
L["The %s only shows while a camera mode runs: flights, AFK, cozy and the rest."] = "%s: 카메라 모드(비행, 자리 비움, 아늑함 등)가 도는 동안에만 보입니다."
L["Bar height"] = "바 높이"
L["Black bars slide in at the top and bottom of the screen."] = "화면 위아래에서 검은 바가 밀려 들어옵니다."
L["Bar opacity"] = "바 불투명도"
L["Current time"] = "현재 시간"
L["Preview time"] = "미리 보기 시간"
L["See how the tint looks at another time of day. Only a preview: it goes back to the real clock when you leave this page."] = "다른 시간대의 색조를 확인합니다. 미리 보기일 뿐이며, 이 페이지를 나가면 실제 시간으로 돌아갑니다."
L["Here: %s (%s's own preset)"] = "여기: %s (%s 전용 프리셋)"
L["Here: %s (%s%s)"] = "여기: %s (%s%s)"
L[", your choice"] = ", 직접 선택"
L["Previewing: %s (%02d:00)"] = "미리 보는 중: %s (%02d:00)"
L["Now: %s (%02d:%02d your time)"] = "지금: %s (내 시간 %02d:%02d)"
L["Now: %s (%02d:%02d game time)"] = "지금: %s (게임 시간 %02d:%02d)"
L["Custom color"] = "사용자 지정 색"
L["Click to choose the color used by the Custom preset."] = "클릭해서 '사용자 지정' 프리셋에 쓸 색을 고릅니다."
L["Subtle drift"] = "은은한 변화"
L["The tint's strength slowly wanders up and down over a few minutes, so a still scene feels a little more alive. Paused while this page is open."] = "색조 강도가 몇 분에 걸쳐 천천히 오르내려서 정지된 장면이 조금 더 살아 있는 느낌이 납니다. 이 페이지가 열려 있는 동안은 멈춥니다."
L["Drift amount"] = "변화 폭"
L["How far the strength wanders either way, as a share of the strength."] = "강도 대비 비율로, 강도가 위아래로 얼마나 오르내릴지 정합니다."
L["Time of day"] = "시간대"
L["For the Time of day and Zone + time of day presets, and the time of day message."] = "'시간대'와 '지역 + 시간대' 프리셋, 그리고 시간대 메시지에 쓰입니다."
L["Follows"] = "기준"
L["Game time (matches the game's day and night)"] = "게임 시간 (게임의 낮과 밤에 맞춤)"
L["Your computer's clock"] = "내 컴퓨터 시계"
L["Time of day strength"] = "시간대 강도"
L["How strongly the time-of-day color applies, in Time of day and Zone + time of day. Lower it for softer nights; 0 leaves just the zone mood."] = "'시간대'와 '지역 + 시간대'에서 시간대 색이 얼마나 강하게 적용될지 정합니다. 낮추면 밤이 부드러워지고, 0이면 지역 분위기만 남습니다."
L["Phases (click a color to change it)"] = "시간대별 색 (색을 클릭해 변경)"
L["Reset"] = "초기화"
L["Back to the built-in color and strength."] = "기본 색과 강도로 되돌립니다."
L["Choose your own color for %s."] = "%s의 색을 직접 고릅니다."
L["Zone tints"] = "지역 색조"
L["Give the zone you're standing in, or just the area within it (a town, a port), a preset of its own: it replaces your main preset there. With a Zone preset you can also choose its color, which replaces the built-in mood. An area's choices win over its zone's."] = "지금 서 있는 지역, 또는 그 안의 구역(마을, 항구)에 전용 프리셋을 줍니다. 그곳에서는 기본 프리셋 대신 쓰입니다. '지역' 프리셋이라면 색도 고를 수 있으며, 기본 분위기 대신 쓰입니다. 구역의 설정이 지역의 설정보다 우선합니다."
L[", |cffffd100%s|r preset"] = ", |cffffd100%s|r 프리셋"
L["This zone: |cffffd100%s|r - %s%s, %d%% strength%s%s"] = "이 지역: |cffffd100%s|r - %s%s, 강도 %d%%%s%s"
L[" (your choice)"] = " (직접 선택)"
L[" (built in)"] = " (기본 제공)"
L[" (its own)"] = " (전용)"
L["This area: |cffffd100%s|r - %s%s, %d%% strength%s%s"] = "이 구역: |cffffd100%s|r - %s%s, 강도 %d%%%s%s"
L["Change:"] = "변경:"
L["the zone"] = "지역"
L["this area (%s)"] = "이 구역 (%s)"
L["this area (none here)"] = "이 구역 (여기에는 없음)"
L["Same as the zone"] = "지역과 같게"
L["Main preset"] = "기본 프리셋"
L["Preset here"] = "여기 프리셋"
L["A preset for the zone or area chosen above, used there instead of your main preset."] = "위에서 고른 지역이나 구역에 쓸 프리셋으로, 그곳에서는 기본 프리셋 대신 쓰입니다."
L["Built-in mood"] = "기본 분위기"
L["No tint"] = "색조 없음"
L["Pick a color..."] = "색 고르기..."
L["Choose your own color for the zone or area chosen above (for the Zone presets)."] = "위에서 고른 지역이나 구역의 색을 직접 고릅니다('지역' 프리셋용)."
L["Your zone tints"] = "내 지역 색조"
L["%s preset, "] = "%s 프리셋,"
L[", %d%% strength"] = ", 강도 %d%%"
L["None yet."] = "아직 없음."
L["...and %d more."] = "...그 외 %d개."
L["At zone borders"] = "지역 경계에서"
L["Fade time"] = "흐려지는 시간"
L["With a Zone tint preset, crossing into a zone with a different mood fades the old mood out over this long, pauses, then fades the new one in over this long."] = "'지역' 색조 프리셋에서 분위기가 다른 지역으로 넘어가면, 이전 분위기가 이 시간 동안 사라지고, 잠시 멈췄다가, 새 분위기가 이 시간 동안 나타납니다."
L["Pause between tints when flying"] = "비행 중 색조 사이 멈춤"
L["Untinted time between the two zones' moods while you're in the air, where you see the old zone's ground for longer (snow under an ember tint looks red)."] = "공중에 있는 동안 두 지역 분위기 사이에 색조가 없는 시간입니다. 공중에서는 이전 지역의 땅이 더 오래 보이기 때문입니다(잉걸불 색조 아래의 눈은 빨갛게 보입니다)."
L["Pause between tints on the ground"] = "지상에서 색조 사이 멈춤"
L["The same pause when you cross a border on foot or riding."] = "걷거나 탈것을 타고 경계를 넘을 때의 같은 멈춤입니다."
L["Vignette strength"] = "비네트 강도"
L["Soft dark edges that draw the eye to the middle. Works with any tint."] = "시선을 가운데로 모으는 부드럽고 어두운 가장자리입니다. 어떤 색조와도 함께 쓸 수 있습니다."
L["Inns"] = "여관"
L["Light up inns"] = "여관 밝히기"
L["Indoors in an inn, the outdoor tint (a gloomy marsh, a moonlit night) partly lifts and a soft firelit glow fades in, colored by the zone: cooler in the snow, greener in a swamp. Blends over a few seconds as you go through the door."] = "여관 안에 들어가면 바깥 색조(음침한 늪, 달빛 비치는 밤)가 일부 걷히고, 지역에 따라 색이 달라지는 부드러운 불빛이 나타납니다: 눈 속에서는 더 차갑게, 늪에서는 더 푸르게. 문을 지나는 동안 몇 초에 걸쳐 섞입니다."
L["Inn glow amount"] = "여관 불빛 양"
L["How much light the glow adds at its brightest, low on the screen."] = "가장 밝을 때 화면 아래쪽에 불빛이 더하는 빛의 양입니다."
L["Weather strength"] = "날씨 강도"
L["Rain grays and cools the scene, snow turns it pale blue and a sandstorm gives it a dusty orange haze, more strongly the heavier the weather. Works with any tint (None included), lifts under a roof and blends in as a storm builds. Needs a game version that reports the weather."] = "비는 장면을 회색으로 차갑게, 눈은 옅은 푸른색으로, 모래 폭풍은 먼지 낀 주황빛 안개로 만들며, 날씨가 거셀수록 더 강해집니다. 어떤 색조와도(없음 포함) 함께 쓸 수 있고, 지붕 아래에서는 걷히며, 폭풍이 커지면서 서서히 섞입니다. 날씨를 알려 주는 게임 버전이 필요합니다."
L["Haze the screen edges in the camera modes"] = "카메라 모드에서 화면 가장자리 흐리게"
L["A soft haze around the edges of the screen, as if the camera had focused on you. Each camera mode's page sets its own strength. /cine doftest shows it on demand."] = "카메라가 나에게 초점을 맞춘 것처럼 화면 가장자리를 부드럽게 흐립니다. 강도는 각 카메라 모드 페이지에서 정합니다. /cine doftest로 바로 확인할 수 있습니다."
L["Sound during CineMode. Your own sound settings are saved first and put back afterwards, even after a crash. Pick which cameras play music as they start."] = "CineMode 중의 소리입니다. 내 소리 설정은 먼저 저장되었다가 나중에 원래대로 돌아갑니다(게임이 튕겨도). 시작할 때 음악을 재생할 카메라를 고르세요."
L["With your game music off, a camera starting (the ones ticked under Music on the Camera Triggers page) switches it on and fades it in, at your music volume; it fades out when the UI returns and your music is switched off again (logging out too). With your game music on, it's left alone. Unticked, music is never switched on."] = "게임 배경음악이 꺼져 있으면, 카메라가 시작될 때(카메라 발동 조건 페이지의 '음악'에 체크한 것) 배경음악을 켜고 내 음악 음량으로 서서히 키웁니다. UI가 돌아오면(로그아웃할 때도) 서서히 줄이고 다시 끕니다. 게임 배경음악이 켜져 있으면 손대지 않습니다. 해제하면 음악을 켜지 않습니다."
L["Music fade time"] = "음악 페이드 시간"
L["How long music takes to fade in or out with CineMode."] = "CineMode와 함께 음악이 서서히 커지거나 작아지는 데 걸리는 시간입니다."
L["Fatigue"] = "피로"
L["Music fatigue"] = "음악 피로"
L["Once a camera has started music, no camera starts it again for this long, counted from when it started. The first camera after a login or /reload always can. Music coming back after a mute doesn't count. 0 turns this off."] = "카메라가 음악을 시작하면, 시작한 때부터 이 시간 동안은 어떤 카메라도 음악을 다시 시작하지 않습니다. 접속하거나 /reload한 뒤 첫 카메라는 언제나 시작할 수 있습니다. 음소거 뒤에 음악이 돌아오는 것은 치지 않습니다. 0이면 끕니다."
L["Stop music"] = "음악 멈추기"
L["In combat"] = "전투 중"
L["Music fades out over about a second when a fight starts, and a fresh track fades back in once the Calm Timer (on the CineMode page) has passed with no new fight. Works on your own game music too; your volume is put back afterwards."] = "전투가 시작되면 음악이 1초 정도에 걸쳐 사라지고, 새 전투 없이 진정 타이머(CineMode 페이지)가 지나면 새 곡이 서서히 나옵니다. 내 게임 배경음악에도 적용되며, 음량은 나중에 원래대로 돌아갑니다."
L["Leaving a camera mode"] = "카메라 모드를 벗어날 때"
L["Music fades out once you leave the camera modes and move on: walking off from the cozy camera, say. Going from one camera straight to another (vista to cozy) keeps it playing, as does standing still. A fresh track fades in when the next camera starts (standing still counts once the AFK camera starts, with Go AFK's music on, Camera Triggers page). Fades at the music fade time."] = "카메라 모드를 벗어나 이동하면 음악이 사라집니다. 아늑한 카메라에서 걸어 나갈 때처럼요. 한 카메라에서 다른 카메라로 바로 넘어가거나(풍경에서 아늑함으로) 가만히 서 있으면 계속 재생됩니다. 다음 카메라가 시작되면 새 곡이 서서히 나옵니다(가만히 서 있기는 자리 비움 카메라가 시작될 때 치며, 카메라 발동 조건 페이지에서 자리 비움의 음악이 켜져 있어야 합니다). 음악 페이드 시간에 맞춰 흐려집니다."
L["In cities"] = "도시에서"
L["In dungeons"] = "던전에서"
L["In raids"] = "공격대에서"
L["In PvP"] = "PvP 중"
L["Music fades out here (your own game music too) and back in when you leave."] = "여기서는 음악이(내 게임 배경음악도) 사라졌다가 벗어나면 다시 나옵니다."
L["Tar enemy"] = "적 대상"
L["Tar friendly"] = "아군 대상"
L["More settings on the %s page. They can keep it up beyond what's ticked here (hovering, tracking, new auras, cooldowns recharging and the like)."] = "%s 페이지에 설정이 더 있습니다. 여기 체크한 것 외에도 계속 띄워 둘 수 있습니다(마우스오버, 추적, 새 효과, 재사용 대기시간 충전 등)."
L["Show it whenever its frame shows. This overrides its Hover groups: untick it to hide it in CineMode except when hovered or brought up by the other columns."] = "이 창이 보일 때마다 표시합니다. 마우스오버 그룹보다 우선합니다. 해제하면 CineMode에서는 마우스를 올리거나 다른 열이 띄울 때만 보입니다."
L["Show it all through CineMode, instead of hiding it. (The other columns then have nothing to add.)"] = "숨기지 않고 CineMode 내내 표시합니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["Standard Frames"] = "기본 창"
L["Everything here is hidden in CineMode unless ticked. Tick a column to show that frame: Always shows it the whole time, the next three only while you fight or have something targeted, and the places the whole time while you're there (Grouped: in a party or raid). Frames fade in and out at the fade times on the CineMode page. Other addons' frames are on the Addon Frames page."] = "여기 있는 모든 것은 체크하지 않으면 CineMode에서 숨겨집니다. 열에 체크하면 그 창을 표시합니다: '항상'은 내내, 다음 세 열은 전투 중이거나 대상을 지정했을 때만, 장소 열은 그곳에 있는 동안 내내(파티 중: 파티나 공격대에 있을 때). 창은 CineMode 페이지의 흐리기 시간에 맞춰 나타나고 사라집니다. 다른 애드온의 창은 애드온 창 페이지에 있습니다."
L["Enable Page"] = "페이지 사용"
L["On: CineMode fades the frames on this page as their rows say. Off: it leaves them all alone, the minimap, quest tracker, buffs and Cooldown Manager included (their pages' switches only count while this is on)."] = "켜면: 이 페이지의 줄 설정대로 CineMode가 창을 흐리게 합니다. 끄면: 미니맵, 퀘스트 추적기, 강화 효과, 재사용 대기시간 관리자를 포함해 모두 손대지 않습니다(각 페이지의 스위치는 이 옵션이 켜져 있을 때만 적용됩니다)."
L["In combat rows stay for the Calm Timer"] = "'전투 중' 줄은 진정 타이머 동안 유지"
L["Frames ticked In combat (here and on the Addon Frames page) stay up after a fight until the Calm Timer (CineMode page) has run out, then fade. Off: they fade as soon as the fight ends."] = "'전투 중'에 체크한 창(여기와 애드온 창 페이지)은 전투 후 진정 타이머(CineMode 페이지)가 끝날 때까지 남아 있다가 흐려집니다. 끄면: 전투가 끝나자마자 흐려집니다."
L["Cast fade into combat"] = "시전하며 전투로 나타나기"
L["Out of combat, casting a spell at an enemy brings up the frames ticked In combat, as if the fight had started: they fade in over the cast and are fully up as it lands. Instant spells bring them up at the Combat fade in time."] = "전투 밖에서 적에게 주문을 시전하면 전투가 시작된 것처럼 '전투 중'에 체크된 프레임이 나타납니다: 시전하는 동안 서서히 나타나 주문이 적중할 때 완전히 보입니다. 즉시 시전 주문은 전투 중 나타나는 시간으로 보여 줍니다."
L["Unit frames"] = "유닛 프레임"
L["Unit Frames"] = "유닛 프레임"
L["Interface"] = "인터페이스"
L["Party frames (not raid-style)"] = "파티 창 (공격대 스타일 아님)"
L["Battlegrounds"] = "전장"
L["Other"] = "기타"
L["Fishing"] = "낚시"
L["Casting and catching, with the mouse or a gamepad, CineMode or not."] = "마우스나 게임패드로 시전하고 낚아 올리기, CineMode와 상관없이."
L["On: right-click (or a gamepad button) casts again, and the Fishing cast bar hides, as this page says. Off: fishing is left to the game. (The fish camera is on the Camera Modes and Camera Triggers pages.)"] = "켜면: 이 페이지 설정대로 오른쪽 클릭(또는 게임패드 버튼)으로 다시 시전하고, 낚시 시전 바를 숨깁니다. 끄면: 낚시는 게임에 맡깁니다. (낚시 카메라는 카메라 모드와 카메라 발동 조건 페이지에 있습니다.)"
L["Casting"] = "시전"
L["Hide the Fishing cast bar"] = "낚시 시전 바 숨기기"
L["Your cast bar stays hidden while it shows Fishing. Every other spell shows it as usual."] = "낚시를 시전하는 동안 시전 바를 숨깁니다. 다른 주문은 평소처럼 보입니다."
L["Right-click to cast again"] = "오른쪽 클릭으로 다시 시전"
L["While the fish camera is on and no bobber is out, right-clicking in the world casts Fishing again. Each cast still comes from your own click. While the bobber is out, right-click clicks it as usual; in combat, with the loot window open or with your mouse on a player or NPC, right-click is left alone. (Meanwhile right-drag doesn't turn the camera: left-drag still does.)"] = "낚시 카메라가 켜져 있고 찌가 없을 때, 세상을 오른쪽 클릭하면 낚시를 다시 시전합니다. 시전은 언제나 내 클릭으로만 일어납니다. 찌가 있을 때는 평소처럼 오른쪽 클릭으로 찌를 클릭합니다. 전투 중, 전리품 창이 열려 있을 때, 마우스가 플레이어나 NPC 위에 있을 때는 오른쪽 클릭을 건드리지 않습니다. (그동안 오른쪽 끌기로는 카메라가 돌지 않습니다. 왼쪽 끌기는 여전히 됩니다.)"
L["Also the first cast, with a pole equipped"] = "낚싯대를 장착했다면 첫 시전도"
L["With a fishing pole in your main hand, standing still, right-clicking in the world casts Fishing, so you don't have to start the first cast yourself. Not while your mouse is on a player, NPC or object (mailbox, corpse...): right-click works on them as usual. Swap the pole out to have right-click back everywhere."] = "주 장비에 낚싯대를 들고 가만히 서 있으면, 세상을 오른쪽 클릭해 낚시를 시전하므로 첫 시전을 직접 할 필요가 없습니다. 마우스가 플레이어, NPC, 물체(우편함, 시체...) 위에 있을 때는 제외하며, 평소처럼 오른쪽 클릭이 작동합니다. 낚싯대를 빼면 어디서나 오른쪽 클릭이 원래대로 돌아옵니다."
L["Wait after a cast ends"] = "시전이 끝난 뒤 대기"
L["How long after a cast ends (a catch looted, or the bobber gone) before right-click casts again, so the click that loots the fish doesn't cast straight away."] = "시전이 끝난 뒤(물고기를 획득했거나 찌가 사라짐) 오른쪽 클릭으로 다시 시전하기까지의 시간입니다. 물고기를 획득하는 클릭이 바로 시전되지 않도록 합니다."
L["Pause after a missed cast"] = "빗나간 시전 뒤 멈춤"
L["When a cast doesn't land in fishable water (say, a pole left equipped away from water), right-click goes back to normal for this long before it casts again. Moving and then standing still for 1 sec ends it early: you're likely at a new spot to fish from. Off doesn't pause. (\"Skill not high enough\" always pauses it for 30 sec, moving or not.)"] = "시전이 낚시할 수 있는 물에 떨어지지 않으면(물에서 떨어진 곳에서 낚싯대를 든 채로 있을 때 등), 이 시간 동안 오른쪽 클릭이 원래대로 돌아갔다가 다시 시전합니다. 움직였다가 1초간 가만히 서 있으면 일찍 끝납니다. 새 낚시 자리에 왔을 가능성이 높으니까요. 끄면 멈추지 않습니다. ('숙련도가 부족합니다'는 움직이든 아니든 항상 30초 동안 멈춥니다.)"
L["Gamepad: a button casts too"] = "게임패드: 버튼으로도 시전"
L["In gamepad mode, the button below casts Fishing whenever right-click would: in the fish camera with no bobber out, and (if ticked above) with a pole equipped, standing still. The rest of the time it does what it usually does. Each cast still comes from your own press."] = "게임패드 모드에서는 오른쪽 클릭으로 시전할 때마다 아래 버튼으로도 낚시를 시전합니다: 낚시 카메라 중 찌가 없을 때, 그리고 (위에서 체크했다면) 낚싯대를 들고 가만히 서 있을 때. 그 밖에는 평소 기능을 합니다. 시전은 언제나 내가 누를 때만 일어납니다."
L["Left face button (Xbox X)"] = "왼쪽 버튼 (Xbox X)"
L["Top face button (Xbox Y)"] = "위쪽 버튼 (Xbox Y)"
L["Bottom face button (Xbox A)"] = "아래쪽 버튼 (Xbox A)"
L["Right face button (Xbox B)"] = "오른쪽 버튼 (Xbox B)"
L["The gamepad button that casts Fishing."] = "낚시를 시전할 게임패드 버튼입니다."
L["Gamepad"] = "게임패드"
L["The frames gamepad mode adds (Options, Controls, Gamepad): its action bars, the button hints and the reticle (the dot you aim with). As on the Game Frames page, each is hidden in CineMode unless ticked: Always shows it the whole time, the next three only while you fight or have something targeted, and the places while you're there. Rows also on the Game Frames page (the experience bars) follow this page in gamepad mode, and that one otherwise."] = "게임패드 모드가 추가하는 창(옵션, 조작, 게임패드): 행동 단축바, 버튼 안내, 조준점(겨냥하는 점). 게임 창 페이지처럼 체크하지 않으면 CineMode에서 숨겨집니다: '항상'은 내내, 다음 세 열은 전투 중이거나 대상을 지정했을 때만, 장소 열은 그곳에 있는 동안. 게임 창 페이지에도 있는 줄(경험치 바)은 게임패드 모드에서는 이 페이지를, 그 밖에는 게임 창 페이지를 따릅니다."
L["On: CineMode fades the gamepad's bars, button hints and reticle as this page says. Off: it leaves them alone."] = "켜면: 이 페이지 설정대로 CineMode가 게임패드의 바, 버튼 안내, 조준점을 흐리게 합니다. 끄면: 손대지 않습니다."
L["Show the interact prompt (X)"] = "상호작용 안내 표시 (X)"
L["The button prompt over things you can use or talk to (your bobber, an NPC) stays up in CineMode while the nameplates fade, so you can see what the gamepad can reach: a bobber showing it can be caught. Unticked, it fades with them."] = "사용하거나 대화할 수 있는 것(찌, NPC) 위의 버튼 안내는 이름표가 흐려지는 CineMode에서도 남아 있어서 게임패드로 무엇에 닿을 수 있는지 보입니다: 안내가 뜬 찌는 낚아 올릴 수 있습니다. 해제하면 이름표와 함께 흐려집니다."
L["Show the action bars when you press a button"] = "버튼을 누르면 행동 단축바 표시"
L["Gamepad mode's mouseover: pressing any gamepad button brings the action bars up, and they fade out again your \"stays after mouseover\" time later (Hover groups page). Each press starts that time again. Choose the buttons in the list below. Presses that make you jump don't count (whichever button jumps), nor presses while you fish (the fish camera on, a cast going, or looting)."] = "게임패드 모드의 마우스오버: 게임패드 버튼을 누르면 행동 단축바가 나타나고, '마우스오버 후 유지' 시간(마우스오버 그룹 페이지) 뒤에 다시 사라집니다. 누를 때마다 시간이 다시 시작됩니다. 버튼은 아래 목록에서 고르세요. 점프하는 버튼 입력(어느 버튼이든)과 낚시 중(낚시 카메라, 시전 중, 전리품 획득 중)의 입력은 치지 않습니다."
L["Buttons that show them"] = "표시할 버튼"
L["Click to show or hide the list of buttons: untick one and pressing it doesn't bring the action bars up."] = "클릭해서 버튼 목록을 보이거나 숨깁니다. 체크를 해제한 버튼은 눌러도 행동 단축바를 띄우지 않습니다."
L["Action bar fading"] = "행동 단축바 흐리기"
L["Stay after a press"] = "누른 뒤 유지"
L["How long the action bars stay after your last button press, counting their fade out."] = "마지막 버튼 입력 뒤에 행동 단축바가 남아 있는 시간으로, 사라지는 시간을 포함합니다."
L["How long the gamepad action bars take to fade in: for button presses, fights and targets alike. The rest of the UI uses the fade times on the CineMode page."] = "게임패드 행동 단축바가 나타나는 데 걸리는 시간입니다: 버튼 입력, 전투, 대상 모두 같습니다. 나머지 UI는 CineMode 페이지의 흐리기 시간을 씁니다."
L["How long the gamepad action bars take to fade out."] = "게임패드 행동 단축바가 사라지는 데 걸리는 시간입니다."
L["Nameplates"] = "이름표"
L["Friendly nameplates"] = "아군 이름표"
L["Enemy nameplates"] = "적 이름표"
L["Which nameplates and names stay up in CineMode: in groups, in fights and in each kind of place."] = "CineMode에서 어떤 이름표와 이름을 남길지 정합니다: 파티 중, 전투 중, 장소별로."
L["On: CineMode fades nameplates and names as this page says. Off: it leaves them alone, and the game's own options decide, in CineMode and out."] = "켜면: 이 페이지 설정대로 CineMode가 이름표와 이름을 흐리게 합니다. 끄면: 손대지 않으며, CineMode든 아니든 게임 옵션을 따릅니다."
L["Show in fights, and for the Calm Timer after."] = "전투 중, 그리고 전투 후 진정 타이머 동안 표시합니다."
L["Show in fights while you're PvP flagged, and for the Calm Timer after."] = "PvP 활성화 상태의 전투 중, 그리고 전투 후 진정 타이머 동안 표시합니다."
L["Always show while you're in a party or raid."] = "파티나 공격대에 있는 동안 항상 표시합니다."
L["Blizzard's Always Show Nameplates is off, so nameplates only show in combat."] = "블리자드의 '이름표 항상 표시'가 꺼져 있어 이름표는 전투 중에만 보입니다."
L["Target Nameplate"] = "대상 이름표"
L["Enemy Player"] = "적 플레이어"
L["Enemy NPC"] = "적 NPC"
L["Neutral Player"] = "중립 플레이어"
L["Neutral NPC"] = "중립 NPC"
L["Friendly Player"] = "우호 플레이어"
L["Friendly NPC"] = "우호 NPC"
L["Your pet"] = "내 소환수"
L["Group members"] = "파티원"
L[" Your target's nameplate while it's a player you can attack, whatever the Nameplates grid says."] = " 대상이 공격할 수 있는 플레이어일 때, 이름표 표 설정과 관계없이 대상의 이름표."
L[" Your target's nameplate while it's a hostile NPC, whatever the Nameplates grid says."] = " 대상이 적대적 NPC일 때, 이름표 표 설정과 관계없이 대상의 이름표."
L[" Your target's nameplate while it's the other faction's player but you can't attack them, whatever the Nameplates grid says."] = " 대상이 공격할 수 없는 상대 진영 플레이어일 때, 이름표 표 설정과 관계없이 대상의 이름표."
L[" Your target's nameplate while it's a neutral NPC, whatever the Nameplates grid says."] = " 대상이 중립 NPC일 때, 이름표 표 설정과 관계없이 대상의 이름표."
L[" Your target's nameplate while it's a friendly or dead player, whatever the Nameplates grid says."] = " 대상이 우호적이거나 죽은 플레이어일 때, 이름표 표 설정과 관계없이 대상의 이름표."
L[" Your target's nameplate while it's a friendly or dead NPC, whatever the Nameplates grid says."] = " 대상이 우호적이거나 죽은 NPC일 때, 이름표 표 설정과 관계없이 대상의 이름표."
L[" Your pet's nameplate, whatever the Minions rows say, grouped or not."] = " 내 소환수의 이름표, 하수인 줄과 상관없이, 파티 여부와 상관없이."
L[" Your party or raid members' nameplates, whatever Friendly players says. Not in dungeons and raids: there, Friendly plates in dungeons and raids decides."] = " 파티나 공격대원의 이름표로, 아군 플레이어 설정과 관계없이 적용됩니다. 던전과 공격대에서는 제외: 그곳에서는 던전 및 공격대의 아군 이름표가 결정합니다."
L["Friendly plates in dungeons and raids"] = "던전 및 공격대의 아군 이름표"
L["In dungeons and raids the game won't let addons fade friendly nameplates, so each kind below is either all on or all off there, in CineMode. The grids' friendly rows (your target's included) have no Instances box: these take its place.\n\nWith a friendly target: on while you have one of that kind targeted, out of fights. Every plate of that kind shows then, not just your target's.\n\nThe game won't switch nameplates on or off during a fight: they stay as the fight found them.\n\nFriendly players' setting covers their pets too, so with pets shown, friendly players' plates show as well."] = "던전과 공격대에서는 게임이 애드온의 아군 이름표 흐리기를 허용하지 않으므로, CineMode에서 아래 각 종류는 그곳에서 모두 켜지거나 모두 꺼집니다. 표의 아군 행(대상 행 포함)에는 인스턴스 칸이 없으며, 이 설정이 그 역할을 합니다.\n\n아군 대상이 있을 때: 전투 밖에서 그 종류의 대상을 잡고 있는 동안 켜집니다. 그때는 대상뿐 아니라 그 종류의 모든 이름표가 표시됩니다.\n\n게임은 전투 중에 이름표를 켜거나 끄지 않습니다: 전투가 시작될 때의 상태로 유지됩니다.\n\n아군 플레이어 설정은 그들의 소환수도 포함하므로, 소환수를 표시하면 아군 플레이어의 이름표도 표시됩니다."
L["Pets and minions"] = "소환수 및 하수인"
L["Hidden"] = "숨김"
L["Shown"] = "표시"
L["With a friendly target"] = "아군 대상이 있을 때"
L[" Your party or raid members' pets, whatever the Minions rows say."] = " 파티나 공격대원의 소환수, 하수인 줄과 상관없이."
L["Show while PvP flagged, outside battlegrounds and arenas."] = "전장과 투기장 밖에서 PvP 활성화 상태일 때 표시합니다."
L["Show in battlegrounds and arenas."] = "전장과 투기장에서 표시합니다."
L["Show everywhere else, cities and inns included."] = "그 밖의 모든 곳(도시와 여관 포함)에서 표시합니다."
L["Show everywhere, in fights and out. The rest of the row keeps its ticks for when you untick this."] = "전투 중이든 아니든 어디서나 표시합니다. 이 항목을 해제할 때를 위해 줄의 나머지 체크는 그대로 유지됩니다."
L["Show in dungeons, scenarios and raids."] = "던전, 시나리오, 공격대에서 표시합니다."
L["In PvP combat"] = "PvP 전투 중"
L["Hostile NPCs"] = "적대적 NPC"
L["Neutral NPCs"] = "중립 NPC"
L["Minor"] = "하급"
L["Friendly NPCs"] = "우호적 NPC"
L[" Also turns these nameplates on in the game's options."] = " 게임 옵션에서 이 이름표도 켭니다."
L[" Ticking any box turns these names on in the game's options. Ticking none turns them off."] = " 아무 칸이나 체크하면 게임 옵션에서 이 이름을 켭니다. 하나도 체크하지 않으면 끕니다."
L[" Beyond nameplate range (the game's nameplateMaxDistance setting: 60 yards on retail) the game draws raid markers over units itself, as it does over your own head, and addons can't hide them."] = " 이름표 거리(게임의 nameplateMaxDistance 설정: 리테일에서 60미터) 밖에서는 게임이 직접 유닛 위에 공격대 징표를 그리며, 내 머리 위와 마찬가지로 애드온이 숨길 수 없습니다."
L[" Ticked, raid markers (skull, moon...) stay over their units in CineMode as the rest of their nameplates fades, or shows just their names, so your group can still see what's marked. Unticked, they fade with the plates (the Plate parts row decides them on the plates that are up)."] = " 체크하면 CineMode에서 이름표의 나머지가 사라지거나 이름만 보일 때도 공격대 징표(해골, 달...)가 유닛 위에 남아 파티가 무엇이 징표로 표시됐는지 볼 수 있습니다. 체크 해제하면 이름표와 함께 사라집니다(보이는 이름표에서는 이름표 부분의 줄이 정합니다)."
L[" In CineMode, away from dungeons and raids, the name shows on the unit's nameplate instead, with the rest of the plate hidden."] = " CineMode에서 던전과 공격대 밖에서는 이름이 대신 유닛의 이름표에 표시되고, 이름표의 나머지는 숨겨집니다."
L[" The game only allows this to be set as the fight starts."] = " 게임은 전투가 시작될 때만 이 설정을 바꿀 수 있게 합니다."
L["The chat window fades with the rest of the UI in CineMode. Mousing over it or typing always shows it."] = "CineMode에서는 대화창이 나머지 UI와 함께 흐려집니다. 마우스를 올리거나 입력하면 항상 보입니다."
L["On: CineMode fades the chat windows and tabs as this page says. Off: it leaves them alone."] = "켜면: 이 페이지 설정대로 CineMode가 대화창과 탭을 흐리게 합니다. 끄면: 손대지 않습니다."
L["Chat window"] = "대화창"
L["Show chat when a message arrives"] = "메시지가 오면 대화창 표시"
L["While the UI is faded, a new message briefly shows just the chat window it arrived in, with its tabs. Choose which messages below."] = "UI가 흐려진 동안 새 메시지가 오면, 그 메시지가 온 대화창만 탭과 함께 잠깐 보여 줍니다. 어떤 메시지일지는 아래에서 고르세요."
L["Show chat for"] = "대화창 표시 시간"
L["How long chat stays up after a message arrives or after you finish typing."] = "메시지가 오거나 입력을 마친 뒤 대화창이 남아 있는 시간입니다."
L["Keep chat up until whispers are read"] = "귓속말을 읽을 때까지 대화창 유지"
L["When a whisper arrives in its own tab, the whole chat window stays up in CineMode while that tab flashes, until you click it. Whispers that land in the tab you're looking at don't flash, so they just show as above."] = "귓속말이 별도 탭에 오면, 그 탭이 깜박이는 동안 클릭할 때까지 CineMode에서도 대화창 전체가 남아 있습니다. 보고 있는 탭에 온 귓속말은 깜박이지 않으므로 위와 같이 보이기만 합니다."
L["Hide your messages"] = "내 메시지 숨기기"
L["Your own messages don't show chat: your emotes (a /bow, or sitting or kneeling at the campfire), and what you say in /say, party, guild and so on. Other people's still do."] = "내 메시지로는 대화창이 나타나지 않습니다: 내 감정 표현(/bow, 모닥불에서 앉기나 무릎 꿇기)과 /say, 파티, 길드 등에서 한 말. 다른 사람의 메시지는 그대로 나타납니다."
L["Hide speech you can see as a bubble"] = "말풍선으로 보이는 대화 숨기기"
L["Says and yells (people's and NPCs') don't show chat when their chat bubble shows on your screen: you can read it there. Ones from out of view, or where bubbles are off, still do."] = "말하기와 외치기(플레이어와 NPC)는 말풍선이 화면에 보이면 대화창을 나타내지 않습니다: 거기서 읽을 수 있습니다. 화면 밖에서 온 것이나 말풍선이 꺼진 곳에서는 그대로 나타납니다."
L["%s is under attack!"] = "%s 공격받고 있습니다!"
L["Show chat for these messages"] = "다음 메시지에 대화창 표시"
L["Game messages"] = "게임 메시지"
L["Capital cities. "] = "수도."
L["Show chat for these channels"] = "다음 채널에 대화창 표시"
L["Channels you've joined, like General or Trade. The list updates each time you open this page."] = "가입한 채널(공개, 거래 등)입니다. 이 페이지를 열 때마다 목록이 갱신됩니다."
L["No channels joined."] = "가입한 채널이 없습니다."
L["Takes this frame off the list. A frame you added stops fading; one you kept up fades again if it's one the addon fades by itself."] = "이 창을 목록에서 뺍니다. 직접 추가한 창은 흐려지지 않게 되고, 계속 표시하게 한 창은 애드온이 원래 흐리게 하는 창이라면 다시 흐려집니다."
L["Show this frame the whole time in CineMode (Cinematic leaves it alone). Unticked, it's hidden, except as the other columns say."] = "CineMode 내내 이 창을 표시합니다(Cinematic이 손대지 않음). 해제하면 다른 열 설정에 따를 때 말고는 숨겨집니다."
L["picked"] = "선택함"
L["When the minimap (and on retail the quest waypoint) stays up in CineMode. Hovering the minimap always shows it. To keep it up all the time, or in fights, see the Game Frames page."] = "CineMode에서 미니맵(리테일에서는 퀘스트 목적지도)이 언제 남아 있을지 정합니다. 미니맵에 마우스를 올리면 항상 보입니다. 항상 또는 전투 중에 띄워 두려면 게임 창 페이지를 보세요."
L["On: CineMode fades and shrinks the minimap as this page and its Game Frames row say. Off: it leaves it alone."] = "켜면: 이 페이지와 게임 창 페이지의 해당 줄에 따라 CineMode가 미니맵을 흐리게 하고 줄입니다. 끄면: 손대지 않습니다."
L["Always show the quest waypoint"] = "퀘스트 목적지 항상 표시"
L["Keeps the marker showing where your tracked quest or map pin is, with its distance, visible in CineMode. Off, it fades with the rest of the UI."] = "추적 중인 퀘스트나 지도 핀의 위치를 거리와 함께 알려 주는 표시를 CineMode에서도 보이게 둡니다. 끄면 나머지 UI와 함께 흐려집니다."
L["Keep minimap open while tracking"] = "추적 중에는 미니맵 유지"
L["While you're tracking one of the kinds ticked below, the minimap stays up during CineMode. Also on the minimap button's menu."] = "아래에 체크한 종류를 추적하는 동안 CineMode에서도 미니맵이 남아 있습니다. 미니맵 버튼 메뉴에도 있습니다."
L["Reveal when a group member pings it"] = "파티원이 핑을 찍으면 표시"
L["You or someone in your party or raid pinging the minimap shows it as if you'd hovered it, so you can see where, with the rest of the Hover groups that have Minimap ping ticked, for as long as the slider under it says. Ore, herbs and treasure pinged by Ping where it is don't count."] = "내가 또는 파티원이나 공격대원이 미니맵에 핑을 찍으면, 마우스를 올린 것처럼 미니맵(과 '미니맵 핑'에 체크한 다른 마우스오버 그룹)을 보여 주어 위치를 확인할 수 있습니다: 아래 슬라이더의 시간 동안 표시됩니다. '위치에 핑'이 찍는 광석, 약초, 보물 핑은 치지 않습니다."
L["Show for"] = "표시 시간"
L["How long the minimap stays up after someone pings it, before it fades."] = "누군가 미니맵에 핑을 찍은 뒤 미니맵이 사라지기 전까지 표시되는 시간입니다."
L["Keep minimap open indoors"] = "실내에서는 미니맵 유지"
L["Inside buildings, caves and cities like Ironforge, the minimap stays up during CineMode. The game stops updating the indoor map while the minimap is hidden, so after walking around it can come back blank or out of date for a moment. Off, it's redrawn as it comes back."] = "건물, 동굴, 아이언포지 같은 도시 안에서는 CineMode에서도 미니맵이 남아 있습니다. 게임은 미니맵이 숨겨진 동안 실내 지도를 갱신하지 않으므로, 돌아다닌 뒤에는 잠깐 비어 있거나 옛 모습으로 돌아올 수 있습니다. 끄면 돌아올 때 다시 그립니다."
L["While this tracking is active, the minimap stays up during cinematic mode so you can spot nodes or creatures."] = "이 추적이 켜져 있는 동안 시네마틱 모드에서도 미니맵이 남아 있어 채집물이나 생물을 찾을 수 있습니다."
L["Herbs (Find Herbs)"] = "약초 (약초 찾기)"
L["Minerals (Find Minerals)"] = "광물 (광물 찾기)"
L["Reveal"] = "표시"
L["Pings"] = "핑"
L["Keep open"] = "계속 열기"
L["Nearby ore, herbs and treasure"] = "근처의 광석, 약초, 보물"
L["Ping where it is"] = "위치에 핑"
L["When a vein, herb or chest shows up on the minimap, it's pinged there, the same ping as clicking the minimap: in a group, everyone sees it."] = "광맥, 약초 또는 상자가 미니맵에 나타나면 미니맵을 클릭한 것과 같은 핑을 그 위치에 찍습니다: 파티에서는 모두가 봅니다."
L["Quest turn-ins"] = "퀘스트 완료 보고"
L["Other icons"] = "기타 아이콘"
L["Tracking creatures or fish"] = "생물 또는 물고기 추적"
L["Tracking herbs, minerals or treasure"] = "약초, 광물 또는 보물 추적"
L["Cinematic looks every second or two by pointing at the minimap the way your mouse would (not in combat), and the minimap fades again a few seconds after it's gone. While any of these is ticked, the faded minimap stays in its place, invisible, instead of being shrunk away."] = "Cinematic은 마우스처럼 미니맵을 가리켜 1~2초마다 확인하며(전투 중 제외), 사라진 뒤 몇 초 후 미니맵이 다시 흐려집니다. 이 중 하나라도 체크되어 있으면 흐려진 미니맵은 축소되지 않고 보이지 않는 채로 제자리에 있습니다."
L["With Find Minerals, Find Herbs or Find Treasure on, the minimap comes up while a vein, herb or chest shows on it."] = "광물 찾기, 약초 찾기 또는 보물 찾기가 켜져 있으면 광맥, 약초 또는 상자가 미니맵에 보이는 동안 미니맵이 나타납니다."
L["The minimap comes up while a quest of yours that's done shows on it, where you hand it in."] = "완료한 퀘스트의 보고 위치가 미니맵에 보이는 동안 미니맵이 나타납니다."
L["Quest areas"] = "퀘스트 지역"
L["The minimap comes up while the area of a quest of yours that isn't done shows on it, the shaded part where its objectives are."] = "완료하지 않은 내 퀘스트의 지역(목표가 있는 음영 부분)이 미니맵에 보이는 동안 미니맵이 나타납니다."
L["The minimap comes up while anything else with a name shows on it: quest givers with a quest for you, flight masters and innkeepers you track and the like. Your group and pets don't count."] = "이름이 있는 다른 것이 미니맵에 보이는 동안 미니맵이 나타납니다: 나에게 줄 퀘스트가 있는 NPC, 추적 중인 비행 조련사와 여관주인 등. 파티와 소환수는 포함되지 않습니다."
L["While hunter, druid or warlock creature tracking, or Find Fish, is on, the minimap stays up during CineMode."] = "사냥꾼, 드루이드, 흑마법사의 생물 추적이나 물고기 찾기가 켜져 있는 동안 CineMode에서 미니맵이 계속 표시됩니다."
L["While Find Herbs, Find Minerals or Find Treasure is on, the minimap stays up during CineMode, except in the places below."] = "약초 찾기, 광물 찾기 또는 보물 찾기가 켜져 있는 동안 아래 장소를 제외하고 CineMode에서 미니맵이 계속 표시됩니다."
L["Treasure (Find Treasure)"] = "보물 (보물 찾기)"
L["Fish (Find Fish)"] = "물고기 (물고기 찾기)"
L["Creatures (hunter, druid, warlock)"] = "생물 (사냥꾼, 드루이드, 흑마법사)"
L["Except in"] = "제외할 곳"
L["Battlegrounds and arenas (being flagged for PvP out in the world doesn't count). Alterac Valley's mines do have ore, so untick this if you mine there. "] = "전장과 투기장(필드에서 PvP가 활성화된 것은 치지 않음). 알터랙 계곡의 광산에는 광석이 있으니 그곳에서 채광한다면 해제하세요."
L["BGs"] = "전장"
L["Tracking doesn't keep the minimap up here. Hovering it still shows it."] = "이곳에서는 추적해도 미니맵이 남아 있지 않습니다. 마우스를 올리면 여전히 보입니다."
L["Hide in camera modes"] = "카메라 모드에서 숨기기"
L["When the quest tracker comes up in CineMode. Hovering it always shows it. To keep it up all the time, or in fights, see the Game Frames page."] = "CineMode에서 퀘스트 추적기가 언제 나타날지 정합니다. 마우스를 올리면 항상 보입니다. 항상 또는 전투 중에 띄워 두려면 게임 창 페이지를 보세요."
L["Reveal on new quest"] = "새 퀘스트를 받으면 표시"
L["Accepting a quest shows the quest tracker as if you'd hovered it (with the rest of the Hover groups that have Quest progress ticked): it goes after \"Stays after mouseover\" (Hover groups page)."] = "퀘스트를 수락하면 마우스를 올린 것처럼 퀘스트 추적기(와 '퀘스트 진행'에 체크한 다른 마우스오버 그룹)를 보여 줍니다: '마우스오버 후 유지'(마우스오버 그룹 페이지) 시간 뒤에 사라집니다."
L["On: CineMode fades the quest tracker (and the quest timer and waypoint) as this page and its Game Frames row say. Off: it leaves them alone."] = "켜면: 이 페이지와 게임 창 페이지의 해당 줄에 따라 CineMode가 퀘스트 추적기(와 퀘스트 타이머, 목적지)를 흐리게 합니다. 끄면: 손대지 않습니다."
L["Reveal on receiving quest objective"] = "퀘스트 목표를 달성하면 표시"
L["Keep up for the Calm Timer"] = "진정 타이머 동안 유지"
L["The quest tracker stays up for the Calm Timer (CineMode page) instead of the mouseover time, if that's longer."] = "퀘스트 추적기가 마우스오버 시간 대신 진정 타이머(CineMode 페이지) 동안 떠 있습니다. 진정 타이머가 더 길 때만 적용됩니다."
L["Progress on a quest's objectives (a kill or item counted towards it) shows the quest tracker the same way."] = "퀘스트 목표가 진행되면(처치나 아이템이 집계되면) 같은 방식으로 퀘스트 추적기를 보여 줍니다."
L["Show just that quest"] = "해당 퀘스트만 표시"
L["When accepting a quest or progress on one brings the quest tracker up, just that quest shows (and any others accepted or moved on while it's up); the rest of the tracker, headers and all, stays faded. Scenario progress shows just the scenario. Hovering it shows it all."] = "퀘스트를 수락하거나 진행해서 퀘스트 추적기가 나타나면 그 퀘스트만 보입니다(표시 중에 수락하거나 진행한 다른 퀘스트도 포함). 제목을 포함한 나머지 추적기는 숨겨진 채로 남습니다. 시나리오가 진행되면 시나리오만 보입니다. 마우스를 올리면 모두 보입니다."
L["Stay up for the Calm Timer after a fight"] = "전투 후 진정 타이머 동안 유지"
L["With the quest tracker ticked In combat (Game Frames page), it stays up after a fight until the Calm Timer (CineMode page) has run out, then fades. Off: it fades as soon as the fight ends."] = "퀘스트 추적기의 '전투 중'에 체크했다면(게임 창 페이지), 전투 후 진정 타이머(CineMode 페이지)가 끝날 때까지 남아 있다가 흐려집니다. 끄면: 전투가 끝나자마자 흐려집니다."
L["Show the quest timer while one is running"] = "퀘스트 타이머가 돌아가는 동안 표시"
L["Keeps the quest timer box up in CineMode, and in fights, while a timed quest counts down. Just the timer: the quest tracker stays faded."] = "제한 시간 퀘스트가 시간을 세는 동안 CineMode와 전투 중에도 퀘스트 타이머 상자를 띄워 둡니다. 타이머만 보이고 퀘스트 추적기는 흐려진 채로 있습니다."
L["Which of the game's swing timer bars show, in CineMode and out. When they come up in CineMode is the Swing timer row on the Game Frames page."] = "CineMode 안팎에서 게임의 평타 타이머 바 중 어떤 것을 보일지 정합니다. CineMode에서 언제 나타날지는 게임 창 페이지의 평타 타이머 줄에서 정합니다."
L["On: CineMode fades the swing timer as this page and its Game Frames row say. Off: it leaves it alone, and the game shows every bar as usual, in CineMode and out."] = "켜면: 이 페이지와 게임 창 페이지의 해당 줄에 따라 CineMode가 평타 타이머를 흐리게 합니다. 끄면: 손대지 않으며, CineMode든 아니든 게임이 평소처럼 모든 바를 보여 줍니다."
L["Only show the weapons you're using"] = "사용 중인 무기만 표시"
L["The main hand (and off-hand) bars show while you auto-attack, the ranged bar while you shoot. A hunter's main hand bar comes up when they melee, a warrior's ranged bar when they shoot, and each fades out a while after (the slider below)."] = "자동 공격 중에는 주 장비(와 보조장비) 바가, 사격 중에는 원거리 바가 보입니다. 사냥꾼은 근접 공격할 때 주 장비 바가, 전사는 사격할 때 원거리 바가 나타나며, 각각 잠시 뒤에(아래 슬라이더) 사라집니다."
L["Fade out after the bar is done for"] = "바가 끝난 뒤 사라지기까지"
L["Once you stop swinging or shooting and the bar has run down to 0, it stays this long before fading out."] = "휘두르기나 사격을 멈추고 바가 0까지 내려가면, 이 시간 동안 남아 있다가 사라집니다."
L["Hide the off-hand bar"] = "보조장비 바 숨기기"
L["Never show the off-hand swing timer, dual wielding or not."] = "쌍수 무기를 들든 아니든 보조장비 평타 타이머를 표시하지 않습니다."
L["Ranged bar on top for %s"] = "원거리 바를 위로 (%s)"
L["The main hand and ranged bars trade places, so the ranged bar is where the main hand's was. Set for each class on its own (ticked for hunters, mages, priests and warlocks to start with), so one profile suits all your characters."] = "주 장비 바와 원거리 바의 자리를 바꿔서 원거리 바가 주 장비 바 자리에 옵니다. 직업마다 따로 설정되므로(처음에는 사냥꾼, 마법사, 사제, 흑마법사에 체크됨) 한 프로필로 모든 캐릭터에 맞출 수 있습니다."
L["When the Cooldown Manager comes up in CineMode (Enhanced Cooldown Manager's bars too). Hovering it always shows it. To keep it up all the time, or in fights, see the Game Frames page; what comes up with it is on the Hover groups page."] = "CineMode에서 재사용 대기시간 관리자(Enhanced Cooldown Manager의 바 포함)가 언제 나타날지 정합니다. 마우스를 올리면 항상 보입니다. 항상 또는 전투 중에 띄워 두려면 게임 창 페이지를, 함께 나타나는 것은 마우스오버 그룹 페이지를 보세요."
L["On: CineMode fades the Cooldown Manager as this page and its Game Frames row say. Off: it leaves it alone, and the game's own options decide, in CineMode and out."] = "켜면: 이 페이지와 게임 창 페이지의 해당 줄에 따라 CineMode가 재사용 대기시간 관리자를 흐리게 합니다. 끄면: 손대지 않으며, CineMode든 아니든 게임 옵션을 따릅니다."
L["Stay up while a cooldown is recharging"] = "재사용 대기시간이 충전되는 동안 유지"
L["Keeps the Cooldown Manager up until every cooldown in it is ready again, then it fades. Not the global cooldown, nor its buff bars. (It brings up the Hover groups with Cooldown recharging ticked: the Cooldowns group by default.)"] = "안의 모든 재사용 대기시간이 다시 준비될 때까지 재사용 대기시간 관리자를 띄워 두었다가 흐리게 합니다. 전역 재사용 대기시간과 강화 효과 바는 제외합니다. ('재사용 대기시간 충전 중'에 체크한 마우스오버 그룹을 함께 띄웁니다. 기본값은 재사용 대기시간 그룹입니다.)"
L["Only within the Calm Timer after a fight (CineMode page): after that it fades even with a long cooldown still going, and cooldowns used out of fights don't bring it up."] = "전투 후 진정 타이머(CineMode 페이지) 안에서만: 그 뒤에는 긴 재사용 대기시간이 남아 있어도 흐려지고, 비전투 중에 쓴 재사용 대기시간으로는 뜨지 않습니다."
L["Only when ready in combat"] = "전투 중 준비됐을 때만"
L["Tick a spell to show its icon only in fights, and only once it's nearly ready: out of fights, and while it recharges, it fades out, in CineMode or not. It comes back once it's ready, or with Show early ticked the seconds set beside it before (left empty: %d%% of its cooldown). Its place in the bar stays, so it sits best at the end of one. In fights the game may not say how long is left, so then it goes by when you last cast it."] = "주문에 체크하면 그 아이콘은 전투 중에만, 그리고 거의 준비됐을 때만 보입니다: 비전투 중이거나 충전 중에는 CineMode든 아니든 흐려집니다. 준비되면, 또는 '미리 표시'에 체크했다면 옆에 정한 초만큼 일찍(비워 두면 재사용 대기시간의 %d%%) 돌아옵니다. 바 안의 자리는 그대로 남으므로 바 끝에 두는 것이 가장 좋습니다. 전투 중에는 게임이 남은 시간을 알려 주지 않을 수 있어서, 그때는 마지막으로 시전한 때를 기준으로 합니다."
L["Spell"] = "주문"
L["Show early"] = "미리 표시"
L["No spells in the Cooldown Manager's spell bars right now."] = "지금은 재사용 대기시간 관리자의 주문 바에 주문이 없습니다."
L["Out of fights, and while it recharges, this spell's icon fades out of the Cooldown Manager."] = "비전투 중이거나 충전 중에는 이 주문의 아이콘이 재사용 대기시간 관리자에서 흐려집니다."
L["Bring the icon back a little before it's ready, by the seconds beside it. Unticked, it comes back once it's ready."] = "준비되기 조금 전, 옆에 적은 초만큼 일찍 아이콘을 다시 보여 줍니다. 해제하면 준비됐을 때 돌아옵니다."
L["How many seconds before it's ready the icon comes back. Leave it empty for %d%% of its cooldown."] = "준비되기 몇 초 전에 아이콘이 돌아올지 정합니다. 비워 두면 재사용 대기시간의 %d%%입니다."
L["sec (empty: %d)"] = "초 (비우면: %d)"
L["sec (empty: %d%%)"] = "초 (비우면: %d%%)"
L["Spell %d"] = "주문 %d"
L[" |cff808080(not in it now)|r"] = " |cff808080(지금은 없음)|r"
L["On: CineMode hides tooltips as this page says. Off: every tooltip shows as normal."] = "켜면: 이 페이지 설정대로 CineMode가 툴팁을 숨깁니다. 끄면: 모든 툴팁이 평소처럼 보입니다."
L["Only in CineMode. Hold your Show hidden tooltips key (set it on the Keybinds page) to see a hidden one anyway."] = "CineMode에서만. 숨긴 툴팁 보기 키(단축키 페이지에서 지정)를 누르고 있으면 숨긴 툴팁도 볼 수 있습니다."
L["Players and NPCs you can attack (neutral mobs too), and their pets, minions and totems."] = "공격할 수 있는 플레이어와 NPC(중립 몹 포함), 그리고 그들의 소환수, 하수인, 토템."
L["Herbs, ore and creatures you can skin."] = "약초, 광석, 무두질할 수 있는 생물."
L["Tooltips listing one of your quest objectives (like \"5/7 Thistle Boar slain\")."] = "퀘스트 목표 중 하나가 표시된 툴팁(예: \"엉겅퀴 멧돼지 5/7 처치\")."
L["Mouse still"] = "마우스 정지"
L["Hide tooltips"] = "툴팁 숨기기"
L["In CineMode. Ticked, those tooltips hide. Always: in and out of fights. In combat: just in fights. Something that's more than one kind (a quest mob is an enemy too) hides only with each of its kinds ticked."] = "CineMode에서. 체크하면 해당 툴팁을 숨깁니다. 항상: 전투 안팎 모두. 전투 중: 전투 때만. 여러 종류에 해당하는 것(퀘스트 몹은 적이기도 함)은 해당 종류를 모두 체크했을 때만 숨깁니다."
L["Hidden all the time."] = "언제나 숨깁니다."
L["Hidden in fights only."] = "전투 때만 숨깁니다."
L["Objects in the world, and the UI's tooltips: action bars, buffs and debuffs, bags, menus and the rest."] = "월드의 오브젝트, UI 툴팁: 행동 단축바, 강화 및 약화 효과, 가방, 메뉴 등."
L["Every tooltip in the world and on unit frames is hidden while this camera mode is running."] = "이 카메라 모드가 도는 동안 월드와 유닛 프레임의 모든 툴팁을 숨깁니다."
L["Tooltip look"] = "툴팁 모양"
L["Ticked, that part of the tooltip shows: On first hover, as soon as it appears; After, once you've hovered as long as set above, until you mouse over something else. In and out of CineMode."] = "체크하면 툴팁의 그 부분이 표시됩니다. 처음 올릴 때: 나타나자마자. 이후: 위에서 정한 시간만큼 마우스를 올려 둔 뒤, 다른 것에 올릴 때까지. CineMode 안팎 모두."
L["Where the game's tooltips (things in the world, unit frames, action bars, bags) show: in their default position (the bottom-right corner, or wherever you've moved it), or by the mouse cursor, following it (or just in fights)."] = "게임 툴팁(월드의 대상, 유닛 프레임, 행동 단축바, 가방)의 위치: 기본 위치(오른쪽 아래 구석, 또는 옮겨 둔 곳), 또는 마우스 커서 옆에서 따라다님 (또는 전투 때만)."
L["Default position"] = "기본 위치"
L["At the mouse cursor in combat"] = "전투 중 마우스 커서 옆"
L["Fade in/out"] = "페이드 인/아웃"
L["How long tooltips take to fade in as they show, and to fade out when the mouse has been still too long (Mouse still, below). Off: no fading."] = "툴팁이 표시될 때 서서히 나타나는 시간, 그리고 마우스가 너무 오래 멈춰 있을 때 서서히 사라지는 시간 (아래의 마우스 정지). 끔: 페이드 없음."
L["After hovering for"] = "마우스를 올린 시간"
L["How long you hover over something before the After column's parts take over, until you mouse over something else. Off: tooltips show as normal, every part of them."] = "이후 열의 부분이 적용되기까지 마우스를 올려 두는 시간이며, 다른 것에 올릴 때까지 유지됩니다. 끔: 툴팁이 모든 부분과 함께 평소처럼 표시됩니다."
L["On first hover"] = "처음 올릴 때"
L["After %d sec"] = "%d초 후"
L["After (off)"] = "이후 (끔)"
L["Shown as soon as the tooltip appears."] = "툴팁이 나타나자마자 표시합니다."
L["Shown once you've hovered as long as set above."] = "위에서 정한 시간만큼 마우스를 올려 둔 뒤 표시합니다."
L["At the mouse cursor"] = "마우스 커서 옆"
L["Health bar"] = "생명력 바"
L["The health bar under the tooltips of players, NPCs and mobs."] = "플레이어, NPC, 몬스터 툴팁 아래의 생명력 바."
L["Works with this page switched off too."] = "이 페이지가 꺼져 있어도 작동합니다."
L["Background and border"] = "배경과 테두리"
L["The box around the tooltip. Unticked, just the text shows."] = "툴팁 둘레의 상자. 체크하지 않으면 글자만 표시됩니다."
L["Guild and title (<...>)"] = "길드와 칭호 (<...>)"
L["A player's <Guild> line, or an NPC's <Innkeeper>-style title."] = "플레이어의 <길드> 줄, 또는 <여관주인> 같은 NPC 칭호."
L["The level line (for players, with their race and class)."] = "레벨 줄 (플레이어는 종족과 직업 포함)."
L["Level"] = "레벨"
L["Spec and class"] = "전문화와 직업"
L["A player's spec and class line (\"Fury Warrior\")."] = "플레이어의 전문화와 직업 줄 (\"분노 전사\")."
L["Creature type"] = "생물 유형"
L["The kind of creature: Elemental, Beast, Humanoid and so on."] = "생물의 종류: 정령, 야수, 인간형 등."
L["Faction and PvP"] = "진영과 PvP"
L["The Horde or Alliance line and the PvP line."] = "호드 또는 얼라이언스 줄과 PvP 줄."
L["Reputation faction"] = "평판 세력"
L["The faction an NPC belongs to, whose reputation you earn (\"Hara'ti\")."] = "NPC가 속한 세력으로, 그 평판을 얻습니다 (\"Hara'ti\")."
L["Threat"] = "위협 수준"
L["How much of the mob's threat you have (\"100% Threat\")."] = "몬스터에 대한 내 위협 수준 (\"위협 수준 100%\")."
L["Quest lines"] = "퀘스트 줄"
L["The names of your quests the unit is for, and their objectives (\"5/7 Thistle Boar slain\")."] = "해당 유닛이 필요한 퀘스트 이름과 목표 (\"엉겅퀴 멧돼지 5/7 처치\")."
L["Quest lines on objects"] = "사물의 퀘스트 줄"
L["The same on things in the world you use or pick up for a quest (\"0/1 Palehill Runestone\")."] = "퀘스트를 위해 사용하거나 줍는 월드의 사물에도 똑같이 적용됩니다 (\"0/1 Palehill 룬석\")."
L["On flights"] = "비행 중"
L["AFK camera (standing still or AFK)"] = "자리 비움 카메라 (가만히 서 있기 또는 자리 비움)"
L["Cozy (campfire, sitting, emotes)"] = "아늑함 (모닥불, 앉기, 감정 표현)"
L["Tele (Hearthstone, teleports)"] = "순간이동 (귀환석, 순간이동)"
L["Vista (/stare)"] = "풍경 (/stare)"
L["Fish (fishing)"] = "낚시 (낚시 중)"
L["RP walking"] = "RP 걷기"
L["Auto-running"] = "자동 달리기"
L["Quest camera (talking to quest givers)"] = "퀘스트 카메라 (퀘스트 NPC와 대화)"
L["Enemies"] = "적"
L["Friendlies"] = "아군"
L["Gatherables (herbs, ore, skinnable)"] = "채집물 (약초, 광석, 무두질 가능)"
L["Quest objectives"] = "퀘스트 목표"
L["Players and NPCs you can't attack, and their pets, minions and totems."] = "공격할 수 없는 플레이어와 NPC, 그리고 그들의 소환수, 하수인, 토템."
L["Everything else"] = "그 밖의 모든 것"
L["Advanced Frames"] = "고급 창"
L["On: CineMode fades the supported addons' frames, and frames you added, as this page says. Off: it leaves them all alone."] = "켜면: 이 페이지 설정대로 CineMode가 지원하는 애드온의 창과 직접 추가한 창을 흐리게 합니다. 끄면: 모두 손대지 않습니다."
L["Supported addons"] = "지원하는 애드온"
L["These addons' frames are hidden in CineMode unless ticked, like the game's frames on the Game Frames page. Tick Always to leave an addon's frames alone (shown the whole time); the next three show them only while you fight or have something targeted, and the places while you're there."] = "이 애드온들의 창은 게임 창 페이지의 게임 창처럼 체크하지 않으면 CineMode에서 숨겨집니다. '항상'에 체크하면 그 애드온의 창에 손대지 않고(내내 표시), 다음 세 열은 전투 중이거나 대상을 지정했을 때만, 장소 열은 그곳에 있는 동안 표시합니다."
L["Show %s the whole time in CineMode (Cinematic leaves them alone). Unticked, they're hidden, except as the other columns say.%s"] = "CineMode 내내 %s 창을 표시합니다(Cinematic이 손대지 않음). 해제하면 다른 열 설정에 따를 때 말고는 숨겨집니다.%s"
L["Click to show or hide its parts."] = "클릭해서 구성 요소를 보이거나 숨깁니다."
L["Loaded"] = "불러옴"
L["Installed, not loaded"] = "설치됨, 불러오지 않음"
L["Not installed"] = "설치되지 않음"
L["Also supported, when installed: %s"] = "설치하면 함께 지원: %s"
L["Custom frames"] = "사용자 지정 창"
L["To fade something else, hover over it and type |cffffd100/cine add|r, or type |cffffd100/cine add|r and its frame name. To pick up several, use the button below (or |cffffd100/cine add mode|r) and hover over each one. The columns work as for the supported addons above; the X takes a frame off the list."] = "다른 것을 흐리게 하려면 그 위에 마우스를 올리고 |cffffd100/cine add|r를 입력하거나, |cffffd100/cine add|r와 창 이름을 입력하세요. 여러 개를 고르려면 아래 버튼(또는 |cffffd100/cine add mode|r)을 쓰고 하나씩 마우스를 올리세요. 열은 위의 지원 애드온과 같이 작동하며, X는 창을 목록에서 뺍니다."
L["Hover over the frames you want to fade (move this window out of the way, or close it), then click Stop or type /cine add mode again to fade them all. The game's own frames and ones already faded are left out. /cine add cancel drops them."] = "흐리게 할 창 위에 마우스를 올리세요(이 창은 옆으로 옮기거나 닫으세요). 그런 다음 '중지'를 클릭하거나 /cine add mode를 다시 입력하면 모두 흐리게 합니다. 게임 기본 창과 이미 흐려지는 창은 제외됩니다. /cine add cancel로 취소합니다."
L["Stop"] = "중지"
L["Pick frames by hovering"] = "마우스를 올려 창 고르기"
L["Hide the UI"] = "UI 숨기기"
L["Like Blizzard's Alt+Z: hides the whole UI, but keeps the tint, letterbox and time-of-day title. Press again (or Blizzard's key) to bring it back."] = "블리자드의 Alt+Z처럼 UI 전체를 숨기지만, 색조, 레터박스, 시간대 제목은 남깁니다. 다시 누르면(또는 블리자드의 키) 돌아옵니다."
L["Take a CineShot"] = "CineShot 찍기"
L["Hides the UI but keeps the tint and letterbox, takes a screenshot, then brings the UI straight back. Not in a fight."] = "UI를 숨기되 색조와 레터박스는 유지한 채 스크린샷을 찍고 UI를 바로 되돌립니다. 전투 중에는 안 됩니다."
L["Turns CineMode on or off, like /cine."] = "/cine처럼 CineMode를 켜거나 끕니다."
L["Starts the AFK camera now, without waiting out its delay. Press again, move or jump to stop it."] = "지연 시간을 기다리지 않고 자리 비움 카메라를 바로 시작합니다. 다시 누르거나, 움직이거나, 점프하면 멈춥니다."
L["Starts the cozy camera now, as if you'd sat down. Press again, move or jump to stop it."] = "앉은 것처럼 아늑한 카메라를 바로 시작합니다. 다시 누르거나, 움직이거나, 점프하면 멈춥니다."
L["Starts the vista camera now, as if you'd done a /stare. Press again, move or jump to stop it."] = "/stare를 한 것처럼 풍경 카메라를 바로 시작합니다. 다시 누르거나, 움직이거나, 점프하면 멈춥니다."
L["Starts the fish camera now, without casting. Press again, move or jump to stop it."] = "시전하지 않고 낚시 카메라를 바로 시작합니다. 다시 누르거나, 움직이거나, 점프하면 멈춥니다."
L["Starts the tele camera now, as if you were casting your Hearthstone. Press again, move or jump to stop it."] = "귀환석을 시전하는 것처럼 순간이동 카메라를 바로 시작합니다. 다시 누르거나, 움직이거나, 점프하면 멈춥니다."
L["Death camera test"] = "죽음 카메라 시험"
L["Camera wheel"] = "카메라 휠"
L["Hold to bring up a wheel of the cameras below, an icon for each: point at one and let go to start it. Tap it instead and the wheel stays up for you to click one. Picking the camera that's running stops it."] = "누르고 있으면 아래 카메라들이 아이콘으로 표시된 휠이 나타납니다: 하나를 가리키고 손을 떼면 시작합니다. 짧게 누르면 휠이 열린 채로 남아 클릭해서 고를 수 있습니다. 실행 중인 카메라를 고르면 멈춥니다."
L["Menu wheel"] = "메뉴 휠"
L["Hold to bring up a wheel of the game's menu buttons (character, spellbook, quest log...), the ones on your menu bar: point at one and let go to open its window, even with the UI hidden. Tap it instead and the wheel stays up for you to click one."] = "누르고 있으면 메뉴 바에 있는 게임 메뉴 버튼(캐릭터, 주문책, 퀘스트 목록 등)의 휠이 나타납니다. 하나를 가리키고 떼면 그 창이 열리며, UI가 숨겨져 있어도 됩니다. 짧게 누르면 휠이 계속 떠 있어 클릭으로 고를 수 있습니다."
-- CameraWheel.lua
L["running: pick it to stop it"] = "실행 중: 다시 고르면 멈춤"
L["can't start now"] = "지금은 시작할 수 없음"
-- MenuWheel.lua
L["open: pick it to close it"] = "열림: 다시 고르면 닫힘"
L["can't open now"] = "지금은 열 수 없음"
L["Pretends you're dead for 30 seconds so the death camera runs. Press again to stop. Like /cine deathtest."] = "30초 동안 죽은 척해서 죽음 카메라를 돌립니다. 다시 누르면 멈춥니다. /cine deathtest와 같습니다."
L["Show hidden tooltips"] = "숨긴 툴팁 보기"
L["Hold to see the tooltips the Tooltips page hides, in combat and in CineMode. Pressing it while you're on a unit or something in the world brings its tooltip up; anything else, hover it again with the key held."] = "누르고 있으면 툴팁 페이지에서 숨긴 툴팁을 전투 중과 CineMode에서도 볼 수 있습니다. 유닛이나 세상의 무언가에 마우스를 둔 채 누르면 그 툴팁이 뜨고, 그 밖의 것은 키를 누른 채 다시 마우스를 올리세요."
L["Turns the Tooltips page's \"CineMode Tooltips\" switch on or off."] = "툴팁 페이지의 'CineMode 툴팁' 스위치를 켜거나 끕니다."
L["Press a key"] = "키를 누르세요"
L["|cff808080Not bound|r"] = "|cff808080지정 안 됨|r"
L["keybinds can't be changed in combat"] = "전투 중에는 단축키를 바꿀 수 없습니다"
L["%s was bound to %s and now isn't"] = "%s 키는 %s에 지정되어 있었지만 이제 해제되었습니다"
L["Click, then press a key (with Shift, Ctrl or Alt if you like). Right-click to clear. Escape cancels."] = "클릭한 다음 키를 누르세요(원하면 Shift, Ctrl, Alt와 함께). 오른쪽 클릭으로 지웁니다. Esc로 취소합니다."
L["Keybinds"] = "단축키"
L["Keys for Cinematic. These are the same bindings as under Key Bindings > AddOns, so setting them in either place works."] = "Cinematic의 키입니다. 단축키 설정 > 애드온에 있는 것과 같은 단축키이므로 어느 쪽에서 설정해도 됩니다."
L["Keys"] = "키"
L["settings can't be opened in combat"] = "전투 중에는 설정을 열 수 없습니다"
L["A profile needs a name."] = "프로필 이름이 필요합니다."
L["There's already a profile called %s."] = "이미 %s(이)라는 프로필이 있습니다."
L["Name the new profile (it starts from your current settings):"] = "새 프로필 이름을 입력하세요(현재 설정에서 시작합니다):"
L["Rename the profile:"] = "프로필 이름 변경:"
L["Describe the profile:"] = "프로필 설명:"
L["Delete the profile %s?"] = "%s 프로필을 삭제하시겠습니까?"
L["Put the profile %s back to how it started? Every change you've made to it goes."] = "%s 프로필을 처음 상태로 되돌리시겠습니까? 지금까지 바꾼 내용이 모두 사라집니다."
L["Profiles"] = "프로필"
L["A profile is a whole set of settings. Pick one to switch to it; changes you make go into the active profile and stay with it. The built-in ones keep your changes too, until you reset them. New profile starts one of your own from the settings you have now. Every character uses the same profile unless you tick the box below for one. Not part of a profile: the minimap button, frames you added or stopped fading, and the zone and time tint colors you picked."] = "프로필은 설정 전체의 묶음입니다. 하나를 고르면 그 프로필로 바뀌며, 바꾼 내용은 현재 프로필에 저장되어 남습니다. 기본 제공 프로필도 초기화하기 전까지는 바꾼 내용을 유지합니다. '새 프로필'은 지금 설정에서 나만의 프로필을 시작합니다. 아래 칸에 체크하지 않으면 모든 캐릭터가 같은 프로필을 씁니다. 프로필에 포함되지 않는 것: 미니맵 버튼, 직접 추가했거나 흐리기를 멈춘 창, 직접 고른 지역 및 시간대 색조 색."
L["Use a profile just for this character"] = "이 캐릭터 전용 프로필 사용"
L["Ticked: switching profiles changes only this character's, and it stays on it whatever your other characters use. Unticked: this character uses the same profile as the rest (switching back to it now if this one's differs)."] = "체크하면: 프로필을 바꿔도 이 캐릭터의 것만 바뀌며, 다른 캐릭터가 무엇을 쓰든 그대로 유지됩니다. 해제하면: 이 캐릭터는 나머지와 같은 프로필을 씁니다(지금 프로필이 다르면 그 프로필로 돌아갑니다)."
L["Use a profile just for this character |cff808080(other characters use %s)|r"] = "이 캐릭터 전용 프로필 사용 |cff808080(다른 캐릭터는 %s 사용)|r"
L["New profile"] = "새 프로필"
L["A profile of your own, starting from your current settings. To copy another profile, switch to it first."] = "현재 설정에서 시작하는 나만의 프로필입니다. 다른 프로필을 복사하려면 먼저 그 프로필로 바꾸세요."
L["Rename"] = "이름 변경"
L["Rename the active profile (your own ones only)."] = "현재 프로필의 이름을 바꿉니다(직접 만든 프로필만)."
L["Description"] = "설명"
L["Write what the active profile is for, shown when you point at its icon (your own ones only)."] = "현재 프로필의 용도를 적습니다. 아이콘에 마우스를 올리면 표시됩니다(직접 만든 프로필만)."
L["Delete"] = "삭제"
L["Delete the active profile (your own ones only), switching to %s."] = "현재 프로필을 삭제하고(직접 만든 프로필만) %s 프로필로 바꿉니다."
L["Put the active built-in profile back to its own values (your own profiles keep your changes as you go)."] = "현재 기본 제공 프로필을 원래 값으로 되돌립니다 (직접 만든 프로필은 바꾸는 대로 저장됩니다)."
L["Your own profile. Pick it, then Description to say what it's for."] = "직접 만든 프로필입니다. 고른 다음 '설명'으로 용도를 적으세요."
L["Mouseover groups"] = "마우스오버 그룹"
L["Mouseover Groups"] = "마우스오버 그룹"
L["UI Manager"] = "UI 관리자"
L["Frames in the same group come up together when you mouse over any of them. A frame can be in more than one group; one in no group comes up on its own."] = "같은 그룹의 창은 그중 하나에 마우스를 올리면 함께 나타납니다. 한 창이 여러 그룹에 속할 수 있으며, 그룹에 없는 창은 혼자 나타납니다."
L["Pointing at a faded frame shows it, with the rest of its groups."] = "흐려진 창을 가리키면 그 창과 같은 그룹의 나머지가 함께 보입니다."
L["Stays after mouseover"] = "마우스오버 후 유지"
L["How long until a frame is gone after your mouse leaves it (and its groups), fade included. Events that bring a group up hold it this long too. In the camera modes the shorter default is used."] = "마우스가 창(과 그 그룹)을 벗어난 뒤 사라질 때까지의 시간으로, 흐려지는 시간을 포함합니다. 그룹을 띄우는 이벤트도 이 시간 동안 유지합니다. 카메라 모드에서는 더 짧은 기본값을 씁니다."
