L["Settings window"] = "설정 창"
L["Force reload on Settings exit"] = "설정 종료 시 강제 재시작"
L["A workaround for a game bug: in gamepad mode, closing the Settings window after using an addon's settings (any addon's, not just Cinematic's) can freeze the game. With this on, once you've opened a Cinematic page, closing Settings (X, Close, Escape or the gamepad) reloads the UI instead, which closes it without the freeze. Your settings are saved first, as they are on every reload. Turning it off takes effect after a reload."] = "게임 버그 우회 방법: 게임패드 모드에서 애드온 설정(Cinematic뿐 아니라 모든 애드온)을 사용한 뒤 설정 창을 닫으면 게임이 멈출 수 있습니다. 이 옵션을 켜면 Cinematic 페이지를 연 뒤 설정을 닫을 때(X, 닫기, Esc 또는 게임패드) 대신 UI를 다시 불러와 멈춤 없이 창을 닫습니다. 설정은 다시 불러올 때마다 그렇듯 먼저 저장됩니다. 끄면 다시 불러온 뒤에 적용됩니다."
L["closing Settings now reloads the UI (Force reload on Settings exit, Gamepad Frames page)."] = "이제 설정을 닫으면 UI를 다시 불러옵니다 (설정 종료 시 강제 재시작, 게임패드 페이지)."
L["Hide the minimap button in gamepad mode"] = "게임패드 모드에서 미니맵 버튼 숨기기"
L["Using Cinematic's minimap button in gamepad mode tends to freeze the game, like closing Settings does. With this on, the button is hidden while gamepad mode is on and comes back when it's off. Cinematic's settings are still in the game's Settings (AddOns tab), or type /cine."] = "게임패드 모드에서 Cinematic의 미니맵 버튼을 사용하면 설정을 닫을 때처럼 게임이 멈추는 경우가 많습니다. 이 옵션을 켜면 게임패드 모드 동안 버튼이 숨겨지고 모드를 끄면 다시 나타납니다. Cinematic 설정은 게임 설정(애드온 탭)이나 /cine 명령으로 열 수 있습니다."
