-- Profiles.lua
L["Everything on: the UI fades, the letterbox and tint, and every camera mode. The defaults, and how the developer plays every day."] = "모두 켜짐: UI 흐리기, 레터박스와 색조, 모든 카메라 모드. 기본값이며, 개발자가 매일 플레이하는 방식입니다."
L["Immersive, with the Cooldown Manager in place of action bars 1 to 3, the micro menu and the XP bar in fights and with an enemy targeted. After a fight it stays up until its cooldowns are ready."] = "몰입감 있게, 전투 중과 적을 대상으로 잡았을 때 행동 단축바 1~3, 마이크로 메뉴와 경험치 바 대신 재사용 대기시간 관리자가 나타납니다. 전투 후에는 재사용 대기시간이 준비될 때까지 남아 있습니다."
L["The UI fades and the look stays, with just a few cameras: flights (and fly-bys), AFK, and your Hearthstone and teleports. No cozy, vista, fish, RP walk, auto-run, death or quest cameras."] = "UI는 흐려지고 분위기는 유지하되 카메라는 몇 가지만: 비행(과 플라이바이), 자리 비움, 귀환석과 순간이동. 아늑함, 풍경, 낚시, RP 걷기, 자동 달리기, 죽음, 퀘스트 카메라는 없습니다."
L["Just the visual effects (tint, vignette, weather) over your normal UI: nothing fades, no letterbox, and the camera's left to you."] = "일반 UI 위에 화면 효과(색조, 비네트, 날씨)만: 아무것도 흐려지지 않고, 레터박스도 없으며, 카메라는 직접 조작합니다."
L["The normal UI until a camera starts (standing still, going AFK, a flight, an emote...), then CineMode until it ends. The letterbox, tint, vignette and weather show only while a camera mode runs; no soft edges. Standing still starts the AFK camera, and every camera can start music."] = "카메라가 시작될 때까지(가만히 서 있기, 자리 비움, 비행, 감정 표현...) 일반 UI, 그다음 카메라가 끝날 때까지 CineMode. 레터박스, 색조, 비네트, 날씨는 카메라 모드가 도는 동안에만 보이며, 가장자리 흐림은 없습니다. 가만히 서 있으면 자리 비움 카메라가 시작되고, 모든 카메라가 음악을 시작할 수 있습니다."
L["Everything on while you're out in the world on your own; the normal UI in a group, in dungeons, raids and PvP."] = "필드에서 혼자일 때는 모두 켜짐. 파티 중이거나 던전, 공격대, PvP에서는 일반 UI."
L["As little UI as possible: chat, buffs, the quest tracker and your portrait don't pop up on their own (hovering still shows them), group members' nameplates aren't kept up, and fights don't bring the letterbox down. Fights bring up only your target and your cast bar (hidden otherwise), and every camera can start music."] = "UI를 최대한 적게: 대화, 강화 효과, 퀘스트 추적기, 초상화가 저절로 뜨지 않고(마우스를 올리면 여전히 보임), 파티원의 이름표도 유지하지 않으며, 전투 중에도 레터박스가 내려가지 않습니다. 전투 중에는 대상과 시전 바(평소에는 숨김)만 나타나고, 모든 카메라가 음악을 시작할 수 있습니다."
L["Started from %s."] = "%s에서 시작했습니다."

-- Share.lua
L["Export"] = "내보내기"
L["Import"] = "가져오기"
L["The active profile as a line of text to copy and paste wherever your friends will see it, so they can import it (your own ones only: everyone has the built-in ones)."] = "활성 프로필을 한 줄의 텍스트로 만들어 친구들이 볼 수 있는 곳에 복사해 붙여넣으면 친구들이 가져올 수 있습니다 (내 프로필만 가능: 기본 제공 프로필은 모두가 이미 가지고 있습니다)."
L["Add a profile someone shared with you, from the text they gave you. Your own profiles stay as they are."] = "누군가 공유해 준 텍스트로 프로필을 추가합니다. 내 프로필은 그대로 유지됩니다."
L["Share a profile with friends."] = "친구와 프로필을 공유하세요."
L["share the active profile as text to copy"] = "활성 프로필을 복사할 텍스트로 공유"
L["add a profile someone shared with you"] = "누군가 공유해 준 프로필 추가"
L["%s is a built-in profile, which everyone has already. To share your changes to it, make a New profile from it on the Profiles page and export that."] = "%s은(는) 모두가 이미 가지고 있는 기본 제공 프로필입니다. 변경 사항을 공유하려면 프로필 페이지에서 이 프로필로 새 프로필을 만든 뒤 그것을 내보내세요."
L["Shared profile"] = "공유된 프로필"
L["This profile needs a newer version of Cinematic. Update it, then try again."] = "이 프로필은 더 최신 버전의 Cinematic이 필요합니다. 업데이트한 뒤 다시 시도하세요."
L["That isn't a whole Cinematic profile. Copy all of it and paste it again."] = "완전한 Cinematic 프로필이 아닙니다. 전부 복사해서 다시 붙여넣으세요."
L["Paste a profile someone shared with you (Ctrl+V)."] = "누군가 공유해 준 프로필을 붙여넣으세요 (Ctrl+V)."
L["%s, shared by %s: %d settings changed from the defaults."] = "%s, %s 님이 공유: 기본값에서 바뀐 설정 %d개."
L["%s: %d settings changed from the defaults."] = "%s: 기본값에서 바뀐 설정 %d개."
L["%d settings from a newer Cinematic (%s) will be skipped. Update Cinematic to get them all."] = "설정 %d개는 더 최신 Cinematic(%s)의 것이라 건너뜁니다. 모두 받으려면 Cinematic을 업데이트하세요."
L["Shared by %s."] = "%s 님이 공유함."
L["profile imported: %s"] = "프로필 가져옴: %s"
L["Select all"] = "모두 선택"
L["Save as:"] = "저장할 이름:"
L["Export profile: %s"] = "프로필 내보내기: %s"
L["Press Ctrl+C to copy this, then paste it wherever your friends will see it. They add it with Import on their Cinematic Profiles page (or /cine import)."] = "Ctrl+C로 복사한 다음 친구들이 볼 수 있는 곳에 붙여넣으세요. 친구들은 Cinematic 프로필 페이지의 가져오기(또는 /cine import)로 추가합니다."
L["Only Cinematic settings are in it: nothing about you or your character but its name. Not in it, as with any profile: frames you added and your zone and time tint colors."] = "Cinematic 설정만 들어 있습니다. 캐릭터 이름 외에는 나나 내 캐릭터에 대한 정보가 없습니다. 다른 프로필과 마찬가지로 직접 추가한 프레임과 지역 및 시간대 색조 색상은 포함되지 않습니다."
L["Import a profile"] = "프로필 가져오기"
L["Paste in a profile someone shared, give it a name, and Import. It's added as a new profile and switched to; your own profiles stay as they are."] = "공유받은 프로필을 붙여넣고 이름을 정한 뒤 가져오기를 누르세요. 새 프로필로 추가되어 바로 적용되며, 내 프로필은 그대로 유지됩니다."

