L["its cooldown bars"] = "재사용 대기시간 바"
L["its health, power and totem bars"] = "생명력, 자원, 토템 바"
L["Its cast bar isn't faded, like the game's. Its swing timer is the Swing timer row on the Game Frames page."] = "시전 바는 게임 기본 시전 바처럼 흐리게 하지 않습니다. 평타 타이머는 게임 창 페이지의 평타 타이머 줄입니다."
L["its data bars"] = "데이터 바"
