-- Support/Plater.lua
L["Follows the Nameplates page"] = "이름표 페이지를 따름"
L["Plater's nameplates fade in CineMode and follow the Nameplates page's rows. Plater can change the game's nameplate settings itself (at login, and with its auto toggles); Cinematic puts its own back afterwards."] = "Plater의 이름표는 CineMode에서 흐려지며 이름표 페이지의 줄 설정을 따릅니다. Plater는 게임의 이름표 설정을 스스로 바꿀 수 있지만(접속할 때, 자동 전환으로), Cinematic이 나중에 자신의 설정을 되돌립니다."

-- Tint.lua
L["None"] = "없음"
L["No color tint."] = "색조 없음."
L["Warm / golden hour"] = "따뜻함 / 골든 아워"
L["Soft orange, like late-afternoon light."] = "늦은 오후 햇살 같은 부드러운 주황색."
L["Cool"] = "차가움"
L["Pale blue, crisp and wintry."] = "옅은 파란색, 산뜻하고 겨울 같은 느낌."
L["Night"] = "밤"
L["Deep blue and darker, like moonlight."] = "달빛처럼 짙은 파란색에 더 어둡게."
L["Dusk gradient"] = "황혼 그라데이션"
L["Orange at the top fading to purple at the bottom, like a sunset."] = "노을처럼 위쪽의 주황색이 아래쪽 보라색으로 바뀝니다."
L["Sepia-ish"] = "세피아풍"
L["Warm brownish yellow, old-photo warmth. (The world can't be truly desaturated.)"] = "오래된 사진 같은 따뜻한 갈색빛 노랑. (세상의 채도를 완전히 뺄 수는 없습니다.)"
L["Dreamy"] = "몽환"
L["A faint warm glow added over the scene. Soft and hazy."] = "장면 위에 은은하고 따뜻한 빛을 더합니다. 부드럽고 아련하게."
L["Custom"] = "사용자 지정"
L["Your own color, chosen with the color picker below."] = "아래 색 선택기로 고른 나만의 색."
L["Changes through the day: blue at night, pink at dawn, clear in the day, golden in the evening and purple at dusk."] = "하루에 따라 바뀝니다: 밤에는 파랑, 새벽에는 분홍, 낮에는 맑게, 저녁에는 황금빛, 해 질 녘에는 보라."
L["Zone"] = "지역"
L["A mood for the zone you're in: pale blue in the snow, sandy in deserts, green in swamps and jungles, sickly in blighted lands, ember red near volcanoes. Other zones are left untinted."] = "지금 있는 지역의 분위기: 눈 속에서는 옅은 파랑, 사막에서는 모래빛, 늪과 정글에서는 초록, 역병에 물든 땅에서는 병든 빛, 화산 근처에서는 잉걸불 빨강. 다른 지역에는 색조를 입히지 않습니다."
L["Zone + time of day"] = "지역 + 시간대"
L["The zone's mood and the time-of-day color together: a desert at night is warm sand darkened by moonlight."] = "지역 분위기와 시간대 색을 함께: 밤의 사막은 달빛에 어두워진 따뜻한 모래빛입니다."
