-- Welcome.lua
L["Trying %s. Pick another to compare."] = "%s 체험 중. 다른 것을 골라 비교해 보세요."
L["Done"] = "완료"
L["Nothing runs until you pick one."] = "하나를 고를 때까지 아무것도 작동하지 않습니다."
L["Decide later"] = "나중에 정하기"
L["Welcome to Cinematic"] = "Cinematic에 오신 것을 환영합니다"
L["Between fights, Cinematic fades your UI away, adds letterbox bars and a color tint, and brings the camera to life: on flights, standing still, sitting by a campfire. Fights, casting and opening windows bring the UI back. Hovering a faded frame shows it.\n\nHow much of that do you want? Pick a profile to start from:"] = "Cinematic은 전투 사이에 UI를 흐리게 하고, 레터박스 바와 색조를 더하며, 카메라에 생기를 불어넣습니다: 비행 중에, 가만히 서 있을 때, 모닥불 옆에 앉아 있을 때. 전투, 시전, 창 열기를 하면 UI가 돌아옵니다. 흐려진 창에 마우스를 올리면 보입니다.\n\n어느 정도를 원하시나요? 시작할 프로필을 고르세요:"
L["Try as many as you like: each one starts straight away behind this window. Afterwards you can switch any time, tweak a profile or make your own on the Profiles page (Options > AddOns > Cinematic, or right-click the minimap button), or with /cine profile. /cine toggles Cinematic on and off."] = "원하는 만큼 체험해 보세요. 고르는 즉시 이 창 뒤에서 시작됩니다. 나중에 언제든 바꾸거나, 프로필 페이지(옵션 > 애드온 > Cinematic, 또는 미니맵 버튼 오른쪽 클릭)나 /cine profile에서 프로필을 조정하거나 직접 만들 수 있습니다. /cine로 Cinematic을 켜고 끕니다."
L["off until you pick a profile. This window comes back next login, or now with /cine welcome."] = "프로필을 고를 때까지 꺼져 있습니다. 이 창은 다음 접속 때, 또는 지금 /cine welcome으로 다시 열립니다."
L["profile: %s. Change it any time on the Profiles settings page, or with /cine profile."] = "프로필: %s. 프로필 설정 페이지나 /cine profile에서 언제든 바꿀 수 있습니다."
L["Turn Cinematic off"] = "Cinematic 끄기"
L["turned off. /cine brings this window back to pick a profile."] = "꺼졌습니다. /cine로 이 창을 다시 열어 프로필을 고를 수 있습니다."
L["Settings"] = "설정"

-- Looked up by name (page names, times of day...)
L["Dawn"] = "새벽"
L["Day"] = "낮"
L["Golden hour"] = "골든 아워"
L["Dusk"] = "해 질 녘"
L["Morning"] = "아침"
L["Midday"] = "한낮"
L["Afternoon"] = "오후"
L["Evening"] = "저녁"
L["turned off"] = "꺼짐"
L["you moved the camera"] = "카메라를 움직임"
L["combat"] = "전투"
L["landed"] = "착륙함"
L["cozy camera"] = "아늑한 카메라"
L["vista camera"] = "풍경 카메라"
L["fish camera"] = "낚시 카메라"
L["tele camera"] = "순간이동 카메라"
L["death camera"] = "죽음 카메라"

-- Campfire.lua
L["Quality of life"] = "편의 기능"
L["Small helpers for getting about the world. Ideas for more in the spirit of this page are welcome: please send them to the developer."] = "세상을 다니는 데 도움이 되는 작은 기능들입니다. 이 페이지와 비슷한 아이디어가 더 있다면 개발자에게 보내 주세요."
L["Campfire button"] = "모닥불 버튼"
L["Hovering a campfire with the cursor near the middle of the screen shows a campfire icon where the cursor is: click it to settle down by the fire (sit, kneel or lie down, as ticked below), without typing the emote. Moving the cursor off it puts it away. Not in a fight or while mounted."] = "화면 중앙 근처에서 커서를 모닥불 위에 올리면 커서 위치에 모닥불 아이콘이 나타납니다. 클릭하면 감정 표현을 입력하지 않아도 불가에 자리 잡습니다(아래에서 선택한 대로 앉기, 무릎 꿇기 또는 눕기). 커서를 떼면 사라집니다. 전투 중이거나 탈것을 탄 상태에서는 나오지 않습니다."
L["Sit"] = "앉기"
L["Kneel"] = "무릎 꿇기"
L["Lie down"] = "눕기"
L["What clicking the Campfire button does. With more than one ticked, it's one of them at random each time."] = "모닥불 버튼을 클릭했을 때 하는 동작입니다. 둘 이상 선택하면 매번 그중 하나를 무작위로 합니다."
L["Clicking the Campfire button (Quality of life page). Once the campfire's buff comes, the first row's camera takes over. Moving, jumping or another emote ends it."] = "모닥불 버튼을 클릭할 때 (편의 기능 페이지). 모닥불 효과가 생기면 첫 줄의 카메라가 이어받습니다. 움직이거나 점프하거나 다른 감정 표현을 하면 끝납니다."
L["Stand up once you get Camp Benefits"] = "야영지 혜택을 받으면 일어서기"
L["Open the character window when dragging gear out of your bags"] = "가방 밖으로 장비를 끌면 캐릭터 창 열기"
L["Dragging something you can wear out of your bags, over the game world, opens the character window, so its slots are there to drop it on. Moving it between bags doesn't. Put it back without wearing it and the window closes again. Not in a fight."] = "착용할 수 있는 물건을 가방 밖 게임 세계 위로 끌면 캐릭터 창이 열려 슬롯에 바로 놓을 수 있습니다. 가방 사이에서 옮길 때는 열리지 않습니다. 착용하지 않고 다시 내려놓으면 창이 다시 닫힙니다. 전투 중에는 동작하지 않습니다."
L["Off by default on this client: opened by an addon, the window makes your player frame's health and power numbers show errors in BugSack and other error catchers. They're harmless."] = "이 클라이언트에서는 기본적으로 꺼져 있습니다: 애드온이 창을 열면 플레이어 프레임의 생명력·자원 숫자가 BugSack 등 오류 수집기에 오류를 표시합니다. 무해한 오류입니다."
L["Open windows in the middle of the screen"] = "창을 화면 가운데에 열기"
L["Windows the game opens on the left (quest log, group finder, character, spellbook and the like) open in the middle of the screen instead. Two open at once still sit side by side, together in the middle. Quest givers' windows open a little in from the left edge instead, out of the way of the quest giver. A window another addon has moved stays where that addon put it."] = "게임이 왼쪽에 여는 창(퀘스트 목록, 파티 찾기, 캐릭터, 마법책 등)이 대신 화면 가운데에 열립니다. 두 창을 함께 열면 여전히 나란히, 함께 가운데에 놓입니다. 퀘스트 제공자의 창은 퀘스트 제공자를 가리지 않도록 왼쪽 가장자리에서 조금 안쪽에 열립니다. 다른 애드온이 옮긴 창은 그 애드온이 둔 자리에 그대로 있습니다."
L["Drag windows to move them"] = "창을 끌어서 옮기기"
L["Drag the game's windows (quest log, group finder, character, spellbook and the like) to move them. A window opens where you last dropped it from then on, in this profile. Some windows can't be moved in a fight."] = "게임 창(퀘스트 목록, 파티 찾기, 캐릭터, 마법책 등)을 끌어서 옮깁니다. 그 뒤로 창은 이 프로필에서 마지막으로 놓은 자리에 열립니다. 일부 창은 전투 중에 옮길 수 없습니다."
L["Put windows back"] = "창 위치 되돌리기"
L["Forget where you've dragged the windows to: each opens in its usual place again."] = "창을 끌어 놓은 자리를 잊습니다. 각 창이 다시 원래 자리에 열립니다."
L["Sitting by a Welcoming Campfire for its minute gives you Camp Benefits: as it arrives, you stand up again, ready to go."] = "환영의 모닥불 옆에 1분 동안 앉아 있으면 야영지 혜택을 받습니다. 혜택을 받는 즉시 다시 일어서서 바로 출발할 수 있습니다."

-- Options.lua: the Camera Settings page
L["Camera Settings"] = "카메라 설정"
L["Each camera's own settings. Click a camera's name to open its settings, and again to close them. The Camera Modes page has the settings they share, and Camera Triggers what starts each one."] = "각 카메라의 개별 설정입니다. 카메라 이름을 클릭하면 설정이 열리고, 다시 클릭하면 닫힙니다. 공통 설정은 카메라 모드 페이지에, 각 카메라를 시작하는 조건은 카메라 발동 조건 페이지에 있습니다."
L["Put this camera's settings back to the profile's own?"] = "이 카메라의 설정을 프로필 값으로 되돌리시겠습니까?"
L["Put this camera's settings back to the active profile's own values (the defaults, or a built-in profile's)."] = "이 카메라의 설정을 현재 프로필의 값(기본값 또는 기본 제공 프로필의 값)으로 되돌립니다."
L["While the death camera runs, a song picked at random from the list below plays in place of the zone music. With CineMode music off, only if your game music is on. It stops when you release or come back."] = "죽음 카메라가 실행되는 동안 아래 목록에서 무작위로 고른 곡이 지역 음악 대신 재생됩니다. CineMode 음악이 꺼져 있으면 게임 음악이 켜져 있을 때만 재생됩니다. 영혼을 놓아주거나 되살아나면 멈춥니다."
L["Hunter"] = "사냥꾼"

-- QuestTalk.lua (and its options on the Quest Vision page)
L["%s artifact power"] = "유물력 %s"
L["%s honor"] = "명예 %s"
L["Quests"] = "퀘스트"
L["Show the game's window"] = "게임 창 보기"
L["Talk"] = "대화"
L["Title: %s"] = "칭호: %s"
L["campaign"] = "전역"
L["daily"] = "일일"
L["done"] = "완료"
L["important"] = "중요"
L["in progress"] = "진행 중"
L["legendary"] = "전설"
L["locked"] = "잠김"
L["low level"] = "낮은 레벨"
L["meta"] = "메타"
L["ready to turn in"] = "완료 가능"
L["repeatable"] = "반복"
L["weekly"] = "주간"
L["Talking to NPCs"] = "NPC와 대화"
L["Custom dialogue frames"] = "사용자 대화 창"
L["Talking to an NPC, what they say shows in a speech bubble over their head, and what you can say back in a list near the bottom of the screen, instead of the game's gossip and quest windows. The list has everything the window would: quests to turn in, pick up or still in progress, and every other option (vendor, trainer, inn, flight master...). A quest offered or turned in shows its objective and rewards on a card, with its buttons; click a reward to choose it. \"Show the game's window\" on the card brings the game's window back for that conversation. The game's popups (a cost to confirm, a party member's escort quest) come up as usual."] = "NPC와 대화할 때 NPC의 말이 머리 위 말풍선에 나타나고, 대답할 수 있는 내용은 게임의 대화 및 퀘스트 창 대신 화면 아래쪽 목록에 나타납니다. 목록에는 창에 있을 모든 것이 있습니다: 완료할 퀘스트, 받을 퀘스트, 진행 중인 퀘스트, 그리고 다른 모든 선택지(상인, 기술 전문가, 여관, 비행 조련사...). 제안되거나 완료하는 퀘스트는 목표와 보상을 버튼과 함께 카드에 보여 줍니다. 보상을 클릭해 선택하세요. 카드의 \"게임 창 보기\"는 그 대화 동안 게임 창을 되돌려 놓습니다. 게임의 팝업(확인할 비용, 파티원의 호위 퀘스트)은 평소처럼 나타납니다."
L["Parchment"] = "양피지"
L["Chat bubble"] = "채팅 말풍선"
L["How the bubble looks: parchment like the quest window's, or the game's own chat bubble."] = "말풍선 모양: 퀘스트 창 같은 양피지, 또는 게임 자체의 채팅 말풍선."
L["Bubble look"] = "말풍선 모양"
L["Number keys and Space"] = "숫자 키와 스페이스"
L["1 to 9 and 0 pick from the list, as numbered. Space shows the next paragraph, and on the last one does the card's first button (Accept, Continue, Complete Quest). Only keys that do something there are held back from your action bars, and none in a fight."] = "1~9와 0은 번호대로 목록에서 선택합니다. 스페이스는 다음 문단을 보여 주고, 마지막 문단에서는 카드의 첫 번째 버튼(수락, 계속, 퀘스트 완료)을 누릅니다. 거기서 무언가 하는 키만 행동 단축바에서 가로채며, 전투 중에는 하나도 가로채지 않습니다."
L["Size"] = "크기"
L["The size of the bubble and the list."] = "말풍선과 목록의 크기."
L["List height on the screen"] = "화면에서 목록 높이"
L["How far up the screen the list of replies starts: its top edge, from the bottom of the screen. Moving this also forgets where you dragged the list to."] = "대답 목록이 화면에서 얼마나 높이 시작하는지: 화면 아래에서부터 목록의 위쪽 가장자리까지. 이것을 움직이면 목록을 끌어다 놓은 위치도 잊습니다."
L["The NPC's portrait"] = "NPC 초상화"
L["Their portrait, round, on the bubble's top left corner, as on the game's quest window. Not for a quest from an item, with nobody to show."] = "NPC의 초상화를 게임 퀘스트 창처럼 말풍선 왼쪽 위 모서리에 둥글게 보여 줍니다. 보여 줄 사람이 없는 아이템 퀘스트에는 나오지 않습니다."
L["Put them back"] = "원래대로"
L["Drag the list of replies to move it, and the bubble while it isn't over an NPC. This forgets where you dropped them: each opens in its usual place again."] = "대답 목록을 끌어서 옮길 수 있고, NPC 위에 있지 않을 때는 말풍선도 옮길 수 있습니다. 이 버튼은 놓은 위치를 잊어, 각각 원래 자리에 다시 열립니다."
L["Bubble height"] = "말풍선 높이"
L["%d lines"] = "%d줄"
L["How many lines of their words the bubble holds. It's always this tall, however little is on the page; more words go on the next page."] = "말풍선에 들어가는 대사 줄 수. 페이지 내용이 적어도 항상 이 높이이며, 넘치는 말은 다음 페이지로 갑니다."
L["Below"] = "아래"
L["Quest card beside the bubble"] = "말풍선 옆 퀘스트 카드"
L["Quest card on the bubble's background"] = "말풍선 배경의 퀘스트 카드"
L["The quest card has the bubble's look (parchment, or the chat bubble) instead of its own dark one, its words in colors that suit it."] = "퀘스트 카드가 자체의 어두운 배경 대신 말풍선 모양(양피지 또는 채팅 말풍선)이 되고, 글자 색도 그에 맞춥니다."
L["Space above the bubble"] = "말풍선 위 여백"
L["Over the NPC's head, the bubble always stays at least this far down from the top of the screen (and below the letterbox), so it never sits right against the edge."] = "NPC 머리 위에서 말풍선은 항상 화면 위쪽(그리고 레터박스 아래)에서 최소 이만큼 떨어져 있어, 가장자리에 붙지 않습니다."
L["Over the head"] = "머리 위"
L["Fixed"] = "고정"
L["Opposite clicked"] = "클릭 반대편"
L["Where the bubble goes. Over the head: over the NPC's nameplate, following them on the screen. Fixed: above the middle of the screen, or wherever you drag it. Opposite clicked: wherever you drag it, but when you clicked the NPC on that half of the screen, at the same spot on the other half (they stand where you clicked, so that half is clearer), the quest card beside it. With nobody to stand over or no click (a quest from an item, or the interact key), it goes where Fixed would."] = "말풍선 위치. 머리 위: NPC 이름표 위에서 화면에서 NPC를 따라갑니다. 고정: 화면 가운데 위, 또는 끌어다 놓은 곳. 클릭 반대편: 끌어다 놓은 곳이지만, 화면의 그쪽 절반에서 NPC를 클릭했다면 다른 쪽 절반의 같은 자리(NPC는 클릭한 곳에 있으니 그쪽 절반이 더 비어 있습니다)에 퀘스트 카드와 함께 놓입니다. 위에 설 사람이 없거나 클릭이 없으면(아이템 퀘스트, 또는 상호작용 키) 고정 위치로 갑니다."
L["Bubble position"] = "말풍선 위치"
L["Hold the camera still"] = "카메라 고정"
L["With the bubble over the head, the quest camera turns in as usual but doesn't drift to and fro while you talk: following the NPC on the screen, the bubble and card would jiggle as it moved."] = "말풍선이 머리 위에 있으면 퀘스트 카메라가 평소처럼 돌아 들어가지만 대화 중에는 좌우로 흔들리지 않습니다. 말풍선과 카드가 화면에서 NPC를 따라가므로 움직임에 따라 떨리게 됩니다."
L["+%d reputation"] = "평판 +%d"
L["More rewards"] = "보상 더 보기"
L["Back"] = "뒤로"
L["Right"] = "오른쪽"
L["Left"] = "왼쪽"
L["Where the quest card (the objective, rewards and buttons, or the list of replies) goes beside the bubble. Below: as wide as the bubble, which moves up to make room for it. Side: with Opposite clicked, on the bubble's outer side (away from the middle of the screen), else on the right. Right or Left: always that side. Beside it, it's as tall as the bubble."] = "퀘스트 카드(목표, 보상과 버튼, 또는 대답 목록)가 말풍선 옆 어디에 놓일지. 아래: 말풍선과 같은 너비이며 말풍선이 위로 올라가 자리를 만듭니다. 측면: 클릭 반대편일 때는 말풍선의 바깥쪽(화면 가운데에서 먼 쪽), 그 외에는 오른쪽. 오른쪽 또는 왼쪽: 항상 그쪽. 옆에 있을 때는 말풍선과 같은 높이입니다."
L["\"Show the game's window\" link"] = "\"게임 창 보기\" 링크"
L["A small link at the bottom of the quest card that brings back the game's own quest window for the rest of that conversation (for a long quest text, or to read it the usual way)."] = "퀘스트 카드 아래쪽의 작은 링크로, 그 대화가 끝날 때까지 게임 자체의 퀘스트 창을 되돌려 놓습니다 (긴 퀘스트 글이나, 평소처럼 읽고 싶을 때)."
L["Look"] = "모양"
L["Where they go"] = "위치"

-- StoryVision.lua
L["Opens the Story Vision page."] = "Story Vision 페이지를 엽니다."
L["Shows it now, to see how it looks."] = "지금 표시해서 어떻게 보이는지 확인합니다."
L["Words that fade in on the screen at moments in your session that aren't your own fights: what you did last time, the time of day, a place under attack, your death. (Fights and bosses: Battle Vision.)"] = "내 전투가 아닌 순간에 화면에 서서히 나타나는 글귀: 지난번에 한 일, 시간대, 공격받는 장소, 나의 죽음. (전투와 우두머리: Battle Vision.)"
L["Last time"] = "지난번"
L["On a real login (not a reload), a line under the zone name saying what you did last time you played: where you spent the most time, quests done, a level reached and bosses killed, such as \"Last time: Darkshore · 3 quests done · reached level 24\". Only what happened, and nothing if nothing did; never in a fight, nor after more than two weeks away."] = "실제로 접속할 때(다시 불러오기 제외) 지역 이름 아래에 지난번 플레이에서 한 일을 한 줄로 표시합니다: 가장 오래 머문 곳, 완료한 퀘스트, 달성한 레벨, 처치한 우두머리. 예: \"지난번: 어둠해안 · 퀘스트 3개 완료 · 24레벨 달성\". 일어난 일만 표시하고, 아무 일도 없었다면 표시하지 않습니다. 전투 중이나 2주 넘게 쉬었을 때는 표시하지 않습니다."
L["Last time: nothing to say yet this session (no quests, level or bosses), so this is a sample."] = "지난번: 이번 세션에는 아직 할 말이 없어 (퀘스트, 레벨, 우두머리 없음) 예시를 보여 줍니다."
L["Plays your login now: the zone name fades in with the Last time line under it, from this session so far (a sample if nothing counted yet). Close the settings to see it."] = "지금 접속 장면을 재생합니다: 지역 이름 아래에 지금까지의 이번 세션을 바탕으로 한 지난번 줄이 나타납니다 (아직 아무것도 없으면 예시). 설정을 닫아야 보입니다."
L["The font of every line on this page. General: the one picked on the Style hub's General page, so changing it there changes it here. Russian, Korean or Chinese text keeps the game's, so its letters show. Only with Enable Style on (Style hub, General page)."] = "이 페이지의 모든 줄에 쓰이는 글꼴입니다. General: Style 허브의 General 페이지에서 고른 글꼴이므로, 그곳에서 바꾸면 여기서도 바뀝니다. 러시아어, 한국어, 중국어 글자는 제대로 보이도록 게임 글꼴을 유지합니다. Enable Style이 켜져 있을 때만 적용됩니다 (Style 허브, General 페이지)."
L["Last time: %s"] = "지난번: %s"
L["%d quest done"] = "퀘스트 %d개 완료"
L["%d quests done"] = "퀘스트 %d개 완료"
L["reached level %d"] = "%d레벨 달성"
L["%d boss down"] = "우두머리 %d마리 처치"
L["%d bosses down"] = "우두머리 %d마리 처치"
L["On: each moment below shows as ticked. Off: none of them do, and each keeps its tick for when you turn this back on."] = "켜기: 아래의 각 순간이 체크한 대로 표시됩니다. 끄기: 아무것도 표시되지 않으며, 각 항목은 다시 켤 때를 위해 체크를 유지합니다."
L["Time of day at login"] = "접속 시 시간대"
L["Dawn, Morning, Midday, Afternoon, Evening, Dusk or Night, under the zone name when you log in or reload. Follows the clock picked on the Tint page."] = "접속하거나 다시 불러올 때 지역 이름 아래에 새벽, 아침, 한낮, 오후, 저녁, 해 질 녘, 밤을 표시합니다. 색조 페이지에서 고른 시계를 따릅니다."
L["Time of day changes"] = "시간대 변화"
L["When the time of day changes during play (not in combat), its name fades in where the zone name shows, with a fitting sound: a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "플레이 중에 시간대가 바뀌면(전투 중 제외) 지역 이름이 나타나는 자리에 그 이름이 어울리는 소리와 함께 나타납니다: 새벽에는 수탉, 아침에는 말, 한낮에는 진영의 종소리, 저녁에는 개구리, 해 질 녘에는 올빼미, 밤에는 늑대."
L["Under attack"] = "공격받는 중"
L["When the LocalDefense channel says a place is under attack (\"Dun Algaz is under attack!\"), it shows in red where the zone name appears, with your faction's city bell. The same place shows at most once every 90 seconds."] = "지역방어 채널에서 어떤 장소가 공격받고 있다고 알리면(\"던 알가즈가 공격받고 있습니다!\"), 지역 이름이 나타나는 자리에 빨간색으로 진영 도시의 종소리와 함께 표시합니다. 같은 장소는 90초에 한 번까지만 표시됩니다."
L["Only with the death camera on (the Die row on the Scenes page)."] = "죽음 카메라가 켜져 있을 때만 (장면 페이지의 죽음 줄)."
L["The time of day's title and sound:"] = "시간대 제목과 소리:"
L["Attacks shown on the screen:"] = "화면에 표시되는 공격:"
L["The death banner:"] = "죽음 배너:"

