L["Parts"] = "구성 요소"
L["When it shows in CineMode (always, in fights, in places): its rows on the Game Frames page."] = "CineMode에서 언제 표시되는지(항상, 전투 중, 장소별): 게임 창 페이지의 해당 줄."
L["Opens the Unit Frames page: which parts of your own, your target's and the other unit frames show, and when."] = "유닛 프레임 페이지를 엽니다: 내 프레임, 대상 프레임과 다른 유닛 프레임의 어떤 부분이 언제 표시되는지."

-- More pages and settings (AI translation)
L[" A class icon beside enemy players' health bars."] = " 적 플레이어의 생명력 바 옆에 직업 아이콘을 표시합니다."
L[" A class icon beside friendly players' health bars."] = " 아군 플레이어의 생명력 바 옆에 직업 아이콘을 표시합니다."
L[" A mark on your target's nameplate (and its name, health bar or border in its color), shown even while the rest of the plate is faded or shows just its name. Its look: the Style hub's Nameplates page."] = " 대상의 이름표에 표시를 붙입니다(이름, 생명력 바 또는 테두리를 그 색으로). 이름표의 나머지가 흐려지거나 이름만 보일 때도 표시됩니다. 모양: 스타일 허브의 이름표 페이지."
L[" A role icon beside your group's damage dealers' health bars."] = " 파티의 공격 전담 생명력 바 옆에 역할 아이콘을 표시합니다."
L[" A role icon beside your group's healers' health bars."] = " 파티의 치유 전담 생명력 바 옆에 역할 아이콘을 표시합니다."
L[" A role icon beside your group's tanks' health bars."] = " 파티의 방어 전담 생명력 바 옆에 역할 아이콘을 표시합니다."
L[" Beyond nameplate range, and in dungeons and raids, the game has no setting for neutral NPCs' names alone: they show there while all three NPC rows do."] = " 이름표 거리 밖이나 던전과 공격대에서는 게임에 중립 NPC 이름만 따로 정하는 설정이 없습니다: NPC 세 줄이 모두 표시될 때 함께 표시됩니다."
L[" Beyond nameplate range, and in dungeons and raids, the game only shows friendly NPCs with something for you (quest givers, vendors, flight masters...) unless all three NPC rows show: then all of them, guards too."] = " 이름표 거리 밖이나 던전과 공격대에서는 NPC 세 줄이 모두 표시되지 않는 한, 게임이 나와 관련된 아군 NPC(퀘스트 NPC, 상인, 비행 조련사...)만 보여 줍니다: 모두 표시되면 경비병까지 전부 보입니다."
L[" In CineMode, on the nameplates that are up."] = " CineMode에서, 떠 있는 이름표에."
L[" Its look: the Dialogue tab."] = " 모양: 대화 탭."
L[" Its look: the Quest Item Button tab."] = " 모양: 퀘스트 아이템 버튼 탭."
L[" Off unless ticked. In CineMode, on the nameplates that are up; outside it, only with Always ticked."] = " 체크하지 않으면 꺼짐. CineMode에서는 떠 있는 이름표에, 그 밖에서는 '항상'에 체크했을 때만."
L[" Players' guilds, under their names wherever their names show: over their heads, and in CineMode on nameplates showing just the name."] = " 플레이어의 길드를 이름이 보이는 곳마다 이름 아래에 표시합니다: 머리 위, 그리고 CineMode에서 이름만 보이는 이름표."
L[" Quest objective icons and other widgets over the plate."] = " 이름표 위의 퀘스트 목표 아이콘과 기타 위젯."
L[" The border round your target's or mouseover's plate."] = " 대상 또는 마우스오버 대상의 이름표 테두리."
L[" The buffs shown on the plate."] = " 이름표에 표시되는 강화 효과."
L[" The cast bar."] = " 시전 바."
L[" The debuffs (and crowd control) shown on the plate."] = " 이름표에 표시되는 약화 효과(와 군중 제어)."
L[" The elite, rare or boss icon."] = " 정예, 희귀 또는 우두머리 아이콘."
L[" The glow while a mob has you (or is about to) as its target."] = " 몹이 나를 대상으로 삼았을 때(또는 곧 삼으려 할 때)의 빛."
L[" The health bar."] = " 생명력 바."
L[" The level."] = " 레벨."
L[" The name on the plate (the Names grid below is for names without a plate)."] = " 이름표의 이름(아래 이름 격자는 이름표가 없는 이름용입니다)."
L[" The raid target marker (skull, star...)."] = " 공격대 징표(해골, 별...)."
L[" Their look: the Style hub's Names page."] = " 모양: 스타일 허브의 이름 페이지."
L[" Your target's name, even with its kind's names off in the Names grid. For some kinds only, name them in its rule (Edit): Enemy players, Hostile NPCs, Neutral players... Beyond nameplate range, and in dungeons and raids, the game has one setting for your target's name, which can't change in fights: it stays as the fight found it."] = " 이름 격자에서 그 종류의 이름을 꺼 두었어도 대상의 이름은 표시합니다. 일부 종류에만 적용하려면 규칙(편집)에 이름을 적으세요: Enemy players, Hostile NPCs, Neutral players... 이름표 거리 밖이나 던전과 공격대에서는 게임에 대상 이름 설정이 하나뿐이며 전투 중에는 바꿀 수 없습니다: 전투가 시작될 때 상태 그대로 유지됩니다."
L[" Your target's nameplate, whatever the Nameplates grid says. For some kinds only, name them in its rule (Edit): Enemy players, Hostile NPCs, Neutral players... In dungeons and raids, friendly targets go by Friendly plates in dungeons and raids."] = " 이름표 격자 설정과 관계없이 대상의 이름표를 표시합니다. 일부 종류에만 적용하려면 규칙(편집)에 이름을 적으세요: Enemy players, Hostile NPCs, Neutral players... 던전과 공격대에서 아군 대상은 '던전 및 공격대의 아군 이름표'를 따릅니다."
