L["1 need"] = "1개 필요"
L["1 scene"] = "장면 1개"
L["1. Type |cffffd100/cine log|r in chat, or click Open the log below.\n2. The log opens already selected: press Ctrl+C to copy it.\n3. Paste it into your bug report. On Discord it's too long for a message: paste it into a .txt file and attach that.\nIt holds the addon's recent history, any Lua errors and a summary of your setup (game version, changed settings, other addons). It doesn't include your character's name or realm."] = "1. 대화창에 |cffffd100/cine log|r를 입력하거나 아래 '로그 열기'를 클릭하세요.\n2. 로그가 이미 선택된 채로 열립니다: Ctrl+C로 복사하세요.\n3. 버그 보고에 붙여 넣으세요. Discord에서는 메시지로 보내기엔 너무 깁니다: .txt 파일에 붙여 넣고 그 파일을 첨부하세요.\n로그에는 애드온의 최근 기록, Lua 오류, 설정 요약(게임 버전, 바꾼 설정, 다른 애드온)이 담깁니다. 캐릭터 이름이나 서버는 들어가지 않습니다."
L["1.85:1"] = "1.85:1"
L["2 minutes"] = "2분"
L["2.39:1 (cinema)"] = "2.39:1 (영화관)"
L["2:1"] = "2:1"
L["30 seconds"] = "30초"
L["5 minutes"] = "5분"
L["< Back"] = "< 뒤로"
L["<NAME>"] = "<NAME>"
L["A 2.39:1 frame, as at the cinema."] = "영화관처럼 2.39:1 화면."
L["A Stop camera button on screen while its steps run (under the release popup when you're dead): click it for your own view back, until what started it is over."] = "단계가 실행되는 동안 화면에 '카메라 멈추기' 버튼을 표시합니다(죽었을 때는 영혼 해방 창 아래). 클릭하면 시작한 원인이 끝날 때까지 내 시점으로 돌아옵니다."
L["A big bar in a gold frame, red when you're behind, gold when you lead, loud words."] = "금색 테두리의 큰 바. 뒤처지면 빨강, 앞서면 금색, 큰 글자."
L["A big hit takes"] = "큰 타격으로 잃는 양"
L["A big hit's flash, and the color the world drains toward."] = "큰 타격의 번쩍임과 세상이 물들어 가는 색."
L["A black border round its numbers."] = "숫자 둘레의 검은 테두리."
L["A black border around the letters, for see-through backgrounds."] = "글자 둘레의 검은 테두리. 비치는 배경용."
L["A black border around the letters, on every Vision that follows this page."] = "글자 둘레의 검은 테두리. 이 페이지를 따르는 모든 Vision에 적용됩니다."
L["A black border around the letters, on every page that follows General. The game's: as each page's default has it."] = "글자 둘레의 검은 테두리. 일반 페이지를 따르는 모든 페이지에 적용됩니다. 게임 기본: 각 페이지의 기본값대로."
L["A black border around the letters, so they stand out against the world. Thick + shadow also drops a shadow below and to the right of them."] = "글자 둘레의 검은 테두리로 세상 위에서 돋보이게 합니다. '두껍게 + 그림자'는 오른쪽 아래로 그림자도 드리웁니다."
L["A black border around the letters: easier to read with no panel behind them."] = "글자 둘레의 검은 테두리: 뒤에 판이 없을 때 읽기 쉽습니다."
L["A black border around the letters: for light words with no panel behind them."] = "글자 둘레의 검은 테두리: 뒤에 판이 없는 밝은 글자용."
L["A border in the color beside it around the icon while it flashes."] = "아이콘이 번쩍이는 동안 옆의 색으로 아이콘 둘레에 테두리를 그립니다."
L["A border around the letters."] = "글자 둘레의 테두리."
L["A boss"] = "우두머리"
L["A box where it and its recap show: drag it where you want it, left-click to set, right-click to put it back. Close the settings to see it."] = "이것과 요약이 표시되는 상자: 원하는 곳으로 끌고, 왼쪽 클릭으로 정하고, 오른쪽 클릭으로 되돌립니다. 설정을 닫아야 보입니다."
L["A breeze that shows you the way: wind blows across the screen toward your waypoint (your map pin, or the quest you're tracking), in gusts. When it's off the screen, the wind sweeps off the side to turn to. It goes by the way you face, so it's off while you swing the camera round on its own (on retail it follows the game's waypoint marker exactly). A demo for now."] = "길을 알려 주는 바람: 목적지(지도 핀이나 추적 중인 퀘스트)를 향해 바람이 화면을 가로질러 돌풍처럼 붑니다. 목적지가 화면 밖에 있으면 돌아야 할 쪽 가장자리로 바람이 빠져나갑니다. 바라보는 방향을 기준으로 하므로 카메라만 따로 돌리는 동안은 꺼집니다(리테일에서는 게임의 목적지 표시를 정확히 따릅니다). 지금은 시연용입니다."
L["A bubble the game would put at the very top of the screen (someone above you, up some stairs say) shows a little lower instead, below the letterbox bar (or a bit down from the top with the bars off), where you can read it."] = "게임이 화면 맨 위에 띄울 말풍선(예: 계단 위처럼 나보다 높은 곳의 누군가)을 조금 아래, 레터박스 바 밑(바가 꺼져 있으면 위에서 조금 아래)에 표시해서 읽을 수 있게 합니다."
L["A built-in camera: Copy it to change it."] = "기본 카메라입니다: 바꾸려면 복사하세요."
L["A button on your talents window opens a talent calculator: your class's three trees side by side, to plan a build without learning anything. Left-click adds a point, right-click takes one back; above the trees, the level the build needs and the points left. It opens in the talents window's place, and a button on it takes you back. It starts from the talents you have; Copy over changes puts what the plan adds in your talents window, to apply there. Also /cine talents."] = "특성 창의 버튼으로 특성 계산기를 엽니다: 직업의 세 특성 트리를 나란히 놓고 아무것도 배우지 않고 빌드를 계획합니다. 왼쪽 클릭은 점수 추가, 오른쪽 클릭은 되돌리기. 트리 위에는 빌드에 필요한 레벨과 남은 점수가 나옵니다. 특성 창 자리에 열리며, 버튼으로 돌아갈 수 있습니다. 지금 가진 특성에서 시작하며, '변경 사항 옮기기'는 계획에서 추가한 것을 특성 창에 옮겨 거기서 적용하게 합니다. /cine talents로도 열 수 있습니다."
L["A button under the release popup while the death camera's on: click it for your own view back until you release or come back. The Stop the camera key binding does the same."] = "죽음 카메라가 켜져 있는 동안 영혼 해방 창 아래에 버튼을 표시합니다: 클릭하면 영혼을 해방하거나 되살아날 때까지 내 시점으로 돌아옵니다. '카메라 멈추기' 단축키도 같은 일을 합니다."
L["A change here starts a profile of your own, %s."] = "여기서 바꾸면 나만의 프로필 %s을(를) 시작합니다."
L["A chat message is peeking"] = "대화 메시지가 잠깐 보이는 중"
L["A close, gentle zoom: it starts by easing in to the close-up distance below, then drifts a little in and out around it."] = "가깝고 부드러운 확대: 먼저 아래의 근접 거리까지 천천히 다가간 뒤 그 주위에서 조금씩 앞뒤로 흘러갑니다."
L["A color of your own (the swatch), for both lines."] = "직접 고른 색(견본), 두 줄 모두에."
L["A color of your own (the swatch)."] = "직접 고른 색(견본)."
L["A copy of this camera's script, yours to change, and its tab opened."] = "이 카메라 스크립트의 사본. 마음대로 바꿀 수 있으며, 그 탭이 열립니다."
L["A copy of this script, yours to change."] = "이 스크립트의 사본. 마음대로 바꿀 수 있습니다."
L["A crown"] = "왕관"
L["A crown and the number in its color."] = "왕관과 그 색의 숫자."
L["A damage dealer (or anyone without a role) shows once their health drops below this. 100% shows them at any damage; lower keeps them hidden through small hits."] = "공격 전담(또는 역할이 없는 사람)은 생명력이 이 아래로 떨어지면 표시됩니다. 100%는 조금만 다쳐도 표시하고, 낮을수록 작은 타격에는 숨겨 둡니다."
L["A dark copy of the letters just behind them, down and to the right."] = "글자 바로 뒤 오른쪽 아래에 어두운 글자 사본."
L["A dark copy of the letters just behind them, to lift them off the world."] = "글자 바로 뒤의 어두운 사본으로 세상 위에서 글자를 띄워 줍니다."
L["A dark fill over the icon, going down as the cooldown runs out."] = "재사용 대기시간이 지나면서 내려가는, 아이콘 위의 어두운 채움."
L["A dark panel behind it all, this dark. 0: none."] = "모든 것 뒤에 이만큼 어두운 판. 0: 없음."
L["A dark panel in the rounded edge of the game's roll frames, in the item's quality color."] = "게임 주사위 창의 둥근 테두리 안에 아이템 품질 색의 어두운 판."
L["A dark panel with a thin line round it, in the item's quality color."] = "아이템 품질 색의 가는 선을 두른 어두운 판."
L["A debuff that brings them up keeps them up while you have any debuff (bar the ones listed below), however long that is, fights included."] = "이것을 띄우는 약화 효과는 내게 약화 효과(아래 목록 제외)가 하나라도 있는 동안, 전투를 포함해 얼마나 오래든 계속 띄워 둡니다."
L["A dungeon"] = "던전"
L["A feared, stunned, polymorphed, rooted or silenced duelist gets an icon of the spell beside their nameplate, with the time left."] = "공포, 기절, 변이, 이동 불가, 침묵에 걸린 결투자의 이름표 옆에 그 주문 아이콘과 남은 시간을 표시합니다."
L["A fight you go into with your mana, rage, energy or the like at rest (rage at 0, mana full...) brings up your resource bar only once it changes: your first cast, your first hit. Going in with it still filling or draining, it comes up straight away. It stays up for the rest of the fight."] = "마나, 분노, 기력 등이 평소 상태(분노 0, 마나 가득...)로 전투에 들어가면 자원 바는 그것이 변할 때 비로소 나타납니다: 첫 시전, 첫 타격. 아직 차오르거나 줄어드는 중에 들어가면 곧바로 나타납니다. 전투가 끝날 때까지 유지됩니다."
L["A film's frame"] = "영화의 한 장면"
L["A flat bubble in a color of your own (the swatch)."] = "직접 고른 색(견본)의 납작한 말풍선."
L["A flat dark bubble."] = "납작하고 어두운 말풍선."
L["A flat fill in your colors on a dark ground, a thin black edge, Arial Narrow, the seconds left."] = "어두운 바탕에 내 색으로 채운 납작한 바, 가는 검은 테두리, Arial Narrow, 남은 초."
L["A glow along the row, a crown and the number in its color."] = "줄을 따라 빛, 왕관과 그 색의 숫자."
L["A golden exclamation mark beside their nameplates' health bars, wherever their plates show (beside their names when just their names show). Always on with Quest mark above. Needs the Nameplates page enabled."] = "이름표가 보이는 곳마다 생명력 바 옆에 황금색 느낌표를 표시합니다(이름만 보일 때는 이름 옆). 위의 '퀘스트 표시'와 함께라면 항상 켜집니다. 이름표 페이지를 사용해야 합니다."
L["A group of your own, to pick its frames and icon."] = "창과 아이콘을 직접 고르는 나만의 그룹."
L["A healer shows once their health drops below this. 100% shows them at any damage; lower keeps them hidden through small hits."] = "치유 전담은 생명력이 이 아래로 떨어지면 표시됩니다. 100%는 조금만 다쳐도 표시하고, 낮을수록 작은 타격에는 숨겨 둡니다."
L["A line of text to copy and paste to friends, who add it with Import a wheel."] = "친구에게 복사해 붙여 줄 한 줄의 문자. 친구는 '휠 가져오기'로 추가합니다."
L["A little icon before each detail: a map, a watch, a quest mark, a skull, coins..."] = "각 정보 앞에 작은 아이콘: 지도, 시계, 퀘스트 표시, 해골, 동전..."
L["A made-up fight for 25 seconds, to see how it looks (Stop ends it). It works with the page off too. Close the settings to see it."] = "25초 동안 가짜 전투를 보여 주어 어떻게 보이는지 확인합니다('중지'로 끝냄). 페이지가 꺼져 있어도 됩니다. 설정을 닫아야 보입니다."
L["A member with a debuff you can dispel shows, at full health too."] = "내가 해제할 수 있는 약화 효과에 걸린 파티원은 생명력이 가득해도 표시됩니다."
L["A member with any debuff at all shows, at full health too."] = "약화 효과에 걸린 파티원은 무엇이든 생명력이 가득해도 표시됩니다."
L["A message shows"] = "메시지가 표시됨"
L["A minimap blip's tooltip, which always shows"] = "미니맵 점의 툴팁(항상 표시됨)"
L["A name of your own for it, shown on the rows. Empty: what starts it."] = "줄에 표시할 이름. 비우면: 시작 원인."
L["A name of your own for this row, shown on the grid and the preview, say Far trash. Empty: its kind's name."] = "격자와 미리 보기에 표시할 이 줄의 이름(예: 먼 잡몹). 비우면: 종류 이름."
L["A name of your own for this row, shown on the grid, say AFK in dungeons. Empty: its trigger's."] = "격자에 표시할 이 줄의 이름(예: 던전에서 자리 비움). 비우면: 발동 조건 이름."
L["A new camera of yours, with a few steps to start from."] = "시작할 단계 몇 개가 들어 있는 새 카메라."
L["A new name for this theme of yours."] = "내 테마의 새 이름."
L["A new rule above the last one, for the fights you pick."] = "고른 전투에 적용할 새 규칙을 마지막 규칙 위에 추가합니다."
L["A new rule at the end, for the places you pick (move it up to read it first)."] = "고른 장소에 적용할 새 규칙을 끝에 추가합니다(먼저 읽게 하려면 위로 옮기세요)."
L["A new rule at the end, for the time of day and places you pick."] = "고른 시간대와 장소에 적용할 새 규칙을 끝에 추가합니다."
L["A new rule for boss fights, first on this tab."] = "우두머리 전투용 새 규칙을 이 탭 맨 앞에 추가합니다."
L["A new script of yours, with a few steps to start from."] = "시작할 단계 몇 개가 들어 있는 새 스크립트."
L["A pet shows once its health drops below this. 100% shows it at any damage."] = "소환수는 생명력이 이 아래로 떨어지면 표시됩니다. 100%는 조금만 다쳐도 표시합니다."
L["A picture: red with a dark outline, on a flat black band, its own colors."] = "그림: 어두운 외곽선의 빨강, 납작한 검은 띠, 고유 색."
L["A plate takes its whole look (mark, colors, opacity) from the first row that fits it, top to bottom; the rows below aren't looked at. Click a row to open its settings: its mark, the plate's colors and opacity, and When it fits. The chips beside its name show what's set apart from the usual. Move a row with its arrows, copy it with its two squares, take it off with its x. Add row puts a new one at the end; its Row line says what it's for: a Kind, for Aggro and Units which of them, Who for just its enemies, neutral units or friends, and Distance for just those within or past 11, 28 or 40 yards (Any unit past 40 yards fades far plates). The same kind again is another row of it (Target (2)), say with a different When for raids. Put a row for just some units above its kind's own row, so it comes first for them. Default, always last, is for plates no row fits: the game's look unless you change it."] = "이름표는 위에서부터 맞는 첫 줄에서 모양 전체(표시, 색, 불투명도)를 가져오며, 그 아래 줄은 보지 않습니다. 줄을 클릭하면 설정이 열립니다: 표시, 이름표 색과 불투명도, '적용 조건'. 이름 옆 칩은 평소와 다르게 설정된 것을 보여 줍니다. 화살표로 줄을 옮기고, 네모 두 개로 복사하고, x로 뺍니다. '줄 추가'는 끝에 새 줄을 넣습니다. 그 '줄' 항목에서 용도를 정합니다: 종류, 위협과 유닛이면 그중 무엇인지, '대상'으로 적만/중립만/아군만, '거리'로 11, 28, 40m 안 또는 밖만(40m 밖의 모든 유닛은 먼 이름표를 흐리게 함). 같은 종류를 다시 넣으면 그 종류의 또 다른 줄(대상 (2))이 되며, 예를 들어 공격대용으로 '적용 조건'을 달리할 수 있습니다. 일부 유닛만을 위한 줄은 그 종류의 기본 줄 위에 두어야 그 유닛에 먼저 적용됩니다. 항상 맨 끝인 '기본'은 어떤 줄에도 맞지 않는 이름표용입니다: 바꾸지 않으면 게임의 모양입니다."
L["A player's class icon in place of their face (NPCs keep theirs)."] = "얼굴 대신 플레이어의 직업 아이콘(NPC는 그대로)."
L["A pretend 8-second cast, on the screen (close the settings to see it)."] = "화면에 8초짜리 가짜 시전을 표시합니다(설정을 닫아야 보입니다)."
L["A profile of your own, a copy of the active one as you have it now, named after it. To copy another profile, right-click it, then Copy profile."] = "지금 상태 그대로의 현재 프로필을 복사해 같은 이름을 붙인 나만의 프로필. 다른 프로필을 복사하려면 그것을 오른쪽 클릭한 뒤 '프로필 복사'를 고르세요."
L["A profile of your own, a copy of the active one as you have it now, named after it. To copy another profile, switch to it first."] = "지금 상태 그대로의 현재 프로필을 복사해 같은 이름을 붙인 나만의 프로필. 다른 프로필을 복사하려면 먼저 그것으로 바꾸세요."
L["A profile preview shows just its own frames"] = "프로필 미리 보기에서 그 프로필의 창만 표시"
L["A quest timer is running"] = "퀘스트 타이머가 진행 중"
L["A quiet flat bar: no icon, spark or border, a soft ground, small outlined text."] = "조용하고 납작한 바: 아이콘, 불꽃, 테두리 없이 부드러운 바탕과 외곽선 있는 작은 글자."
L["A ring of color round it."] = "둘레에 색 고리."
L["A round button with a soft glow when ready."] = "준비되면 은은하게 빛나는 둥근 버튼."
L["A scene of your own. Open it to set its triggers, when it ends, and where it comes among the others."] = "나만의 장면. 열어서 발동 조건, 끝나는 때, 다른 장면 사이의 순서를 정하세요."
L["A script holds 80 steps at most."] = "스크립트에는 최대 80단계까지 넣을 수 있습니다."
L["A set time"] = "정한 시간"
L["A shot is one of the cameras that run while you stand still (cozy, vista, fish or AFK) with numbers of your own for how it sways and zooms. Make one here, then pick it as a scene's camera on the Scenes page. A number you haven't changed follows the camera's own settings."] = "샷은 가만히 서 있을 때 도는 카메라(아늑함, 풍경, 낚시, 자리 비움) 중 하나를, 흔들림과 확대/축소 수치를 직접 정해 쓰는 것입니다. 여기서 만든 뒤 장면 페이지에서 장면의 카메라로 고르세요. 바꾸지 않은 수치는 그 카메라의 설정을 따릅니다."
L["A slider changes nothing until you move it. Higher (in gold) costs frame rate, lower (in blue) saves it. Tick and untick a setting to compare it with the game's own; Reset page leaves them all alone again."] = "슬라이더는 움직이기 전까지 아무것도 바꾸지 않습니다. 높을수록(금색) 프레임을 잡아먹고, 낮을수록(파랑) 아낍니다. 설정을 체크하고 해제하면서 게임 기본값과 비교해 보세요. '페이지 초기화'는 모두 다시 손대지 않은 상태로 돌립니다."
L["A small Reload button at the top of the screen reloads the UI in one click. It stays up with the UI hidden. Drag it to move it. There's a key for it too (Keybinds page)."] = "화면 위의 작은 '다시 불러오기' 버튼으로 한 번에 UI를 다시 불러옵니다. UI를 숨겨도 남아 있습니다. 끌어서 옮기세요. 단축키도 있습니다(단축키 페이지)."
L["A small icon in the bottom right of a chat window, while your mouse is over it, opens that window's lines as text you can select and copy with Ctrl+C."] = "대화창 위에 마우스를 올리면 오른쪽 아래에 작은 아이콘이 나타나며, 클릭하면 그 창의 줄을 선택해서 Ctrl+C로 복사할 수 있는 문자로 엽니다."
L["A small line low on the screen, where a film's subtitles go."] = "영화 자막이 들어가는 화면 아래쪽의 작은 줄."
L["A soft halo round it."] = "둘레에 부드러운 후광."
L["A soft haze around the edges of the screen in the camera modes, as if the camera had focused on you. Each camera mode's page sets its own strength: this turns them all up or down. /cine doftest shows it on demand."] = "카메라 모드에서 카메라가 나에게 초점을 맞춘 듯 화면 가장자리를 부드럽게 흐립니다. 강도는 카메라 모드마다 각 페이지에서 정하며, 이것은 그 전체를 높이거나 낮춥니다. /cine doftest로 바로 볼 수 있습니다."
L["A soft haze around the edges of the screen in this camera mode, as if the camera had focused on you. 0% leaves it off. Moving the slider shows it for a moment. Needs \"Camera haze\" on the Visual Effects page, which also turns it up or down."] = "이 카메라 모드에서 카메라가 나에게 초점을 맞춘 듯 화면 가장자리를 부드럽게 흐립니다. 0%면 끕니다. 슬라이더를 움직이면 잠깐 보여 줍니다. 화면 효과 페이지의 \"카메라 흐림\"이 필요하며, 거기서 전체를 높이거나 낮출 수도 있습니다."
L["A soft haze around the edges of the screen while this camera runs, as if it had focused on you. 0 leaves it off. Needs Camera haze on the Visual Effects page, which also turns it up or down."] = "이 카메라가 도는 동안 나에게 초점을 맞춘 듯 화면 가장자리를 부드럽게 흐립니다. 0이면 끕니다. 화면 효과 페이지의 '카메라 흐림'이 필요하며, 거기서 전체를 높이거나 낮출 수도 있습니다."
L["A string of this script to give to friends."] = "친구에게 줄 이 스크립트의 문자열."
L["A style with +2 has two settings of its own over the one it starts from (the Style tab lists them)."] = "+2가 붙은 스타일은 시작한 스타일 위에 자체 설정이 두 개 있습니다(스타일 탭에 목록이 있습니다)."
L["A tank (by role, or main tank in a raid) shows once their health drops below this. 100% shows tanks always, at full health too."] = "방어 전담(역할 또는 공격대의 메인 탱커)은 생명력이 이 아래로 떨어지면 표시됩니다. 100%는 생명력이 가득해도 항상 표시합니다."
L["A theme of your own, made from the one shown."] = "보이는 테마로 만든 나만의 테마."
L["A thick black border around the letters."] = "글자 둘레의 두꺼운 검은 테두리."
L["A thin black border around the letters."] = "글자 둘레의 가는 검은 테두리."
L["A thin black edge, the icon zoomed in to cut its border, an edge glow when ready, Arial Narrow."] = "가는 검은 테두리, 테두리를 잘라 내도록 확대한 아이콘, 준비되면 가장자리 빛, Arial Narrow."
L["A thin line, no border or spark."] = "가는 선, 테두리나 불꽃 없음."
L["A wave of the game's art creeping in from past the edges on each heartbeat (each second without one). With Blizzard art, or a Game art theme."] = "심장이 뛸 때마다(박동이 없으면 매초) 가장자리 밖에서 게임 그림이 물결처럼 스며듭니다. 블리자드 그림이나 게임 그림 테마와 함께."
L["A whole look in one pick. Changing a setting after it shows Custom; picking Custom puts back your own settings from before the preset."] = "한 번에 고르는 전체 모양. 그 뒤 설정을 바꾸면 '사용자 지정'으로 표시되고, '사용자 지정'을 고르면 프리셋 전의 내 설정으로 돌아갑니다."
L["ANY OF THESE WOULD SHOW IT"] = "다음 중 하나라도 맞으면 표시"
L["Achievement"] = "업적"
L["Across the middle of the screen on a dark band with soft edges, coming in and going slowly, as YOU DIED does."] = "YOU DIED처럼 부드러운 가장자리의 어두운 띠 위에 화면 가운데를 가로질러 천천히 나타났다 사라집니다."
L["Action bars 1-3"] = "행동 단축바 1-3"
L["Add %s"] = "%s 추가"
L["Add a rule"] = "규칙 추가"
L["Add a scene or shot a friend shared (the text from their Share button)."] = "친구가 공유한 장면이나 샷을 추가합니다(친구의 '공유' 버튼으로 나온 문자)."
L["Add a script someone shared with you."] = "누군가 공유해 준 스크립트를 추가합니다."
L["Add a sound"] = "소리 추가"
L["Add a wheel someone shared with you: paste in its text, and read what's on it before you add it."] = "누군가 공유해 준 휠을 추가합니다: 문자를 붙여 넣고, 추가하기 전에 무엇이 들어 있는지 읽어 보세요."
L["Add an emote"] = "감정 표현 추가"
L["Add an emote: %s"] = "감정 표현 추가: %s"
L["Add an icon"] = "아이콘 추가"
L["Add back"] = "다시 추가"
L["Add back all"] = "모두 다시 추가"
L["Add it"] = "추가"
L["Add it to the rows below, with its When set to anywhere but battlegrounds and arenas, out of fights (open its row to change that)."] = "아래 줄에 추가하며, '적용 조건'은 전장과 투기장을 뺀 모든 곳, 비전투 중으로 정해집니다(바꾸려면 그 줄을 여세요)."
L["Add row"] = "줄 추가"
L["Add script"] = "스크립트 추가"
L["Add this zone"] = "이 지역 추가"
L["Add wheel"] = "휠 추가"
L["Added"] = "추가됨"
L["Addon"] = "애드온"
L["Addons installed but not loaded, and the ones supported but not installed."] = "설치했지만 불러오지 않은 애드온과, 지원하지만 설치되지 않은 애드온."
L["Adds \"%s\". A green dot: true where you are now."] = "\"%s\"을(를) 추가합니다. 초록 점: 지금 있는 곳에서 참."
L["Adds \"%s\": true for a tooltip of this kind (one can be more than one: a quest mob is an enemy too). Anything else: none of the others, and every tooltip of the UI."] = "\"%s\"을(를) 추가합니다: 이 종류의 툴팁이면 참(하나가 여러 종류일 수 있음: 퀘스트 몹은 적이기도 함). 그 밖의 것: 다른 어느 것도 아닌 것과 UI의 모든 툴팁."
L["Adds a row at the end of the grid, for any unit to start with, its settings open: pick what it's for on its Row line, and its look."] = "격자 끝에 줄을 추가하고(처음에는 모든 유닛 대상) 설정을 엽니다: '줄' 항목에서 용도와 모양을 고르세요."
L["Adds a theme a friend shared with Share theme."] = "친구가 '테마 공유'로 공유한 테마를 추가합니다."
L["Adds an icon to the wheel, for a command of its own."] = "휠에 아이콘을 추가하고 거기에 명령을 정합니다."
L["After"] = "이후"
L["After a Zone or Subzone card, no other comes for this long, so passing through places quickly doesn't bring one after another. 0: every time."] = "지역 또는 하위 지역 카드가 나온 뒤 이 시간 동안은 다른 카드가 나오지 않아서, 여러 곳을 빨리 지나가도 카드가 줄줄이 나오지 않습니다. 0: 매번."
L["After a fight"] = "전투 후"
L["After a reload (/reload, the Reload button or its key), what you had open opens again: these settings at the page you were on, your bags, the character window, map, spellbook and the game's other windows, and Cinematic's own."] = "다시 불러오기(/reload, '다시 불러오기' 버튼 또는 그 키) 뒤에 열려 있던 것을 다시 엽니다: 보고 있던 페이지의 이 설정, 가방, 캐릭터 창, 지도, 주문책, 그 밖의 게임 창과 Cinematic 창."
L["After swinging behind you, the camera comes round this far to one side, so you see the quest giver past you at an angle rather than straight over your head. 0 stays straight behind you. It turns back behind you as the window closes."] = "뒤쪽으로 돌아간 뒤 카메라가 이만큼 옆으로 돌아서, 퀘스트 NPC가 머리 바로 위가 아니라 비스듬히 나를 지나 보이게 합니다. 0이면 바로 뒤에 머뭅니다. 창이 닫히면 다시 뒤쪽으로 돌아갑니다."
L["After the first pull-back, keep drifting to new random distances (within the limits below), pausing between each. Off: a single pull-back that then holds."] = "처음 물러난 뒤에도 (아래 범위 안에서) 무작위 거리로 계속 흘러가며 사이사이 멈춥니다. 끄면: 한 번만 물러나고 그대로 유지합니다."
L["After you drag the camera, use camera keys or zoom, this camera waits this long, then carries on from your new view."] = "카메라를 끌거나 카메라 키, 확대/축소를 쓰면 이 카메라는 이만큼 기다린 뒤 새 시점에서 이어 갑니다."
L["After you log in or /reload, the camera zooms to the distance below, rather than staying wherever you left it."] = "접속하거나 /reload한 뒤, 카메라가 두었던 곳에 머물지 않고 아래 거리로 확대/축소합니다."
L["After you stop turning, the view holds this long before gliding around to your new facing, in case you turn again. Turning again starts the wait over."] = "방향 전환을 멈춘 뒤, 다시 돌 경우에 대비해 이 시간 동안 시점을 유지했다가 새 방향으로 부드럽게 돌아갑니다. 다시 돌면 대기를 처음부터 다시 셉니다."
L["Aggro"] = "위협"
L["Aggro on a healer"] = "치유 전담에게 위협"
L["Aggro on non-tank"] = "방어 전담 아닌 사람에게 위협"
L["Aggro on not you"] = "내가 아닌 사람에게 위협"
L["Aggro on you"] = "나에게 위협"
L["Align:"] = "정렬:"
L["All"] = "모두"
L["All addons"] = "모든 애드온"
L["All addons %.1f%% (%.3f ms)"] = "모든 애드온 %.1f%% (%.3f ms)"
L["All addons (the game's figures, ms a frame)"] = "모든 애드온 (게임 수치, 프레임당 ms)"
L["All bosses"] = "모든 우두머리"
L["All changes"] = "모든 변경 사항"
L["All marks"] = "모든 표시"
L["All of them"] = "전부"
L["All rows"] = "모든 줄"
L["Along the top"] = "위쪽을 따라"
L["Already on this card (or the card is full). Right-click: play it."] = "이미 이 카드에 있습니다(또는 카드가 가득 찼습니다). 오른쪽 클릭: 재생."
L["Also for NPCs with nothing to say about quests (innkeepers, guards...), as the \"Talk to a quest giver\" event. Off: only when they have a quest to offer or take in, or a \"(Quest)\" line (the \"Talk about a quest\" event)."] = "퀘스트와 관계없는 NPC(여관주인, 경비병...)에게도 \"퀘스트 NPC와 대화\" 이벤트로 적용합니다. 끄면: 줄 퀘스트나 받을 퀘스트가 있거나 \"(퀘스트)\" 줄이 있을 때만(\"퀘스트에 관해 대화\" 이벤트)."
L["Always backed up just before Delete and Reset, and the saved version on Save."] = "삭제와 초기화 직전에, 그리고 저장할 때 저장된 버전을 항상 백업합니다."
L["Always is ticked"] = "'항상'이 체크됨"
L["Always is ticked on the Tooltips row"] = "툴팁 줄에 '항상'이 체크됨"
L["Always list your own roll"] = "내 주사위는 항상 목록에 표시"
L["Always show the waypoint is on"] = "'목적지 항상 표시'가 켜져 있음"
L["Always show their"] = "항상 표시할 것:"
L["Amber while you're behind, teal once you lead (or your own two)."] = "뒤처지면 호박색, 앞서면 청록색(또는 직접 고른 두 색)."
L["Amount"] = "양"
L["An NPC you're talking to (its window open, or closed in the last 30 seconds), your target, or a party NPC talking (their chat bubbles). The camera zooms in and swings toward whoever's talking, drifting while they go on, and turns back once no one's talked for a while. Moving hands the camera straight back to you. Its settings are under Chat Cam on the Camera Settings page."] = "대화 중인 NPC(창이 열려 있거나 30초 안에 닫힘), 대상, 또는 말하는 파티 NPC(말풍선). 카메라가 말하는 쪽으로 확대하며 돌아가고, 말하는 동안 흘러가다가 한동안 아무도 말하지 않으면 원래대로 돌아옵니다. 움직이면 곧바로 카메라를 돌려받습니다. 설정은 카메라 설정 페이지의 '대화 카메라'에 있습니다."
L["An addon"] = "애드온"
L["An edge"] = "가장자리"
L["An icon before the words: each event's own (a map for a zone, a skull for a boss...), unless it's given another with the button beside this."] = "글자 앞의 아이콘: 이벤트마다 고유한 것(지역은 지도, 우두머리는 해골...). 옆 버튼으로 다른 것을 정하지 않았다면."
L["Animation:"] = "애니메이션:"
L["Another of the game's effects over the first, added on as light and cut by the same edge (not over an edge like the red one). Theme's pick: the one picked to go with your theme, if any."] = "첫 효과 위에 덧씌우는 게임의 또 다른 효과. 빛으로 더해지고 같은 가장자리로 잘립니다(빨간 것처럼 가장자리 위에는 아님). 테마 선택: 테마에 맞춰 고른 것(있다면)."
L["Another thing that starts this scene: any one of its triggers starts it."] = "이 장면을 시작하는 또 다른 원인: 발동 조건 중 하나만 맞아도 시작합니다."
L["Any"] = "아무거나"
L["Any distance"] = "모든 거리"
L["Any distance: all of them, near or far. Within or past 11, 28 or 40 yards: just those that far from you, say Any unit past 40 yards to fade the plates far off. 40 yards asks a 40-yard spell on your action bars; with none there, the row fits no unit past 28 yards."] = "모든 거리: 가깝든 멀든 전부. 11, 28, 40m 안 또는 밖: 그만큼 떨어진 것만. 예를 들어 '40m 밖의 모든 유닛'으로 먼 이름표를 흐리게 합니다. 40m는 행동 단축바에 있는 40m 주문으로 확인하며, 없으면 그 줄은 28m 밖의 유닛에는 맞지 않습니다."
L["Any edge"] = "아무 가장자리"
L["Any enemy attacking a healer (you too, if you're one): for a healer, who's after you or the other healers; for a tank, the ones to pull off them."] = "치유 전담을 공격하는 모든 적(내가 치유 전담이면 나도): 치유 전담에게는 나나 다른 치유 전담을 노리는 적, 방어 전담에게는 떼어 내야 할 적."
L["Any enemy attacking a player who isn't a tank (you too, unless you're one): for a healer, who's in trouble; for a tank, the ones to taunt. A pet tanking doesn't count."] = "방어 전담이 아닌 플레이어를 공격하는 모든 적(내가 방어 전담이 아니면 나도): 치유 전담에게는 위험한 사람, 방어 전담에게는 도발할 적. 소환수가 방어하는 것은 치지 않습니다."
L["Any enemy attacking you (you have its aggro). Above the Target row, or that one wins on your target. A cell set to Your target's takes the Target row's; change it to set this one apart."] = "나를 공격하는 모든 적(내가 위협을 가짐). 대상 줄보다 위에 두세요. 아니면 내 대상에는 대상 줄이 이깁니다. '내 대상의 것'으로 정한 칸은 대상 줄 값을 따르므로, 따로 정하려면 바꾸세요."
L["Any enemy in a fight attacking someone friendly other than you: a group member, a pet or another player. For a tank, the ones to pick up."] = "전투 중 내가 아닌 아군(파티원, 소환수, 다른 플레이어)을 공격하는 모든 적. 방어 전담에게는 데려와야 할 적."
L["Any enemy in a fight attacking whoever its ticks say: you or someone friendly other than you, and their role (no role set counts as DPS; a pet only with all three roles ticked)."] = "전투 중 체크한 대상을 공격하는 모든 적: 나 또는 내가 아닌 아군과 그 역할(역할이 없으면 공격 전담으로 침. 소환수는 세 역할을 모두 체크했을 때만)."
L["Any fight"] = "모든 전투"
L["Any living NPC, normal or elite."] = "살아 있는 모든 NPC, 일반이든 정예든."
L["Any time"] = "언제든"
L["Any unit"] = "모든 유닛"
L["Anyone"] = "누구든"
L["Anything a player controls: pets, totems and guardians."] = "플레이어가 조종하는 모든 것: 소환수, 토템, 수호물."
L["Anything else"] = "그 밖의 것"
L["Anything targeted"] = "대상으로 지정된 모든 것"
L["Arcade"] = "아케이드"
L["Arenas"] = "투기장"
L["Arrived"] = "도착함"
L["Arrow"] = "화살표"
L["Arrows and bullets at a vendor get a Fill button: it buys enough to fill your quiver or ammo pouch, topping up its part stacks and filling its empty slots, as far as your money goes. Point at it to see how many and the cost first."] = "상인에게서 화살과 탄환에 '채우기' 버튼이 붙습니다: 가진 돈이 허락하는 만큼 화살통이나 탄약 주머니를 채울 만큼 사서, 덜 찬 묶음을 채우고 빈 칸도 채웁니다. 먼저 가리키면 수량과 비용을 볼 수 있습니다."
L["Art"] = "그림"
L["As NPCs talk near you, the camera zooms in and swings toward whoever's talking (by their chat bubble), drifting slowly while they go on. It swings again only when someone else speaks, and turns back and zooms out once no one's talked for a while. Moving, or moving the camera yourself, hands it straight back to you."] = "근처에서 NPC가 말하면 카메라가 (말풍선을 기준으로) 말하는 쪽으로 확대하며 돌아가고, 말하는 동안 천천히 흘러갑니다. 다른 누군가가 말할 때만 다시 돌며, 한동안 아무도 말하지 않으면 원래대로 돌아와 축소합니다. 움직이거나 카메라를 직접 움직이면 곧바로 카메라를 돌려받습니다."
L["As Roll Vision has always looked (the defaults)."] = "Roll Vision의 원래 모습(기본값)."
L["As a fight starts or as it ends. Click to switch."] = "전투가 시작될 때 또는 끝날 때. 클릭해서 바꿉니다."
L["As it always has, in its own look (the Style tab)."] = "원래대로, 고유한 모양으로(스타일 탭)."
L["As it comes: amber when you're behind, teal when you lead, a thin border."] = "그대로: 뒤처지면 호박색, 앞서면 청록색, 가는 테두리."
L["As it comes: nothing changed."] = "그대로: 바뀐 것 없음."
L["As it shows"] = "표시될 때"
L["As it starts, the camera rises this much to look down on your body; it comes back down afterwards. The game stops it just short of straight down, so a big number means \"as high as it goes\". 0 keeps your angle."] = "시작될 때 카메라가 이만큼 올라가 내 몸을 내려다보며, 나중에 다시 내려옵니다. 게임은 수직 바로 앞에서 멈추므로 큰 숫자는 \"최대한 높이\"를 뜻합니다. 0이면 각도를 유지합니다."
L["As it swings round, the camera also comes down this much toward the ground, so it feels low and close rather than looking down from above. It stops at the ground, so a big number just means \"as low as it goes\". 0 keeps your angle."] = "돌아가는 동안 카메라가 이만큼 땅 쪽으로 내려와서 위에서 내려다보는 대신 낮고 가까운 느낌이 납니다. 땅에서 멈추므로 큰 숫자는 \"최대한 낮게\"를 뜻합니다. 0이면 각도를 유지합니다."
L["As little UI as possible: nameplates show only for enemies in fights, and fights don't bring the letterbox down. Fights bring up only your resource bar and the Cooldown Manager, the cast bar shows all through CineMode, your health shows at the screen's edges and your personal resource display fades in as it drops (Vitals Vision), and every camera can start music."] = "UI를 최소한으로: 이름표는 전투 중인 적에게만 보이고, 전투가 레터박스를 내리지 않습니다. 전투 때는 자원 바와 재사용 대기시간 관리자만 나타나고, 시전 바는 CineMode 내내 보이며, 생명력은 화면 가장자리에 표시되고 줄어들면 개인 자원 표시가 나타납니다(Vitals Vision). 모든 카메라가 음악을 틀 수 있습니다."
L["As the Style hub's General page says."] = "스타일 허브의 일반 페이지 설정대로."
L["As the Visions hub's Style page says."] = "Visions 허브의 스타일 페이지 설정대로."
L["As the boss is pulled, as it dies or as your group wipes. Click to switch."] = "우두머리를 풀링할 때, 처치할 때 또는 파티가 전멸할 때. 클릭해서 바꿉니다."
L["As the card shows."] = "카드가 보여 주는 대로."
L["As the game's options say (class colors, or green)."] = "게임 옵션대로(직업 색 또는 초록)."
L["As you cast your Hearthstone, Astral Recall or a teleport, a portal's glowing rim closes in around you, brighter and turning quicker as the cast fills, and flashes as you're whisked away. It shows whenever the tele camera would play for that cast (Cameras), with or alongside it."] = "귀환석, 영혼의 귀환 또는 순간이동을 시전하면 차원문의 빛나는 테두리가 나를 둘러싸며 좁혀 오고, 시전이 찰수록 밝아지고 빨리 돌다가 이동하는 순간 번쩍입니다. 그 시전에 순간이동 카메라가 재생될 때마다(카메라) 함께 표시됩니다."
L["As you land, the camera glides back to the zoom distance you had when you took off. If you zoomed yourself on the way, it stays where you put it."] = "착륙하면 카메라가 이륙할 때의 확대/축소 거리로 부드럽게 돌아갑니다. 도중에 직접 확대/축소했다면 그대로 둡니다."
L["At full"] = "가득 찼을 때"
L["At most this many rows: #1 on down, and you in the last row if you're further down than that."] = "최대 이만큼의 줄: 1위부터 아래로, 내가 그보다 아래라면 마지막 줄에 나."
L["At the start of a fight"] = "전투가 시작될 때"
L["Auras"] = "효과"
L["Auras anchored to another frame fade with that frame."] = "다른 창에 붙은 효과는 그 창과 함께 흐려집니다."
L["Auto"] = "자동"
L["Auto (%s)"] = "자동 (%s)"
L["Auto-running. The camera's settings are under Auto-run Cam on the Camera Settings page."] = "자동 달리기 중. 카메라 설정은 카메라 설정 페이지의 '자동 달리기 카메라'에 있습니다."
L["Auto-walking (auto-run in walk mode). The camera's settings are under RP Walk Cam on the Camera Settings page."] = "자동 걷기 중(걷기 모드에서 자동 달리기). 카메라 설정은 카메라 설정 페이지의 'RP 걷기 카메라'에 있습니다."
L["Automatic"] = "자동"
