L["Big words"] = "큰 글자"
L["Big words across the middle of the screen on a dark band, as YOU DIED shows: a win in gold, a loss in red (the Victory and Death styles' looks)."] = "YOU DIED처럼 화면 가운데를 가로지르는 어두운 띠 위의 큰 글자: 승리는 금색, 패배는 빨강(승리와 죽음 스타일의 모양)."
L["Big words in the middle of the screen, the rest under them."] = "화면 가운데에 큰 글자, 나머지는 그 아래."
L["Black"] = "검정"
L["Black edges"] = "검은 가장자리"
L["Black edges closing in from the screen's sides as the cast fills, then over the whole screen at the last moment."] = "시전이 찰수록 화면 양옆에서 검은 가장자리가 좁혀 오다가, 마지막 순간 화면 전체를 덮습니다."
L["Blackout"] = "암전"
