L["Bloodsail Buccaneers"] = "붉은해적단"
L["Blows toward your waypoint for 30 seconds (or, with none, a pretend one off to your right: turn toward it and the wind follows). It works with the page off too. Close the settings to see it."] = "30초 동안 목적지를 향해 바람이 붑니다(목적지가 없으면 오른쪽에 가짜 목적지: 그쪽으로 돌면 바람이 따라옵니다). 페이지가 꺼져 있어도 됩니다. 설정을 닫아야 보입니다."
L["Blue"] = "파랑"
L["Blue, as the game's names over their heads (green while they're PvP flagged, as there too)."] = "게임의 머리 위 이름처럼 파랑(PvP 활성화 중에는 거기처럼 초록)."
L["Bold"] = "굵게"
L["Border"] = "테두리"
L["Border:"] = "테두리:"
L["Borderless flat bars in class colors, small white names."] = "직업 색의 테두리 없는 납작한 바, 작은 흰 이름."
L["Borderless flat bars on a faint ground, small names."] = "옅은 바탕 위의 테두리 없는 납작한 바, 작은 이름."
L["Boss"] = "우두머리"
L["Boss %d"] = "우두머리 %d"
