L["Bring back a built-in scene you deleted, with its settings as they were."] = "삭제한 기본 장면을 원래 설정대로 되살립니다."
L["Brings up the window with three made-up drops, your group picking and rolling on them over a few seconds. Change things here while it's up to see them."] = "가짜 전리품 세 개가 담긴 창을 띄우고, 몇 초에 걸쳐 파티가 고르고 주사위를 굴립니다. 떠 있는 동안 여기서 바꾸면 바로 보입니다."
L["Bubble"] = "말풍선"
L["Bubble:"] = "말풍선:"
L["Buff on you"] = "나에게 걸린 강화 효과"
L["Buff: %s"] = "강화 효과: %s"
L["Buffs not in the Cooldown Manager now"] = "지금 재사용 대기시간 관리자에 없는 강화 효과"
L["Building detail distance"] = "건물 세부 묘사 거리"
L["Built in"] = "기본 제공"
L["Built in, changed by you: change anything. Reset puts ours back. The camera itself still runs on its own code: set a row to this script to use it instead."] = "기본 제공, 내가 바꿈: 무엇이든 바꿀 수 있습니다. 초기화하면 원래대로 돌아갑니다. 카메라 자체는 여전히 자체 코드로 돌아갑니다: 대신 이것을 쓰려면 줄을 이 스크립트로 정하세요."
L["Built in, from your settings: change anything, and it's kept as yours of it (Reset puts ours back). The camera itself still runs on its own code: set a row to this script to use it instead."] = "기본 제공, 내 설정에서 만듦: 무엇이든 바꾸면 내 것으로 보관됩니다(초기화하면 원래대로). 카메라 자체는 여전히 자체 코드로 돌아갑니다: 대신 이것을 쓰려면 줄을 이 스크립트로 정하세요."
