L["Camera settings that aren't on the Scripts page yet, a tab for each camera that has some. The rest of each camera's settings are on the Scripts page, under the steps they make; the Scenes page has what starts each one."] = "아직 스크립트 페이지에 없는 카메라 설정. 설정이 있는 카메라마다 탭이 있습니다. 각 카메라의 나머지 설정은 스크립트 페이지에서 그 설정이 만드는 단계 아래에 있고, 무엇이 각 카메라를 시작하는지는 장면 페이지에 있습니다."
