L["Cast Fishing (or any event set to it on the Scenes page): the vista camera, made for fishing. The camera glides around behind you and sways only a little either side, so your bobber stays in view. It carries on after the cast until you move or jump."] = "낚시 시전(또는 장면 페이지에서 그것으로 정한 이벤트): 낚시용으로 만든 풍경 카메라. 카메라가 뒤쪽으로 부드럽게 돌아가 좌우로 조금만 흔들려서 찌가 계속 보입니다. 시전 뒤에도 움직이거나 점프할 때까지 이어집니다."
L["Cast bar is the bar under the target and focus frames as they cast."] = "시전 바는 대상과 주시 대상 프레임 아래에서 시전할 때 나타나는 바입니다."
L["Cast bar style"] = "시전 바 스타일"
L["Casting your Hearthstone or a teleport, the camera swings round in front of you, quickly enough to be there before you go, then spins around you faster and faster as it zooms in. Cancel the cast and it goes back to where it was; once you're there, it swings around behind you. Its music, haze and tooltips follow the Cozy Cam's settings. The events on the Scenes page can also make it wait a moment."] = "귀환석이나 순간이동을 시전하면 카메라가 떠나기 전에 도착할 만큼 빠르게 앞쪽으로 돌아간 뒤, 확대하면서 점점 빠르게 주위를 돕니다. 시전을 취소하면 원래 자리로 돌아가고, 도착하면 뒤쪽으로 돌아갑니다. 음악, 흐림, 툴팁은 아늑한 카메라 설정을 따릅니다. 장면 페이지의 이벤트로 잠시 기다리게 할 수도 있습니다."
L["Center"] = "가운데"
