L["Clean Up Bags leaves the part stack of arrows or bullets last, but you shoot from the first stack, so a full one would run down and leave you with two part stacks. Once the bags are cleaned up, the smallest stack is moved first, to be shot first."] = "가방 정리는 덜 찬 화살이나 탄환 묶음을 맨 뒤에 두지만, 사격은 첫 묶음부터 쓰므로 가득 찬 묶음이 줄어 덜 찬 묶음이 두 개가 됩니다. 가방 정리가 끝나면 가장 작은 묶음을 앞으로 옮겨 먼저 쏘게 합니다."
L["Clear"] = "비우기"
