L["Dead members are hidden whatever their health, debuffs or role (unless one is your target). How much of them still shows. 0% hides them completely."] = "죽은 파티원은 생명력, 약화 효과, 역할과 관계없이 숨겨집니다(대상이 아니라면). 그래도 얼마나 보일지 정합니다. 0%는 완전히 숨깁니다."
