L["Debuffs that last longer than this (their full time, not what's left: Deserter, Resurrection Sickness...) don't bring them up, nor keep them up until gone. Not in fights, when what they are can't be seen. Buffs always do."] = "이보다 오래 지속되는 약화 효과(남은 시간이 아니라 전체 시간: 탈영병, 부활 후유증...)는 띄우지도, 사라질 때까지 유지하지도 않습니다. 무엇인지 알 수 없는 전투 중에는 적용되지 않습니다. 강화 효과는 항상 띄웁니다."
