L["Delete the scene %s and its settings?"] = "%s 장면과 그 설정을 삭제하시겠습니까?"
L["Delete the scene %s? It starts no camera until you bring it back with Add back, above the rows (its settings are kept)."] = "%s 장면을 삭제하시겠습니까? 줄 위의 '다시 추가'로 되살릴 때까지 카메라를 시작하지 않습니다(설정은 보관됩니다)."
L["Delete the shot %s? Scenes that played it go back to its camera."] = "%s 샷을 삭제하시겠습니까? 그것을 재생하던 장면은 원래 카메라로 돌아갑니다."
L["Delete the theme %s?"] = "%s 테마를 삭제하시겠습니까?"
L["Delete the wheel %s?"] = "%s 휠을 삭제하시겠습니까?"
L["Delete this scene of your own, with its copies."] = "이 나만의 장면과 그 사본을 삭제합니다."
L["Delete this scene: its rows go and it starts no camera. Add back, above the rows, brings it back with its settings."] = "이 장면 삭제: 줄이 사라지고 카메라를 시작하지 않습니다. 줄 위의 '다시 추가'로 설정과 함께 되살릴 수 있습니다."
L["Delete this shot. Scenes that played it go back to its camera."] = "이 샷을 삭제합니다. 그것을 재생하던 장면은 원래 카메라로 돌아갑니다."
L["Delete wheel"] = "휠 삭제"
L["Deleted"] = "삭제됨"
L["Deleted %s, kept until %s"] = "%s 삭제됨, %s까지 보관"
L["Deletes this script (click twice). Rows set to it go back to no camera."] = "이 스크립트를 삭제합니다(두 번 클릭). 이것으로 정한 줄은 카메라 없음으로 돌아갑니다."
L["Deletes this theme of yours."] = "이 나만의 테마를 삭제합니다."
L["Deletes this wheel, and takes its keys off."] = "이 휠을 삭제하고 그 키 지정도 풉니다."
L["Departing"] = "출발"
L["Describe the camera:"] = "카메라 설명:"
L["Detailed"] = "자세히"
L["Detailed CPU recording  %d:%02d"] = "상세 CPU 기록  %d:%02d"
L["Detailed CPU recording for %d seconds: play as usual."] = "%d초 동안 상세 CPU 기록 중: 평소처럼 플레이하세요."
L["Details"] = "세부 정보"
L["Dialogue"] = "대화"
L["Diamond"] = "마름모"
L["Dim"] = "흐릿함"
L["Discovered"] = "발견함"
L["Do /%s"] = "/%s 하기"
L["Dock"] = "도킹"
L["Dots:"] = "점:"
L["Drag over the lines you want (or Select all), then press Ctrl+C to copy them."] = "원하는 줄 위로 끌어서 고르고(또는 '모두 선택'), Ctrl+C로 복사하세요."
L["Drag to move it."] = "끌어서 옮기세요."
L["Dragging the window moves only it, not the game's roll frames, and dragging those moves only them, so the two can sit anywhere on the screen. The window comes up where you last dropped it. Until you've dragged it, it comes up by the game's roll frames as usual. Its dragging works even with \"Drag windows to move them\" off."] = "창을 끌면 그 창만 움직이고 게임 주사위 창은 움직이지 않으며, 주사위 창을 끌면 그것만 움직이므로 둘을 화면 어디에든 둘 수 있습니다. 창은 마지막으로 놓은 곳에 나타납니다. 끌기 전까지는 평소처럼 게임 주사위 창 옆에 나타납니다. '창을 끌어서 옮기기'가 꺼져 있어도 끌 수 있습니다."
L["Drifting gas"] = "떠도는 가스"
L["Drops the rule: its ticks, as they were, decide again."] = "규칙을 버립니다: 원래 체크 상태가 다시 정합니다."
L["Drops the rule: the row's dropdowns decide again, ticked as they were before."] = "규칙을 버립니다: 줄의 드롭다운이 이전 체크 상태대로 다시 정합니다."
L["Duel"] = "결투"
L["Duel Vision"] = "Duel Vision"
L["Duel Vision test: not shown now (%s)."] = "Duel Vision 시험: 지금은 표시 안 됨 (%s)."
L["Duel starts"] = "결투 시작"
L["Dungeon"] = "던전"
L["Dungeon done"] = "던전 완료"
L["Dungeon line"] = "던전 줄"
L["Dungeons & raids"] = "던전 및 공격대"
L["Dying while a boss fight is on, you keep your own view to watch the rest of it. The death camera starts once the encounter ends (a kill or a wipe), if you're still dead."] = "우두머리 전투 중에 죽으면 나머지 전투를 지켜볼 수 있도록 내 시점을 유지합니다. 교전이 끝나면(처치 또는 전멸) 아직 죽어 있을 경우 죽음 카메라가 시작됩니다."
L["Dying, until you release or are resurrected. The camera's settings are under Death Cam on the Camera Settings page."] = "죽은 뒤 영혼을 해방하거나 부활할 때까지. 카메라 설정은 카메라 설정 페이지의 '죽음 카메라'에 있습니다."
L["Each Vision's own"] = "각 Vision 고유"
L["Each bar a share of the screen's height."] = "각 바가 화면 높이의 일정 비율."
L["Each dot its player's class icon."] = "각 점이 그 플레이어의 직업 아이콘."
L["Each event's card on or off, and where it shows."] = "이벤트별 카드 켜기/끄기와 표시 위치."
L["Each fight"] = "각 전투"
L["Each line slides up from below the bottom of the screen, as if from behind the camera, instead of just fading in."] = "각 줄이 그냥 나타나지 않고, 카메라 뒤에서 나오듯 화면 아래 밖에서 미끄러져 올라옵니다."
L["Each moment's card has a button for each emote under it, in that order. Untick a moment for no card at all. + opens a moment."] = "각 순간의 카드 아래에는 감정 표현마다 버튼이 그 순서대로 있습니다. 순간을 해제하면 카드가 전혀 나오지 않습니다. +로 순간을 엽니다."
L["Each move also tilts the camera to a random angle between the down and up limits. 0 on both keeps it level."] = "움직일 때마다 카메라를 아래/위 한계 사이의 무작위 각도로 기울입니다. 둘 다 0이면 수평을 유지합니다."
L["Each page as its own defaults have it (the game's look)."] = "각 페이지의 기본값대로(게임의 모양)."
L["Each player's number at the end of their row once the game reveals the rolls. Unticked: just who won."] = "게임이 주사위 결과를 공개하면 각 플레이어의 숫자를 줄 끝에 표시합니다. 해제: 누가 이겼는지만."
L["Each row is a scene: when one of its triggers happens, it plays its camera. When two scenes are on at once, a Hearthstone or teleport cast comes first, then logging out, going AFK, the latest emote, a drawn weapon, a campfire, and standing still last. Click a row to open its settings: its camera, Music and CineMode, When it may start, its triggers, and anything it needs. The chips beside its name show what's set apart from the usual. Where its When doesn't fit, a row starts no camera. Untick the box at the start of a row to turn it off for now."] = "줄마다 장면입니다: 발동 조건 중 하나가 일어나면 그 카메라를 재생합니다. 두 장면이 동시에 켜지면 귀환석이나 순간이동 시전이 먼저, 다음으로 로그아웃, 자리 비움, 최근 감정 표현, 무기 꺼내기, 모닥불 순이고 가만히 서 있기가 마지막입니다. 줄을 클릭하면 설정이 열립니다: 카메라, 음악과 CineMode, 시작해도 되는 때('적용 조건'), 발동 조건, 필요한 것. 이름 옆 칩은 평소와 다르게 설정된 것을 보여 줍니다. '적용 조건'에 맞지 않는 곳에서는 줄이 카메라를 시작하지 않습니다. 잠시 끄려면 줄 앞의 상자를 해제하세요."
L["Each time the camera starts, it picks clockwise or anticlockwise at random (and keeps to it until it stops)."] = "카메라가 시작될 때마다 시계 방향이나 반시계 방향을 무작위로 고릅니다(멈출 때까지 유지)."
L["Earlier around the wheel (the first is at the top)."] = "휠에서 더 앞쪽(첫 번째가 맨 위)."
L["Edge darkness"] = "가장자리 어둡기"
L["Edge pulse"] = "가장자리 맥박"
L["Edge reach"] = "가장자리 범위"
L["Edge:"] = "가장자리:"
L["Edges creep in over"] = "가장자리가 스며드는 시간"
L["Edges lift as you near your body"] = "시체에 가까워지면 가장자리가 걷힘"
L["Edges reach in"] = "가장자리가 들어오는 정도"
L["Edit"] = "편집"
L["Edit Mode keeps its old list of layouts until you reload, and saving there before then would undo this. Reload now?"] = "편집 모드는 다시 불러오기 전까지 예전 레이아웃 목록을 유지하므로, 그 전에 거기서 저장하면 이것이 취소됩니다. 지금 다시 불러오시겠습니까?"
L["Edit as a rule"] = "규칙으로 편집"
L["Edit style"] = "스타일 편집"
L["Editing"] = "편집 중"
L["Edwin VanCleef"] = "에드윈 밴클리프"
L["Elite NPC"] = "정예 NPC"
L["Elite near (11 yards)"] = "근처의 정예 (11m)"
L["Elite near (28 yards)"] = "근처의 정예 (28m)"
L["Elite near (40 yards)"] = "근처의 정예 (40m)"
L["Elite/rare icon"] = "정예/희귀 아이콘"
L["Emote"] = "감정 표현"
L["Emote Vision"] = "Emote Vision"
L["Emote Vision test: you'd %s %s."] = "Emote Vision 시험: %s %s 할 것입니다."
L["Emote Vision:"] = "Emote Vision:"
L["Emotes (someone's /point, an NPC that laughs or looks around) never have a bubble: they show with the off-screen bubbles too, in a bubble with no tail so they don't read as speech, instead of bringing up chat."] = "감정 표현(누군가의 /point, 웃거나 둘러보는 NPC)은 말풍선이 없습니다: 대화창을 띄우는 대신 화면 밖 말풍선과 함께, 대사로 보이지 않도록 꼬리 없는 말풍선에 표시합니다."
L["Emotes: the command, with or without its slash. Spells and buffs: the name in your game language, or a spell ID (works in any language). Places: the zone or subzone name as the game shows it."] = "감정 표현: 명령어(빗금은 있어도 없어도 됨). 주문과 강화 효과: 게임 언어로 된 이름 또는 주문 ID(어떤 언어에서도 작동). 장소: 게임에 보이는 지역 또는 하위 지역 이름."
L["Empties the rule."] = "규칙을 비웁니다."
L["Empty: its ticks decide."] = "비우면: 체크 상태가 정합니다."
L["Enable Cameras"] = "카메라 사용"
L["Enable Style"] = "스타일 사용"
L["Enable Visual Effects"] = "화면 효과 사용"
L["Encounter"] = "교전"
L["Encounter bar"] = "교전 바"
L["Ending"] = "끝"
L["Ends"] = "끝남"
L["Enemy"] = "적"
L["Enemy targeted"] = "적을 대상으로 지정"
L["Entering combat"] = "전투 시작"
L["Epic and up"] = "영웅 등급 이상"
L["Essential"] = "필수"
L["Essential Cooldowns"] = "필수 재사용 대기시간"
L["Essential: stay up while a cooldown is recharging"] = "필수: 재사용 대기시간이 충전되는 동안 유지"
L["Event boxes (top of the screen)"] = "이벤트 상자 (화면 위쪽)"
L["Events"] = "이벤트"
L["Every Style page at once: a switch for them all, and the settings they share. Each page's shared settings start on General and follow it; change one on its page and it's that page's own."] = "모든 스타일 페이지를 한 번에: 전체 스위치와 공유 설정. 각 페이지의 공유 설정은 일반 페이지 값으로 시작해 그것을 따르며, 페이지에서 하나를 바꾸면 그 페이지 고유 값이 됩니다."
L["Every Vision's words bigger or smaller, times each one's own size on its page (cards too)."] = "모든 Vision의 글자를 크거나 작게. 각 페이지에서 정한 크기에 곱해집니다(카드도)."
L["Every Vision's words that follow this page. Each Vision's own: the game's font, or the one its page starts with."] = "이 페이지를 따르는 모든 Vision의 글자. 각 Vision 고유: 게임 글꼴 또는 그 페이지의 처음 글꼴."
L["Every camera's settings are on the Scripts page now."] = "이제 모든 카메라 설정은 스크립트 페이지에 있습니다."
L["Every camera, built in and yours: click to pick another."] = "기본 제공과 내 것을 포함한 모든 카메라: 클릭해서 다른 것을 고르세요."
L["Every camera, made of small steps: rotate, tilt, zoom, sway, wait, and Together and Repeat for steps at once or again. Stop rules say what happens when you move the camera, walk, zoom, a fight starts or its trigger ends. The built-in ones are our own cameras' steps, with your settings: set a row on the Scenes page to one to run it instead of the camera, or Copy it to make it yours. A hollow dot: that camera isn't a script yet."] = "모든 카메라는 작은 단계로 이루어집니다: 회전, 기울이기, 확대/축소, 흔들기, 대기, 그리고 여러 단계를 함께 또는 다시 하는 '함께'와 '반복'. 멈춤 규칙은 카메라를 움직이거나, 걷거나, 확대/축소하거나, 전투가 시작되거나, 발동 조건이 끝날 때 어떻게 할지 정합니다. 기본 제공 스크립트는 내 설정이 들어간 우리 카메라의 단계입니다: 장면 페이지에서 줄을 그것으로 정하면 카메라 대신 실행되고, 복사하면 내 것이 됩니다. 속이 빈 점: 그 카메라는 아직 스크립트가 아닙니다."
L["Every card's words bigger or smaller, for a big or wide screen (a card in a letterbox bar goes by the bar's height instead)."] = "모든 카드의 글자를 크거나 작게. 큰 화면이나 와이드 화면용(레터박스 바 안의 카드는 바 높이를 따름)."
L["Every change made to Cinematic, newest first, as written when it was made (in English)."] = "Cinematic의 모든 변경 사항. 최신순이며 만들 당시 쓴 그대로(영어)입니다."
L["Every fight"] = "모든 전투"
L["Every kind of cast bar looks as this tab says until its own tab has Use default settings unticked."] = "모든 종류의 시전 바는 자체 탭에서 '기본 설정 사용'을 해제하기 전까지 이 탭대로 보입니다."
L["Every moment that puts words on your screen, as a card: going into a fight and coming out of it, a boss, a new zone, what you did last time, the time of day, a place under attack, a duel, your death. A row for each: its tick, the style it uses and where it shows; click it for its settings. How they look: the Style tab. One card at a time: a more important one cuts in, a less important one waits for it."] = "화면에 글자를 띄우는 모든 순간을 카드로: 전투 시작과 끝, 우두머리, 새 지역, 지난번에 한 일, 시간대, 공격받는 장소, 결투, 죽음. 줄마다 체크, 사용할 스타일, 표시 위치가 있고, 클릭하면 설정이 열립니다. 모양: 스타일 탭. 카드는 한 번에 하나: 더 중요한 카드가 끼어들고, 덜 중요한 카드는 기다립니다."
L["Every moment's emotes as they come."] = "모든 순간의 감정 표현 그대로."
L["Every other plate, when no row above fits it: the game's own look to start with (no mark, its own colors). Give it a mark or an Also color to change them all."] = "위의 어떤 줄에도 맞지 않는 나머지 모든 이름표: 처음에는 게임의 모양(표시 없음, 고유 색). 표시나 '추가 색'을 주면 모두 바뀝니다."
L["Every page's bars that follow General. The game's: each page's own. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "일반을 따르는 모든 페이지의 바. 게임 기본: 각 페이지 고유. 게임의 몇 가지 아래로 다른 애드온이 공유하는 것(LibSharedMedia를 통해)."
L["Every page's words that follow General. The game's: each page's own. Russian, Korean or Chinese text keeps the game's, so its letters show."] = "일반을 따르는 모든 페이지의 글자. 게임 기본: 각 페이지 고유. 러시아어, 한국어, 중국어 글자는 글자가 보이도록 게임 글꼴을 유지합니다."
L["Every part below is Cinematic's own code: an addon can only time its own. For other addons, see All addons above."] = "아래의 모든 부분은 Cinematic 자체 코드입니다: 애드온은 자기 시간만 잴 수 있습니다. 다른 애드온은 위의 '모든 애드온'을 보세요."
L["Every plate's, those no row fits too, times its row's own. When they show is the Target Indicator row's, as the rows'."] = "모든 이름표(어떤 줄에도 맞지 않는 것 포함)에 대해, 줄 자체 값에 곱해집니다. 언제 보일지는 줄들처럼 대상 표시기 줄이 정합니다."
L["Every plate: NPCs, players and minions."] = "모든 이름표: NPC, 플레이어, 하수인."
L["Every tooltip: units, things in the world and the UI's (action bars, bags, menus and the rest)."] = "모든 툴팁: 유닛, 세상의 사물, UI의 것(행동 단축바, 가방, 메뉴 등)."
L["Every way to style this part, in a panel beside the settings. Pop out to drag it anywhere; Escape or its X closes it."] = "설정 옆 판에 이 부분을 꾸미는 모든 방법. '떼어 내기'로 아무 데나 끌 수 있고, Esc나 X로 닫습니다."
L["Every wheel back on the master wheel, in their usual order (your own wheels off it)."] = "모든 휠을 평소 순서대로 마스터 휠에 되돌립니다(나만의 휠은 빠짐)."
L["Everyone passed"] = "모두 포기함"
L["Everything at once, bars and words."] = "바와 글자 모두 한 번에."
L["Everything here as text, to copy and send us (on Discord, or in a bug report): your game version, the graph's figures, every addon's and the last recording. It's in English, for us to read."] = "여기 있는 모든 것을 문자로 복사해 우리에게 보내세요(Discord나 버그 보고): 게임 버전, 그래프 수치, 모든 애드온 수치, 마지막 기록. 우리가 읽을 수 있도록 영어로 되어 있습니다."
L["Everything here is hidden in CineMode unless ticked. Always shows a frame the whole time; its Fights dropdown, only while you fight or have something targeted; its Places dropdown, the whole time while you're there (Grouped: in a party or raid). Edit turns a row into a rule, for AND, NOT and more places. Frames fade in and out at the fade times on the CineMode page. Other addons' frames are on the Addon Frames page."] = "여기 있는 모든 것은 체크하지 않으면 CineMode에서 숨겨집니다. '항상'은 창을 내내 표시하고, '전투' 드롭다운은 전투 중이거나 대상을 지정했을 때만, '장소' 드롭다운은 그곳에 있는 동안 내내(파티 중: 파티나 공격대에 있을 때) 표시합니다. '편집'은 줄을 규칙으로 바꿔 AND, NOT, 더 많은 장소를 쓸 수 있게 합니다. 창은 CineMode 페이지의 흐리기 시간에 맞춰 나타나고 사라집니다. 다른 애드온의 창은 애드온 창 페이지에 있습니다."
L["Exalted"] = "확고한 동맹"
L["Exit CineMode while a vendor, bank, mailbox, class trainer, trade or auction house window is open. When off, the window still shows but the rest stays hidden."] = "상인, 은행, 우체통, 직업 전문가, 거래, 경매장 창이 열려 있는 동안 CineMode를 끝냅니다. 끄면 창은 보이지만 나머지는 숨겨진 채로 남습니다."
L["Exit CineMode while the spellbook, character sheet, talents, macros, key bindings or these options are open. When off, the window still shows but the rest stays hidden."] = "주문책, 캐릭터 정보, 특성, 매크로, 단축키 설정 또는 이 옵션이 열려 있는 동안 CineMode를 끝냅니다. 끄면 창은 보이지만 나머지는 숨겨진 채로 남습니다."
