L["Flash: the icon flashes for a few seconds as its cooldown ends, shown then even if its setting has it faded."] = "번쩍임: 재사용 대기시간이 끝날 때 아이콘이 몇 초간 번쩍이며, 설정상 흐려져 있어도 그때는 보입니다."
L["Flashes every icon in the Essential and Utility bars once, in this style."] = "필수와 보조 바의 모든 아이콘을 이 스타일로 한 번씩 번쩍입니다."
L["Flashes the icon for a few seconds when the spell's cooldown ends."] = "주문의 재사용 대기시간이 끝나면 아이콘을 몇 초간 번쩍입니다."
L["Flat"] = "납작함"
L["Flat bars and Arial Narrow, thinly outlined."] = "납작한 바와 가는 외곽선의 Arial Narrow."
L["Flat bars with a thin black edge, class-colored names, Arial Narrow."] = "가는 검은 테두리의 납작한 바, 직업 색 이름, Arial Narrow."
L["Flat bars with a thin black edge, health and names in class and reaction colors, Arial Narrow."] = "가는 검은 테두리의 납작한 바, 직업과 반응 색의 생명력과 이름, Arial Narrow."
L["Flat bars, health in your class color, with a thin black edge."] = "가는 검은 테두리의 납작한 바, 직업 색 생명력."
L["Flat cards, gold timers and the winner's row in gold."] = "납작한 카드, 금색 타이머, 승자 줄은 금색."
L["Fled"] = "도망침"
