L["Friendly players around you duel for 30 seconds, in pretend: their nameplates, made-up crowd control, and winners and losers, to see how it looks. Needs CineMode and other players nearby. Clicking Stop ends it."] = "주변의 아군 플레이어들이 30초 동안 가짜로 결투합니다: 이름표, 지어낸 군중 제어, 승자와 패자를 보여 주어 어떻게 보이는지 확인합니다. CineMode와 근처의 다른 플레이어가 필요합니다. '중지'를 클릭하면 끝납니다."
L["Friendly players:"] = "아군 플레이어:"
L["From far out, the zoom in or back out speeds up so it's done in this long. A short zoom still goes at the speeds above."] = "멀리서는 확대 또는 축소가 빨라져서 이 시간 안에 끝납니다. 짧은 확대/축소는 위의 속도 그대로 갑니다."
