L["Gives every row on this page, supported addons and custom frames, the Default row's settings, replacing their own."] = "이 페이지의 모든 줄(지원하는 애드온과 사용자 지정 창)에 기본 줄의 설정을 적용해 각자의 설정을 덮어씁니다."
