L["Ground clutter changes show as the ground around you loads again: move on a little, or /reload. Changing the game's Graphics menu doesn't undo these: they're written again over its new settings."] = "지면 장식물 변경은 주변 땅을 다시 불러올 때 보입니다: 조금 이동하거나 /reload하세요. 게임의 그래픽 메뉴를 바꿔도 취소되지 않습니다: 새 설정 위에 다시 덮어씁니다."
