L["Heal Vision after a fight, until the Calm Timer (CineMode page) has run out."] = "전투 후 진정 타이머(CineMode 페이지)가 끝날 때까지 Heal Vision."
L["Heal Vision everywhere. The rest of the row keeps its ticks for when you untick this."] = "어디서나 Heal Vision. 이 항목을 해제할 때를 위해 줄의 나머지 체크는 그대로 유지됩니다."
L["Heal Vision in fights."] = "전투 중 Heal Vision."
L["Heal Vision out of fights while you have a living enemy targeted."] = "비전투 중 살아 있는 적을 대상으로 지정했을 때 Heal Vision."
L["Heal Vision out of fights while you have anything else targeted: friends, NPCs, dead enemies."] = "비전투 중 다른 것(아군, NPC, 죽은 적)을 대상으로 지정했을 때 Heal Vision."
L["Heal Vision while you're in a party (not a raid), wherever you are."] = "어디에 있든 파티 중일 때(공격대 아님) Heal Vision."
