L["Health"] = "생명력"
L["Health bar and Power bar are the bars (Power: mana, rage, energy...). Bar numbers are the percent and value on them, hidden with their bar too."] = "생명력 바와 자원 바는 바입니다(자원: 마나, 분노, 기력...). 바 숫자는 바 위의 백분율과 값이며, 바와 함께 숨겨집니다."
L["Health bar waits for your health to change"] = "생명력 바는 생명력이 변할 때까지 대기"
L["Health bar:"] = "생명력 바:"
L["Health bars"] = "생명력 바"
L["Health:"] = "생명력:"
L["Heartbeat"] = "심장 박동"
L["Height with a plate"] = "이름표가 있을 때 높이"
L["Height:"] = "높이:"
L["Held back at the fight's start while you're at rest (Resource Display page)"] = "평소 상태일 때 전투 시작 시 보류(자원 표시 페이지)"
L["Held till you've been out of the fight 5 seconds (back in it, longer: a feign death or vanish doesn't let it through), then shown. Dropped after 5 minutes."] = "전투에서 벗어난 지 5초가 될 때까지 보류했다가(다시 전투에 들면 더 오래: 죽은 척이나 소멸로는 통과 못 함) 표시합니다. 5분 뒤에는 버립니다."
L["Help"] = "도움말"
L["Here"] = "여기"
L["Hide all except"] = "다음 빼고 모두 숨기기"
L["Hide error messages"] = "오류 메시지 숨기기"
L["Hide other duels while you duel"] = "결투 중에는 다른 결투 숨기기"
L["Hide until the mouse is still"] = "마우스가 멈출 때까지 숨기기"
L["Hide until the mouse is still: the mouse hadn't been still long enough"] = "마우스가 멈출 때까지 숨기기: 마우스가 충분히 오래 멈춰 있지 않았음"
L["Hide when the mouse is still"] = "마우스가 멈추면 숨기기"
L["Hide when the mouse is still: a tooltip in the world or on a unit frame hides once it's been up this long with the mouse still. Move the mouse and it comes back. Hide until the mouse is still: it shows only once the mouse has rested on it this long. Off leaves tooltips be."] = "마우스가 멈추면 숨기기: 세상이나 유닛 프레임의 툴팁이 마우스가 멈춘 채 이만큼 떠 있으면 숨겨집니다. 마우스를 움직이면 돌아옵니다. 마우스가 멈출 때까지 숨기기: 마우스가 그 위에 이만큼 머문 뒤에야 보입니다. 끄면 툴팁을 그대로 둡니다."
L["Hit text"] = "타격 문자"
L["Hold to bring up a wheel of the ground markers (the colored lights you drop on the floor): point at one and let go, and it drops under the cursor. Picking one that's down moves it; Clear all takes them all up. Tap it instead and the wheel stays up for you to click one. Only in a group."] = "누르고 있으면 바닥 징표(바닥에 놓는 색 불빛) 휠이 나옵니다: 하나를 가리키고 놓으면 커서 아래에 놓입니다. 이미 놓인 것을 고르면 옮기고, '모두 지우기'는 전부 거둡니다. 대신 짧게 누르면 휠이 떠 있어 클릭해서 고를 수 있습니다. 파티 중에만."
L["Hold to bring up a wheel of the raid target markers (skull, cross, square...) for your target, or with none, whatever the cursor is on: point at one and let go to put it on them, or at None to take theirs off. Tap it instead and the wheel stays up for you to click one."] = "누르고 있으면 대상(대상이 없으면 커서 아래의 것)에게 붙일 공격대 징표(해골, 가위표, 네모...) 휠이 나옵니다: 하나를 가리키고 놓으면 붙고, '없음'을 가리키면 떼어 냅니다. 대신 짧게 누르면 휠이 떠 있어 클릭해서 고를 수 있습니다."
L["Hold to bring up a wheel of the visions (Heal, Quest, Duel...), ringed while they're on: point at one and let go to turn it on or off, in a fight too. Tap it instead and the wheel stays up for you to click one."] = "누르고 있으면 Vision(Heal, Quest, Duel...) 휠이 나오며, 켜진 것에는 고리가 둘러집니다: 하나를 가리키고 놓으면 전투 중에도 켜거나 끕니다. 대신 짧게 누르면 휠이 떠 있어 클릭해서 고를 수 있습니다."
L["Hold to bring up a wheel of the wheels below (camera, menu, marker...): point at one and let go to open it, then click what you want on it. Tap it instead and the wheel stays up for you to click one. The camera wheel can't open in a fight."] = "누르고 있으면 아래 휠들(카메라, 메뉴, 징표...)의 휠이 나옵니다: 하나를 가리키고 놓으면 열리고, 그 안에서 원하는 것을 클릭하세요. 대신 짧게 누르면 휠이 떠 있어 클릭해서 고를 수 있습니다. 카메라 휠은 전투 중에 열 수 없습니다."
L["Holds the card up so you can drag it where you want it; Done lets it go. Close the settings to see it."] = "카드를 띄워 두어 원하는 곳으로 끌 수 있게 합니다. '완료'로 놓습니다. 설정을 닫아야 보입니다."
L["Honored"] = "우호"
L["Horizon Suite's quest tracker (Focus), its dungeon banner and its floating quest item button fade with the Quest tracker row on the Game Frames page."] = "Horizon Suite의 퀘스트 추적기(Focus), 던전 배너, 떠 있는 퀘스트 아이템 버튼은 게임 창 페이지의 퀘스트 추적기 줄과 함께 흐려집니다."
L["Hostile"] = "적대적"
L["Hover Find"] = "마우스오버 찾기"
L["Hover Find: %d frame put on the Find frames list."] = "마우스오버 찾기: 창 %d개를 창 찾기 목록에 넣었습니다."
L["Hover Find: %d frames put on the Find frames list."] = "마우스오버 찾기: 창 %d개를 창 찾기 목록에 넣었습니다."
L["Hover Find: hover over the frames you want, then click Stop: they go on the Find frames list, to add. The game's own frames and ones already faded are left out."] = "마우스오버 찾기: 원하는 창 위에 마우스를 올린 뒤 '중지'를 클릭하세요: 창 찾기 목록에 들어가 추가할 수 있습니다. 게임 자체 창과 이미 흐리게 한 창은 빠집니다."
L["Hover group \"%s\": %s"] = "마우스오버 그룹 \"%s\": %s"
L["Hover over the frames you want (move this window out of the way, or close it), then click Stop: they go on the list below, to add. The game's own frames and ones already faded are left out. /cine add cancel drops them."] = "원하는 창 위에 마우스를 올린 뒤(이 창은 비켜 두거나 닫으세요) '중지'를 클릭하세요: 아래 목록에 들어가 추가할 수 있습니다. 게임 자체 창과 이미 흐리게 한 창은 빠집니다. /cine add cancel로 버립니다."
L["Hovering the chat, typing or a whisper to read still brings it all up."] = "대화창에 마우스를 올리거나, 입력하거나, 읽을 귓속말이 있으면 여전히 전부 나타납니다."
L["How Damage Vision looks and where it sits. Press Test on the Settings tab and close the settings to see it."] = "Damage Vision의 모양과 위치. 설정 탭에서 '시험'을 누르고 설정을 닫아야 보입니다."
L["How big a name is with its unit about 10 yards from the camera, next to the plates' own. Nearer, bigger still; further, smaller, as the game's names over heads."] = "유닛이 카메라에서 약 10m 떨어져 있을 때 이름의 크기(이름표 자체 크기 대비). 더 가까우면 더 크고, 멀면 게임의 머리 위 이름처럼 작아집니다."
L["How big a name is with its unit about 50 yards from the camera: about the size of the game's names where those take over, at the edge of nameplate range."] = "유닛이 카메라에서 약 50m 떨어져 있을 때 이름의 크기: 이름표 거리 끝에서 게임 이름이 이어받는 크기와 비슷합니다."
L["How big speech from behind you is, next to a bubble overhead: smaller sounds further away."] = "머리 위 말풍선 대비 뒤에서 들리는 대사의 크기: 작을수록 멀게 들립니다."
L["How big the names are, next to the plates' own."] = "이름표 자체 크기 대비 이름의 크기."
L["How big the text is, next to its usual size."] = "평소 크기 대비 글자 크기."
L["How big the words are, next to their usual size."] = "평소 크기 대비 글자 크기."
L["How big they are, next to the usual."] = "평소 대비 크기."
L["How big your class resource is (combo points, holy power, runes and the like), next to the game's."] = "게임 대비 직업 자원(연계 점수, 신성한 힘, 룬 등)의 크기."
L["How bright both arts' colors are: at 50% as the theme has them; less, darker, down to black at 0%; more, lighter, toward white."] = "두 그림의 색 밝기: 50%면 테마 그대로, 낮을수록 어두워져 0%에서 검정, 높을수록 밝아져 흰색 쪽으로."
L["How chat bubbles look, and speech from behind you with them. Where bubbles show: the UI Manager's Chat bubbles page. Bubbles already showing change with the next thing said."] = "말풍선과 함께 뒤에서 들리는 대사의 모양. 말풍선이 보이는 곳: UI 관리자의 말풍선 페이지. 이미 떠 있는 말풍선은 다음 대사부터 바뀝니다."
L["How close to the waypoint the wind stops (you're there)."] = "목적지에 얼마나 가까워지면 바람이 멈출지(도착)."
L["How dark it is behind the bar."] = "바 뒤의 어둡기."
L["How dark it is behind the bars, with a border of ours."] = "우리 테두리를 쓸 때 바 뒤의 어둡기."
L["How dark it is behind the fill (with a fill of your own; the game's keeps its own)."] = "채움 뒤의 어둡기(직접 고른 채움일 때. 게임 것은 그대로)."
L["How dark it is behind the health bar, with a border of ours."] = "우리 테두리를 쓸 때 생명력 바 뒤의 어둡기."
L["How dark the black edges get."] = "검은 가장자리가 얼마나 어두워질지."
L["How dark the edges are at full."] = "가득 찼을 때 가장자리의 어둡기."
L["How dark the empty part of the bar is."] = "바의 빈 부분의 어둡기."
L["How dark the shadow is."] = "그림자의 어둡기."
L["How dark the world gets outside the portal's rim, in a deep shade of its color."] = "차원문 테두리 밖의 세상이 그 색의 짙은 음영으로 얼마나 어두워질지."
L["How faded the page count (2 / 3) and the numbers by the replies and buttons are."] = "쪽수(2 / 3)와 대답 및 버튼 옆 숫자가 얼마나 흐린지."
L["How far above the letters it falls (below, below 0)."] = "글자보다 얼마나 위에 놓일지(0 미만이면 아래)."
L["How far away buildings keep their full detail."] = "건물이 얼마나 먼 거리까지 세부 묘사를 유지할지."
L["How far away creatures and characters keep their full detail before they're swapped for simpler models."] = "생물과 캐릭터가 단순한 모델로 바뀌기 전까지 세부 묘사를 유지하는 거리."
L["How far away grass and flowers grow full before they start thinning out towards the clutter distance. Above the clutter distance it makes no more difference."] = "풀과 꽃이 장식물 거리 쪽으로 성겨지기 전까지 빽빽하게 자라는 거리. 장식물 거리보다 크면 더는 차이가 없습니다."
L["How far away grass and flowers still show."] = "풀과 꽃이 보이는 거리."
L["How far away nameplates show, in yards. The game won't go past its own limit. Reset page puts the game's default back."] = "이름표가 보이는 거리(m). 게임 자체 한계를 넘지는 못합니다. '페이지 초기화'로 게임 기본값으로 돌아갑니다."
L["How far away small objects stay before they fade out. Much higher costs a lot of frame rate for little to see."] = "작은 사물이 사라지기 전까지 보이는 거리. 훨씬 높이면 볼 것은 별로 없는데 프레임을 많이 잡아먹습니다."
L["How far away the land is drawn in full before it turns into the flat, faded horizon, and how far anything is drawn at all. Very demanding: with terrain and building detail turned up too, most of all."] = "땅이 납작하고 흐린 지평선으로 바뀌기 전까지 온전히 그려지는 거리이자, 무엇이든 그려지는 최대 거리. 매우 무겁습니다: 지형과 건물 세부 묘사까지 높이면 특히 그렇습니다."
L["How far away the land keeps its full shape before it turns low detail."] = "땅이 낮은 세부 묘사로 바뀌기 전까지 온전한 모양을 유지하는 거리."
L["How far away trees, rocks and other objects keep their full detail before they're swapped for simpler ones or fade out."] = "나무, 바위 등 사물이 단순한 것으로 바뀌거나 사라지기 전까지 세부 묘사를 유지하는 거리."
L["How far either side of behind the flight, RP walk and auto-run cameras may swing indoors."] = "실내에서 비행, RP 걷기, 자동 달리기 카메라가 뒤쪽 좌우로 흔들릴 수 있는 폭."
L["How far in it all comes: at 50% as the settings below say (and the theme's own); less, nearer the edges, down to none at 0% (the shadow only to half); more, further in, up to double. It scales the shadow's reach and both arts' reach."] = "전체가 얼마나 안쪽까지 들어올지: 50%면 아래 설정(과 테마 고유값)대로, 낮을수록 가장자리 쪽으로 0%면 없음(그림자는 절반까지), 높을수록 더 안쪽으로 두 배까지. 그림자 범위와 두 그림의 범위에 곱해집니다."
L["How far in it comes from the left and right of the screen at full (screens are wide: the same share comes further in there)."] = "가득 찼을 때 화면 좌우에서 얼마나 들어올지(화면이 넓어서 같은 비율이라도 더 깊이 들어옵니다)."
L["How far in it comes from the top and bottom of the screen at full."] = "가득 찼을 때 화면 위아래에서 얼마나 들어올지."
L["How far in its clear middle closes at full."] = "가득 찼을 때 맑은 가운데가 얼마나 좁혀질지."
L["How far in the black edges come as the cast fills (a share of the screen from each side)."] = "시전이 찰수록 검은 가장자리가 얼마나 들어올지(양쪽에서 화면 비율로)."
L["How far out you can zoom the camera, as times the game's base distance. The game won't go past its own limit. Idle zoom's \"past your max\" still raises it to 2.6 while it zooms, if it's lower."] = "카메라를 얼마나 멀리 축소할 수 있을지(게임 기본 거리의 배수). 게임 자체 한계를 넘지는 못합니다. 대기 확대/축소의 '최대 거리 너머'는 이 값이 더 낮으면 축소하는 동안 2.6까지 올립니다."
L["How far past the bars' edge they fade into the scene."] = "바 가장자리를 지나 장면 속으로 흐려지는 폭."
L["How far past your own distance the slow zoom may pull back indoors. It also never raises the max zoom distance indoors. Walking in pulled back, the camera glides in to this."] = "실내에서 천천히 축소할 때 내 거리보다 얼마나 더 물러날 수 있을지. 실내 최대 축소 거리를 올리지는 않습니다. 물러난 채로 실내에 들어가면 카메라가 이 거리로 부드럽게 다가옵니다."
L["How far past your own zoom the camera pulls back (the first move always goes this far)."] = "카메라가 내 확대 거리보다 얼마나 더 물러날지(첫 움직임은 항상 이만큼)."
L["How far right (X) and up (Y) from the middle of the screen it sits; below 0, left or down. Dragging it with Move fills these in."] = "화면 가운데에서 오른쪽(X)과 위(Y)로 얼마나 떨어져 있을지. 0 미만이면 왼쪽이나 아래. '이동'으로 끌면 채워집니다."
L["How far right (X) of the middle of the screen, and up (Y) from its bottom, the card sits. Typing here or dragging it with Move puts it there; Reset puts it back above speech from behind you."] = "카드가 화면 가운데에서 오른쪽(X)으로, 아래에서 위(Y)로 얼마나 떨어져 있을지. 여기 입력하거나 '이동'으로 끌면 그곳에 놓입니다. '초기화'는 뒤에서 들리는 대사 위로 되돌립니다."
L["How far right of the letters it falls (left, below 0)."] = "글자보다 얼마나 오른쪽에 놓일지(0 미만이면 왼쪽)."
L["How far around you the camera turns with each move."] = "움직일 때마다 카메라가 주위를 얼마나 돌지."
L["How far the camera comes down toward eye level, from wherever you had it. Much more and, close up, it can meet the ground or scenery behind you (a small jump). It goes back up as the window closes (unless you moved the camera yourself meanwhile). 0 keeps your angle."] = "카메라가 원래 높이에서 눈높이 쪽으로 얼마나 내려올지. 너무 많이 내리면 가까울 때 뒤의 땅이나 지형에 닿을 수 있습니다(살짝 튐). 창이 닫히면 다시 올라갑니다(그 사이 직접 카메라를 움직이지 않았다면). 0이면 각도를 유지합니다."
L["How far the camera may come in from its distance."] = "카메라가 거리에서 얼마나 다가올 수 있을지."
L["How far the camera may pull back from its distance."] = "카메라가 거리에서 얼마나 물러날 수 있을지."
L["How far the camera may sway either side of where it settles."] = "카메라가 자리 잡은 곳에서 좌우로 얼마나 흔들릴 수 있을지."
L["How far the camera may swing to either side of directly behind your character. 90° reaches side-on; smaller keeps it closer behind."] = "카메라가 캐릭터 바로 뒤에서 좌우로 얼마나 돌 수 있을지. 90°면 옆까지, 작을수록 뒤쪽에 가깝게 머뭅니다."
L["How far the camera may tilt down as it moves."] = "움직이면서 카메라가 아래로 기울 수 있는 정도."
L["How far the camera may tilt up as it moves."] = "움직이면서 카메라가 위로 기울 수 있는 정도."
L["How far the dark edges reach in once they've closed in, as a share of the screen from each side."] = "어두운 가장자리가 다 좁혀진 뒤 들어오는 정도(양쪽에서 화면 비율로)."
L["How far up the screen the list of replies starts: its top edge, from the bottom of the screen. Changing this also forgets where you dragged the list to."] = "대답 목록이 화면 어디서 시작할지: 화면 아래에서 목록 위쪽 가장자리까지. 바꾸면 목록을 끌어 둔 위치도 잊습니다."
L["How fast"] = "속도"
L["How fast they travel to the waypoint, next to the style's own speed."] = "목적지로 이동하는 속도(스타일 고유 속도 대비)."
L["How it looks: the theme, our art and Blizzard's, the shadow and the heartbeat."] = "모양: 테마, 우리 그림과 블리자드 그림, 그림자, 심장 박동."
L["How long"] = "시간"
L["How long a card stays before it fades. The mouse over it holds it."] = "카드가 사라지기 전까지 머무는 시간. 마우스를 올리면 유지됩니다."
L["How long a plate takes to change its opacity or size a whole 100% when the row it goes by changes: from 100% to 15% takes a bit less. If it changes back before it's there, it turns back from where it is, so a quick look away from an elite and back barely shows. A plate just come into view starts at its row's. 0: at once."] = "따르는 줄이 바뀔 때 이름표가 불투명도나 크기를 100% 전부 바꾸는 데 걸리는 시간: 100%에서 15%는 조금 덜 걸립니다. 도착하기 전에 다시 바뀌면 그 자리에서 되돌아가므로, 정예를 잠깐 봤다가 돌아와도 거의 티가 안 납니다. 방금 시야에 들어온 이름표는 그 줄 값으로 시작합니다. 0: 곧바로."
L["How long a recording runs."] = "기록 시간."
L["How long a repeat is ignored for."] = "반복을 무시하는 시간."
L["How long before the cast ends the black takes over the whole screen. 0: it doesn't."] = "시전이 끝나기 얼마 전에 검정이 화면 전체를 덮을지. 0: 덮지 않음."
L["How long each move takes, start to stop. Longer is slower and smoother."] = "한 번 움직이는 데 처음부터 끝까지 걸리는 시간. 길수록 느리고 부드럽습니다."
L["How long each zoom in or out takes."] = "한 번 확대 또는 축소하는 데 걸리는 시간."
L["How long it stays up once a fight is over."] = "전투가 끝난 뒤 유지하는 시간."
L["How long its camera runs."] = "카메라가 도는 시간."
L["How long the bars take to come in or go. 0: as long as the UI's own fades (the main page's Fade in and Fade out times)."] = "바가 나타나거나 사라지는 데 걸리는 시간. 0: UI 자체 흐리기 시간만큼(메인 페이지의 나타나는 시간, 사라지는 시간)."
L["How long the camera holds still between moves."] = "움직임 사이에 카메라가 멈춰 있는 시간."
L["How long the camera rests between sweeps. 0 keeps it turning continuously at the turn speed, without slowing between sweeps."] = "한 바퀴 돈 뒤 쉬는 시간. 0이면 사이사이 느려지지 않고 회전 속도로 계속 돕니다."
L["How long the card stays between fading in and out (Typewriter: once typed)."] = "카드가 나타나고 사라지기 사이에 머무는 시간(타자기: 다 친 뒤부터)."
L["How long the dark edges take to close in after you die, starting gently and settling at the end."] = "죽은 뒤 어두운 가장자리가 좁혀 오는 시간. 부드럽게 시작해 끝에서 자리 잡습니다."
L["How long the icon flashes once its cooldown ends."] = "재사용 대기시간이 끝난 뒤 아이콘이 번쩍이는 시간."
L["How long the session was."] = "세션 길이."
L["How long things must stay calm (no cast, window, dragging and the like) before CineMode comes back. After a fight it comes back at once instead. 0 returns at once."] = "CineMode가 돌아오기 전까지 잠잠해야(시전, 창, 끌기 등 없음) 하는 시간. 전투 후에는 대신 곧바로 돌아옵니다. 0이면 곧바로 돌아옵니다."
L["How long things take to fade out, in and out of fights: letting go of a target, after a mouseover, and after a fight once the Calm Timer below is over. The mouseover time (Mouseover groups page) includes it: a time shorter than the fade just fades straight away."] = "전투 안팎에서 사라지는 데 걸리는 시간: 대상을 놓았을 때, 마우스오버 뒤, 그리고 전투 후 아래 진정 타이머가 끝났을 때. 마우스오버 시간(마우스오버 그룹 페이지)에 포함됩니다: 흐리기보다 짧으면 곧바로 흐려집니다."
L["How long you stand still before NPCs chatting nearby start this row's camera. 0: straight away. Moving starts the count over."] = "근처에서 NPC들이 잡담할 때 이 줄의 카메라가 시작되기 전까지 가만히 서 있어야 하는 시간. 0: 바로. 움직이면 처음부터 다시 셉니다."
L["How loud the sounds are, next to your sound effects' volume."] = "효과음 음량 대비 소리 크기."
L["How many come a minute at full (a big hit brings a few more)."] = "가득 찼을 때 분당 나오는 수(큰 타격이면 몇 개 더)."
L["How many dungeon or raid bosses you killed."] = "처치한 던전 또는 공격대 우두머리 수."
L["How many quests you turned in."] = "완료 보고한 퀘스트 수."
L["How many seconds before it's ready the icon comes back: 0 for once it's ready. Leave it empty for %d%% of its cooldown."] = "준비되기 몇 초 전에 아이콘이 돌아올지: 0이면 준비됐을 때. 비워 두면 재사용 대기시간의 %d%%."
L["How many streaks (or leaves, or motes) start each second."] = "매초 시작되는 줄기(또는 잎, 티끌) 수."
L["How many times you died."] = "죽은 횟수."
L["How much further in each beat pushes the edges (some themes throb more or less)."] = "박동마다 가장자리를 얼마나 더 밀어 넣을지(테마마다 더하거나 덜 고동침)."
L["How much of a hidden damage dealer still shows, and of the group titles. 0% hides them completely."] = "숨겨진 공격 전담과 그룹 제목이 얼마나 보일지. 0%는 완전히 숨깁니다."
L["How much of a hidden healer still shows. 0% hides them completely."] = "숨겨진 치유 전담이 얼마나 보일지. 0%는 완전히 숨깁니다."
L["How much of a hidden pet still shows. 0% hides them completely."] = "숨겨진 소환수가 얼마나 보일지. 0%는 완전히 숨깁니다."
L["How much of a hidden tank still shows. 0% hides them completely."] = "숨겨진 방어 전담이 얼마나 보일지. 0%는 완전히 숨깁니다."
L["How much of each move is spent speeding up, and again slowing down. 50% is one smooth swell, gentlest at the ends. Lower values get up to speed quicker and cruise in the middle."] = "한 번 움직일 때 가속과 감속에 쓰는 비율. 50%는 양 끝이 가장 부드러운 한 번의 물결입니다. 낮을수록 빨리 속도가 붙고 가운데에서 일정하게 갑니다."
L["How much of each zoom is spent speeding up, and again slowing down. 50% is one smooth swell; lower gets moving sooner and glides in the middle."] = "한 번 확대/축소할 때 가속과 감속에 쓰는 비율. 50%는 한 번의 부드러운 물결이고, 낮을수록 빨리 움직이기 시작해 가운데에서 미끄러집니다."
L["How much of the screen's height the dark top and bottom edges cover at full."] = "가득 찼을 때 위아래 어두운 가장자리가 덮는 화면 높이 비율."
L["How much of the screen's width the dark left and right edges cover at full."] = "가득 찼을 때 좌우 어두운 가장자리가 덮는 화면 너비 비율."
L["How much of your computer's time Cinematic takes. The graph is the game's own figure for this addon: its share of each frame's time, sampled every second (the last five minutes, kept over a reload), each bar colored by what was going on. A recording times the addon's busy parts: it starts when you close the settings, and its results show here. If Cinematic seems slow for you, record a while of your usual play (a fight too), then Copy report and send it to us: it helps us find what to speed up."] = "Cinematic이 컴퓨터 시간을 얼마나 쓰는지 보여 줍니다. 그래프는 이 애드온에 대한 게임 자체 수치입니다: 각 프레임 시간 중 차지하는 비율을 매초 표본으로 담으며(최근 5분, 다시 불러와도 보관), 막대마다 그때 하던 일에 따라 색이 칠해집니다. 기록은 애드온의 바쁜 부분의 시간을 잽니다: 설정을 닫으면 시작되고 결과가 여기 표시됩니다. Cinematic이 느리게 느껴지면 평소 플레이(전투 포함)를 잠시 기록한 뒤 '보고서 복사'로 보내 주세요: 무엇을 빠르게 할지 찾는 데 도움이 됩니다."
L["How much richer you came out, if you did."] = "얼마나 부유해졌는지(그랬다면)."
L["How much this theme throbs, next to Throb above."] = "위 '고동'에 대비해 이 테마가 얼마나 고동치는지."
L["How names look on nameplates showing just the name: in CineMode, away from dungeons and raids, a name kept up over a faded plate is drawn by the plate. Changes show at once, here and on the plates around you."] = "이름만 보이는 이름표의 이름 모양: CineMode에서, 던전과 공격대 밖에서는 흐려진 이름표 위에 남은 이름을 이름표가 그립니다. 바꾸면 여기와 주변 이름표에 곧바로 보입니다."
L["How see-through the background is."] = "배경의 투명도."
L["How see-through the bars are."] = "바의 투명도."
L["How see-through the bubble is."] = "말풍선의 투명도."
L["How see-through the cards are."] = "카드의 투명도."
L["How see-through the names are, on top of their fades."] = "흐리기 위에 더해지는 이름의 투명도."
L["How see-through the panels are."] = "판의 투명도."
L["How see-through the whole of it is."] = "전체의 투명도."
L["How solid speech from behind you is: fainter sounds muffled, out of view."] = "뒤에서 들리는 대사가 얼마나 진할지: 흐릴수록 시야 밖에서 먹먹하게 들립니다."
L["How solid the game's dark background behind each frame is."] = "각 창 뒤 게임의 어두운 배경이 얼마나 진할지."
L["How strong"] = "강도"
L["How strong it all is: at 50% as the settings below say (and the theme's own); less, lighter, down to nothing at 0%; more, up to double. It scales the darkness, the shadow's reach, the throb and both arts' opacity. The color grade (the world draining toward grey, tinged with the theme's color) is as strong as this says."] = "전체 강도: 50%면 아래 설정(과 테마 고유값)대로, 낮을수록 옅어져 0%에서 없음, 높을수록 두 배까지. 어둠, 그림자 범위, 고동, 두 그림의 불투명도에 곱해집니다. 색 보정(테마 색이 섞인 회색 쪽으로 세상이 바래는 것)도 이 강도를 따릅니다."
L["How strong it is as the cast ends (it starts faint)."] = "시전이 끝날 때의 강도(희미하게 시작함)."
L["How strong it is at full."] = "가득 찼을 때의 강도."
L["How strong the edges are out of a fight (eating and drinking back up, say), next to in one. Some clients keep your health secret in fights; there the edges only fade in and out with it."] = "전투 중 대비 전투 밖(예: 먹고 마시며 회복할 때)에서 가장자리 강도. 일부 클라이언트는 전투 중 생명력을 비밀로 하므로, 그때 가장자리는 그에 따라 나타나고 사라지기만 합니다."
L["How strong the glow is, next to the art."] = "그림 대비 빛의 강도."
L["How strongly the tint colors the world, for every preset."] = "모든 프리셋에서 색조가 세상을 물들이는 강도."
L["How tall each bar is, as a share of the screen's height."] = "각 바의 높이(화면 높이 비율)."
L["How tall the bar for the time left is."] = "남은 시간 바의 높이."
L["How tall the bar is (the race track's line is half that, the ladder's rows a little more)."] = "바의 높이(경주 트랙의 선은 절반, 사다리의 줄은 조금 더)."
L["How tall the words are on the screen; the other lines go by them. (In a letterbox bar: Letterbox scale.)"] = "화면에서 글자의 높이. 다른 줄은 이것을 따릅니다. (레터박스 바 안에서는: 레터박스 비율.)"
L["How the bars at the top and bottom of the screen look and come in. When they show: the Letterbox tab. Changes show at once, here and on the bars."] = "화면 위아래 바의 모양과 나타나는 방식. 언제 보일지: 레터박스 탭. 바꾸면 여기와 바에 곧바로 보입니다."
L["How the big button for the nearest quest's item looks. Turning it on: the Vision tab. Where it sits: the extra ability button's place in Edit Mode. Changes show at once (its size after a fight, if you're in one)."] = "가장 가까운 퀘스트 아이템의 큰 버튼 모양. 켜기: Vision 탭. 위치: 편집 모드의 추가 행동 버튼 자리. 바꾸면 곧바로 보입니다(크기는 전투 중이면 전투 후에)."
L["How the card comes in."] = "카드가 나타나는 방식."
L["How the card is set: a title card, a subtitle, a chapter line or a banner."] = "카드 형식: 타이틀 카드, 자막, 장 제목 줄 또는 배너."
L["How the cast bars look: on nameplates, yours, your target's and focus's, and the bosses' and arena enemies'. The Default tab's settings are every bar's until its own tab has Use default settings unticked. All but the nameplates' keep the game's look until their tab's Restyle these bars is ticked. Whether the nameplates' show in CineMode: the Nameplates page's Plate parts grid. Changes show at once, here and on bars casting now."] = "시전 바의 모양: 이름표, 나, 대상과 주시 대상, 우두머리와 투기장 적. 기본 탭의 설정은 자체 탭에서 '기본 설정 사용'을 해제하기 전까지 모든 바에 적용됩니다. 이름표 것을 빼고는 그 탭의 '이 바 다시 꾸미기'에 체크하기 전까지 게임의 모양을 유지합니다. 이름표 시전 바가 CineMode에서 보일지는 이름표 페이지의 이름표 구성 요소 격자에서 정합니다. 바꾸면 여기와 지금 시전 중인 바에 곧바로 보입니다."
L["How the dialogue looks, the \"Show the game's window\" link and the number keys."] = "대화의 모양, \"게임 창 보기\" 링크와 숫자 키."
L["How the game world looks in CineMode (or over the normal UI, with Start in CineMode off on the main page): vignette, inn glow, weather and depth of field. The letterbox bars and the color grading have pages of their own (Letterbox, Tint). The UI isn't tinted. Names and nameplates are on the Nameplates page."] = "CineMode에서(또는 메인 페이지의 'CineMode로 시작'이 꺼져 있으면 일반 UI 위에) 게임 세상이 어떻게 보일지: 비네트, 여관 불빛, 날씨, 피사계 심도. 레터박스 바와 색 보정은 자체 페이지(레터박스, 색조)가 있습니다. UI에는 색조가 입혀지지 않습니다. 이름과 이름표는 이름표 페이지에 있습니다."
L["How the game's tooltips look: their background, edge and words, names in their colors and the health bar. Which lines show and when: the Interface hub's Tooltips page."] = "게임 툴팁의 모양: 배경, 가장자리, 글자, 색 입힌 이름, 생명력 바. 어떤 줄을 언제 보일지: 인터페이스 허브의 툴팁 페이지."
L["How the low-health edges look: the theme, our art and Blizzard's, the shadow and the effects. When they show: the Vision tab. Changes show at once in the preview."] = "낮은 생명력 가장자리의 모양: 테마, 우리 그림과 블리자드 그림, 그림자, 효과. 언제 보일지: Vision 탭. 바꾸면 미리 보기에 곧바로 보입니다."
L["How the personal resource display under your character looks: its health and power bars, and your class resource. When the bars come up: the Interface hub's Resource Display page."] = "캐릭터 아래 개인 자원 표시의 모양: 생명력과 자원 바, 직업 자원. 바가 언제 나타날지: 인터페이스 허브의 자원 표시 페이지."
L["How the quest item button looks."] = "퀘스트 아이템 버튼의 모양."
L["How the raid frames look, the party's when the game draws them raid-style, and the arena's. The Default tab's settings are each group's until its own tab has Use default settings unticked. Which parts show: the Game Frames page's party and raid rows."] = "공격대 창, 게임이 공격대 방식으로 그리는 파티 창, 투기장 창의 모양. 기본 탭의 설정은 자체 탭에서 '기본 설정 사용'을 해제하기 전까지 각 그룹에 적용됩니다. 어떤 부분이 보일지: 게임 창 페이지의 파티와 공격대 줄."
L["How the result shows: its card (with the words above), or a souls banner: VICTORY ACHIEVED or DEFEATED across the middle of the screen, who it was against under it."] = "결과 표시 방식: 카드(위 문구 포함), 또는 소울 배너: 화면 가운데를 가로지르는 VICTORY ACHIEVED 또는 DEFEATED, 그 아래 상대 이름."
L["How the roll window looks."] = "주사위 창의 모양."
L["How the rows are listed: Camera groups them by camera name, Scene by scene name. Either way a scene's rows stay together, in the order they're tried."] = "줄 나열 방식: 카메라는 카메라 이름별로, 장면은 장면 이름별로 묶습니다. 어느 쪽이든 한 장면의 줄은 시도되는 순서대로 함께 있습니다."
L["How the window of the group's loot rolls looks: its cards, the bar for the time left, and each player's pick and number. Turning it on: the Vision tab. Changes show at once, here and on the window."] = "파티 전리품 주사위 창의 모양: 카드, 남은 시간 바, 각 플레이어의 선택과 숫자. 켜기: Vision 탭. 바꾸면 여기와 창에 곧바로 보입니다."
L["How thick the border is, in pixels."] = "테두리 두께(픽셀)."
L["How thickly grass, flowers and stones grow on the ground."] = "땅에 풀, 꽃, 돌이 자라는 빽빽함."
L["How this card looks. It starts from a style (a subzone's, the zone's), each setting following it until you change it here, then the card's own until you put it back. Change the style itself on the Card Types tab, for every card using it. Changes play at once in the preview."] = "이 카드의 모양. 스타일(하위 지역 것, 지역 것)에서 시작하며, 각 설정은 여기서 바꾸기 전까지 스타일을 따르다가 바꾸면 되돌릴 때까지 카드 고유 값이 됩니다. 스타일 자체는 카드 종류 탭에서 바꾸며, 그 스타일을 쓰는 모든 카드에 적용됩니다. 바꾸면 미리 보기에서 곧바로 재생됩니다."
L["How wide a line of speech from behind you can get before it wraps onto the next row, as a bubble overhead does."] = "머리 위 말풍선처럼, 뒤에서 들리는 대사 한 줄이 다음 줄로 넘어가기 전까지 얼마나 넓어질 수 있을지."
L["How wide it is."] = "너비."
L["How your player, target, focus, pet, target of target and party frames look. The Default tab's settings are every frame's until its own tab has Use default settings unticked. Which parts show: the Interface hub's Unit Frames page."] = "플레이어, 대상, 주시 대상, 소환수, 대상의 대상, 파티 프레임의 모양. 기본 탭의 설정은 자체 탭에서 '기본 설정 사용'을 해제하기 전까지 모든 프레임에 적용됩니다. 어떤 부분이 보일지: 인터페이스 허브의 Unit Frames 페이지."
L["How your target, focus and the unit under the mouse stand out on the nameplates, for when no target frame shows them: a mark on each one's plate, a row for each in the grid, and its name, health bar or border in its mark's color (the row's Also color). When they show is the Target Indicator row's, on the Nameplates page's Cinematic plate parts grid. Changes show at once, here and on the plates."] = "대상 프레임이 보이지 않을 때 대상, 주시 대상, 마우스 아래 유닛이 이름표에서 어떻게 돋보일지: 각 이름표의 표시, 격자의 각 줄, 그리고 표시 색(줄의 '추가 색')으로 칠한 이름, 생명력 바 또는 테두리. 언제 보일지는 이름표 페이지 Cinematic 이름표 구성 요소 격자의 대상 표시기 줄이 정합니다. 바꾸면 여기와 이름표에 곧바로 보입니다."
L["How:"] = "방식:"
L["Icon"] = "아이콘"
L["Icon shows"] = "아이콘 표시"
L["Icons"] = "아이콘"
L["Icons have a dark border of their own: zoomed in a little, it's cut off."] = "아이콘에는 자체 어두운 테두리가 있습니다: 조금 확대하면 잘려 나갑니다."
L["Icons of your own, after the wheel's own: each runs a command, as on your own wheels. Room for %d. The same for all your characters."] = "휠 기본 아이콘 뒤에 붙는 나만의 아이콘: 내 휠처럼 각각 명령을 실행합니다. %d개까지. 모든 캐릭터에 공통입니다."
L["Icons on it"] = "들어 있는 아이콘"
L["Ignore repeats from the same person"] = "같은 사람의 반복은 무시"
L["Ignored for:"] = "무시 시간:"
L["Immerse yourself in the world. How much do you want?"] = "세상에 몰입해 보세요. 얼마나 원하시나요?"
L["Import a Vitals theme"] = "Vitals 테마 가져오기"
L["Import a camera script"] = "카메라 스크립트 가져오기"
L["Import a scene or shot"] = "장면 또는 샷 가져오기"
L["Import a wheel"] = "휠 가져오기"
L["Import theme"] = "테마 가져오기"
L["In %s"] = "%s 안"
L["In CineMode"] = "CineMode에서"
L["In CineMode the death camera hides all the frames it fades (bars, chat, unit frames...). The Mouseover page's groups ticked here stay up throughout, party or raid frames say, to watch your group. The release and resurrect popups always show."] = "CineMode에서 죽음 카메라는 흐리게 하는 모든 창(바, 대화창, 유닛 프레임...)을 숨깁니다. 여기 체크한 마우스오버 페이지의 그룹(예: 파티나 공격대 창)은 내내 남아서 파티를 지켜볼 수 있습니다. 영혼 해방과 부활 창은 항상 보입니다."
L["In CineMode, a health bar faded out comes back as your health drops: hidden above its Starts, fading in to fully up at its Full."] = "CineMode에서 흐려진 생명력 바는 생명력이 줄면 돌아옵니다: '시작' 위에서는 숨고, '가득'에서 완전히 보이도록 서서히 나타납니다."
L["In CineMode, as it rains, the view distance comes in from yours: the harder the rain, the closer. At 100% a downpour brings it all the way in, as far as the Graphics menu's lowest View distance; it never goes further out than yours. Yours is put back once the rain stops or you go indoors."] = "CineMode에서 비가 오면 시야 거리가 내 설정보다 가까워집니다: 비가 셀수록 더 가깝게. 100%면 폭우일 때 그래픽 메뉴의 가장 낮은 시야 거리까지 들어오며, 내 설정보다 멀어지지는 않습니다. 비가 그치거나 실내에 들어가면 원래대로 돌아갑니다."
L["In CineMode, away from dungeons and raids, nameplates stay on (just faded), and the game takes its own names away from over the heads of units with a plate. So where a name is kept up over a faded plate, Cinematic draws it on the plate itself, made to look like the game's names: colored, and smaller further off. Beyond nameplate range the game's own names show, so a name can change a little in size or place as its unit crosses that range."] = "CineMode에서, 던전과 공격대 밖에서는 이름표가 (흐려진 채) 켜져 있고, 게임은 이름표가 있는 유닛의 머리 위 이름을 없앱니다. 그래서 흐려진 이름표 위에 이름을 남길 때는 Cinematic이 이름표 위에 게임 이름처럼 보이도록 직접 그립니다: 색을 입히고 멀수록 작게. 이름표 거리 밖에서는 게임 이름이 보이므로, 유닛이 그 거리를 넘나들 때 이름 크기나 위치가 조금 바뀔 수 있습니다."
L["In CineMode, the nameplates of two players dueling near you show, so you can watch their health. Only in the open world, out of fights. Turns on friendly player nameplates while it watches, kept invisible and click-through bar the duelists'. Each duel has its own color, and the winner and loser show when it ends. Needs the Nameplates page enabled."] = "CineMode에서 근처에서 결투하는 두 플레이어의 이름표를 표시해 생명력을 지켜볼 수 있습니다. 필드에서, 비전투 중에만. 지켜보는 동안 아군 플레이어 이름표를 켜되 결투자 외에는 보이지 않고 클릭되지 않게 합니다. 결투마다 고유 색이 있고, 끝나면 승자와 패자를 보여 줍니다. 이름표 페이지를 사용해야 합니다."
L["In CineMode, where and when tooltips show; the rest of the time they're hidden. For some kinds only (enemies, friendlies, gatherables, quest objectives, anything else), Edit its rule: the Tooltip line has a word for each."] = "CineMode에서 툴팁이 어디서 언제 보일지. 그 밖에는 숨겨집니다. 일부 종류에만(적, 아군, 채집물, 퀘스트 목표, 그 밖의 것) 적용하려면 규칙을 편집하세요: 툴팁 줄에 종류마다 단어가 있습니다."
L["In CineMode, your player frame shows whenever your mana is under this share, in a fight or not: drinking, or saving mana for the pull. Off: 0."] = "CineMode에서 마나가 이 비율 아래면 전투 여부와 관계없이 플레이어 프레임을 표시합니다: 마실 때나 풀링 전에 마나를 아낄 때. 끄기: 0."
L["In CineMode, your resource bar shows whenever your mana is under this share, in a fight or not: drinking, or saving mana for the pull. Off: 0."] = "CineMode에서 마나가 이 비율 아래면 전투 여부와 관계없이 자원 바를 표시합니다: 마실 때나 풀링 전에 마나를 아낄 때. 끄기: 0."
L["In a camera mode"] = "카메라 모드 중"
L["In a fight"] = "전투 중"
L["In a fight:"] = "전투 중:"
L["In a group, items rolled on show in a window instead of only as lines in chat: each item, a bar for the time left, and everyone's pick (need, greed, transmog) and number, the winner lit at the top. It opens as an item drops, just under the game's roll frame, so you can see who's picked what before you choose, and takes its place once you have. Each item fades a few seconds after it's won (point at them to keep them). It stays with the game's roll frames: with \"Drag windows to move them\" on, dragging either moves both. /cine rolls shows the latest rolls."] = "파티에서 주사위를 굴리는 아이템을 대화창 줄로만이 아니라 창에 보여 줍니다: 아이템마다 남은 시간 바와 모두의 선택(입찰, 차비, 형상변환)과 숫자, 맨 위에 빛나는 승자. 아이템이 나오면 게임 주사위 창 바로 아래에 열려서 고르기 전에 누가 무엇을 골랐는지 볼 수 있고, 고른 뒤에는 그 자리를 차지합니다. 각 아이템은 주인이 정해지고 몇 초 뒤 사라집니다(가리키면 유지). 게임 주사위 창과 함께 움직입니다: '창을 끌어서 옮기기'가 켜져 있으면 어느 쪽을 끌어도 둘 다 움직입니다. /cine rolls로 최근 주사위를 봅니다."
L["In a raid, each item lists only this many players' rolls: the winner, then need before greed, the highest numbers first. The rest are counted on an \"and N more\" line. In a party, everyone is listed. Click an item's panel to list everyone on it."] = "공격대에서는 아이템마다 이만큼의 플레이어 주사위만 나열합니다: 승자, 그다음 입찰이 차비보다 먼저, 높은 숫자부터. 나머지는 \"외 N명\" 줄로 셉니다. 파티에서는 모두 나열합니다. 아이템 판을 클릭하면 모두 나열합니다."
L["In class color"] = "직업 색으로"
L["In combat is ticked, and you're fighting"] = "'전투 중'이 체크됨, 전투 중"
L["In combat is ticked, but CineMode doesn't stay on in fights"] = "'전투 중'이 체크됨, 하지만 전투 중 CineMode가 유지되지 않음"
L["In combat is ticked: it shows when a fight starts"] = "'전투 중'이 체크됨: 전투가 시작되면 보임"
L["In gusts"] = "돌풍으로"
L["In no scene"] = "장면 없음"
L["In the bar:"] = "바 안:"
L["In the middle of the screen (a subtitle: low on it)."] = "화면 가운데(자막: 아래쪽)."
L["In the zones listed here, the minimap stays up during CineMode: say, one where you do a lot of dailies. Caves and towns inside a zone count as the zone."] = "여기 적은 지역에서는 CineMode 중에도 미니맵이 남아 있습니다: 예를 들어 일일 퀘스트를 많이 하는 곳. 지역 안의 동굴과 마을도 그 지역으로 칩니다."
L["In these zones:"] = "다음 지역에서:"
L["Inner edge:"] = "안쪽 가장자리:"
L["Inside buildings and caves, the camera modes zoom out less and swing less, so the camera doesn't keep pushing into walls and ceilings. Uses the game's own indoor check."] = "건물과 동굴 안에서는 카메라 모드가 덜 축소하고 덜 흔들려서 카메라가 벽과 천장을 계속 파고들지 않습니다. 게임 자체 실내 판정을 씁니다."
L["Inside it: %s"] = "안쪽: %s"
L["Inspect: click any frame to see why it's showing or hidden. Right-click or Escape to stop."] = "살펴보기: 아무 창이나 클릭하면 왜 보이거나 숨겨졌는지 봅니다. 오른쪽 클릭이나 Esc로 멈춥니다."
L["Inspecting someone, a button just right of their level and class opens their talents, and one with their portrait on the talents window takes you back to the inspect window. Not in a fight."] = "누군가를 살펴볼 때 레벨과 직업 바로 오른쪽 버튼으로 그 사람의 특성을 열고, 특성 창의 초상화 버튼으로 살펴보기 창으로 돌아갑니다. 전투 중에는 안 됩니다."
L["Instead of a rule, this row shows whenever another row of its table does, however that one is set now or later. All or nothing: none of this row's own settings count while it follows, and they're kept for when it stops (Grid on the row)."] = "규칙 대신 이 줄은 같은 표의 다른 줄이 보일 때마다 보입니다. 그 줄이 지금이나 나중에 어떻게 설정되든 마찬가지입니다. 전부 아니면 전무: 따르는 동안 이 줄 자체 설정은 하나도 적용되지 않으며, 멈출 때를 위해 보관됩니다(줄의 '격자')."
L["Instead of stopping between moves, the camera keeps creeping slowly back toward the middle."] = "움직임 사이에 멈추는 대신 카메라가 계속 가운데 쪽으로 천천히 되돌아갑니다."
L["Interface Style"] = "인터페이스 스타일"
L["Interrupted"] = "차단됨"
L["Is Cinematic slowing your game?"] = "Cinematic 때문에 게임이 느려지나요?"
L["It ends"] = "끝날 때"
L["It goes with the %s row, which is hidden"] = "%s 줄과 함께 가는데, 그 줄이 숨겨져 있음"
L["It shows only if something happened that's ticked here: quests, a level, bosses, deaths or gold. The zone and time played come with it."] = "여기 체크한 일이 있었을 때만 보입니다: 퀘스트, 레벨, 우두머리, 죽음, 골드. 지역과 플레이 시간이 함께 나옵니다."
L["It sits where the game's %s was, or is named like it: it takes that row's ticks on the Game Frames page until you give it its own."] = "게임의 %s 자리에 있거나 이름이 비슷합니다: 직접 정하기 전까지 게임 창 페이지에서 그 줄의 체크를 따릅니다."
L["It starts once the swing behind you is done, while the zoom carries on. The tilt down follows."] = "뒤쪽으로 다 돌아간 뒤, 확대/축소가 이어지는 동안 시작합니다. 아래로 기울이기가 뒤따릅니다."
L["It stops"] = "멈출 때"
L["It's full (or you can't afford any)."] = "가득 찼습니다(또는 살 돈이 없습니다)."
L["Items shown at once"] = "한 번에 보이는 아이템"
L["Items you can't use (armor or weapons you can't wear, another class's, or a level you're not yet: anything in red on its tooltip) don't get a panel. Their rolls are only in chat."] = "쓸 수 없는 아이템(착용할 수 없는 방어구나 무기, 다른 직업용, 아직 안 된 레벨: 툴팁에 빨갛게 나오는 것)은 판이 생기지 않습니다. 그 주사위는 대화창에만 나옵니다."
L["Its card"] = "카드"
L["Its cast bar isn't faded, like the game's."] = "게임처럼 시전 바를 흐리게 하지 않습니다."
L["Its choices come next."] = "선택지가 다음에 나옵니다."
L["Its color."] = "색."
L["Its color. Auto: your class and spec's (the glow of the Vitals Vision theme Auto picks for you), changing with your spec. Or pick any class and spec's, or your own color beside this."] = "색. 자동: 내 직업과 전문화의 색(자동이 고르는 Vitals Vision 테마의 빛)이며 전문화에 따라 바뀝니다. 또는 아무 직업과 전문화의 색이나 옆에서 직접 고른 색."
L["Its colors, bars and words, and where it sits."] = "색, 바, 글자, 위치."
L["Its group is kept up through the death camera"] = "그 그룹은 죽음 카메라 중에도 유지됨"
L["Its height, next to the game's (nameplates only). The health bar and name ride up on it."] = "게임 대비 높이(이름표만). 생명력 바와 이름이 그 위로 올라갑니다."
L["Its icon is on the master wheel, which opens it. Untick to leave it off: its own key still brings it up. The master wheel is the same for all your characters."] = "아이콘이 마스터 휠에 있어 거기서 엽니다. 빼려면 해제하세요: 자체 키로는 여전히 열 수 있습니다. 마스터 휠은 모든 캐릭터에 공통입니다."
L["Its info panel (XP bar and minimap) follows the Minimap row on the Game Frames page; its unit frames, bars, buffs, chat and quest tracker follow the rows of the frames they replace."] = "정보 판(경험치 바와 미니맵)은 게임 창 페이지의 미니맵 줄을 따르고, 유닛 프레임, 바, 강화 효과, 대화창, 퀘스트 추적기는 대신하는 창의 줄을 따릅니다."
L["Its key binding in the corner"] = "모서리의 단축키"
L["Its look is on the Style tab, a sound for each time of day on the Sounds tab."] = "모양은 스타일 탭에, 시간대별 소리는 소리 탭에 있습니다."
L["Its look is on the Style tab, its sound on the Sounds tab."] = "모양은 스타일 탭에, 소리는 소리 탭에 있습니다."
L["Its look is the Victory style's (the Style tab), its sound on the Sounds tab."] = "모양은 승리 스타일(스타일 탭)을 따르고, 소리는 소리 탭에 있습니다."
L["Its messages show chat any time the UI is faded. (The other columns then have nothing to add.)"] = "UI가 흐려져 있을 때 언제든 이 메시지에 대화창을 표시합니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["Its messages show chat in battlegrounds and arenas."] = "전장과 투기장에서 이 메시지에 대화창을 표시합니다."
L["Its messages show chat in capital cities."] = "수도에서 이 메시지에 대화창을 표시합니다."
L["Its messages show chat in dungeons, scenarios and raids."] = "던전, 시나리오, 공격대에서 이 메시지에 대화창을 표시합니다."
L["Its messages show chat in fights (while you stay cinematic in them)."] = "전투 중(전투 중에도 시네마틱 상태를 유지할 때) 이 메시지에 대화창을 표시합니다."
L["Its messages show chat out in the world, inns included (capital cities are Cities)."] = "여관을 포함한 필드에서 이 메시지에 대화창을 표시합니다(수도는 '도시')."
L["Its messages show chat out of combat with a living enemy targeted."] = "비전투 중 살아 있는 적을 대상으로 지정했을 때 이 메시지에 대화창을 표시합니다."
L["Its messages show chat out of combat with anything else targeted (friends, NPCs, dead enemies)."] = "비전투 중 다른 것(아군, NPC, 죽은 적)을 대상으로 지정했을 때 이 메시지에 대화창을 표시합니다."
L["Its messages show chat while you're in a party or raid, wherever you are."] = "어디에 있든 파티나 공격대 중일 때 이 메시지에 대화창을 표시합니다."
L["Its name in the wheel's middle as you point at it. Empty: its command's first line."] = "가리킬 때 휠 가운데에 나오는 이름. 비우면: 명령의 첫 줄."
L["Its name, mark and the rest of the plate move with the bar's edges. Not on WoW Forever: its plates don't change size."] = "이름, 표시, 이름표의 나머지가 바 가장자리와 함께 움직입니다. WoW Forever에서는 안 됨: 이름표 크기가 바뀌지 않습니다."
L["Its numbers in a color of your own."] = "숫자를 직접 고른 색으로."
L["Its other bars, pet, stance, bag, micro menu, status and art bars are rows on the Standard Frames page."] = "다른 바, 소환수, 태세, 가방, 마이크로 메뉴, 상태, 장식 바는 기본 창 페이지의 줄입니다."
L["Its other bars, pet, stance, totem, micro, bag and data bars are rows on the Standard Frames page, with its unit frames, buffs and chat panels."] = "다른 바, 소환수, 태세, 토템, 마이크로, 가방, 데이터 바는 유닛 프레임, 강화 효과, 대화 판과 함께 기본 창 페이지의 줄입니다."
L["Its own colors"] = "고유 색"
L["Its own:"] = "고유:"
L["Its own: %s. The rest: %s."] = "고유: %s. 나머지: %s."
L["Its rule, as things are now: %s"] = "지금 상태의 규칙: %s"
L["Its size, next to the game's."] = "게임 대비 크기."
L["Its style, words, frame and face, and where it sits."] = "스타일, 글자, 틀, 얼굴, 위치."
L["Its type, and that type's settings."] = "종류와 그 종류의 설정."
L["Its unit frames, cast bar, resource bars, buffs, quest tracker, party and raid frames, XP bar and totems are rows on the Game Frames page."] = "유닛 프레임, 시전 바, 자원 바, 강화 효과, 퀘스트 추적기, 파티와 공격대 창, 경험치 바, 토템은 게임 창 페이지의 줄입니다."
L["Its unnamed frames"] = "이름 없는 창"
L["Its warnings aren't faded, like the game's raid warnings."] = "게임의 공격대 경보처럼 경고를 흐리게 하지 않습니다."
L["Its width, next to the game's, about its middle (nameplates only)."] = "게임 대비 너비, 가운데 기준(이름표만)."
L["Just at the top"] = "위쪽에만"
L["Just the new one"] = "새것만"
L["Just the text, over the world."] = "세상 위에 글자만."
L["Just the words, over the world: an outline helps them read."] = "세상 위에 글자만: 외곽선이 있으면 읽기 쉽습니다."
L["KEEPING IT HIDDEN"] = "숨김 유지 중"
L["Keep bubbles on screen"] = "말풍선을 화면 안에 유지"
L["Keep open: a tracked quest"] = "계속 열기: 추적 중인 퀘스트"
L["Keep open: always"] = "계속 열기: 항상"
L["Keep open: in this zone"] = "계속 열기: 이 지역에서"
L["Keep open: indoors, and you're inside"] = "계속 열기: 실내, 지금 실내에 있음"
L["Keep the active profile as it is now: Reset and each page's Reset put it back to this instead of Cinematic's own settings."] = "현재 프로필을 지금 상태로 보관합니다: 초기화와 각 페이지의 초기화가 Cinematic 기본 설정 대신 이 상태로 되돌립니다."
L["Keep windows open across a reload"] = "다시 불러와도 창을 열어 두기"
L["Keeping a frame up, always or in fights, is on the Game Frames page; your own while you recover, on the Resource Display page."] = "창을 항상 또는 전투 중에 띄워 두는 것은 게임 창 페이지에, 회복하는 동안 내 창은 자원 표시 페이지에 있습니다."
L["Keeps the Cooldown Manager up until every cooldown in its Essential bar (and Enhanced Cooldown Manager's cooldown bars) is ready again, then it fades. Not the global cooldown, nor its buff bars. (It brings up the Hover groups with Cooldown recharging ticked: the Cooldowns group by default.)"] = "필수 바의 모든 재사용 대기시간(과 Enhanced Cooldown Manager의 재사용 대기시간 바)이 다시 준비될 때까지 재사용 대기시간 관리자를 띄워 두었다가 흐리게 합니다. 전역 재사용 대기시간과 강화 효과 바는 제외합니다. ('재사용 대기시간 충전 중'에 체크한 마우스오버 그룹을 함께 띄웁니다. 기본값은 재사용 대기시간 그룹입니다.)"
L["Keeps the Cooldown Manager up until every cooldown in its Utility bar is ready again, then it fades. (It brings up the Hover groups with Cooldown recharging ticked: the Cooldowns group by default.)"] = "보조 바의 모든 재사용 대기시간이 다시 준비될 때까지 재사용 대기시간 관리자를 띄워 두었다가 흐리게 합니다. ('재사용 대기시간 충전 중'에 체크한 마우스오버 그룹을 함께 띄웁니다. 기본값은 재사용 대기시간 그룹입니다.)"
L["Keeps the quest tracker's timers up in CineMode, and in fights, while one counts down: a scenario's or assault's timer, a dungeon's clock, a timed quest's bar. Just the timer's quest or scenario: the rest of the tracker stays faded. Hovering it shows it all."] = "타이머가 줄어드는 동안 CineMode와 전투 중에 퀘스트 추적기의 타이머를 띄워 둡니다: 시나리오나 습격 타이머, 던전 시계, 시간제 퀘스트 바. 타이머의 퀘스트나 시나리오만: 추적기의 나머지는 흐린 채로 둡니다. 마우스를 올리면 전부 보입니다."
L["Keeps your pet frame up after a fight or a fall, within the Calm Timer, until your pet's health is full."] = "전투나 낙하 뒤 진정 타이머 안에서 소환수 생명력이 가득 찰 때까지 소환수 프레임을 띄워 둡니다."
L["Keeps your pet frame up in CineMode, and in fights, while its happiness isn't green: content (yellow) or unhappy (red). It goes again once your pet is happy."] = "소환수의 만족도가 초록이 아닌 동안(만족: 노랑, 불만: 빨강) CineMode와 전투 중에 소환수 프레임을 띄워 둡니다. 소환수가 행복해지면 다시 사라집니다."
L["Keeps your player frame up after a fight, a fall or resurrecting, until your health and power are full. Rage and runic power don't count."] = "전투, 낙하, 부활 뒤 생명력과 자원이 가득 찰 때까지 플레이어 프레임을 띄워 둡니다. 분노와 룬 마력은 치지 않습니다."
L["Kept from the %s profile, which Cinematic no longer has."] = "Cinematic에 더는 없는 %s 프로필에서 보관함."
