L["Key binding"] = "단축키"
L["Kill streak"] = "연속 처치"
L["Land and buildings"] = "땅과 건물"
L["Last recording: %s, %s"] = "마지막 기록: %s, %s"
L["Last recording: %s, %s, detailed"] = "마지막 기록: %s, %s, 상세"
L["Last tooltip"] = "마지막 툴팁"
L["Later around the wheel."] = "휠에서 더 뒤쪽."
L["Layout"] = "배치"
L["Learned"] = "배움"
L["Leave the speaker off center"] = "말하는 사람을 가운데에서 비켜 두기"
L["Leaving combat"] = "전투 종료"
L["Leaving the quest giver, the camera stays close until you walk more than 10 yards from where you started talking (talk to another quest giver and it counts from there), then zooms back out to your own distance at this speed, in a few seconds at most. At 0 it stays in."] = "퀘스트 NPC를 떠날 때, 대화를 시작한 곳에서 10m 넘게 걸어갈 때까지 카메라가 가까이 머물다가(다른 퀘스트 NPC와 대화하면 거기서부터 셈), 이 속도로 길어야 몇 초 안에 내 거리로 다시 축소합니다. 0이면 가까이 머뭅니다."
L["Left-click: add a point. Right-click: take one back."] = "왼쪽 클릭: 점수 추가. 오른쪽 클릭: 하나 되돌리기."
L["Letterbox scale"] = "레터박스 비율"
L["Level %d"] = "%d레벨"
L["Level reached"] = "도달한 레벨"
L["Level required: %s"] = "필요 레벨: %s"
L["Level up"] = "레벨 업"
L["Lift speed"] = "올라가는 속도"
L["Light words on a dark, see-through bubble with a thin edge, in Arial Narrow."] = "가는 테두리의 어둡고 반투명한 말풍선에 밝은 글자, Arial Narrow."
L["Light words on dark, see-through panels, in Arial Narrow."] = "어둡고 반투명한 판에 밝은 글자, Arial Narrow."
L["Lightning"] = "번개"
L["Like the game's"] = "게임처럼"
L["Like the game's names"] = "게임 이름처럼"
L["Like the quest window's page."] = "퀘스트 창의 페이지처럼."
L["Line along the edge:"] = "가장자리를 따라 선:"
L["Line up behind you over %s s"] = "%s초에 걸쳐 뒤쪽으로 정렬"
L["Lines"] = "줄"
L["Lit"] = "켜짐"
L["Living NPCs that aren't elite, rare elite or a boss (minor critters too). Normal NPC - Enemy starts faded to 40% while an elite enemy is within about 28 yards (its When rule: elite28), so in a pull the elites stand out."] = "정예, 희귀 정예, 우두머리가 아닌 살아 있는 NPC(하찮은 동물 포함). '일반 NPC - 적'은 약 28m 안에 정예 적이 있으면 40%로 흐려진 채 시작하므로(적용 조건 규칙: elite28), 풀링할 때 정예가 돋보입니다."
L["Living elite, rare elite and boss NPCs."] = "살아 있는 정예, 희귀 정예, 우두머리 NPC."
L["Location"] = "위치"
L["Logic"] = "논리"
L["Look around for speakers off screen"] = "화면 밖의 말하는 사람 둘러보기"
L["Look in the background"] = "배경 보기"
L["Look:"] = "모양:"
L["Looking out"] = "바깥 보기"
L["Looking... %ds"] = "찾는 중... %d초"
L["Looks once a second for a while, so a frame that only shows now and then is caught: bring it up while it runs. Click again to stop."] = "잠시 동안 매초 확인해서 가끔만 보이는 창도 잡아냅니다: 도는 동안 그 창을 띄우세요. 다시 클릭하면 멈춥니다."
L["Looks over what's on screen for other addons' frames that nothing fades, and guesses which Game Frames row each stands in for. Add one to fade it: it goes on the Loaded tab, under its addon."] = "화면에서 아무것도 흐리게 하지 않는 다른 애드온의 창을 찾고, 각각이 어떤 게임 창 줄을 대신하는지 추측합니다. 흐리게 하려면 추가하세요: '불러옴' 탭의 해당 애드온 아래로 들어갑니다."
L["Loot rolls"] = "전리품 주사위"
L["Lost"] = "잃음"
L["Lost:"] = "잃음:"
L["Low mana"] = "마나 부족"
L["Low mana brings up your player frame as well as your resource bar."] = "마나가 부족하면 자원 바와 함께 플레이어 프레임도 띄웁니다."
L["Low on the left of the screen, as a film names someone, its line fading out to the right."] = "영화에서 인물을 소개하듯 화면 왼쪽 아래, 줄이 오른쪽으로 흐려지며 사라집니다."
L["Lower picks: %d"] = "낮은 선택: %d"
L["Lower third"] = "하단 자막"
L["Lower third with no letterbox"] = "레터박스 없는 하단 자막"
L["Made by %s"] = "%s 제작"
L["Made from these settings. Copy the camera to change the step itself."] = "이 설정으로 만들어졌습니다. 단계 자체를 바꾸려면 카메라를 복사하세요."
L["Made up"] = "지어냄"
L["Make a scene of your own: its triggers (an emote, a spell, a buff, a place, a moment, something you are, or a key), the camera it plays and when it ends."] = "나만의 장면을 만듭니다: 발동 조건(감정 표현, 주문, 강화 효과, 장소, 순간, 나의 상태, 또는 키), 재생할 카메라, 끝나는 때."
L["Make a shot, starting from the cozy camera's own numbers. Pick another camera for it below."] = "아늑한 카메라의 수치에서 시작하는 샷을 만듭니다. 아래에서 다른 카메라를 고를 수 있습니다."
L["Make this layout again as Cinematic has it, undoing any changes you made to it in Edit Mode."] = "이 레이아웃을 Cinematic 기본대로 다시 만들어 편집 모드에서 바꾼 것을 취소합니다."
L["Makes the tint stronger on this client, whose brighter, more colorful world shows the same tint less than retail does. Off: the tint as the Strength slider sets it."] = "이 클라이언트에서 색조를 더 강하게 합니다. 이 클라이언트는 세상이 더 밝고 다채로워서 같은 색조가 리테일보다 약하게 보입니다. 끄면: 강도 슬라이더대로의 색조."
L["Mana"] = "마나"
L["Mana bar"] = "마나 바"
L["Mana bar:"] = "마나 바:"
L["Manage and share"] = "관리와 공유"
L["Mark"] = "표시"
L["Mark %d%%"] = "표시 %d%%"
L["Mark's"] = "표시 색"
L["Marker wheel"] = "징표 휠"
L["Marks"] = "표시"
L["Master wheel"] = "마스터 휠"
L["Max level"] = "최고 레벨"
L["Max width"] = "최대 너비"
L["Max zoom distance"] = "최대 축소 거리"
L["Meanwhile the camera pulls back this far, and returns to your own distance afterwards. Zooming yourself leaves it where you put it."] = "그동안 카메라가 이만큼 물러났다가 나중에 내 거리로 돌아옵니다. 직접 확대/축소하면 놓은 곳에 그대로 둡니다."
L["Mechanical Squirrel"] = "기계 다람쥐"
L["Members more than 100 yards away show this much, out of reach of your heals, whatever their health, debuffs or role (unless one is your target). In a dungeon or raid, so does anyone not in it with you. In battlegrounds, where WoW Forever won't say how far anyone is, members out of range of your heals (about 40 yards) fade to this instead of the game's own dimming, on top of the rest of the page. 100% leaves them be; 0% hides them completely."] = "100m 넘게 떨어진, 치유가 닿지 않는 파티원은 생명력, 약화 효과, 역할과 관계없이 이만큼 보입니다(대상이 아니라면). 던전이나 공격대에서는 함께 들어오지 않은 사람도 그렇습니다. 전장에서는 WoW Forever가 거리를 알려 주지 않으므로, 치유 사거리(약 40m) 밖의 파티원이 게임 자체의 흐림 대신 이만큼으로 흐려지며 페이지의 나머지 설정 위에 더해집니다. 100%면 그대로 두고, 0%면 완전히 숨깁니다."
L["Memory made and thrown away, a second: the game spends time clearing it up."] = "초당 만들고 버리는 메모리: 게임이 이를 정리하는 데 시간을 씁니다."
L["Menu look"] = "메뉴 모양"
L["Mine"] = "내 것"
L["Minimal"] = "최소"
L["Minimap Glow Helper"] = "미니맵 빛 도우미"
L["Minimap header"] = "미니맵 머리글"
L["Minion"] = "하수인"
L["Mobs and NPCs you still need for a quest objective keep their nameplates up, with a quest mark on them and on your target frame, and the quest object in front of you glows."] = "퀘스트 목표에 아직 필요한 몹과 NPC는 이름표를 유지하고, 이름표와 대상 프레임에 퀘스트 표시가 붙으며, 앞에 있는 퀘스트 사물이 빛납니다."
L["Moment"] = "순간"
L["Moments"] = "순간"
L["Mor'Ladim"] = "모르라딤"
L["More themes"] = "테마 더 보기"
L["Motes of its color winding in from the rim."] = "테두리에서 감겨 들어오는 그 색의 티끌."
L["Motes spiraling in"] = "나선으로 들어오는 티끌"
L["Mounted"] = "탈것 탑승"
L["Mouseover"] = "마우스오버"
L["Mouseover min opacity"] = "마우스오버 최소 불투명도"
L["Mouseover, at least"] = "마우스오버, 최소"
L["Move"] = "이동"
L["Move across"] = "가로질러 이동"
L["Move apart from the game's roll frames"] = "게임 주사위 창과 따로 이동"
L["Move down"] = "아래로"
L["Move this emote up: its button comes first."] = "이 감정 표현을 위로: 버튼이 먼저 나옵니다."
L["Move this row down: a plate tries it later."] = "이 줄을 아래로: 이름표가 나중에 시도합니다."
L["Move this row down: its trigger tries it later."] = "이 줄을 아래로: 발동 조건이 나중에 시도합니다."
L["Move this row up: a plate tries it sooner."] = "이 줄을 위로: 이름표가 더 일찍 시도합니다."
L["Move this row up: its trigger tries it sooner."] = "이 줄을 위로: 발동 조건이 더 일찍 시도합니다."
L["Move this rule up: it's read before the ones below it."] = "이 규칙을 위로: 아래 규칙보다 먼저 읽힙니다."
L["Move up"] = "위로"
L["Moves a name up (or down, below 0) from where the plates put it, with its unit about 10 yards from the camera."] = "유닛이 카메라에서 약 10m일 때, 이름표가 놓는 자리에서 이름을 위로(0 미만이면 아래로) 옮깁니다."
L["Moves a name up (or down, below 0) with its unit about 50 yards from the camera, as the game's names over heads sit closer to the head further off."] = "유닛이 카메라에서 약 50m일 때 이름을 위로(0 미만이면 아래로) 옮깁니다. 게임의 머리 위 이름은 멀수록 머리에 가깝게 붙기 때문입니다."
L["Moves the card from where its place puts it: right, or left below 0, as a share of the screen's width."] = "카드를 원래 자리에서 오른쪽(0 미만이면 왼쪽)으로 옮깁니다. 화면 너비 비율."
L["Moves the card from where its place puts it: up, or down below 0, as a share of the screen's height."] = "카드를 원래 자리에서 위(0 미만이면 아래)로 옮깁니다. 화면 높이 비율."
L["Moves the marks drawn over the plate (arrow, chevron, diamond) up, or down below 0, from just over the name, while the plate shows."] = "이름표가 보이는 동안 이름표 위에 그리는 표시(화살표, 갈매기표, 마름모)를 이름 바로 위에서 위로(0 미만이면 아래로) 옮깁니다."
L["Moves the marks drawn over the plate up, or down below 0, from where the plate's middle is, while nothing of the plate shows. As the plate fades in or out, the marks move between the two heights."] = "이름표가 전혀 보이지 않는 동안 이름표 위에 그리는 표시를 이름표 가운데에서 위로(0 미만이면 아래로) 옮깁니다. 이름표가 나타나거나 사라지면 표시도 두 높이 사이를 움직입니다."
L["Moves the names up (or down, below 0) from where the plates put them."] = "이름표가 놓는 자리에서 이름을 위로(0 미만이면 아래로) 옮깁니다."
L["Moves the real camera through this script now (click again to stop it). Its stop rules count, as for a trigger."] = "지금 실제 카메라를 이 스크립트대로 움직입니다(다시 클릭하면 멈춤). 발동 조건처럼 멈춤 규칙이 적용됩니다."
L["Moves the real camera through this script now, with a drawing of it beside the settings and its steps lit up as it goes (click again to stop it). Its stop rules count, as for a trigger."] = "지금 실제 카메라를 이 스크립트대로 움직이며, 설정 옆에 그림을 그리고 진행에 따라 단계를 밝힙니다(다시 클릭하면 멈춤). 발동 조건처럼 멈춤 규칙이 적용됩니다."
L["Moving, jumping or Esc cancels the cast: the spin slows to a stop and turns back to where the camera was before you started. Off: it stops where it is."] = "움직이거나 점프하거나 Esc를 누르면 시전이 취소됩니다: 회전이 느려지며 멈추고 시작 전 카메라 자리로 돌아갑니다. 끄면: 그 자리에서 멈춥니다."
L["Music can play all through CineMode. (The other columns then have nothing to add.)"] = "CineMode 내내 음악을 틀 수 있습니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["Music fades out once you leave the camera modes and move on: walking off from the cozy camera, say. Going from one camera straight to another (vista to cozy) keeps it playing, as does standing still. A fresh track fades in when the next camera starts (standing still counts once the AFK camera starts, with Go AFK's music on, Scenes page). Fades at the music fade time."] = "카메라 모드를 벗어나 움직이면 음악이 사라집니다: 예를 들어 아늑한 카메라에서 걸어 나갈 때. 한 카메라에서 다른 카메라로 바로 넘어가면(풍경에서 아늑함으로) 계속 재생되며, 가만히 서 있어도 마찬가지입니다. 다음 카메라가 시작되면 새 곡이 서서히 나옵니다(가만히 서 있기는 자리 비움 카메라가 시작될 때 침. 장면 페이지에서 자리 비움의 음악이 켜져 있을 때). 음악 페이드 시간에 맞춰 흐려집니다."
L["Music file IDs, separated by commas. One is picked at random while the Die row's Music is ticked on the Scenes page."] = "음악 파일 ID, 쉼표로 구분. 장면 페이지에서 죽음 줄의 음악에 체크하면 그중 하나를 무작위로 고릅니다."
L["Music file IDs, separated by commas; one is picked at random each time you die (Wowhead lists the IDs on each sound's page). Try one with /cine songtest <ID>."] = "음악 파일 ID, 쉼표로 구분. 죽을 때마다 하나를 무작위로 고릅니다(Wowhead의 각 소리 페이지에 ID가 있습니다). /cine songtest <ID>로 들어 보세요."
L["Music plays in"] = "음악 재생 장소"
L["Music starts as its camera starts (Audio page)."] = "카메라가 시작될 때 음악이 시작됩니다(소리 페이지)."
L["Music starts as this event's camera starts, unless the addon started music within the fatigue time (Audio page). Music already playing just carries on. Off: this camera never starts music. Needs the Audio page enabled."] = "이 이벤트의 카메라가 시작될 때 음악이 시작됩니다. 단, 피로 시간 안에 애드온이 음악을 튼 적이 있으면 제외합니다(소리 페이지). 이미 재생 중인 음악은 그대로 이어집니다. 끄면: 이 카메라는 음악을 틀지 않습니다. 소리 페이지를 사용해야 합니다."
