L["Nearly every one of the addon's functions timed too, not just its busy parts, each listed under the part that called it: it shows what inside a busy part costs. The timing itself takes time, so everything reads higher than it is."] = "바쁜 부분만이 아니라 애드온의 거의 모든 함수의 시간도 재며, 각각 호출한 부분 아래에 나열합니다: 바쁜 부분 안에서 무엇이 비용을 쓰는지 보여 줍니다. 시간 재기 자체도 시간이 들어서 모든 값이 실제보다 높게 나옵니다."
L["Need"] = "입찰"
