L["No card coming out of a fight shorter than this, so a stray hit doesn't bring it up. 0: after every fight."] = "이보다 짧은 전투가 끝날 때는 카드를 띄우지 않아서, 어쩌다 한 대 맞은 것으로는 나오지 않습니다. 0: 모든 전투 뒤에."
