L["No panels behind the cards: outlined text over the world, the winner just crowned."] = "카드 뒤에 판 없음: 세상 위에 외곽선 글자, 승자에게는 왕관만."
L["No panels: outlined words, like a film's subtitles."] = "판 없음: 영화 자막처럼 외곽선 글자."
L["No profile yet"] = "아직 프로필 없음"
L["No recording yet."] = "아직 기록이 없습니다."
L["No red error text at the top of the screen (like \"Target not in line of sight\" or \"Can't do that while moving\") while you're fighting, and for the Calm Timer after it."] = "전투 중과 그 뒤 진정 타이머 동안 화면 위의 빨간 오류 문자(\"대상이 시야에 없습니다\"나 \"이동 중에는 할 수 없습니다\" 같은)를 없앱니다."
L["No red error text at the top of the screen (like \"Target not in line of sight\" or \"Can't do that while moving\") while you're out of combat."] = "비전투 중에 화면 위의 빨간 오류 문자(\"대상이 시야에 없습니다\"나 \"이동 중에는 할 수 없습니다\" 같은)를 없앱니다."
L["No rolls yet."] = "아직 주사위가 없습니다."
