L["No scene plays it yet: pick it as a scene's camera on the Scenes page."] = "아직 이것을 재생하는 장면이 없습니다: 장면 페이지에서 장면의 카메라로 고르세요."
L["No scene plays this camera yet: pick it as a scene's camera on the Scenes page."] = "아직 이 카메라를 재생하는 장면이 없습니다: 장면 페이지에서 장면의 카메라로 고르세요."
L["No shots yet. + New shot makes one, or Import adds one a friend shared."] = "아직 샷이 없습니다. '+ 새 샷'으로 만들거나, '가져오기'로 친구가 공유한 것을 추가하세요."
L["No sounds: silent"] = "소리 없음: 조용함"
L["No spell"] = "주문 없음"
L["No tooltip yet this session: point at something, then look again"] = "이번 세션에 아직 툴팁이 없습니다: 무언가를 가리킨 뒤 다시 보세요"
L["None found"] = "찾지 못함"
L["None of its own: it's all %s."] = "자체 값 없음: 모두 %s."
L["None yet. A built-in profile is backed up just before Reset."] = "아직 없음. 기본 프로필은 초기화 직전에 백업됩니다."
L["None yet. One's taken the first day this profile changes, and just before Delete."] = "아직 없음. 이 프로필이 바뀐 첫날과 삭제 직전에 하나씩 만들어집니다."
L["None yet. Your own profiles are backed up the first day they change, and just before Delete; built-in ones just before Reset."] = "아직 없음. 내 프로필은 바뀐 첫날과 삭제 직전에, 기본 프로필은 초기화 직전에 백업됩니다."
L["None: its own settings"] = "없음: 자체 설정"
L["Normal"] = "일반"
