L["Not a script yet: it runs on its own code. Laying it out as steps needs %s, steps the runner doesn't have yet."] = "아직 스크립트가 아닙니다: 자체 코드로 돌아갑니다. 단계로 펼치려면 %s이(가) 필요한데, 실행기에 아직 없는 단계입니다."
L["Not after fights under"] = "다음보다 짧은 전투 뒤에는 안 함"
