L["Not bosses"] = "우두머리 아님"
L["Not finished: %s. Closing now puts back the rule it had."] = "완성되지 않음: %s. 지금 닫으면 원래 규칙으로 돌아갑니다."
L["Not finished: %s. Its ticks decide until it is."] = "완성되지 않음: %s. 완성될 때까지 체크 상태가 정합니다."
L["Not finished: %s. The dropdowns decide until it is."] = "완성되지 않음: %s. 완성될 때까지 드롭다운이 정합니다."
L["Not for dailies"] = "일일 퀘스트는 제외"
L["Not in %s"] = "%s 아님"
L["Not in a fight."] = "전투 중 아님."
L["Not in fights"] = "전투 중에는 안 함"
L["Not in the Cooldown Manager now"] = "지금 재사용 대기시간 관리자에 없음"
L["Not on flight paths"] = "비행 경로에서는 안 함"
L["Not on it"] = "없음"
L["Not on screen right now."] = "지금 화면에 없습니다."
L["Not on you"] = "나에게 없음"
L["Not ones lasting longer than"] = "다음보다 오래 지속되는 것은 제외"
L["Not shown at all in a fight, or in the 5 seconds after one."] = "전투 중이나 전투 후 5초 동안은 전혀 표시하지 않습니다."
L["Not the damage meter's numbers: your race with the player ahead of you, or your lead over #2 once you're #1. It reads the game's own damage meter, so that needs to be on (Options, Gameplay Enhancements: Enable Damage Meter). Its type: the Settings tab. How it looks: the Look tab."] = "피해량 측정기 숫자가 아닙니다: 바로 앞 플레이어와의 경쟁, 또는 1위가 되면 2위와의 격차. 게임 자체 피해량 측정기를 읽으므로 그것을 켜야 합니다(옵션, 게임플레이 향상: 피해량 측정기 사용). 종류: 설정 탭. 모양: 모양 탭."
L["Not with a soulstone or Reincarnation"] = "영혼석이나 윤회가 있으면 안 함"
L["Not you"] = "내가 아님"
L["Nothing"] = "없음"
L["Nothing found yet. Smart Find looks at what's on screen: run it while the frames you want are showing."] = "아직 찾은 것이 없습니다. 스마트 찾기는 화면에 있는 것을 봅니다: 원하는 창이 보이는 동안 실행하세요."
L["Nothing in the Cooldown Manager right now."] = "지금 재사용 대기시간 관리자에 아무것도 없습니다."
L["Nothing is ticked on its row: tick Always to keep it up"] = "줄에 아무것도 체크되지 않음: 계속 띄우려면 '항상'에 체크하세요"
L["Nothing of its own here: its look is on the Style tab, its sound on the Sounds tab."] = "여기에는 자체 설정이 없습니다: 모양은 스타일 탭에, 소리는 소리 탭에 있습니다."
L["Nothing on it yet"] = "아직 아무것도 없음"
L["Nothing on the meter yet."] = "아직 측정기에 아무것도 없습니다."
L["Nothing ticked"] = "체크한 것 없음"
