L["Now"] = "지금"
L["Now and then in the middle of a flight, the camera slowly turns round to look back past you, holds there, then turns back behind you. On a route's first flight (its length not known yet), just one, early on. Dragging the camera stops it. /cine flyby starts one whenever you like. Once you move the camera yourself on a flight, there are no more for that flight."] = "비행 중간중간 카메라가 천천히 돌아서 나를 지나 뒤를 돌아보고, 잠시 머문 뒤 다시 뒤쪽으로 돌아갑니다. 경로의 첫 비행(길이를 아직 모를 때)에는 초반에 한 번만. 카메라를 끌면 멈춥니다. /cine flyby로 언제든 시작할 수 있습니다. 비행 중 직접 카메라를 움직이면 그 비행에서는 더 나오지 않습니다."
L["Now: %s"] = "지금: %s"
L["Numbers follow the game's Show Numbers for Cooldowns"] = "숫자는 게임의 '재사용 대기시간 숫자 표시'를 따름"
L["Numbers opacity"] = "숫자 불투명도"
L["Object detail distance"] = "사물 세부 묘사 거리"
L["Object fade distance"] = "사물 사라짐 거리"
L["Objective boxes (below the minimap)"] = "목표 상자 (미니맵 아래)"
L["Objects and creatures"] = "사물과 생물"
L["Off with the General page's switch."] = "일반 페이지의 스위치로 꺼짐."
L["Off-screen bubble"] = "화면 밖 말풍선"
L["Off-screen plates in CineMode"] = "CineMode에서 화면 밖 이름표"
L["Off. Right-click to turn this page on."] = "꺼짐. 오른쪽 클릭하면 이 페이지를 켭니다."
L["Off: %s"] = "꺼짐: %s"
L["Off: right-click the Profiler icon to sample."] = "꺼짐: 표본을 담으려면 프로파일러 아이콘을 오른쪽 클릭하세요."
L["Off: the UI stays as it is and the camera's left to you, with just the visual effects over it (as the Visual Effects page says), as in the Subtle profile. Triggers with CineMode ticked on the Scenes page still bring CineMode on while their camera runs: standing still or going AFK, say, for a screensaver."] = "끄면: UI는 그대로 두고 카메라도 직접 조작하며, 화면 효과만 위에 덧씌웁니다(화면 효과 페이지 설정대로). 'Subtle' 프로필과 같습니다. 장면 페이지에서 CineMode에 체크한 발동 조건은 그 카메라가 도는 동안 여전히 CineMode를 켭니다. 예를 들어 가만히 서 있거나 자리를 비울 때 화면 보호기처럼 쓸 수 있습니다."
L["Offline"] = "오프라인"
L["Offline members are hidden whatever their health, debuffs or role (unless one is your target). How much of them still shows. 0% hides them completely."] = "오프라인 파티원은 생명력, 약화 효과, 역할과 관계없이 숨겨집니다(대상이 아니라면). 그래도 얼마나 보일지 정합니다. 0%는 완전히 숨깁니다."
L["Offline opacity"] = "오프라인 불투명도"
L["On a flight path the minimap stays hidden: pings, the reveals above and the tracking and zones under Keep open don't bring it up (you can't gather while flying), and nothing is pinged. Hovering it still shows it."] = "비행 경로에서는 미니맵이 숨겨진 채로 있습니다: 핑, 위의 표시 설정, '계속 열기'의 추적과 지역이 미니맵을 띄우지 않으며(비행 중에는 채집할 수 없음), 핑도 찍지 않습니다. 마우스를 올리면 여전히 보입니다."
L["On a healer"] = "치유 전담에게"
L["On a non-tank"] = "방어 전담 아닌 사람에게"
L["On after a fight, until the Calm Timer (CineMode page) has run out. With In combat too: the fight, then that."] = "전투 후 진정 타이머(CineMode 페이지)가 끝날 때까지 켜짐. '전투 중'도 함께면: 전투 동안, 그다음 그 시간 동안."
L["On flight paths. The camera swings around behind you as you take off, sways behind you on the way and settles behind you before landing."] = "비행 경로에서. 이륙할 때 카메라가 뒤쪽으로 돌아가고, 가는 동안 뒤에서 흔들리며, 착륙 전에 뒤쪽에 자리 잡습니다."
L["On in fights, and with the Calm Timer, after them till it's run out."] = "전투 중 켜짐. 진정 타이머도 함께면 전투 후 그 시간이 끝날 때까지."
L["On out of fights, once the Calm Timer after one has run out. With Calm Timer too: as soon as a fight ends."] = "비전투 중, 전투 후 진정 타이머가 끝나면 켜짐. 진정 타이머도 함께면: 전투가 끝나자마자."
L["On the bar:"] = "바 위:"
L["On the master wheel"] = "마스터 휠에"
L["On the screen"] = "화면에"
L["On while a camera mode runs (flights, AFK, cozy and the rest)."] = "카메라 모드(비행, 자리 비움, 아늑함 등)가 도는 동안 켜짐."
L["On while you have one of these targeted, out of fights."] = "비전투 중 다음 중 하나를 대상으로 지정했을 때 켜짐."
L["On while you're in any of these (Party and Raid: in one, wherever you are)."] = "다음 중 어디에든 있는 동안 켜짐(파티와 공격대: 어디에 있든 그 안에 있을 때)."
L["On you"] = "나에게"
L["On. Right-click to turn this page off."] = "켜짐. 오른쪽 클릭하면 이 페이지를 끕니다."
L["On: Heal Vision works as ticked below. Off: it doesn't, and each keeps its tick for when you turn this back on."] = "켜면: Heal Vision이 아래 체크대로 작동합니다. 끄면: 작동하지 않으며, 다시 켤 때를 위해 각 체크는 유지됩니다."
L["On: chat bubbles look as this page says. Off: the game's own bubbles (the preview shows that too). Each setting keeps its value for when you turn this back on. (Not in instances on retail: the game doesn't let addons change bubbles there.)"] = "켜면: 말풍선이 이 페이지대로 보입니다. 끄면: 게임 자체 말풍선(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다. (리테일 인스턴스에서는 안 됨: 게임이 그곳에서 애드온의 말풍선 변경을 막습니다.)"
L["On: chat bubbles show where this page says. Off: the game's own chat bubble settings, as you had them."] = "켜면: 말풍선이 이 페이지가 정한 곳에 보입니다. 끄면: 원래 쓰던 게임 자체 말풍선 설정."
L["On: each card shows as its row says. Off: none of them do, and each row keeps its tick for when you turn this back on."] = "켜면: 각 카드가 줄 설정대로 보입니다. 끄면: 하나도 보이지 않으며, 다시 켤 때를 위해 각 줄의 체크는 유지됩니다."
L["On: each card shows as the Events tab says, as this tab sets it. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "켜면: 각 카드가 이벤트 탭대로, 이 탭의 설정으로 보입니다. 끄면: 하나도 보이지 않습니다. 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: each card shows as the Events tab says, in its style. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "켜면: 각 카드가 이벤트 탭대로, 그 스타일로 보입니다. 끄면: 하나도 보이지 않습니다. 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: each card shows as the Events tab says, looking as its Style page says. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "켜면: 각 카드가 이벤트 탭대로, 스타일 페이지의 모양으로 보입니다. 끄면: 하나도 보이지 않습니다. 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: each card shows as the Events tab says, with its sounds. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "켜면: 각 카드가 이벤트 탭대로, 그 소리와 함께 보입니다. 끄면: 하나도 보이지 않습니다. 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: every Style page looks as it says. Off: none of them do; everything shows the game's look. Each page keeps its settings for when you turn this back on."] = "켜면: 모든 스타일 페이지가 설정대로 보입니다. 끄면: 하나도 적용되지 않고 모두 게임의 모양으로 보입니다. 다시 켤 때를 위해 각 페이지의 설정은 유지됩니다."
L["On: everything below works as ticked. Off: none of it does, and each keeps its tick for when you turn this back on."] = "켜면: 아래 모든 것이 체크대로 작동합니다. 끄면: 하나도 작동하지 않으며, 다시 켤 때를 위해 각 체크는 유지됩니다."
L["On: it looks as this page says. Off: Cinematic's plain look (the defaults). Each setting keeps its value for when you turn this back on."] = "켜면: 이 페이지대로 보입니다. 끄면: Cinematic의 기본 모양(기본값). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: it shows as you cast. Off: it doesn't, and keeps its settings for when you turn this back on."] = "켜면: 시전할 때 보입니다. 끄면: 보이지 않으며, 다시 켤 때를 위해 설정은 유지됩니다."
L["On: new messages, typing, unread whispers and scrolling back bring up the chat windows as this page says. Off: none of them do, and the chat windows fade as their Game Frames row says."] = "켜면: 새 메시지, 입력, 읽지 않은 귓속말, 위로 스크롤이 이 페이지대로 대화창을 띄웁니다. 끄면: 아무것도 띄우지 않으며, 대화창은 게임 창 줄대로 흐려집니다."
L["On: right-click (or a gamepad button) casts again, and the Fishing cast bar hides, as this page says. Off: fishing is left to the game. (The fish camera is on the Scenes page.)"] = "켜면: 오른쪽 클릭(또는 게임패드 버튼)으로 다시 시전하고, 낚시 시전 바를 이 페이지대로 숨깁니다. 끄면: 낚시는 게임에 맡깁니다. (낚시 카메라는 장면 페이지에 있습니다.)"
L["On: the bars look as this page says. Off: Cinematic's own, thin black bars sliding in with the UI's fade (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "켜면: 바가 이 페이지대로 보입니다. 끄면: UI 흐리기와 함께 미끄러져 들어오는 Cinematic 자체의 가는 검은 바(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: the bars look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "켜면: 바가 이 페이지대로 보입니다. 끄면: 게임 자체 바(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: the button looks as this page says. Off: like the game's extra ability button (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "켜면: 버튼이 이 페이지대로 보입니다. 끄면: 게임의 추가 행동 버튼처럼(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: the camera moves over your right shoulder. This uses one of Blizzard's experimental camera settings: the game shows its experimental camera warning (Accept keeps it working). The game's Keep Character Centered option (Accessibility) stops it, so that's turned off meanwhile. Off: your own settings come back."] = "켜면: 카메라가 오른쪽 어깨 너머로 옮겨 갑니다. 블리자드의 실험적 카메라 설정 중 하나를 쓰므로 게임이 실험적 카메라 경고를 띄웁니다('수락'해야 계속 작동). 게임의 '캐릭터를 가운데에 유지' 옵션(접근성)이 이를 막으므로 그동안 꺼 둡니다. 끄면: 내 설정이 돌아옵니다."
L["On: the cameras start as the rows below say. Off: none of them ever starts, and the camera is left to you; CineMode still fades the UI."] = "켜면: 아래 줄대로 카메라가 시작됩니다. 끄면: 어떤 카메라도 시작하지 않고 카메라는 직접 조작합니다. CineMode는 여전히 UI를 흐리게 합니다."
L["On: the cards show as ticked below. Off: none do, and it keeps its settings for when you turn this back on."] = "켜면: 아래 체크대로 카드가 보입니다. 끄면: 하나도 보이지 않으며, 다시 켤 때를 위해 설정은 유지됩니다."
L["On: the cast bars look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "켜면: 시전 바가 이 페이지대로 보입니다. 끄면: 게임 자체 바(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: the dialogue looks as this page says. Off: parchment, in the game's fonts (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "켜면: 대화가 이 페이지대로 보입니다. 끄면: 게임 글꼴의 양피지(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: the edges look as this page says. Off: as they start out (each setting keeps its value for when you turn this back on)."] = "켜면: 가장자리가 이 페이지대로 보입니다. 끄면: 처음 모습대로(다시 켤 때를 위해 각 설정 값은 유지됩니다)."
L["On: the graph samples the game's figure every second and keeps it over a reload, and you can record. Off (to start with): nothing is sampled or saved, and it costs nothing."] = "켜면: 그래프가 매초 게임 수치를 담고 다시 불러와도 보관하며, 기록할 수 있습니다. 끄면(처음 상태): 아무것도 담거나 저장하지 않아 비용이 없습니다."
L["On: the marks and colors on this page show on the plates, when the Nameplates page's Target Indicator row says. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "켜면: 이 페이지의 표시와 색이 이름표 페이지의 대상 표시기 줄이 정할 때 이름표에 보입니다. 끄면: 하나도 보이지 않습니다. 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: the raid frames look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "켜면: 공격대 창이 이 페이지대로 보입니다. 끄면: 게임 자체 창(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: the settings below, as you've set them. Off: the game's own settings, put back as they were."] = "켜면: 아래 설정을 정한 대로. 끄면: 게임 자체 설정을 원래대로 되돌립니다."
L["On: the unit frames look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "켜면: 유닛 프레임이 이 페이지대로 보입니다. 끄면: 게임 자체 프레임(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: the unit frames show the parts the grids below say. Off: CineMode leaves them alone, every part showing as the game has it."] = "켜면: 유닛 프레임이 아래 격자가 정한 부분을 보여 줍니다. 끄면: CineMode가 손대지 않아 모든 부분이 게임대로 보입니다."
L["On: the window looks as this page says. Off: as Roll Vision has always looked. Each setting keeps its value for when you turn this back on."] = "켜면: 창이 이 페이지대로 보입니다. 끄면: Roll Vision의 원래 모습대로. 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: these names look as this page says. Off: as the nameplate draws them: white or gray for every unit, with a heavy black outline, growing and shrinking with distance (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "켜면: 이 이름들이 이 페이지대로 보입니다. 끄면: 이름표가 그리는 대로: 모든 유닛에 흰색 또는 회색, 두꺼운 검은 외곽선, 거리에 따라 커지고 작아짐(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: this page's peeks bring your buffs and debuffs up in CineMode. Off: no peeks; they still fade as their Game Frames row says."] = "켜면: 이 페이지의 잠깐 보이기가 CineMode에서 강화/약화 효과를 띄웁니다. 끄면: 잠깐 보이기 없음. 여전히 게임 창 줄대로 흐려집니다."
L["On: this page's settings can bring the minimap up or keep it up in CineMode. Off: they don't; it still fades as its Game Frames rows say."] = "켜면: 이 페이지의 설정이 CineMode에서 미니맵을 띄우거나 유지할 수 있습니다. 끄면: 그러지 않으며, 여전히 게임 창 줄대로 흐려집니다."
L["On: this page's settings can bring the quest tracker, quest timer and durability figure up in CineMode. Off: they don't; they still fade as their Game Frames rows say."] = "켜면: 이 페이지의 설정이 CineMode에서 퀘스트 추적기, 퀘스트 타이머, 내구도 표시를 띄울 수 있습니다. 끄면: 그러지 않으며, 여전히 게임 창 줄대로 흐려집니다."
L["On: this page's settings can fade out the bars you aren't using. Off: they don't; the swing timer still fades as its Game Frames row says, every bar alike."] = "켜면: 이 페이지의 설정이 쓰지 않는 바를 흐리게 할 수 있습니다. 끄면: 그러지 않으며, 평타 타이머는 여전히 게임 창 줄대로 모든 바가 똑같이 흐려집니다."
L["On: this page's settings can keep the Cooldown Manager up in CineMode, or show only the icons you pick. Off: they don't; it still fades as its Game Frames row says."] = "켜면: 이 페이지의 설정이 CineMode에서 재사용 대기시간 관리자를 띄워 두거나 고른 아이콘만 보여 줄 수 있습니다. 끄면: 그러지 않으며, 여전히 게임 창 줄대로 흐려집니다."
L["On: tooltips look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "켜면: 툴팁이 이 페이지대로 보입니다. 끄면: 게임 자체 툴팁(미리 보기에도 나옴). 다시 켤 때를 위해 각 설정 값은 유지됩니다."
L["On: with your game music off, a camera starting (the ones ticked under Music on the Camera Triggers page) switches it on and fades it in, at your music volume; it fades out when the UI returns and your music is switched off again (logging out too). With your game music on, it's left alone, bar the stops below. Off: CineMode leaves your music alone."] = "켜면: 게임 배경음악이 꺼져 있을 때, 카메라가 시작되면(카메라 발동 조건 페이지의 '음악'에 체크한 것) 배경음악을 켜고 내 음악 음량으로 서서히 키웁니다. UI가 돌아오면(로그아웃할 때도) 서서히 줄이고 다시 끕니다. 게임 배경음악이 켜져 있으면 아래 멈춤 설정 말고는 손대지 않습니다. 끄면: CineMode가 음악에 손대지 않습니다."
L["On: your player frame, pet frame and personal resource display stay up or wait as this page says, and its mana bar and mana cost show. Off: none of it; they come up only as their Game Frames rows say."] = "켜면: 플레이어 프레임, 소환수 프레임, 개인 자원 표시가 이 페이지대로 유지되거나 기다리며, 마나 바와 마나 비용이 표시됩니다. 끄면: 하나도 적용되지 않고 게임 창 줄대로만 나타납니다."
L["Once anyone picks need, players on greed or transmog for that item aren't listed (they can't win it), only counted on a \"Lower picks\" line. Players still choosing stay listed. Click an item's panel to list everyone on it."] = "누군가 입찰을 고르면 그 아이템에 차비나 형상변환을 고른 플레이어는(이길 수 없으므로) 나열하지 않고 \"낮은 선택\" 줄에서 세기만 합니다. 아직 고르는 중인 플레이어는 나열됩니다. 아이템 판을 클릭하면 모두 나열합니다."
L["Once it has swung round to face you, the camera sways gently from side to side in front of your character, pausing between moves."] = "나를 마주 보도록 돌아간 뒤, 카메라가 캐릭터 앞에서 좌우로 부드럽게 흔들리며 사이사이 멈춥니다."
L["Once round in front, the spin keeps going and picks up speed until you go. 0 keeps a steady speed."] = "앞쪽으로 돈 뒤에도 회전이 계속되며 떠날 때까지 빨라집니다. 0이면 일정한 속도를 유지합니다."
L["Once the camera has settled on a speaker, it drifts slowly to and fro, side to side, across this many degrees, so the shot isn't stock-still. 0 holds still."] = "카메라가 말하는 사람에게 자리 잡으면 이 각도만큼 좌우로 천천히 오가서 장면이 꼼짝 않고 멈춰 있지 않게 합니다. 0이면 고정합니다."
L["Once the camera has settled, it drifts slowly to and fro, side to side, across this many degrees, so the shot isn't stock-still. 0 holds still."] = "카메라가 자리 잡으면 이 각도만큼 좌우로 천천히 오가서 장면이 꼼짝 않고 멈춰 있지 않게 합니다. 0이면 고정합니다."
L["Once the conversation's over, the camera zooms back out to your own distance at this speed (not if you zoomed yourself meanwhile). At 0 it stays in."] = "대화가 끝나면 카메라가 이 속도로 내 거리까지 다시 축소합니다(그 사이 직접 확대/축소했다면 안 함). 0이면 가까이 머뭅니다."
L["Once you're there (after the loading screen, if there is one), the camera swings around behind you."] = "도착하면(로딩 화면이 있으면 그 뒤) 카메라가 뒤쪽으로 돌아갑니다."
L["Once you've stood still for a while with the UI faded, or as soon as you go AFK, the camera slowly sweeps around your character. Moving stops it. What starts it, and how long you stand still first, is on the Scenes page."] = "UI가 흐려진 채 한동안 가만히 서 있거나 자리 비움이 되자마자 카메라가 캐릭터 주위를 천천히 돕니다. 움직이면 멈춥니다. 무엇으로 시작하는지, 얼마나 서 있어야 하는지는 장면 페이지에 있습니다."
L["One line under the game's zone name, as it comes in at login, in place of a card. (The look above is the card's.)"] = "접속할 때 카드 대신 게임의 지역 이름 아래 한 줄로. (위 모양은 카드의 것입니다.)"
L["One size at any distance. Unticked, a name grows and shrinks with its plate as its unit comes nearer or goes."] = "거리와 관계없이 같은 크기. 해제하면 유닛이 다가오거나 멀어질 때 이름이 이름표와 함께 커지고 작아집니다."
L["One thing that starts this scene: an emote you do, a spell you cast, a buff on you, a place you're in, a moment (leveling up...), something you are (mounted...), or a key you press. Any one of a scene's triggers starts it."] = "이 장면을 시작하는 원인 하나: 내가 하는 감정 표현, 시전하는 주문, 나에게 걸린 강화 효과, 있는 장소, 순간(레벨 업...), 나의 상태(탈것 탑승...), 또는 누르는 키. 장면의 발동 조건 중 하나만 맞아도 시작합니다."
L["Only after progress"] = "진행이 있은 뒤에만"
L["Only after you use mana, for"] = "마나를 쓴 뒤에만, 지속 시간"
L["Only in CineMode"] = "CineMode에서만"
L["Only in combat"] = "전투 중에만"
L["Only items of this quality and better get a panel in the window. Rolls on the rest are only in chat. The test (/cine rolls test) goes by it too."] = "이 품질 이상의 아이템만 창에 판이 생깁니다. 나머지 주사위는 대화창에만 나옵니다. 시험(/cine rolls test)도 이를 따릅니다."
L["Only items you can use"] = "쓸 수 있는 아이템만"
L["Only out of combat"] = "비전투 중에만"
L["Only show the best pick"] = "가장 좋은 선택만 표시"
L["Only the buff you gained or refreshed shows; your other buffs stay faded. Hovering shows them all. In fights too, for new buffs (procs and the like)."] = "얻거나 갱신한 강화 효과만 보이고 다른 강화 효과는 흐린 채로 둡니다. 마우스를 올리면 모두 보입니다. 전투 중에도 새 강화 효과(발동 효과 등)에 적용됩니다."
L["Only while you stand still"] = "가만히 서 있는 동안만"
L["Only with Zone ticked: it takes the game's zone text away. Its look follows Zone's until it's given its own here; its lines are Zone's."] = "'지역'에 체크했을 때만: 게임의 지역 문자를 대신합니다. 여기서 따로 정하기 전까지 모양은 '지역'을 따르며, 줄도 '지역'의 것입니다."
L["Only:"] = "다음만:"
L["Opacity"] = "불투명도"
L["Opacity while hidden"] = "숨김 중 불투명도"
L["Opacity:"] = "불투명도:"
L["Open"] = "열기"
L["Open its settings page"] = "설정 페이지 열기"
L["Open on Scenes >"] = "장면에서 열기 >"
L["Open on Scripts >"] = "스크립트에서 열기 >"
L["Open or close this moment's emotes."] = "이 순간의 감정 표현 열기/닫기."
L["Open the Profiler"] = "프로파일러 열기"
L["Open the log"] = "로그 열기"
L["Opens the Card Vision page."] = "Card Vision 페이지를 엽니다."
L["Opens the Settings tab with this event picked."] = "이 이벤트를 고른 채로 설정 탭을 엽니다."
L["Opens the Sounds tab with this event picked."] = "이 이벤트를 고른 채로 소리 탭을 엽니다."
L["Opens the Style hub's Cast bars page: how nameplate cast bars look."] = "스타일 허브의 시전 바 페이지를 엽니다: 이름표 시전 바의 모양."
L["Opens the Style hub's Chat bubbles page: how off-screen bubbles look and where they show."] = "스타일 허브의 말풍선 페이지를 엽니다: 화면 밖 말풍선의 모양과 표시 위치."
L["Opens the Style hub's Chat bubbles page: how the bubbles and speech from behind you look."] = "스타일 허브의 말풍선 페이지를 엽니다: 말풍선과 뒤에서 들리는 대사의 모양."
L["Opens the Style hub's Nameplates page: how nameplates look."] = "스타일 허브의 이름표 페이지를 엽니다: 이름표의 모양."
L["Opens the Style hub's Names page: how names over heads look."] = "스타일 허브의 이름 페이지를 엽니다: 머리 위 이름의 모양."
L["Opens the Style hub's Personal Resource Display page: how the bars look."] = "스타일 허브의 개인 자원 표시 페이지를 엽니다: 바의 모양."
L["Opens the Style hub's Raid frames page: how the raid and raid-style party frames look."] = "스타일 허브의 공격대 창 페이지를 엽니다: 공격대 창과 공격대 방식 파티 창의 모양."
L["Opens the Style hub's Tooltips page: how tooltips look."] = "스타일 허브의 툴팁 페이지를 엽니다: 툴팁의 모양."
L["Opens the Style hub's Unit frames page: how the frames look."] = "스타일 허브의 유닛 프레임 페이지를 엽니다: 프레임의 모양."
L["Opens the Style tab with this event picked."] = "이 이벤트를 고른 채로 스타일 탭을 엽니다."
L["Opens the rule editor, for AND, NOT and more places and situations than the dropdowns have."] = "규칙 편집기를 엽니다: AND, NOT, 드롭다운보다 많은 장소와 상황을 쓸 수 있습니다."
L["Opens this chat window's lines to copy."] = "이 대화창의 줄을 복사할 수 있게 엽니다."
L["Opens this style on the Card Types tab: a change there is for every card using it."] = "카드 종류 탭에서 이 스타일을 엽니다: 거기서 바꾸면 이 스타일을 쓰는 모든 카드에 적용됩니다."
L["Or find one:"] = "또는 찾기:"
L["Or hits adding up to"] = "또는 타격 합계가 다음에 이르면"
L["Orbiting stars"] = "도는 별"
L["Other NPCs talking near you, such as a city's citizens chatting among themselves. The same chat camera, once you've stood still for the time below, so passers-by don't swing it about while you're busy."] = "근처에서 말하는 다른 NPC, 예를 들어 도시 주민들끼리의 잡담. 같은 대화 카메라를 쓰되, 아래 시간만큼 가만히 서 있은 뒤에만 시작해서 바쁠 때 행인 때문에 카메라가 흔들리지 않습니다."
L["Other buffs"] = "다른 강화 효과"
