L["Paste in a script someone shared (Ctrl+V), then Add script. It's added as a new script of yours."] = "누군가 공유한 스크립트를 붙여 넣고(Ctrl+V) '스크립트 추가'를 누르세요. 나만의 새 스크립트로 추가됩니다."
L["Paste in a wheel someone shared (Ctrl+V), read what's on it below, and Add wheel. It's added as a new wheel of yours."] = "누군가 공유한 휠을 붙여 넣고(Ctrl+V), 아래에서 무엇이 들어 있는지 읽은 뒤 '휠 추가'를 누르세요. 나만의 새 휠로 추가됩니다."
L["Paste the text a friend sent (Ctrl+V). What it holds shows below before you add it."] = "친구가 보낸 문자를 붙여 넣으세요(Ctrl+V). 추가하기 전에 무엇이 들어 있는지 아래에 보입니다."
L["Pattern:"] = "무늬:"
L["Peak"] = "최고점"
L["People joining and leaving your group."] = "파티에 들어오고 나가는 사람."
L["Personal Resource Display"] = "개인 자원 표시"
L["Personal mana bar"] = "개인 마나 바"
L["Personal resource display"] = "개인 자원 표시"
L["Pick Greed's color."] = "차비 색을 고르세요."
L["Pick Need's color."] = "입찰 색을 고르세요."
L["Pick Transmog's color."] = "형상변환 색을 고르세요."
L["Pick a frame in game"] = "게임에서 창 고르기"
L["Pick a level to try it now. You can change it any time, here or on the Profiles page."] = "수준을 골라 지금 바로 체험해 보세요. 여기서나 프로필 페이지에서 언제든 바꿀 수 있습니다."
L["Pick a profile to switch to it."] = "프로필을 고르면 그것으로 바뀝니다."
L["Pick a setting"] = "설정 고르기"
L["Pick an emote to add as a button on this card: a common one, any of the game's, or a voice emote (said out loud). Up to six."] = "이 카드에 버튼으로 넣을 감정 표현을 고르세요: 흔한 것, 게임의 아무것, 또는 음성 감정 표현(소리 내어 말함). 최대 여섯 개."
L["Pick its style, then how its words and frame look and where it sits. The font, outline, shadow and border start on Visions Style's. Press Test and close the settings to see it."] = "스타일을 고른 뒤 글자와 틀의 모양과 위치를 정하세요. 글꼴, 외곽선, 그림자, 테두리는 Visions 스타일 값으로 시작합니다. '시험'을 누르고 설정을 닫아야 보입니다."
L["Pick its type, then that type's settings below. Press Test and close the settings to see it. Its colors and words: the Look tab."] = "종류를 고른 뒤 아래에서 그 종류의 설정을 정하세요. '시험'을 누르고 설정을 닫아야 보입니다. 색과 글자: 모양 탭."
L["Pick sounds for this rule from the game's."] = "게임 소리 중에서 이 규칙의 소리를 고르세요."
L["Pick the bar's color."] = "바 색을 고르세요."
L["Pick the bars' color."] = "바들의 색을 고르세요."
L["Pick the color of a cast or channel that can't be interrupted."] = "차단할 수 없는 시전이나 정신 집중의 색을 고르세요."
L["Pick the color of a cast that was interrupted (when the game says: not in every fight)."] = "차단된 시전의 색을 고르세요(게임이 알려 줄 때: 모든 전투에서는 아님)."
L["Pick the color of a cast."] = "시전 색을 고르세요."
L["Pick the color of a channel."] = "정신 집중 색을 고르세요."
L["Pick the glow's color."] = "빛 색을 고르세요."
L["Pick the line's color."] = "선 색을 고르세요."
L["Pick the outline's color."] = "외곽선 색을 고르세요."
L["Pick the pulse's color."] = "맥박 색을 고르세요."
L["Pick the small lines' color."] = "작은 선 색을 고르세요."
L["Pick the text's color."] = "글자 색을 고르세요."
L["Pick the winner's color."] = "승자 색을 고르세요."
L["Pick when each spell's icon shows. Always: as the game shows it. When ready: out of fights, and while it recharges, it fades out; it comes back once it's ready, or the seconds in its box before (empty: %d%% of its cooldown). While recharging: in fights or not, it shows only while it recharges. When it procs: in fights or not, it shows only while the game makes it glow (a proc, like an instant Lightning Bolt). A faded icon keeps its place in the bar. In fights the game may not say how long is left, so then it goes by when you last cast it. The settings beside each group's name set every spell in it at once."] = "각 주문 아이콘이 언제 보일지 고르세요. 항상: 게임이 보여 주는 대로. 준비됐을 때: 비전투 중이거나 충전 중에는 흐려지고, 준비되면, 또는 칸에 적은 초만큼 일찍(비우면 재사용 대기시간의 %d%%) 돌아옵니다. 충전 중: 전투 여부와 관계없이 충전되는 동안만 보입니다. 발동할 때: 전투 여부와 관계없이 게임이 빛나게 하는 동안만(즉시 시전 번개 화살 같은 발동 효과) 보입니다. 흐려진 아이콘은 바 안의 자리를 유지합니다. 전투 중에는 게임이 남은 시간을 알려 주지 않을 수 있어서, 그때는 마지막으로 시전한 때를 기준으로 합니다. 각 그룹 이름 옆 설정은 그 안의 모든 주문을 한 번에 정합니다."
L["Picked now"] = "지금 선택됨"
L["Picking up an item or spell (to drag it to your action bars, say) brings the UI back until you put it down. Off: picking things up never does; mouse over a faded bar to see it when dragging there."] = "아이템이나 주문을 집으면(예: 행동 단축바로 끌려고) 내려놓을 때까지 UI가 돌아옵니다. 끄면: 집어도 돌아오지 않습니다. 끌어다 놓을 때는 흐려진 바에 마우스를 올리면 보입니다."
L["Picks"] = "선택"
L["Place"] = "장소"
L["Place:"] = "장소:"
L["Plain discs on arrows: you in your color, them in their class's."] = "화살표 위의 단순한 원: 나는 내 색, 상대는 직업 색."
L["Plate"] = "이름표"
L["Plate color"] = "이름표 색"
L["Plate off screen"] = "화면 밖 이름표"
L["Plate parts"] = "이름표 구성 요소"
L["Plate size %d%%"] = "이름표 크기 %d%%"
L["Plate size %d%% x %d%%"] = "이름표 크기 %d%% x %d%%"
L["Plate style"] = "이름표 스타일"
L["Play %s"] = "%s 재생"
L["Play as usual. Stop on the Profiler page ends it."] = "평소처럼 플레이하세요. 프로파일러 페이지의 '중지'로 끝냅니다."
L["Play it, at its volume."] = "그 음량으로 재생합니다."
L["Play it, to see it (at no one)."] = "재생해서 확인합니다(대상 없이)."
L["Play this shot now (stand still). Press it again, or move, to stop."] = "이 샷을 지금 재생합니다(가만히 서 있으세요). 다시 누르거나 움직이면 멈춥니다."
L["Played by"] = "재생하는 장면"
L["Played by: %s"] = "재생하는 장면: %s"
L["Player frame waits for your health or power to change"] = "플레이어 프레임은 생명력이나 자원이 변할 때까지 대기"
L["Players in their class color, everyone else red, yellow or green by how they see you."] = "플레이어는 직업 색, 나머지는 나를 보는 태도에 따라 빨강, 노랑, 초록."
L["Players shown per item in a raid"] = "공격대에서 아이템당 표시할 플레이어"
L["Players' names in their class color, NPCs' in their reaction to you (red, yellow or green)."] = "플레이어 이름은 직업 색, NPC 이름은 나에 대한 반응 색(빨강, 노랑, 초록)."
L["Players' names show in their class color, as in the chat window. NPCs' don't have one."] = "대화창처럼 플레이어 이름을 직업 색으로 표시합니다. NPC에는 직업 색이 없습니다."
L["Players, friendly or enemy as the Nameplates page has them (the other faction's are enemies)."] = "플레이어, 이름표 페이지 설정대로 아군 또는 적(상대 진영은 적)."
L["Plays a card in this style in the preview and on your screen (close the settings to see it there): the first card using it, else the zone you're in."] = "이 스타일의 카드를 미리 보기와 화면에 재생합니다(화면에서 보려면 설정을 닫으세요): 이 스타일을 쓰는 첫 카드, 없으면 지금 있는 지역."
L["Plays the card in the preview and on your screen, as it will look, with its sound (close the settings to see it there). A card with moments (Duel) plays each in turn; clicking Stop ends it."] = "카드를 실제 모양과 소리 그대로 미리 보기와 화면에 재생합니다(화면에서 보려면 설정을 닫으세요). 순간이 있는 카드(결투)는 차례로 재생하며, '중지'를 클릭하면 끝납니다."
L["Plays the scenes of yours whose trigger is this key: set a scene's trigger to it on the Scenes page. Press again to stop it."] = "발동 조건이 이 키인 내 장면을 재생합니다: 장면 페이지에서 장면의 발동 조건을 이 키로 정하세요. 다시 누르면 멈춥니다."
L["Points left"] = "남은 점수"
L["Pop out"] = "떼어 내기"
L["Pop out: drag the window anywhere (by its edge). Dock: back beside the settings."] = "떼어 내기: 창을 (가장자리를 잡고) 아무 데나 끌 수 있습니다. 도킹: 설정 옆으로 돌아갑니다."
L["Portal ring"] = "차원문 고리"
L["Portrait"] = "초상화"
L["Portrait:"] = "초상화:"
L["Position"] = "위치"
L["Position:"] = "위치:"
L["Power"] = "자원"
L["Power bar"] = "자원 바"
L["Preset"] = "프리셋"
L["Preset:"] = "프리셋:"
L["Press Ctrl+C to copy this, then paste it wherever your friend will see it."] = "Ctrl+C로 복사한 뒤 친구가 볼 수 있는 곳에 붙여 넣으세요."
L["Press Ctrl+C to copy this, then paste it wherever your friends will see it. They add it with Import a wheel on their Your wheels page."] = "Ctrl+C로 복사한 뒤 친구들이 볼 수 있는 곳에 붙여 넣으세요. 친구들은 '내 휠' 페이지의 '휠 가져오기'로 추가합니다."
L["Press Ctrl+C to copy this, then paste it wherever your friends will see it. They add it with Import on their Scripts page."] = "Ctrl+C로 복사한 뒤 친구들이 볼 수 있는 곳에 붙여 넣으세요. 친구들은 스크립트 페이지의 '가져오기'로 추가합니다."
L["Pressing Enter to type brings up the chat window with the input box where it's ticked. Elsewhere just the input box comes up, so you can type without the chat window (or Mouseover groups set to come up for Typing) showing."] = "Enter를 눌러 입력하면 체크한 곳에서는 대화창과 입력 상자가 함께 나타납니다. 그 밖의 곳에서는 입력 상자만 나타나서, 대화창(또는 입력 시 나타나도록 정한 마우스오버 그룹) 없이 입력할 수 있습니다."
L["Preview"] = "미리 보기"
L["Previewing - %s"] = "미리 보는 중 - %s"
L["Previously"] = "지난 이야기"
L["Previously, on %s"] = "지난 이야기, %s"
L["Print to chat"] = "대화창에 출력"
L["Profession"] = "전문 기술"
L["Profiler"] = "프로파일러"
L["Profiler: press Ctrl+C to copy"] = "프로파일러: Ctrl+C로 복사하세요"
L["Progress in a scenario (the stages and objectives the tracker shows for some raid bosses, dungeons and events) shows the quest tracker the same way."] = "시나리오의 진행(일부 공격대 우두머리, 던전, 이벤트에서 추적기에 나오는 단계와 목표)도 같은 방식으로 퀘스트 추적기를 띄웁니다."
L["Put %s back as it comes?"] = "%s을(를) 원래대로 되돌리시겠습니까?"
L["Put back"] = "되돌리기"
L["Put every spell's, buff's and group's icon setting, and Smart set, back to the active profile's own."] = "모든 주문, 강화 효과, 그룹의 아이콘 설정과 '스마트 설정'을 현재 프로필 값으로 되돌립니다."
L["Put everything back over %s s"] = "%s초에 걸쳐 모두 되돌리기"
L["Put the %d points the plan adds into your talents window, for its Apply Changes."] = "계획에서 추가한 %d점을 특성 창에 넣어 '변경 사항 적용'을 할 수 있게 합니다."
L["Put the active profile back to how you last saved it, or a built-in one back to its own values (your own profiles keep your changes as you go)."] = "현재 프로필을 마지막으로 저장한 상태로, 또는 기본 프로필을 원래 값으로 되돌립니다(내 프로필은 바꾸는 대로 저장됩니다)."
L["Put the mouse on it"] = "마우스를 올리기"
L["Put the profile %s back to how you last saved it? Changes you've made since then go."] = "%s 프로필을 마지막으로 저장한 상태로 되돌리시겠습니까? 그 뒤에 바꾼 것은 사라집니다."
L["Put the turn and tilt back over %s s"] = "%s초에 걸쳐 회전과 기울기 되돌리기"
L["Put these settings back to the profile's own?"] = "이 설정을 프로필 값으로 되돌리시겠습니까?"
L["Puts one of the event's own settings back, to come from the style it starts from again."] = "이벤트 자체 설정 하나를 되돌려 다시 시작한 스타일을 따르게 합니다."
L["Puts one of your changes to the style back, as it comes."] = "스타일에 바꾼 것 하나를 원래대로 되돌립니다."
L["Puts our script back, made from its camera's settings again, in place of your changes (click twice)."] = "내 변경 사항 대신 카메라 설정으로 다시 만든 우리 스크립트로 되돌립니다(두 번 클릭)."
L["Puts the card back where it starts: just above where speech from behind you shows (the Chat Bubbles page's Move), beside the chat window."] = "카드를 처음 자리로 되돌립니다: 대화창 옆, 뒤에서 들리는 대사가 나오는 곳(말풍선 페이지의 '이동') 바로 위."
L["Puts the rule's words back in the dropdowns."] = "규칙의 단어를 드롭다운으로 되돌립니다."
L["Puts this theme back as it comes, undoing your changes to its own settings (edge, colors, sparks, heartbeat)."] = "이 테마를 원래대로 되돌려 테마 자체 설정(가장자리, 색, 불꽃, 심장 박동)에 바꾼 것을 취소합니다."
L["PvP flagged"] = "PvP 활성화"
L["PvP icon"] = "PvP 아이콘"
L["Quest Item Button"] = "퀘스트 아이템 버튼"
L["Quest Vision"] = "Quest Vision"
L["Quest Vision's list of replies and its bubble too."] = "Quest Vision의 대답 목록과 말풍선도."
L["Quest complete"] = "퀘스트 완료"
L["Quest givers"] = "퀘스트 NPC"
L["Quest icon by their nameplates or names"] = "이름표나 이름 옆에 퀘스트 아이콘"
L["Quest item button"] = "퀘스트 아이템 버튼"
L["Quest mark (!)"] = "퀘스트 표시 (!)"
L["Quest mark icon"] = "퀘스트 표시 아이콘"
L["Quest mobs' nameplates and marks, the quest item button, the glow on quest objects, and where the dialogue sits."] = "퀘스트 몹의 이름표와 표시, 퀘스트 아이템 버튼, 퀘스트 사물의 빛, 대화 위치."
L["Quest objective"] = "퀘스트 목표"
L["Quest talk"] = "퀘스트 대화"
L["Quest talk is on: talking to an NPC, what they say and what you can say back show here instead of the game's window"] = "퀘스트 대화가 켜져 있음: NPC와 대화할 때 NPC의 말과 내가 할 수 있는 대답이 게임 창 대신 여기 나옴"
L["Quest/widget icons"] = "퀘스트/위젯 아이콘"
L["Questie's quest tracker and its quest item buttons fade with the Quest tracker row on the Game Frames page."] = "Questie의 퀘스트 추적기와 퀘스트 아이템 버튼은 게임 창 페이지의 퀘스트 추적기 줄과 함께 흐려집니다."
L["Quests done"] = "완료한 퀘스트"
L["Race track"] = "경주 트랙"
L["Rage, runic power and the like count until drained"] = "분노, 룬 마력 등은 다 빠질 때까지 침"
L["Rage, runic power and the other resources that drain away out of combat count too: the frames ticked above stay up until they're back to 0, within the Calm Timer."] = "분노, 룬 마력 등 비전투 중에 빠져나가는 자원도 칩니다: 위에 체크한 창은 진정 타이머 안에서 그 자원이 0으로 돌아갈 때까지 남아 있습니다."
L["Raid marker"] = "공격대 징표"
L["Raid-style"] = "공격대 방식"
