L["Raid-style party debuffs"] = "공격대 방식 파티 약화 효과"
L["Raid-style party pet names"] = "공격대 방식 파티 소환수 이름"
L["Raid-style party pets"] = "공격대 방식 파티 소환수"
L["Raid-style party player names"] = "공격대 방식 파티 플레이어 이름"
L["Raid-style party players"] = "공격대 방식 파티 플레이어"
L["Raid-style party role icons"] = "공격대 방식 파티 역할 아이콘"
