L["Raid-style party title"] = "공격대 방식 파티 제목"
L["Raises the game's max camera distance (to 2.6) while pulled back, so the zoom isn't cut short. Your own maximum comes back once you've zoomed in again."] = "물러나 있는 동안 게임의 최대 카메라 거리를 (2.6까지) 올려서 축소가 중간에 끊기지 않게 합니다. 다시 확대하면 내 최대 거리가 돌아옵니다."
L["Random fly-bys are spread over the part of the flight below: one per this many seconds of it (at least one), each at a random moment in its share."] = "무작위 플라이바이는 아래 비행 구간에 흩어집니다: 그 구간의 이 초마다 하나씩(최소 하나), 각자 몫의 무작위 순간에."
L["Random zoom only. Each pause is picked at random this much shorter or longer than the pause above: 3 sec with a 10 sec pause waits anywhere from 7 to 13 sec. 0 keeps every pause the same."] = "무작위 확대/축소만 해당. 각 멈춤은 위 멈춤 시간보다 이만큼 짧거나 긴 값으로 무작위로 정해집니다: 멈춤이 10초이고 3초면 7~13초 사이로 기다립니다. 0이면 매번 같습니다."
L["Rank %d/%d"] = "%d/%d단계"
L["Rank ladder"] = "순위 사다리"
L["Rare"] = "희귀"
L["Rare and up"] = "희귀 등급 이상"
L["Rare elite"] = "희귀 정예"
L["Reach"] = "범위"
L["Reach, sides"] = "범위, 좌우"
L["Reach, top and bottom"] = "범위, 위아래"
L["Read every command before you add it: each runs as if you'd typed it, and /run ones can do anything an addon can."] = "추가하기 전에 모든 명령을 읽어 보세요: 각각 직접 입력한 것처럼 실행되며, /run 명령은 애드온이 할 수 있는 무엇이든 할 수 있습니다."
L["Ready"] = "준비됨"
L["Ready also needs the resources to cast it: Maelstrom, mana, rage and so on. Until you have them the icon stays faded."] = "준비됨에는 시전에 필요한 자원(소용돌이, 마나, 분노 등)도 필요합니다. 그 자원이 생길 때까지 아이콘은 흐린 채로 있습니다."
L["Ready check"] = "전투 준비 확인"
L["Ready: it's up (you're near the quest's area) and not cooling down."] = "준비됨: 사용할 수 있고(퀘스트 지역 근처) 재사용 대기 중이 아님."
L["Recap after:"] = "요약 표시 시점:"
L["Recaps"] = "요약"
L["Recently deleted"] = "최근 삭제됨"
L["Record"] = "기록"
L["Recording (the addon's own timers)"] = "기록 (애드온 자체 타이머)"
L["Recording CPU  %d:%02d"] = "CPU 기록 중  %d:%02d"
L["Recording: %d:%02d left."] = "기록 중: %d:%02d 남음."
L["Red for hostile units, yellow for neutral ones and green for friendly ones, as over their heads. Unticked: the plate's own color, white or gray."] = "머리 위처럼 적대적 유닛은 빨강, 중립은 노랑, 우호적은 초록. 해제: 이름표 자체 색(흰색 또는 회색)."
L["Reduce view distance in rain"] = "비가 오면 시야 거리 줄이기"
L["Regenerate"] = "다시 만들기"
L["Released to a graveyard with no spirit healer's countdown, the dark edges stay as you walk back, and lift the closer you get to your body, gone once you're there."] = "영혼의 치유사 카운트다운이 없는 묘지로 영혼을 해방하면, 돌아가는 동안 어두운 가장자리가 남아 있다가 시체에 가까워질수록 걷히고 도착하면 사라집니다."
L["Reload button on the screen"] = "화면의 다시 불러오기 버튼"
L["Reload the UI"] = "UI 다시 불러오기"
L["Reloads the UI, like /reload. With Keep windows open across a reload ticked (Quality of life > General), what you had open opens again after."] = "/reload처럼 UI를 다시 불러옵니다. '다시 불러와도 창을 열어 두기'(편의 기능 > 일반)에 체크했다면 열려 있던 것이 다시 열립니다."
L["Remove this copy."] = "이 사본을 제거합니다."
L["Remove this row. Add it again under the grid."] = "이 줄을 제거합니다. 격자 아래에서 다시 추가할 수 있습니다."
L["Remove this rule and its sounds."] = "이 규칙과 그 소리를 제거합니다."
L["Remove this step"] = "이 단계 제거"
L["Remove this trigger."] = "이 발동 조건을 제거합니다."
L["Rename the camera:"] = "카메라 이름 변경:"
L["Rename the theme:"] = "테마 이름 변경:"
L["Renown %d"] = "명성 %d"
L["Repeat %s times"] = "%s회 반복"
L["Repeat until it ends"] = "끝날 때까지 반복"
L["Repeats:"] = "반복:"
L["Replies to a /who, shift-clicking a name in the guild list too."] = "/who에 대한 응답. 길드 목록에서 이름을 Shift+클릭할 때도."
L["Requires %d points in %s"] = "%d점 필요: %s"
L["Requires %d points in %s Talents"] = "%d점 필요: %s 특성"
L["Reset addon"] = "애드온 초기화"
L["Reset the zoom on login and /reload"] = "접속과 /reload 시 확대/축소 거리 초기화"
L["Reset theme"] = "테마 초기화"
L["Reset to grid"] = "격자로 초기화"
L["Resource bar"] = "자원 바"
L["Resource bar waits for your power to change"] = "자원 바는 자원이 변할 때까지 대기"
L["Resources"] = "자원"
L["Rested"] = "휴식 상태"
L["RestedXP's guide window, waypoint arrow, quest item and target buttons and level splits fade with the Quest tracker row on the Game Frames page."] = "RestedXP의 가이드 창, 목적지 화살표, 퀘스트 아이템과 대상 버튼, 레벨 구간은 게임 창 페이지의 퀘스트 추적기 줄과 함께 흐려집니다."
L["Resting (an inn or a city)"] = "휴식 중 (여관 또는 도시)"
L["Resting at a campfire, sitting, sleeping, dancing and the like (whichever events pick it on the Scenes page): the camera swings slowly round to face you, then sways gently from side to side in front of you, and eases in close. Moving (or standing up) ends it."] = "모닥불에서 휴식, 앉기, 잠자기, 춤추기 등(장면 페이지에서 이것을 고른 이벤트): 카메라가 천천히 돌아 나를 마주 본 뒤, 앞에서 좌우로 부드럽게 흔들리며 가까이 다가옵니다. 움직이면(또는 일어서면) 끝납니다."
L["Restore"] = "복원"
L["Restored from a backup of %s from %s."] = "%s의 %s 백업에서 복원했습니다."
L["Restyle these bars"] = "이 바 다시 꾸미기"
L["Result"] = "결과"
L["Reveal on scenario progress"] = "시나리오 진행 시 표시"
L["Right click attack also uses Auto-shot"] = "오른쪽 클릭 공격에 자동 사격도 사용"
L["Right now: hidden"] = "지금: 숨김"
L["Right now: shown"] = "지금: 표시"
L["Right-click for more."] = "오른쪽 클릭하면 더 있습니다."
L["Right-click the Profiler icon to turn it on and record."] = "켜고 기록하려면 프로파일러 아이콘을 오른쪽 클릭하세요."
L["Right-click: back to its own icon."] = "오른쪽 클릭: 원래 아이콘으로."
L["Right-click: copy it, or rename, describe, change the icon of or delete one of yours."] = "오른쪽 클릭: 복사하거나, 내 것이라면 이름 변경, 설명, 아이콘 변경, 삭제."
L["Right-clicking an enemy targets it and attacks: Auto Shot when it's far enough away to shoot, a melee swing when it's too close, in a fight or out of one. In a fight the game only checks what's under the mouse a few times a second, so a very quick right-click on a new enemy can still be a melee one."] = "적을 오른쪽 클릭하면 대상으로 지정하고 공격합니다: 쏠 수 있을 만큼 멀면 자동 사격, 너무 가까우면 근접 공격. 전투 중이든 아니든. 전투 중에는 게임이 마우스 아래를 초당 몇 번만 확인하므로, 새 적을 아주 빨리 오른쪽 클릭하면 근접 공격이 될 수도 있습니다."
L["Ripple wave"] = "잔물결"
L["Rise up from below the screen"] = "화면 아래에서 떠오르기"
L["Rising heat"] = "피어오르는 열기"
L["Rising motes"] = "떠오르는 티끌"
L["Role"] = "역할"
L["Role icon (damage)"] = "역할 아이콘 (공격)"
L["Role icon (healer)"] = "역할 아이콘 (치유)"
L["Role icon (tank)"] = "역할 아이콘 (방어)"
L["Roll Vision"] = "Roll Vision"
L["Rolling..."] = "굴리는 중..."
L["Roomy"] = "넉넉함"
L["Rotate %s° %s over %s s"] = "%s° %s 회전, %s초 동안"
L["Round"] = "둥근"
L["Round each bar: the game's frame alone, or a border of ours (Custom: its thickness and color under it)."] = "각 바의 둘레: 게임 틀만, 또는 우리 테두리(사용자 지정: 아래에서 두께와 색)."
L["Round each frame: the game's, or a border of ours (Custom: its thickness and color under it)."] = "각 창의 둘레: 게임 것, 또는 우리 테두리(사용자 지정: 아래에서 두께와 색)."
L["Round the button: the game's (the extra ability button's frame), or one of ours (Custom: its thickness and color under it)."] = "버튼 둘레: 게임 것(추가 행동 버튼의 틀), 또는 우리 것(사용자 지정: 아래에서 두께와 색)."
L["Row"] = "줄"
L["Rows:"] = "줄:"
L["Rule"] = "규칙"
L["Rule: %s"] = "규칙: %s"
L["Rule: %s (the rule decides, not the ticks)"] = "규칙: %s (체크가 아니라 규칙이 정함)"
L["Rules for the card's sound, read top to bottom as it shows: the first that fits plays one of its sounds at random. A rule's condition uses the rules' words (Cities, Raids, In CineMode...); none: any time. A rule with no sounds: silent. Each sound's slider sets it next to the others, the cue volume sets them all (every card's sounds share it)."] = "카드 소리 규칙. 카드가 보일 때 위에서부터 읽어서 처음 맞는 규칙이 그 소리 중 하나를 무작위로 재생합니다. 규칙 조건에는 규칙 단어(Cities, Raids, In CineMode...)를 씁니다. 없으면: 언제든. 소리 없는 규칙: 조용함. 각 소리의 슬라이더는 다른 소리 대비 크기, 신호음 음량은 전체 크기입니다(모든 카드 소리가 공유)."
L["Rules for the sounds, read top to bottom as a fight starts or ends: the first that fits plays one of its sounds at random. A rule's condition uses the rules' words (Boss fight, Raids, In CineMode...); none: any fight. Each sound's slider sets it next to the others, the cue volume sets them all. They play on the Ambience channel, its volume set for them and put back after."] = "소리 규칙. 전투가 시작되거나 끝날 때 위에서부터 읽어서 처음 맞는 규칙이 그 소리 중 하나를 무작위로 재생합니다. 규칙 조건에는 규칙 단어(Boss fight, Raids, In CineMode...)를 씁니다. 없으면: 모든 전투. 각 소리의 슬라이더는 다른 소리 대비 크기, 신호음 음량은 전체 크기입니다. 주변 소리 채널로 재생되며, 그 음량을 이 소리에 맞췄다가 나중에 되돌립니다."
L["Rules for the sounds, read top to bottom as the time of day changes: the first for the new time that fits plays one of its sounds at random. A rule's condition uses the rules' words (Cities, In CineMode...); none: any time. A rule with no sounds: silent. Each sound's slider sets it next to the others, the cue volume sets them all (the fights' sounds share it)."] = "소리 규칙. 시간대가 바뀔 때 위에서부터 읽어서 새 시간대에 처음 맞는 규칙이 그 소리 중 하나를 무작위로 재생합니다. 규칙 조건에는 규칙 단어(Cities, In CineMode...)를 씁니다. 없으면: 언제든. 소리 없는 규칙: 조용함. 각 소리의 슬라이더는 다른 소리 대비 크기, 신호음 음량은 전체 크기입니다(전투 소리와 공유)."
L["Run"] = "실행"
L["Runs its command now, as picking it on the wheel would."] = "휠에서 고른 것처럼 지금 그 명령을 실행합니다."
L["Runs this camera for 30 seconds where you stand, to see your settings at work. Moving, or clicking Stop, ends it."] = "서 있는 자리에서 이 카메라를 30초 동안 돌려 설정이 어떻게 작동하는지 봅니다. 움직이거나 '중지'를 클릭하면 끝납니다."
L["Runs when the camera ends, whatever ends it (its stop rules say which do). Every camera has it: it can't be removed. Pick it and add steps to put them inside."] = "무엇 때문에 끝나든 카메라가 끝날 때 실행됩니다(무엇이 끝내는지는 멈춤 규칙이 정함). 모든 카메라에 있으며 제거할 수 없습니다. 골라서 단계를 추가하면 그 안에 들어갑니다."
L["SD (the game's look)"] = "SD (게임의 모양)"
L["SHOWING"] = "표시 중"
L["SHOWN BECAUSE"] = "표시 이유"
L["Same as raid frames"] = "공격대 창과 같게"
L["Same as target"] = "대상과 같게"
L["Same as the words"] = "글자와 같게"
L["Same back"] = "똑같이 답하기"
L["Same size at any distance"] = "거리와 관계없이 같은 크기"
L["Save"] = "저장"
L["Says and yells whose bubble isn't on your screen (the speaker is behind you, or out of view) show in a bubble low on the screen, with the speaker's name, instead of bringing up chat. It needs the Chat page's Show chat when a message arrives and Hide speech you can see as a bubble."] = "말풍선이 화면에 없는 일반 대화와 외치기(말하는 사람이 뒤에 있거나 시야 밖)를 대화창을 띄우는 대신 화면 아래쪽 말풍선에 말한 사람 이름과 함께 표시합니다. 대화 페이지의 '메시지가 오면 대화창 표시'와 '말풍선으로 보이는 대화 숨기기'가 필요합니다."
L["Says and yells whose bubble isn't on your screen, shown low on the screen instead. Turn it on on the Interface hub's Chat bubbles page (with that page on)."] = "말풍선이 화면에 없는 일반 대화와 외치기를 대신 화면 아래쪽에 표시합니다. 인터페이스 허브의 말풍선 페이지에서 켜세요(그 페이지도 켜야 함)."
L["Scale"] = "비율"
