L["Seconds left in the middle"] = "가운데에 남은 초"
L["Seconds the edges take to close all the way in when your health drops. Keep it short: it's the warning."] = "생명력이 떨어질 때 가장자리가 끝까지 좁혀 오는 데 걸리는 초. 짧게 두세요: 경고이니까요."
L["See-through"] = "반투명"
L["See-through and borderless, the health bar thin along the top."] = "반투명하고 테두리 없음, 위쪽을 따라 가는 생명력 바."
L["Sending your log"] = "로그 보내기"
L["Separate"] = "따로"
L["Separate: the card stays where you drag it (or at the list's height), wherever the bubble goes."] = "따로: 말풍선이 어디로 가든 카드는 끌어 둔 곳(또는 목록 높이)에 머뭅니다."
