L["Sets every buff in this group to this. Buffs you haven't set on their own follow it."] = "이 그룹의 모든 강화 효과를 이것으로 정합니다. 따로 정하지 않은 강화 효과는 이것을 따릅니다."
L["Sets every spell in this group to this. Spells you haven't set on their own follow it, and a spell here made When ready on its own starts with its Resources and Show early."] = "이 그룹의 모든 주문을 이것으로 정합니다. 따로 정하지 않은 주문은 이것을 따르며, 여기서 따로 '준비됐을 때'로 정한 주문은 그 자원과 '미리 표시' 설정으로 시작합니다."
