L["Shortly before you land, the rotation stops and the camera turns back behind you and stays there until you touch down. Needs one flight on a route to learn how long it takes. Skipped if you've moved the camera yourself on that flight: it stays how you set it."] = "착륙 직전에 회전을 멈추고 카메라가 뒤쪽으로 돌아가 착지할 때까지 머뭅니다. 경로마다 한 번은 비행해야 걸리는 시간을 압니다. 그 비행에서 직접 카메라를 움직였다면 건너뜁니다: 정한 대로 둡니다."
