L["Shoulder Cam turned off: the game's experimental camera warning was disabled."] = "어깨 카메라 꺼짐: 게임의 실험적 카메라 경고가 꺼져 있었습니다."
L["Show all"] = "모두 표시"
L["Show all through CineMode in capital cities."] = "수도에서 CineMode 내내 표시합니다."
L["Show all through CineMode out in the world, inns included (capital cities are Cities)."] = "여관을 포함한 필드에서 CineMode 내내 표시합니다(수도는 '도시')."
L["Show below health"] = "생명력이 다음 아래일 때 표시"
L["Show below this much mana"] = "마나가 다음 아래일 때 표시"
L["Show during:"] = "표시 시점:"
L["Show emotes too"] = "감정 표현도 표시"
L["Show fewer"] = "적게 표시"
L["Show in"] = "표시 장소"
L["Show in capital cities."] = "수도에서 표시합니다."
L["Show it"] = "표시"
L["Show it now"] = "지금 표시"
L["Show it the whole time, CineMode or not. Unticked, it's hidden, except as the other columns say."] = "CineMode 여부와 관계없이 내내 표시합니다. 해제하면 다른 열 설정에 따를 때 말고는 숨겨집니다."
L["Show keybinds"] = "단축키 표시"
L["Show mana cost indicator"] = "마나 비용 표시기 보이기"
L["Show me"] = "보여 주기"
L["Show members with a debuff you can dispel"] = "내가 해제할 수 있는 약화 효과에 걸린 파티원 표시"
L["Show members with any debuff"] = "약화 효과에 걸린 파티원 표시"
L["Show off-screen bubbles"] = "화면 밖 말풍선 표시"
L["Show off-screen bubbles is on: a say or yell from someone you can't see shows here instead of bringing up the chat window"] = "'화면 밖 말풍선 표시'가 켜져 있음: 보이지 않는 사람의 일반 대화나 외치기가 대화창을 띄우는 대신 여기 나옴"
L["Show or hide this row's settings."] = "이 줄의 설정을 보이거나 숨깁니다."
L["Show out in the world, inns included (capital cities are Cities)."] = "여관을 포함한 필드에서 표시합니다(수도는 '도시')."
L["Show out of fights while you have a living enemy targeted."] = "비전투 중 살아 있는 적을 대상으로 지정했을 때 표시합니다."
L["Show out of fights while you have anything else targeted: friends, NPCs, dead enemies."] = "비전투 중 다른 것(아군, NPC, 죽은 적)을 대상으로 지정했을 때 표시합니다."
L["Show remaining mana text"] = "남은 마나 문자 표시"
L["Show rolls on"] = "주사위 표시 대상"
L["Show the counts under each item"] = "각 아이템 아래에 개수 표시"
L["Show the game's window brings the game's own window back for the rest of the conversation"] = "'게임 창 보기'가 남은 대화 동안 게임 자체 창을 되돌려 놓음"
L["Show timers in the quest tracker while one is running"] = "타이머가 돌아가는 동안 퀘스트 추적기에 타이머 표시"
L["Show tooltips"] = "툴팁 표시"
L["Show who said it"] = "말한 사람 표시"
L["Show your mana when it isn't your power"] = "주 자원이 마나가 아닐 때도 마나 표시"
L["Show your personal resource display until health and power are full"] = "생명력과 자원이 가득 찰 때까지 개인 자원 표시 보이기"
L["Show your pet frame until its health is full"] = "소환수 생명력이 가득 찰 때까지 소환수 프레임 표시"
L["Show your player frame until health and power are full"] = "생명력과 자원이 가득 찰 때까지 플레이어 프레임 표시"
L["Show:"] = "표시:"
L["Showing in its own window. Click here to put it back."] = "자체 창에 표시 중. 여기를 클릭하면 되돌립니다."
L["Shown as:"] = "표시 방식:"
L["Shown in fights: any of them, or only while you're PvP flagged."] = "전투 중 표시: 모든 전투, 또는 PvP 활성화 중에만."
L["Shown in the wheel's middle, on the master wheel and in the game's key bindings."] = "휠 가운데, 마스터 휠, 게임 단축키 설정에 표시됩니다."
L["Shows a box where speech from behind you appears: drag it where you want the lines."] = "뒤에서 들리는 대사가 나오는 상자를 보여 줍니다: 줄이 나올 곳으로 끄세요."
L["Shows a line of speech from behind you, from you, as it looks now."] = "지금 모양 그대로, 내가 말한 것으로 뒤에서 들리는 대사 한 줄을 보여 줍니다."
L["Shows all through CineMode. (The other columns then have nothing to add.)"] = "CineMode 내내 표시합니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["Shows as:"] = "표시 방식:"
L["Shows each of its cards in turn, to see how they look (close the settings to see them). Clicking Stop ends it."] = "카드를 하나씩 차례로 보여 주어 어떻게 보이는지 확인합니다(설정을 닫아야 보입니다). '중지'를 클릭하면 끝납니다."
L["Shows in every fight, wherever you are. (The other columns then have nothing to add.)"] = "어디에 있든 모든 전투에서 표시합니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["Shows its card now, to see how it looks (close the settings to see it)."] = "지금 카드를 보여 주어 어떻게 보이는지 확인합니다(설정을 닫아야 보입니다)."
L["Shows the key each spell is bound to in the corner of its icon in the Essential and Utility bars, as on an action button: the key of the first action bar button holding it (or a macro casting it)."] = "행동 버튼처럼 필수와 보조 바의 각 주문 아이콘 모서리에 지정된 키를 표시합니다: 그 주문이 든 첫 행동 단축바 버튼(또는 그것을 시전하는 매크로)의 키."
L["Shows the lines in their chat colors. Copied text keeps the color codes, so untick this to copy plain text."] = "줄을 대화 색으로 표시합니다. 복사한 문자에 색 코드가 남으므로, 일반 문자로 복사하려면 해제하세요."
L["Shows the preview larger, in a window of its own beside the settings (its Pop out lets you move it anywhere) that you can resize from its corner, so you can watch it while you scroll down the page. Click again to put it back."] = "설정 옆 자체 창에 미리 보기를 크게 보여 주어(그 창의 '떼어 내기'로 아무 데나 옮길 수 있음) 모서리로 크기를 바꿀 수 있고, 페이지를 스크롤하면서 지켜볼 수 있습니다. 다시 클릭하면 되돌립니다."
L["Shows wherever you are. (Never in a fight: a card from one waits for it to end.)"] = "어디에 있든 표시합니다. (전투 중에는 안 함: 전투 중 카드는 전투가 끝날 때까지 기다립니다.)"
L["Shows wherever you are. (The other columns then have nothing to add.)"] = "어디에 있든 표시합니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["Sides"] = "좌우"
L["Size %d%%"] = "크기 %d%%"
L["Size:"] = "크기:"
L["Sizes"] = "크기"
L["Skip it"] = "건너뛰기"
