L["Smart Find every 20 seconds while an addon is new to it (its first 15 minutes of play, for each addon you install that isn't supported), not in fights, so frames that come and go (another addon's popups) are caught while they're up. After that, look with the button below."] = "애드온이 새로울 때(지원하지 않는 애드온을 설치한 뒤 처음 15분 플레이 동안) 전투 중이 아닐 때 20초마다 스마트 찾기를 해서, 나타났다 사라지는 창(다른 애드온의 팝업)도 떠 있을 때 잡아냅니다. 그 뒤로는 아래 버튼으로 찾으세요."
