L["Sounds for boss fights, read before the fights' (Entering and Leaving combat's): as a boss is pulled, killed or your group wipes, the first rule that fits plays one of its sounds at random. A rule here has Boss fight in its condition (taken out, it moves to the fights'). Each sound's slider sets it next to the others, the cue volume sets them all."] = "우두머리 전투 소리. 전투 소리(전투 시작과 전투 종료)보다 먼저 읽습니다: 우두머리를 풀링하거나 처치하거나 파티가 전멸할 때 처음 맞는 규칙이 그 소리 중 하나를 무작위로 재생합니다. 여기 규칙은 조건에 Boss fight가 들어 있습니다(빼면 전투 쪽으로 옮겨 갑니다). 각 소리의 슬라이더는 다른 소리 대비 크기, 신호음 음량은 전체 크기입니다."
