L["Stop and /stare out at the view (or any event set to it on the Scenes page): the camera glides around behind you and sways very gently there, looking out the way you're facing. Like the RP walk camera, only slower and softer. Moving, jumping or another emote ends it."] = "멈춰 서서 /stare로 경치를 바라보면(또는 장면 페이지에서 그것으로 정한 이벤트): 카메라가 뒤쪽으로 부드럽게 돌아가 아주 은은하게 흔들리며 바라보는 방향을 내다봅니다. RP 걷기 카메라와 비슷하지만 더 느리고 부드럽습니다. 움직이거나 점프하거나 다른 감정 표현을 하면 끝납니다."
