L["Talking to a quest giver, the camera zooms in and swings around behind you, looking past you at them. It goes back once you close the window or move off (your zoom stays if you zoomed yourself meanwhile). Works whether or not CineMode is on. The \"Talk to a quest giver\" and \"Talk about a quest\" events on the Scenes page can also turn it off or make it wait a moment."] = "퀘스트 NPC와 대화하면 카메라가 확대하며 뒤쪽으로 돌아가 나를 지나 NPC를 바라봅니다. 창을 닫거나 떠나면 돌아갑니다(그 사이 직접 확대/축소했다면 그 거리 유지). CineMode가 켜져 있든 아니든 작동합니다. 장면 페이지의 \"퀘스트 NPC와 대화\"와 \"퀘스트에 관해 대화\" 이벤트로 끄거나 잠시 기다리게 할 수도 있습니다."
L["Talking to an NPC with a \"(Quest)\" line to pick but no quest to pick up or hand in: a quest step done by talking to them. Works whether or not CineMode is on."] = "받거나 완료할 퀘스트는 없지만 고를 \"(퀘스트)\" 줄이 있는 NPC와 대화할 때: 대화로 하는 퀘스트 단계. CineMode가 켜져 있든 아니든 작동합니다."
