L["The UI fades and the look stays, with just a few cameras: flights, AFK, and your Hearthstone and teleports. No cozy, vista, fish, RP walk, auto-run, death or quest cameras."] = "UI가 흐려지고 화면 효과는 유지되며, 카메라는 몇 개만: 비행, 자리 비움, 귀환석과 순간이동. 아늑함, 풍경, 낚시, RP 걷기, 자동 달리기, 죽음, 퀘스트 카메라는 없습니다."
L["The Unloaded tab has the addons installed but not loaded, to set them up before you turn them on, and the ones supported but not installed."] = "'불러오지 않음' 탭에는 설치했지만 불러오지 않은 애드온(켜기 전에 설정할 수 있음)과, 지원하지만 설치되지 않은 애드온이 있습니다."
L["The addons loaded now: their frames, and the ones you added."] = "지금 불러온 애드온: 그 창과 내가 추가한 창."
L["The arrow by your buffs that folds them away. Hidden in CineMode even while your buffs show; hovering your buffs brings it up."] = "강화 효과 옆에서 효과를 접는 화살표. 강화 효과가 보이는 동안에도 CineMode에서는 숨겨지며, 강화 효과에 마우스를 올리면 나타납니다."
L["The arrow, chevron and diamond bob up and down, the brackets, carets and corners close in and out, the glow and underline pulse. Unticked, it holds still."] = "화살표, 갈매기표, 마름모는 위아래로 까딱이고, 괄호, 꺾쇠, 모서리는 좁혀졌다 벌어지며, 빛과 밑줄은 맥박칩니다. 해제하면 가만히 있습니다."
L["The art's color."] = "그림 색."
L["The background's color, for Custom."] = "사용자 지정일 때 배경 색."
L["The bar behind the zone's name above the minimap (the name has a row of its own). Untick it to leave the name floating on its own. Hovering the minimap brings it up with the map: to keep it hidden then too, take Minimap header out of the Minimap group on the Hover groups page."] = "미니맵 위 지역 이름 뒤의 바(이름은 자체 줄이 있음). 해제하면 이름만 따로 떠 있습니다. 미니맵에 마우스를 올리면 지도와 함께 나타납니다: 그때도 숨기려면 마우스오버 그룹 페이지의 미니맵 그룹에서 미니맵 머리글을 빼세요."
L["The bar in your class's color, whether you lead or chase."] = "앞서든 쫓든 직업 색의 바."
L["The bar's color once you lead. Picking one turns Colors to Your own."] = "앞설 때 바 색. 고르면 '색'이 '직접 고름'으로 바뀝니다."
L["The bar's color while you're behind. Picking one turns Colors to Your own."] = "뒤처질 때 바 색. 고르면 '색'이 '직접 고름'으로 바뀝니다."
L["The bar's fill. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "바의 채움. 게임의 몇 가지 아래로 다른 애드온이 공유하는 것(LibSharedMedia를 통해)."
L["The bars and boxes the game puts at the top of the screen for a zone event or scenario, such as a timer to the next event. Until you change its ticks it does what the quest tracker's row does."] = "지역 이벤트나 시나리오를 위해 게임이 화면 위에 띄우는 바와 상자(예: 다음 이벤트까지 타이머). 체크를 바꾸기 전까지는 퀘스트 추적기 줄을 따릅니다."
L["The bars as tall as it takes for what's left between them to have a film's shape, whatever your screen."] = "화면이 어떻든 바 사이에 남는 화면이 영화 비율이 되도록 바의 높이를 맞춥니다."
L["The bars fade in at their full height."] = "바가 최대 높이로 서서히 나타납니다."
L["The bars fade into the scene past their edge."] = "바가 가장자리를 지나 장면 속으로 흐려집니다."
L["The bars grow in from the screen's edges."] = "바가 화면 가장자리에서 자라 들어옵니다."
L["The bars of every Vision that follows this page (Damage Vision's, Roll Vision's time left). Below the game's own few: any other addon shares (through LibSharedMedia)."] = "이 페이지를 따르는 모든 Vision의 바(Damage Vision, Roll Vision의 남은 시간). 게임의 몇 가지 아래로 다른 애드온이 공유하는 것(LibSharedMedia를 통해)."
L["The bars' border: the game's, or one of ours (Custom: its thickness and color under it)."] = "바 테두리: 게임 것, 또는 우리 것(사용자 지정: 아래에서 두께와 색)."
L["The bars' fill."] = "바의 채움."
L["The bars' fill. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "바의 채움. 게임의 몇 가지 아래로 다른 애드온이 공유하는 것(LibSharedMedia를 통해)."
L["The battle begins"] = "전투가 시작됩니다"
L["The big words across the screen. <NAME>: the name of the one that fell."] = "화면을 가로지르는 큰 글자. <NAME>: 쓰러진 쪽의 이름."
L["The big words as you lose a duel."] = "결투에서 졌을 때의 큰 글자."
L["The big words as you win a duel."] = "결투에서 이겼을 때의 큰 글자."
L["The border round every page's bars, panels and buttons that follow General. The game's: as each page's default has it. Custom: its thickness and color under it."] = "일반을 따르는 모든 페이지의 바, 판, 버튼 둘레의 테두리. 게임 기본: 각 페이지의 기본값대로. 사용자 지정: 아래에서 두께와 색."
L["The border around the Vision parts that follow this page (the quest item button's frame). Custom: its thickness and color under it."] = "이 페이지를 따르는 Vision 부분(퀘스트 아이템 버튼의 틀) 둘레의 테두리. 사용자 지정: 아래에서 두께와 색."
L["The border the game puts round your target's health bar, in its mark's color."] = "게임이 대상의 생명력 바 둘레에 두르는 테두리를 표시 색으로."
L["The border's color."] = "테두리 색."
L["The border's color. Picking one turns it to Custom."] = "테두리 색. 고르면 '사용자 지정'으로 바뀝니다."
L["The boss's name as its fight starts, in place of Entering combat's card. Once a run for each boss."] = "전투가 시작될 때 전투 시작 카드 대신 우두머리 이름. 우두머리마다 한 번 진행에 한 번."
L["The boss's name as you first come within about 28 yards of it, before the fight. A dungeon or raid boss is told by its level: a skull, or on retail two over yours."] = "전투 전, 우두머리에게 처음 약 28m 안으로 다가갈 때 그 이름. 던전이나 공격대 우두머리는 레벨로 알아봅니다: 해골, 또는 리테일에서는 내 레벨보다 2 높음."
L["The boss's name as you first target it, before the fight. A dungeon or raid boss is told by its level: a skull, or on retail two over yours."] = "전투 전, 우두머리를 처음 대상으로 지정할 때 그 이름. 던전이나 공격대 우두머리는 레벨로 알아봅니다: 해골, 또는 리테일에서는 내 레벨보다 2 높음."
L["The boxes the game puts under the minimap for a scenario's or quest's current step, such as a capture bar. Always shown to start with."] = "시나리오나 퀘스트의 현재 단계를 위해 게임이 미니맵 아래에 띄우는 상자(예: 점령 바). 처음에는 항상 표시됩니다."
L["The bubble's color, for Custom."] = "사용자 지정일 때 말풍선 색."
L["The bubble's tail sits on top, pointing up, instead of under it pointing down. (In a bubble only: not with no bubble behind the words.)"] = "말풍선 꼬리를 아래로 향하게 밑에 두는 대신 위로 향하게 위에 둡니다. (말풍선이 있을 때만: 글자 뒤에 말풍선이 없으면 아님.)"
L["The bubble's words in a color of your own (the quest card keeps its ink)."] = "말풍선 글자를 직접 고른 색으로(퀘스트 카드는 원래 잉크 유지)."
L["The buff fades"] = "강화 효과가 사라질 때"
L["The button's width and height."] = "버튼의 너비와 높이."
L["The buttons beside the chat window (chat menu, channels, voice...) come up with a new message."] = "대화창 옆 버튼(대화 메뉴, 채널, 음성...)이 새 메시지와 함께 나타납니다."
L["The calendar button on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "미니맵 머리글의 달력 버튼. 해제하면 미니맵이 떠 있어도 CineMode에서 숨깁니다. 미니맵에 마우스를 올리면 지도와 함께 나타납니다."
L["The camera distance to start at. The game's furthest out may be less than this."] = "시작할 카메라 거리. 게임의 최대 거리가 이보다 짧을 수 있습니다."
L["The camera eases out a little, then drifts in and out around your own distance. When you stop it glides back."] = "카메라가 조금 물러난 뒤 내 거리 주위에서 앞뒤로 흘러갑니다. 멈추면 부드럽게 돌아옵니다."
L["The camera eases out a little, then drifts in and out around your own distance. When you stop walking it glides back."] = "카메라가 조금 물러난 뒤 내 거리 주위에서 앞뒤로 흘러갑니다. 걷기를 멈추면 부드럽게 돌아옵니다."
L["The camera eases out a little, then drifts slowly in and out around your own distance. Your own distance comes back afterwards."] = "카메라가 조금 물러난 뒤 내 거리 주위에서 천천히 앞뒤로 흘러갑니다. 나중에 내 거리가 돌아옵니다."
L["The camera is %d yards from you: a unit next to you is about %d yards from it, one at 20 yards about %d, one at 35 about %d."] = "카메라는 나에게서 %dm: 옆에 있는 유닛은 카메라에서 약 %dm, 20m 떨어진 유닛은 약 %dm, 35m는 약 %dm."
L["The camera it moves like: cozy swings round to face you, vista and fish settle behind you (fish sways less), AFK turns right around you. Its other settings (Camera Settings page) go on as they are."] = "움직임을 본뜰 카메라: 아늑함은 나를 마주 보도록 돌고, 풍경과 낚시는 뒤쪽에 자리 잡으며(낚시는 덜 흔들림), 자리 비움은 주위를 한 바퀴 돕니다. 다른 설정(카메라 설정 페이지)은 그대로 적용됩니다."
L["The camera lines up behind you, then turns this far round: 180 looks straight back at you."] = "카메라가 뒤쪽에 정렬한 뒤 이만큼 돕니다: 180이면 나를 정면으로 돌아봅니다."
L["The camera never tilts more than this far below where it was when auto-run started, even when it lowers while you steer."] = "자동 달리기가 시작될 때의 각도보다 더 아래로는 기울지 않습니다. 방향을 조종하며 내려갈 때도 마찬가지입니다."
L["The camera slowly pulls back, then (with random zoom) drifts in and out. Moving glides it back to your distance; zooming yourself keeps your new distance."] = "카메라가 천천히 물러난 뒤 (무작위 확대/축소를 켜면) 앞뒤로 흘러갑니다. 움직이면 내 거리로 부드럽게 돌아오고, 직접 확대/축소하면 새 거리를 유지합니다."
L["The camera snaps straight to whoever's talking instead of swinging, the letterbox comes in twice as tall for the conversation with subtitles in its bottom bar, and the whole UI fades out: the minimap, frames, nameplates, names and the circle under your target."] = "카메라가 돌지 않고 말하는 사람에게 곧바로 붙으며, 대화 동안 레터박스가 두 배 높이로 들어와 아래 바에 자막이 나오고, UI 전체가 사라집니다: 미니맵, 창, 이름표, 이름, 대상 아래 원."
L["The camera sways this much lower than where it lines up behind you, so it looks out across the view rather than down at it. 0 keeps your angle."] = "카메라가 뒤쪽 정렬 위치보다 이만큼 낮게 흔들려서 경치를 내려다보지 않고 가로질러 바라봅니다. 0이면 각도를 유지합니다."
L["The camera sways this much lower than where it lines up behind you, so it looks out across the water rather than down at it. 0 keeps your angle."] = "카메라가 뒤쪽 정렬 위치보다 이만큼 낮게 흔들려서 물을 내려다보지 않고 가로질러 바라봅니다. 0이면 각도를 유지합니다."
L["The camera sweeps around your character, pausing between sweeps. Moving or dragging the camera stops it."] = "카메라가 캐릭터 주위를 돌며 사이사이 멈춥니다. 움직이거나 카메라를 끌면 멈춥니다."
L["The camera swings a little from side to side behind your character, pausing between moves. Narrower than the vista camera's sway."] = "카메라가 캐릭터 뒤에서 좌우로 조금 흔들리며 사이사이 멈춥니다. 풍경 카메라보다 폭이 좁습니다."
L["The camera swings from side to side behind your character, pausing between moves. Dragging the camera pauses it."] = "카메라가 캐릭터 뒤에서 좌우로 흔들리며 사이사이 멈춥니다. 카메라를 끌면 잠시 멈춥니다."
L["The camera swings gently from side to side behind your character, pausing between moves."] = "카메라가 캐릭터 뒤에서 좌우로 부드럽게 흔들리며 사이사이 멈춥니다."
L["The camera swings very gently from side to side behind your character, pausing between moves."] = "카메라가 캐릭터 뒤에서 좌우로 아주 부드럽게 흔들리며 사이사이 멈춥니다."
L["The camera this row starts. No camera: none (and its trigger's rows below aren't tried)."] = "이 줄이 시작하는 카메라. 카메라 없음: 없음(그리고 그 발동 조건의 아래 줄은 시도하지 않음)."
L["The camera turns back over the 6 seconds before this, so it's settled behind you this long before you land."] = "카메라가 이 시점 전 6초에 걸쳐 돌아와서, 착륙하기 이만큼 전에 뒤쪽에 자리 잡습니다."
L["The camera waits this long on a quest window before starting. Accept a quest and go sooner, and it doesn't move at all; stay to read, and it starts. Clicking through several quests, each new window adds a second to the wait. 0 starts at once."] = "퀘스트 창에서 카메라가 시작하기 전까지 기다리는 시간. 퀘스트를 수락하고 그 전에 떠나면 전혀 움직이지 않고, 남아서 읽으면 시작합니다. 여러 퀘스트를 연달아 클릭하면 새 창마다 대기가 1초씩 늘어납니다. 0이면 곧바로 시작합니다."
L["The camera waits this long on the window before starting. Close it sooner, and it doesn't move at all. 0 starts at once."] = "창에서 카메라가 시작하기 전까지 기다리는 시간. 그 전에 닫으면 전혀 움직이지 않습니다. 0이면 곧바로 시작합니다."
L["The camera's steps, in order, and what it does when it ends."] = "카메라의 단계(순서대로)와 끝날 때 하는 일."
L["The card fades in and out."] = "카드가 서서히 나타나고 사라집니다."
L["The cast bar's border: the game's, or one of ours (Custom: its thickness and color under it)."] = "시전 바 테두리: 게임 것, 또는 우리 것(사용자 지정: 아래에서 두께와 색)."
L["The cast ends"] = "시전이 끝날 때"
L["The chat window's dark background comes up with a new message. Untick for just the lines of text."] = "새 메시지와 함께 대화창의 어두운 배경이 나타납니다. 글자 줄만 원하면 해제하세요."
L["The chat window's tabs (General, Combat Log...) come up with a new message."] = "새 메시지와 함께 대화창 탭(일반, 전투 기록...)이 나타납니다."
L["The chat windows, with their tabs and buttons. Tick where they stay up while the rest fades; which messages bring them up for a moment is on the Chat page."] = "탭과 버튼을 포함한 대화창. 나머지가 흐려지는 동안 남아 있을 곳에 체크하세요. 어떤 메시지가 잠깐 띄울지는 대화 페이지에 있습니다."
L["The classic smooth fill in your colors, no border."] = "내 색으로 부드럽게 채운 전통적인 바, 테두리 없음."
L["The clock on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "미니맵 머리글의 시계. 해제하면 미니맵이 떠 있어도 CineMode에서 숨깁니다. 미니맵에 마우스를 올리면 지도와 함께 나타납니다."
L["The close-up distance the cozy camera zooms in to, if you're further out. The zoom settings above then work around it. Your own distance comes back afterwards."] = "내가 더 멀리 있으면 아늑한 카메라가 다가가는 근접 거리. 위 확대/축소 설정은 그 주위에서 작동합니다. 나중에 내 거리가 돌아옵니다."
L["The color grading over the game world: a preset, the time of day and each zone's mood. Where and when it shows: the Tint tab. The UI isn't tinted."] = "게임 세상 위의 색 보정: 프리셋, 시간대, 지역별 분위기. 어디서 언제 보일지: 색조 탭. UI에는 색조가 입혀지지 않습니다."
L["The dark edges' color, at full Shadow tint."] = "그림자 색조가 최대일 때 어두운 가장자리의 색."
L["The day and night dial by the minimap. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "미니맵 옆 낮/밤 다이얼. 해제하면 미니맵이 떠 있어도 CineMode에서 숨깁니다. 미니맵에 마우스를 올리면 지도와 함께 나타납니다."
L["The death camera fades everything while you're dead"] = "죽어 있는 동안 죽음 카메라가 모든 것을 흐리게 함"
L["The dungeon or raid and its difficulty under the boss's name (beside it in a letterbox bar)."] = "우두머리 이름 아래(레터박스 바 안에서는 옆)에 던전 또는 공격대와 난이도."
L["The edge in a unit's class or reaction color, or an item's quality."] = "유닛의 직업이나 반응 색, 또는 아이템 품질 색의 가장자리."
L["The edges flash in the theme's color when a hit takes a lot at once. (What counts as big: the Vision tab.)"] = "한 번에 많이 깎는 타격을 받으면 가장자리가 테마 색으로 번쩍입니다. (무엇이 큰 타격인지: Vision 탭.)"
L["The edges of the screen flash for a moment as the card shows, this strongly. 0: no pulse."] = "카드가 나타날 때 화면 가장자리가 이 강도로 잠깐 번쩍입니다. 0: 맥박 없음."
L["The edges throb with a heartbeat, quicker as you weaken."] = "가장자리가 심장 박동처럼 고동치며, 약해질수록 빨라집니다."
L["The extra bar some bosses, quests and vehicles bring up, such as a boss's own power."] = "일부 우두머리, 퀘스트, 탈것이 띄우는 추가 바(예: 우두머리 고유 자원)."
L["The fastest the camera swings toward a new speaker. Each swing speeds up and slows down gently, as the flight camera's fly-bys do, so a short one never gets this fast and takes a few seconds."] = "새로 말하는 사람에게 카메라가 도는 최고 속도. 비행 카메라의 플라이바이처럼 매번 부드럽게 가속하고 감속하므로, 짧게 돌 때는 이 속도에 이르지 않고 몇 초 걸립니다."
L["The fastest the edges lift when you're healed, as a share of all the way each second (40%: a full heal takes at least 2.5 seconds). They speed up to it and slow as they settle."] = "치유받을 때 가장자리가 걷히는 최고 속도(초당 전체 대비 비율. 40%: 완전 회복에 최소 2.5초). 그 속도까지 빨라졌다가 자리 잡으며 느려집니다."
L["The first swing waits for the zoom in to finish."] = "첫 회전은 확대가 끝나기를 기다립니다."
L["The first time you log in after Cinematic updates, a line in chat says so, with a What's new link to what's been added. Chat shows for it while the UI is faded."] = "Cinematic이 업데이트된 뒤 처음 접속하면 대화창에 그 사실과 새로 추가된 것으로 가는 '새 소식' 링크가 나옵니다. UI가 흐려져 있어도 이때는 대화창이 보입니다."
L["The full report: how you did on the run, boss by boss and the rest, with the whole party (/cine report). Made-up bosses while the meter has none."] = "전체 보고서: 우두머리별 등 진행 동안의 성과를 파티 전체와 함께(/cine report). 측정기에 우두머리가 없으면 지어낸 우두머리."
L["The game only shows a bubble over someone on your screen, and puts one from someone above you at the very top of the screen, under the letterbox bar. So Cinematic draws bubbles of its own, looking like the game's, for speech whose bubble you can't see. How they look, and where speech from behind you shows: the Style hub's Chat bubbles page."] = "게임은 화면에 보이는 사람 위에만 말풍선을 띄우고, 나보다 높은 곳에 있는 사람의 말풍선은 화면 맨 위 레터박스 바 밑에 놓습니다. 그래서 말풍선이 보이지 않는 대사는 Cinematic이 게임 것처럼 보이는 자체 말풍선을 그립니다. 모양과 뒤에서 들리는 대사의 위치: 스타일 허브의 말풍선 페이지."
L["The game shows only your main power under your character: Maelstrom, Insanity, Astral Power, rage or energy in a form. Ticked, your mana gets a bar of its own under it. When it comes up is the Personal mana bar row on the Game Frames page."] = "게임은 캐릭터 아래에 주 자원만 보여 줍니다: 소용돌이, 광기, 천공의 힘, 또는 변신 중의 분노나 기력. 체크하면 그 아래에 마나 바가 따로 생깁니다. 언제 나타날지는 게임 창 페이지의 개인 마나 바 줄에서 정합니다."
L["The game's"] = "게임 기본"
L["The game's Show Offscreen Nameplates in CineMode. Ticked: on, plates for units out of view stay, pinned to the edge of the screen, so rows and rules that look for plates still find them, like an elite behind you for the elite rules. Unticked: off in CineMode. Your own setting comes back when CineMode ends."] = "CineMode에서 게임의 '화면 밖 이름표 표시'. 체크하면: 켜짐. 시야 밖 유닛의 이름표가 화면 가장자리에 붙어 남으므로, 이름표를 찾는 줄과 규칙이 계속 찾을 수 있습니다(예: 정예 규칙을 위한 뒤쪽의 정예). 해제하면: CineMode에서 꺼짐. CineMode가 끝나면 내 설정이 돌아옵니다."
L["The game's background tinted a color of your own (the swatch)."] = "직접 고른 색(견본)으로 물들인 게임 배경."
L["The game's bars, as it draws them (the defaults)."] = "게임이 그리는 그대로의 바(기본값)."
L["The game's bubbles, with bigger words."] = "글자를 키운 게임 말풍선."
L["The game's dice and coin before each name."] = "각 이름 앞에 게임의 주사위와 동전."
L["The game's effect shown. Theme's pick: the one picked to go with your theme (it changes with it)."] = "표시할 게임 효과. 테마 선택: 테마에 맞춰 고른 것(테마와 함께 바뀜)."
L["The game's effects slide slowly under their edge, as they do in the game (not an edge like the red one)."] = "게임에서처럼 게임 효과가 가장자리 아래로 천천히 미끄러집니다(빨간 것 같은 가장자리는 아님)."
L["The game's figure"] = "게임 수치"
L["The game's figure, the last five minutes"] = "게임 수치, 최근 5분"
L["The game's frame"] = "게임 틀"
L["The game's frames, as it draws them (the defaults)."] = "게임이 그리는 그대로의 창(기본값)."
L["The game's mark and name for who the spell is cast at."] = "주문 대상에 대한 게임의 표시와 이름."
L["The game's mark on casts it counts as important, ones worth interrupting or getting out of."] = "게임이 중요하다고 보는 시전(차단하거나 피할 가치가 있는 것)에 붙이는 게임 표시."
L["The game's menu doesn't change it. Its default is %s."] = "게임 메뉴로는 바뀌지 않습니다. 기본값은 %s입니다."
L["The game's menu doesn't change it: it's %s."] = "게임 메뉴로는 바뀌지 않습니다: %s입니다."
L["The game's menu goes from %s to %s."] = "게임 메뉴 범위는 %s부터 %s까지입니다."
L["The game's own bubble."] = "게임 자체 말풍선."
L["The game's own bubbles (the defaults)."] = "게임 자체 말풍선(기본값)."
L["The game's own cast bars (the defaults)."] = "게임 자체 시전 바(기본값)."
L["The game's own chat bubble."] = "게임 자체 말풍선."
L["The game's own graphics settings one by one, past its Graphics menu either way: higher for a better look, lower for a faster game. They're this computer's: the same in every profile."] = "게임 자체 그래픽 설정을 하나씩, 그래픽 메뉴 범위를 넘어 위아래로: 높이면 더 좋은 화질, 낮추면 더 빠른 게임. 이 컴퓨터의 설정이라 모든 프로필에서 같습니다."
L["The game's own screen effects (fire, frost, lightning, ripples...) cut to an edge, closing in with ours, over it. Each theme has one picked to go with it. Classic has only a few of them."] = "게임 자체 화면 효과(불, 냉기, 번개, 잔물결...)를 가장자리 모양으로 잘라 우리 것과 함께 좁혀 오며 그 위에 덧씌웁니다. 테마마다 어울리는 것이 하나씩 골라져 있습니다. 클래식에는 몇 개만 있습니다."
L["The game's own screen effects, cut to an edge, over ours."] = "게임 자체 화면 효과를 가장자리 모양으로 잘라 우리 것 위에."
L["The game's own setting (Options, Nameplates, Style): the size and color of its plates' bars, all in the same texture. Shown here for what it is; Cinematic doesn't change it."] = "게임 자체 설정(옵션, 이름표, 스타일): 이름표 바의 크기와 색, 모두 같은 질감. 참고로 여기 보여 줄 뿐 Cinematic은 바꾸지 않습니다."
L["The game's party and raid frames show only who needs healing: everyone (pets too) while below full health, and tanks as set below. The group titles hide. The members stay in their places, so there are gaps. Out of combat, the mouse over the frames brings everyone back. Ticked in the grid, it's on there. Always: everywhere. Party and Raid: while you're in one, wherever you are. Members with debuffs can't be shown: the game doesn't let addons see your group's debuffs in fights."] = "게임의 파티 및 공격대 창이 치유가 필요한 사람만 보여 줍니다: 생명력이 가득하지 않은 모두(소환수 포함)와, 아래 설정대로 방어 전담. 그룹 제목은 숨겨집니다. 파티원은 제자리에 있어서 빈칸이 생깁니다. 비전투 중에는 창 위에 마우스를 올리면 모두 돌아옵니다. 격자에서 체크한 곳에서 켜집니다. 항상: 어디서나. 파티와 공격대: 어디에 있든 그 안에 있을 때. 약화 효과에 걸린 파티원은 표시할 수 없습니다: 게임이 전투 중 파티의 약화 효과를 애드온이 보지 못하게 합니다."
L["The game's profiler isn't on this client."] = "이 클라이언트에는 게임 프로파일러가 없습니다."
L["The game's profiler isn't on this client: use a recording below."] = "이 클라이언트에는 게임 프로파일러가 없습니다: 아래 기록을 쓰세요."
L["The game's raid frames, as it draws them (the defaults)."] = "게임이 그리는 그대로의 공격대 창(기본값)."
L["The game's shield over the icon while the cast can't be interrupted."] = "시전을 차단할 수 없는 동안 아이콘 위의 게임 방패."
L["The game's sweep"] = "게임의 쓸기"
L["The game's tooltips, as it draws them (the defaults)."] = "게임이 그리는 그대로의 툴팁(기본값)."
L["The game's: each part in its own (the quest window's for the words). Russian, Korean or Chinese text keeps the game's, so its letters show."] = "게임 기본: 부분마다 고유한 것(글자는 퀘스트 창 것). 러시아어, 한국어, 중국어 글자는 글자가 보이도록 게임 글꼴을 유지합니다."
L["The game's: its own fill, in its own colors. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "게임 기본: 고유 채움, 고유 색. 게임의 몇 가지 아래로 다른 애드온이 공유하는 것(LibSharedMedia를 통해)."
L["The glow round it, added on as light (Glow's only color)."] = "둘레의 빛, 빛으로 더해짐(빛의 유일한 색)."
L["The health bar's color, for Custom."] = "사용자 지정일 때 생명력 바 색."
L["The health bar's fill. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "생명력 바의 채움. 게임의 몇 가지 아래로 다른 애드온이 공유하는 것(LibSharedMedia를 통해)."
L["The health bar's height, next to the game's."] = "게임 대비 생명력 바 높이."
L["The health bar's height."] = "생명력 바 높이."
L["The health bar's width."] = "생명력 바 너비."
L["The icon glows bright and dim while it flashes."] = "번쩍이는 동안 아이콘이 밝아졌다 어두워졌다 합니다."
L["The icon grows a little and back with each beat while it flashes."] = "번쩍이는 동안 박동마다 아이콘이 조금 커졌다 돌아옵니다."
L["The icon's size, next to the game's. On nameplates, the health bar and name ride up on it."] = "게임 대비 아이콘 크기. 이름표에서는 생명력 바와 이름이 그 위로 올라갑니다."
L["The icon. Click to pick it from all the game's. Right-click: back to the event's own."] = "아이콘. 클릭하면 게임의 모든 아이콘에서 고릅니다. 오른쪽 클릭: 이벤트 고유 아이콘으로."
L["The icons this bar shows sit together in their order, centered on the bar, instead of faded ones leaving gaps. Edit Mode shows the game's own layout."] = "이 바가 보여 주는 아이콘을 흐려진 아이콘이 빈칸을 남기지 않도록 순서대로 모아 바 가운데에 정렬합니다. 편집 모드에서는 게임 자체 배치가 보입니다."
L["The item's quality"] = "아이템 품질"
L["The key you've bound to it (Key Bindings, Cinematic: Use the quest item), in its top corner."] = "위쪽 모서리에 지정한 키(단축키 설정, Cinematic: 퀘스트 아이템 사용)."
L["The kind of plate the row is for: your target, focus or the unit under the mouse; Aggro, enemies by who they're attacking; Units, by what they are; or Default, every other plate."] = "줄이 적용될 이름표 종류: 대상, 주시 대상 또는 마우스 아래 유닛, 위협(누구를 공격하는지에 따른 적), 유닛(무엇인지에 따라), 또는 기본(나머지 모든 이름표)."
L["The last tooltip, %d sec ago"] = "마지막 툴팁, %d초 전"
L["The least of the member you've targeted that shows while they'd be hidden. It only ever makes them more visible: a target whose own opacity above is higher (a tank shown always, say) keeps it. 100% always shows them, at full health too."] = "숨겨질 파티원을 대상으로 지정했을 때 보이는 최소한의 정도. 더 잘 보이게만 합니다: 위의 자체 불투명도가 더 높은 대상(예: 항상 보이는 방어 전담)은 그 값을 유지합니다. 100%면 생명력이 가득해도 항상 보입니다."
L["The letters start spread apart and close up, as a film's title comes in; the other lines rise in after. A name the game keeps secret (a boss's before its fight, on retail) opens as Reveal instead."] = "영화 제목이 나타나듯 글자가 벌어진 채 시작해 모이고, 다른 줄이 뒤따라 떠오릅니다. 게임이 비밀로 하는 이름(리테일에서 전투 전 우두머리 이름)은 대신 '드러내기'로 나옵니다."
L["The level you reached, if you went up."] = "레벨이 올랐다면 도달한 레벨."
L["The line round a Dark or Custom bubble. Custom: its thickness and color under it."] = "어두움이나 사용자 지정 말풍선 둘레의 선. 사용자 지정: 아래에서 두께와 색."
L["The lines under an item's players: \"and N more\", \"Lower picks\", who passed, and \"Click to list everyone\". Off: just the players. Clicking an item's panel still lists everyone."] = "아이템의 플레이어 아래 줄: \"외 N명\", \"낮은 선택\", 포기한 사람, \"클릭하면 모두 나열\". 끄면: 플레이어만. 아이템 판을 클릭하면 여전히 모두 나열합니다."
L["The list comes with each release. (For the dev copy, run Tools/commits.sh and /reload.)"] = "목록은 릴리스마다 함께 옵니다. (개발용 사본은 Tools/commits.sh를 실행하고 /reload하세요.)"
L["The little point under the bubble. Unticked, just the bubble."] = "말풍선 아래의 작은 꼬리. 해제하면 말풍선만."
L["The look every Vision shares. Each setting starts on the Style hub's General page's; a Vision with a setting of its own on its page keeps it."] = "모든 Vision이 공유하는 모양. 각 설정은 스타일 허브의 일반 페이지 값으로 시작하며, 자체 페이지에서 따로 정한 Vision은 그 값을 유지합니다."
L["The look of Cinematic's settings pages and windows, for all your characters. HD: flat and dark, with thin edges. SD: the game's own buttons and windows. Auto: HD on retail, SD on classic, and on WoW Forever as your Character Models setting is (Standard: SD)."] = "모든 캐릭터에 적용되는 Cinematic 설정 페이지와 창의 모양. HD: 가는 테두리의 납작하고 어두운 모양. SD: 게임 자체 버튼과 창. 자동: 리테일은 HD, 클래식은 SD, WoW Forever는 캐릭터 모델 설정에 따라(표준: SD)."
L["The look: Auto picks your class and spec's (by the talent tree you've put most into, on clients without specs), or pick any. Each class has a theme for each spec. Create theme makes one of your own from the one shown, under Your themes; the theme's own settings below change the one shown (ours become your version, which Reset theme puts back)."] = "모양: 자동은 내 직업과 전문화의 것을 고르거나(전문화가 없는 클라이언트에서는 가장 많이 투자한 특성 트리 기준), 아무것이나 직접 고르세요. 직업마다 전문화별 테마가 있습니다. '테마 만들기'는 보이는 테마로 나만의 테마를 만들어 '내 테마' 아래에 둡니다. 아래 테마 자체 설정은 보이는 테마를 바꿉니다(우리 테마는 내 버전이 되며, '테마 초기화'로 되돌립니다)."
L["The mana bar shows for this many seconds after you spend mana, then fades out until you spend some again. 0: whenever it's up."] = "마나를 쓴 뒤 이 초 동안 마나 바를 보이다가, 다시 쓸 때까지 흐리게 합니다. 0: 떠 있을 때는 항상."
L["The mana bar's color, for Custom."] = "사용자 지정일 때 마나 바 색."
L["The mana bar's height, next to the power bar's."] = "자원 바 대비 마나 바 높이."
L["The mark on important casts"] = "중요한 시전 표시"
L["The mark's color."] = "표시의 색."
L["The mark's own opacity (the plate's is on the Plate line)."] = "표시 자체의 불투명도(이름표의 것은 이름표 줄에 있음)."
L["The mark's size."] = "표시의 크기."
L["The member under your mouse fades in to at least this, in fights too, and starts fading out the moment the mouse leaves them. 0% turns it off."] = "마우스 아래의 파티원은 전투 중에도 최소 이만큼 나타나며, 마우스가 벗어나는 순간 흐려지기 시작합니다. 0%면 끕니다."
L["The meter's totals are hidden in a fight (and for a whole key). The report fills in once it's over."] = "측정기 합계는 전투 중(그리고 쐐기돌 전체 동안) 숨겨집니다. 끝나면 보고서가 채워집니다."
L["The minimap stays up only this long after you pick up a quest or make progress on a tracked one, then fades until you do again. Off: it stays up the whole time a quest is tracked."] = "퀘스트를 받거나 추적 중인 퀘스트를 진행한 뒤 이 시간 동안만 미니맵을 띄우고, 다시 그럴 때까지 흐리게 합니다. 끄면: 퀘스트를 추적하는 동안 내내 띄웁니다."
L["The moment this rule is for. Click to switch."] = "이 규칙이 적용되는 순간. 클릭해서 바꿉니다."
L["The most the addon took in one frame."] = "애드온이 한 프레임에 쓴 최대치."
L["The mouse is on it, or on a frame in its Hover group"] = "마우스가 그 위, 또는 그 마우스오버 그룹의 창 위에 있음"
L["The name's font. Russian, Korean or Chinese names keep the game's, so their letters show."] = "이름 글꼴. 러시아어, 한국어, 중국어 이름은 글자가 보이도록 게임 글꼴을 유지합니다."
L["The name's size, next to the game's."] = "게임 대비 이름 크기."
L["The names and portraits above the chat of who's talking in voice chat. Untick Always to hide them in CineMode."] = "음성 대화에서 말하는 사람의 이름과 초상화(대화창 위). CineMode에서 숨기려면 '항상'을 해제하세요."
L["The new angle is never within this many degrees of the current one, either way. Keep it below the swing for varied moves."] = "새 각도는 현재 각도에서 어느 쪽으로든 이 각도 안에 들지 않습니다. 움직임이 다양하도록 흔들기 폭보다 작게 두세요."
L["The new buff shows at the start of the row, not in its own place among empty spaces."] = "새 강화 효과를 빈칸 사이 제자리가 아니라 줄 맨 앞에 표시합니다."
L["The other player's name as they challenge you to a duel."] = "상대 플레이어가 나에게 결투를 신청할 때 그 이름."
L["The other player's name as you challenge them to a duel."] = "내가 상대 플레이어에게 결투를 신청할 때 그 이름."
L["The parts of the plate in its color, ticks."] = "그 색으로 칠할 이름표 부분, 체크."
L["The pattern's own"] = "무늬 고유"
L["The pattern's own choice"] = "무늬 고유 선택"
L["The place's color (and the recap's title). Picking one turns it to Your own."] = "장소의 색(과 요약 제목). 고르면 '직접 고름'으로 바뀝니다."
L["The plan adds nothing to your talents."] = "계획이 특성에 아무것도 더하지 않습니다."
L["The plan needs level %d; you're level %d."] = "계획에는 %d레벨이 필요합니다. 지금은 %d레벨입니다."
L["The plan takes back talents you've learned: only a class trainer can unlearn them."] = "계획이 배운 특성을 되돌립니다: 직업 전문가만 초기화할 수 있습니다."
L["The plate's color, for the parts ticked beside it. -: the next row that fits the plate decides (the game's if none does). The game's: the game's, whatever the rows below say. Mark's: the mark's color. The rest as the mark's colors."] = "옆에 체크한 부분에 쓸 이름표 색. -: 이름표에 맞는 다음 줄이 정함(없으면 게임 것). 게임 기본: 아래 줄과 관계없이 게임 것. 표시 색: 표시의 색. 나머지는 표시 색들처럼."
L["The power bar's height, next to the game's."] = "게임 대비 자원 바 높이."
L["The quest camera can't start now: it's off (Scenes page), you're moving or in a fight, or it's turned off where you are."] = "지금은 퀘스트 카메라를 시작할 수 없습니다: 꺼져 있거나(장면 페이지), 움직이거나 전투 중이거나, 지금 있는 곳에서 꺼져 있습니다."
L["The quest card and the list of replies have the bubble's look instead of their own dark one, their words in colors that suit it."] = "퀘스트 카드와 대답 목록이 자체 어두운 모양 대신 말풍선 모양을 쓰고, 글자도 그에 어울리는 색이 됩니다."
L["The quest mark's icon on enemies you still need for a quest (a mob to kill): on their nameplates or names, and on your target frame. Click to pick another."] = "퀘스트에 아직 필요한 적(잡아야 할 몹)에 붙는 퀘스트 표시 아이콘: 이름표나 이름, 대상 프레임에. 클릭해서 다른 것을 고르세요."
L["The quest mark's icon on friendly NPCs you still need for a quest (an NPC to talk to): on their nameplates or names, on your target frame, and over the quest object that glows. One you can't do anything with yourself shows it grayed (with the !, the game's \"in progress\" mark). Click to pick another."] = "퀘스트에 아직 필요한 아군 NPC(대화할 NPC)에 붙는 퀘스트 표시 아이콘: 이름표나 이름, 대상 프레임, 빛나는 퀘스트 사물 위에. 내가 직접 할 수 없는 것은 회색으로 보입니다(!와 함께, 게임의 '진행 중' 표시). 클릭해서 다른 것을 고르세요."
L["The ranged bar goes on top, where the main hand's was, and the main hand and off-hand bars each move down one. Set for each class on its own (ticked for hunters, mages, priests and warlocks to start with), so one profile suits all your characters."] = "원거리 바가 주 장비 바 자리인 맨 위로 가고, 주 장비와 보조장비 바가 한 칸씩 내려갑니다. 직업마다 따로 설정되므로(처음에는 사냥꾼, 마법사, 사제, 흑마법사에 체크됨) 한 프로필로 모든 캐릭터에 맞출 수 있습니다."
L["The ready check's tick, cross or question mark on each member's raid frame."] = "각 파티원의 공격대 창에 표시되는 전투 준비 확인의 체크, 가위표, 물음표."
L["The recap card, with the meter's whole run if you've one, else made up (Stop hides it)."] = "요약 카드. 측정기에 진행 전체가 있으면 그것으로, 없으면 지어낸 것으로('중지'로 숨김)."
L["The rest of its settings are on the Scripts page, under the steps they make: pick this camera there."] = "나머지 설정은 스크립트 페이지에서 그 설정이 만드는 단계 아래에 있습니다: 거기서 이 카메라를 고르세요."
L["The rule isn't finished. Finish it, or close with X or Escape to put back the rule it had."] = "규칙이 완성되지 않았습니다. 완성하거나, X나 Esc로 닫아 원래 규칙으로 되돌리세요."
L["The same for your personal health bar: it comes up with the first hit or heal you take."] = "개인 생명력 바도 마찬가지: 처음 받는 타격이나 치유와 함께 나타납니다."
L["The same for your personal resource display."] = "개인 자원 표시도 마찬가지입니다."
L["The same for your player frame: it comes up once your health or your power changes."] = "플레이어 프레임도 마찬가지: 생명력이나 자원이 변하면 나타납니다."
L["The same person doing the same again (buffing you again, another wave) brings up no card for the minutes below. Their other moments still do."] = "같은 사람이 같은 일을 다시 하면(다시 강화 효과를 걸거나 또 손을 흔들면) 아래 시간(분) 동안 카드를 띄우지 않습니다. 그 사람의 다른 순간은 여전히 띄웁니다."
L["The same place shows at most once every 90 seconds."] = "같은 장소는 90초에 최대 한 번 나옵니다."
L["The screen's edges close in as your health drops, with your theme's art (all the sections below)."] = "생명력이 떨어지면 화면 가장자리가 테마 그림(아래 모든 부분)과 함께 좁혀 옵니다."
L["The seconds left in the middle of the button while it cools down."] = "재사용 대기 중 버튼 가운데에 남은 초."
L["The seconds left on the Cooldown Manager's icons show only when the game's Show Numbers for Cooldowns (Options > Action Bars) is on. Unticked, the Cooldown Manager shows them as it likes."] = "재사용 대기시간 관리자 아이콘의 남은 초는 게임의 '재사용 대기시간 숫자 표시'(옵션 > 행동 단축바)가 켜져 있을 때만 보입니다. 해제하면 재사용 대기시간 관리자가 알아서 보여 줍니다."
L["The seconds left on the cast, at the bar's right end (in the same font). Hidden while the game keeps them secret, in some fights."] = "바 오른쪽 끝에 시전의 남은 초(같은 글꼴). 일부 전투에서 게임이 비밀로 하는 동안은 숨겨집니다."
L["The selection circle on the ground under your target. Hidden, your own setting is put back when the UI returns."] = "대상 아래 땅의 선택 원. 숨기면 UI가 돌아올 때 내 설정이 되돌아옵니다."
L["The settings below as they are while you're this role (your specialization's, or the one picked in the group finder)."] = "이 역할일 때 아래 설정(전문화의 역할, 또는 파티 찾기에서 고른 역할)."
L["The settings below for every role that uses the default settings."] = "기본 설정을 쓰는 모든 역할의 아래 설정."
L["The settings every frame has while its tab uses the default settings."] = "탭이 기본 설정을 쓰는 동안 모든 창에 적용되는 설정."
L["The settings every group has while its tab uses the default settings."] = "탭이 기본 설정을 쓰는 동안 모든 그룹에 적용되는 설정."
L["The settings every kind of cast bar has while its tab uses the default settings."] = "탭이 기본 설정을 쓰는 동안 모든 종류의 시전 바에 적용되는 설정."
L["The share of your health a hit has to take at once to count as big."] = "큰 타격으로 치려면 한 번에 깎아야 하는 생명력 비율."
L["The shield on casts that can't be interrupted"] = "차단할 수 없는 시전의 방패"
L["The shot to show and change."] = "보고 바꿀 샷."
L["The shot's name, as the Scenes page lists it."] = "장면 페이지 목록에 나오는 샷 이름."
L["The size of the bubble and the list as a whole (their words grow with them)."] = "말풍선과 목록 전체의 크기(글자도 함께 커짐)."
L["The size of the game's shadow maps: bigger gives crisper shadow edges, smaller saves frame rate. Players found nothing more above 2048, so 4096 may look the same. Needs shadows on in the game's menu."] = "게임 그림자 맵의 크기: 크면 그림자 가장자리가 선명해지고, 작으면 프레임을 아낍니다. 2048을 넘으면 플레이어들이 차이를 못 느꼈으니 4096도 같아 보일 수 있습니다. 게임 메뉴에서 그림자를 켜야 합니다."
L["The slow drift the camera keeps up between moves. 0: none."] = "움직임 사이에 카메라가 계속하는 느린 흐름. 0: 없음."
L["The small lines over and under the words, bigger or smaller than they come (100%: as they come, by the words' size)."] = "글자 위아래의 작은 줄을 원래보다 크게 또는 작게(100%: 원래대로, 글자 크기 기준)."
L["The small lines' font, over and under the words."] = "글자 위아래 작은 줄의 글꼴."
L["The spark at the fill's end"] = "채움 끝의 불꽃"
L["The spell's icon"] = "주문 아이콘"
L["The spell's name"] = "주문 이름"
L["The spell's name and seconds left in a color of your own."] = "주문 이름과 남은 초를 직접 고른 색으로."
L["The strength, reach and brightness of it all, the shadow, the heartbeat and big hits."] = "전체의 강도, 범위, 밝기, 그림자, 심장 박동, 큰 타격."
L["The style this card starts from. Settings you give it on the Style tab go over it."] = "이 카드가 시작하는 스타일. 스타일 탭에서 준 설정이 그 위에 덮입니다."
L["The style this card starts from. The settings below that you change go over it, as its own."] = "이 카드가 시작하는 스타일. 아래에서 바꾼 설정이 카드 고유 값으로 그 위에 덮입니다."
L["The style this tab shows and sets."] = "이 탭이 보여 주고 정하는 스타일."
L["The styles the cards start from. Change one here and every card that starts from it changes too, except where a card has a setting of its own (its Style page, from its row on the Events tab). Changes play at once in the preview."] = "카드가 시작하는 스타일. 여기서 하나를 바꾸면 그것으로 시작하는 모든 카드가 함께 바뀝니다. 단, 카드가 자체 설정을 가진 곳(이벤트 탭의 줄에서 여는 그 카드의 스타일 페이지)은 제외합니다. 바꾸면 미리 보기에서 곧바로 재생됩니다."
L["The styles the cards start from: change one for every card using it."] = "카드가 시작하는 스타일: 하나를 바꾸면 그것을 쓰는 모든 카드에 적용됩니다."
L["The swing round to face you is timed to get there this long before the cast ends. More is a quicker swing."] = "나를 마주 보도록 도는 것이 시전이 끝나기 이만큼 전에 도착하도록 시간을 맞춥니다. 클수록 빨리 돕니다."
L["The swing stops with the speaker this far from the middle of the screen, on their side, so you stay in the shot beside them. 0 aims right at them (you may block the view)."] = "말하는 사람이 화면 가운데에서 그쪽으로 이만큼 떨어진 곳에서 회전이 멈춰서 나도 그 옆에 함께 잡힙니다. 0이면 정면으로 겨눕니다(내가 시야를 가릴 수 있음)."
L["The tail curls the other way, as if seen in a mirror."] = "거울에 비친 듯 꼬리가 반대로 휩니다."
L["The tail pointing at who's talking"] = "말하는 사람을 가리키는 꼬리"
L["The talent calculator can't read your talents here."] = "여기서는 특성 계산기가 특성을 읽을 수 없습니다."
L["The theme's art soaking in from the edges as they close in (blood, smoke, a glow...)."] = "가장자리가 좁혀 올 때 스며드는 테마 그림(피, 연기, 빛...)."
L["The theme's art: smoke billowing in, a soft glow, blood (or water) soaking in, frost on glass, fur... None: no art, its sparks and shadow only."] = "테마 그림: 밀려드는 연기, 은은한 빛, 스며드는 피(또는 물), 유리의 성에, 털... 없음: 그림 없이 불꽃과 그림자만."
L["The theme's color"] = "테마 색"
L["The theme's color: the effect turned grey and tinted to match your theme. Its own colors: as the game draws it."] = "테마 색: 효과를 회색으로 바꿔 테마에 맞게 물들임. 고유 색: 게임이 그리는 그대로."
L["The theme's own art and its sparks."] = "테마 고유 그림과 불꽃."
L["The theme's sparks (motes, stars, lightning) and the haze drifting over the edges."] = "테마의 불꽃(티끌, 별, 번개)과 가장자리 위를 떠도는 안개."
L["The theme's swirl turning over the screen, closing in from past the corners as they close in, and turning quicker the weaker you are."] = "화면 위를 도는 테마 소용돌이. 가장자리가 좁혀 올 때 모서리 밖에서 함께 좁혀 오며, 약해질수록 빨리 돕니다."
L["The theme's swirl: up to two layers turning over the screen."] = "테마 소용돌이: 화면 위를 도는 최대 두 겹."
L["The thing on the ground you pick up or use for a quest objective glows gold, with the quest mark over it, in CineMode and out. One at a time: the one in front of you that your interact key would use, up to 20 yards away. Only while a quest in this zone still needs something picked up or used. Then it turns on the game's soft targeting for things to interact with (Interact key on keyboard and mouse too); your own settings come back after."] = "퀘스트 목표로 줍거나 쓰는 땅 위의 사물이 CineMode 안팎에서 금빛으로 빛나고 위에 퀘스트 표시가 붙습니다. 한 번에 하나: 앞에 있으며 상호작용 키가 쓸 것, 20m까지. 이 지역의 퀘스트가 아직 무언가를 줍거나 써야 할 때만. 그동안 상호작용 대상에 대한 게임의 소프트 대상 지정을 켭니다(키보드와 마우스의 상호작용 키도). 나중에 내 설정이 돌아옵니다."
L["The time of day this rule is for. Click to switch."] = "이 규칙이 적용되는 시간대. 클릭해서 바꿉니다."
L["The tint's strength slowly wanders up and down over a few minutes, so a still scene feels a little more alive: how far either way, as a share of the strength. Paused while the Style tab is open. Off: it stays put."] = "색조 강도가 몇 분에 걸쳐 천천히 오르내려서 정지된 장면이 조금 더 살아 있는 느낌이 납니다: 강도 대비 위아래 폭. 스타일 탭이 열려 있는 동안은 멈춥니다. 끄면: 고정됩니다."
L["The tooltip fades out over the first 3 seconds of the cast too, and comes back as the cast ends or is cancelled."] = "시전의 처음 3초 동안 툴팁도 흐려지고, 시전이 끝나거나 취소되면 돌아옵니다."
L["The tooltip's edge. In its color: a unit's class or reaction color, an item's quality. Custom: its thickness and color under it."] = "툴팁 가장자리. 그 색으로: 유닛의 직업이나 반응 색, 아이템 품질. 사용자 지정: 아래에서 두께와 색."
L["The tracking button on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "미니맵 머리글의 추적 버튼. 해제하면 미니맵이 떠 있어도 CineMode에서 숨깁니다. 미니맵에 마우스를 올리면 지도와 함께 나타납니다."
L["The two colors after it."] = "그 뒤의 두 색."
L["The unit under the mouse. Hovering a unit itself works too, not just its plate. Just the marks over the plate: the others hang in the air where its plate is hidden."] = "마우스 아래 유닛. 이름표뿐 아니라 유닛 자체에 마우스를 올려도 됩니다. 이름표 위 표시만: 다른 것은 이름표가 숨겨진 자리의 허공에 떠 있습니다."
L["The unit's health bar in its mark's color."] = "유닛의 생명력 바를 표시 색으로."
L["The unit's name in its mark's color, on its plate or shown alone."] = "유닛 이름을 표시 색으로, 이름표 위에서나 이름만 보일 때나."
L["The wheel's icon, as it shows on the master wheel. Click to pick another."] = "마스터 휠에 보이는 휠 아이콘. 클릭해서 다른 것을 고르세요."
L["The whole card at once."] = "카드 전체를 한 번에."
L["The whole plate's opacity while this row fits it, whether it has a mark or not. CineMode's own fade comes on top."] = "이 줄이 맞는 동안 표시 여부와 관계없이 이름표 전체의 불투명도. CineMode 자체 흐리기가 그 위에 더해집니다."
L["The whole run"] = "진행 전체"
L["The window shows this many items at once, newest at the top: four down, the rest in a second column. When another drops, the oldest goes."] = "창이 한 번에 이만큼의 아이템을 보여 줍니다(최신이 맨 위): 아래로 네 개, 나머지는 두 번째 열. 새로 나오면 가장 오래된 것이 빠집니다."
L["The window sits to the right of the game's roll frames, level with their top, instead of under them, so a long list of drops doesn't push it down the screen. It stays there once you've chosen."] = "창이 게임 주사위 창 아래가 아니라 오른쪽, 위쪽에 맞춰 놓여서 전리품 목록이 길어도 화면 아래로 밀려나지 않습니다. 고른 뒤에도 거기 머뭅니다."
L["The windows you have open open again after."] = "열려 있던 창이 그 뒤 다시 열립니다."
L["The words before it all (on a card, over the zone name)."] = "모든 것 앞의 글자(카드에서 지역 이름 위)."
L["The words come in a letter at a time from the left, as if typed; the other lines rise in after. A secret name opens as Reveal instead."] = "글자가 타자 치듯 왼쪽부터 한 글자씩 나오고, 다른 줄이 뒤따라 떠오릅니다. 비밀 이름은 대신 '드러내기'로 나옵니다."
L["The words coming out of a fight. Empty: none, just the rest of the card."] = "전투를 마칠 때의 글자. 비우면: 없음, 카드의 나머지만."
L["The words going into a fight. Empty: none, just the rest of the card."] = "전투에 들어갈 때의 글자. 비우면: 없음, 카드의 나머지만."
L["The words open out from their middle (or from their side, in the lower third or at a bar's side), the line drawing out with them; the other lines rise in after."] = "글자가 가운데에서(하단 자막이나 바 옆에서는 한쪽에서) 펼쳐지며 선이 함께 그어지고, 다른 줄이 뒤따라 떠오릅니다."
L["The words over a line that draws out, as a new scene starts."] = "새 장면이 시작될 때처럼, 그어지는 선 위의 글자."
L["The words the banner shows with Custom picked. Left blank: YOU DIED."] = "'사용자 지정'을 골랐을 때 배너에 나오는 글자. 비우면: YOU DIED."
L["The words the banner shows with Custom picked. Left blank: the first ones in the list."] = "'사용자 지정'을 골랐을 때 배너에 나오는 글자. 비우면: 목록의 첫 번째 것."
L["The words under both names as the duel starts. Empty: none."] = "결투가 시작될 때 두 이름 아래의 글자. 비우면: 없음."
L["The words' color; the lines with them in a lighter shade."] = "글자 색. 함께 있는 선은 더 밝은 색조."
L["The words' font. Russian, Korean or Chinese text keeps the game's, so its letters show."] = "글자 글꼴. 러시아어, 한국어, 중국어 글자는 글자가 보이도록 게임 글꼴을 유지합니다."
L["The words' height next to the bar's: they grow and shrink with your letterbox. (With no letterbox up, a bar as tall as your letterbox's comes in for the card.)"] = "바 대비 글자 높이: 레터박스와 함께 커지고 작아집니다. (레터박스가 없으면 레터박스만 한 바가 카드를 위해 들어옵니다.)"
L["The words' size, next to their own."] = "원래 대비 글자 크기."
L["The world dims and goes cold and gray-blue, with a heavy vignette closing in from the edges. It clears when you release or come back."] = "세상이 어두워지고 차가운 회청색이 되며, 짙은 비네트가 가장자리에서 좁혀 옵니다. 영혼을 해방하거나 되살아나면 걷힙니다."
L["The zone you spent the most time in (on a card, its big name)."] = "가장 오래 머문 지역(카드에서 큰 이름)."
L["The zone's name on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "미니맵 머리글의 지역 이름. 해제하면 미니맵이 떠 있어도 CineMode에서 숨깁니다. 미니맵에 마우스를 올리면 지도와 함께 나타납니다."
L["Their class's color, as the plates draw them."] = "이름표가 그리듯 직업 색."
L["Their color."] = "그 색."
L["Their face"] = "얼굴"
L["Their face."] = "얼굴."
L["Their name"] = "이름"
L["Their numbers, once the rolls are shown"] = "주사위가 공개되면 숫자"
L["Their portrait on the card (their class's icon when they're out of sight)."] = "카드에 그 사람의 초상화(보이지 않으면 직업 아이콘)."
L["Theme colors"] = "테마 색"
L["Theme's pick"] = "테마 선택"
L["Theme's sparks"] = "테마 불꽃"
L["Theme's speed"] = "테마 속도"
L["Theme's swirl"] = "테마 소용돌이"
L["Theme's throb"] = "테마 고동"
L["Theme:"] = "테마:"
L["These bubbles show everywhere, in fights and out. (The other columns then have nothing to add.)"] = "이 말풍선은 전투 안팎 어디서나 보입니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["These cast bars' settings: Default's until you untick Use default settings."] = "이 시전 바의 설정: '기본 설정 사용'을 해제하기 전까지 기본 값."
L["These settings back on General."] = "이 설정을 일반 값으로 되돌리기."
L["These settings back on the Visions hub's Style page."] = "이 설정을 Visions 허브의 스타일 페이지 값으로 되돌리기."
L["Thick"] = "두껍게"
L["Thick + shadow"] = "두껍게 + 그림자"
L["Thickness"] = "두께"
L["Thin"] = "가늘게"
L["Thin bars with a thin gold line along their edge."] = "가장자리를 따라 가는 금색 선이 있는 얇은 바."
L["Thin black bars that slide in with the UI's fade (the defaults)."] = "UI 흐리기와 함께 미끄러져 들어오는 가는 검은 바(기본값)."
L["Thin, borderless bars that barely show over the world."] = "세상 위에서 거의 보이지 않는 얇고 테두리 없는 바."
L["This Edit Mode layout's action bars come on or off after a reload. Reload now?"] = "이 편집 모드 레이아웃의 행동 단축바는 다시 불러온 뒤 켜지거나 꺼집니다. 지금 다시 불러오시겠습니까?"
L["This Vision's shared settings back on Visions Style."] = "이 Vision의 공유 설정을 Visions 스타일 값으로 되돌리기."
L["This boss only"] = "이 우두머리만"
L["This boss only: everyone starts at 0 as a boss is pulled, and when it dies it's back to the whole run. The whole run: the meter's Overall. Each fight: every pull starts at 0."] = "이 우두머리만: 우두머리를 풀링하면 모두 0에서 시작하고, 처치하면 진행 전체로 돌아갑니다. 진행 전체: 측정기의 '전체'. 각 전투: 풀링할 때마다 0에서 시작."
L["This camera can't be tested now: Cinematic or the camera is off (Camera Triggers page), or you're moving, flying or in a fight."] = "지금은 이 카메라를 시험할 수 없습니다: Cinematic이나 카메라가 꺼져 있거나(카메라 발동 조건 페이지), 움직이거나 비행 중이거나 전투 중입니다."
L["This card's rules as they come."] = "이 카드의 원래 규칙."
L["This client has no damage meter."] = "이 클라이언트에는 피해량 측정기가 없습니다."
L["This frame's settings: Default's until you untick Use default settings."] = "이 창의 설정: '기본 설정 사용'을 해제하기 전까지 기본 값."
L["This game version has none of these settings."] = "이 게임 버전에는 이 설정이 하나도 없습니다."
L["This group's settings: Default's until you untick Use default settings."] = "이 그룹의 설정: '기본 설정 사용'을 해제하기 전까지 기본 값."
L["This is from a newer Cinematic: update it to add this one."] = "더 새로운 Cinematic에서 온 것입니다: 이것을 추가하려면 업데이트하세요."
L["This page's shared settings back on General."] = "이 페이지의 공유 설정을 일반 값으로 되돌리기."
L["This row fits everywhere. The rest of the row keeps its ticks for when you untick this."] = "이 줄은 어디서나 맞습니다. 이 항목을 해제할 때를 위해 줄의 나머지 체크는 그대로 유지됩니다."
L["This row's camera may start anywhere. The rest of the row keeps its ticks for when you untick this."] = "이 줄의 카메라는 어디서나 시작할 수 있습니다. 이 항목을 해제할 때를 위해 줄의 나머지 체크는 그대로 유지됩니다."
L["This row's camera waits until the Calm Timer (CineMode page) has run out after a fight."] = "이 줄의 카메라는 전투 후 진정 타이머(CineMode 페이지)가 끝날 때까지 기다립니다."
L["This row: just the enemies among them."] = "이 줄: 그중 적만."
L["This row: just the friendly ones among them."] = "이 줄: 그중 아군만."
L["This row: just the neutral ones among them."] = "이 줄: 그중 중립만."
L["This row: just these among them: %s."] = "이 줄: 그중 다음만: %s."
L["This row: just those about that far from you. 11 and 28 yards are the game's interact distances; 40 asks a 40-yard spell on your action bars (harmful for enemies, helpful for friends), and with none there the row fits no unit past 28 yards."] = "이 줄: 나에게서 대략 그만큼 떨어진 것만. 11m와 28m는 게임의 상호작용 거리이고, 40m는 행동 단축바의 40m 주문으로 확인합니다(적에게는 해로운 주문, 아군에게는 이로운 주문). 없으면 그 줄은 28m 밖의 유닛에는 맞지 않습니다."
L["This sound's volume, next to the others."] = "다른 소리 대비 이 소리의 음량."
L["This swing bar isn't in use"] = "이 평타 바는 쓰이지 않음"
L["This tab's rules as they come: a sound as any other fight starts and one as it ends."] = "이 탭의 원래 규칙: 다른 전투가 시작될 때 소리 하나, 끝날 때 하나."
L["This tab's rules as they come: a war horn as a boss is pulled; a kill and a wipe, no sound yet."] = "이 탭의 원래 규칙: 우두머리를 풀링할 때 전쟁 뿔피리. 처치와 전멸은 아직 소리 없음."
L["This tab's rules as they come: one for each time of day, a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "이 탭의 원래 규칙: 시간대마다 하나씩, 새벽에 수탉, 아침에 말, 한낮에 진영의 종, 저녁에 개구리, 해 질 녘에 올빼미, 밤에 늑대."
L["This theme as a line of text to send a friend, who adds it with Import theme in their theme menu. Only the theme (edge, colors, sparks, heartbeat), not this page's other settings."] = "친구에게 보낼 한 줄의 문자로 된 이 테마. 친구는 테마 메뉴의 '테마 가져오기'로 추가합니다. 테마(가장자리, 색, 불꽃, 심장 박동)만이며 이 페이지의 다른 설정은 아닙니다."
L["This theme's heartbeat, next to the beats a minute above (slower for a creeping theme)."] = "위의 분당 박동 수 대비 이 테마의 심장 박동(서서히 다가오는 테마는 더 느리게)."
L["Threat glow"] = "위협 수준 빛"
L["Throb"] = "고동"
L["Tick Enemy, Neutral or Friendly for just those of them; all of them: any."] = "그중 일부만 원하면 적, 중립, 아군에 체크하세요. 전부: 모두."
L["Ticked, \"#2 of 5\". Unticked, just \"#2\"."] = "체크하면 \"#2 / 5\". 해제하면 \"#2\"만."
L["Ticked, a bright spark at the edge of the filled part."] = "체크하면 채운 부분 끝에 밝은 불꽃."
L["Ticked, a crown pops in as you take #1."] = "체크하면 1위가 될 때 왕관이 톡 나타납니다."
L["Ticked, how you did on that boss as it dies."] = "체크하면 우두머리를 처치할 때 그 우두머리에서의 성과."
L["Ticked, how you did on the whole run as it's done."] = "체크하면 진행이 끝날 때 진행 전체의 성과."
L["Ticked, only while the UI is faded."] = "체크하면 UI가 흐려져 있을 때만."
L["Ticked, supported addons you install later start with Always ticked: shown the whole time in CineMode. Unticked, they start hidden, except as the other columns say. (Frames you add yourself start faded either way.)"] = "체크하면 나중에 설치하는 지원 애드온은 '항상'에 체크된 채 시작합니다: CineMode 내내 표시됨. 해제하면 다른 열 설정에 따를 때 말고는 숨겨진 채 시작합니다. (직접 추가하는 창은 어느 쪽이든 흐린 채 시작합니다.)"
L["Ticked, the bars glide to each new value instead of jumping."] = "체크하면 바가 새 값으로 튀지 않고 부드럽게 미끄러집니다."
L["Ticked, the name of the one you race, in their class's color."] = "체크하면 경쟁하는 사람의 이름을 직업 색으로."
L["Ticked, the wind comes and goes in gusts every few seconds. Unticked, it blows steadily."] = "체크하면 몇 초마다 바람이 돌풍으로 불었다 그쳤다 합니다. 해제하면 꾸준히 붑니다."
L["Ticked, the wind drops while you're in a fight."] = "체크하면 전투 중에는 바람이 잦아듭니다."
L["Ticked, your damage (or healing) so far."] = "체크하면 지금까지의 피해량(또는 치유량)."
L["On the rows:"] = "행에 표시:"
L["Ticked, each player's name on their row."] = "체크하면 각 플레이어의 이름을 해당 행에 표시합니다."
L["Ticked, your place over it (#2)."] = "체크하면 그 위에 내 순위(#2)."
L["Ticked: party frames shown raid-style (the game's Use Raid-Style Party Frames, in Edit Mode) fade as the Raid tab's rows say. Untick it to give them rows of their own."] = "체크하면: 공격대 방식으로 표시되는 파티 창(편집 모드의 게임 설정 '공격대 형태 파티 창 사용')이 공격대 탭의 줄대로 흐려집니다. 따로 줄을 주려면 해제하세요."
L["Ticked: the spells with no cooldown you haven't set yourself go by what they cost, until you set their group's mode: When ready with Resources if they spend a resource you build up (like Maelstrom), else When it procs (like Lightning Bolt). Spells with a cooldown or charges go by their group's setting. It also turns on Flash for Utility Cooldowns, until you set that group's Flash. Unticked: every spell you haven't set yourself goes by its group's setting."] = "체크하면: 직접 정하지 않은 재사용 대기시간 없는 주문은 그룹 모드를 정하기 전까지 비용에 따라 갑니다: 모아 두는 자원을 쓰면(소용돌이처럼) 자원과 함께 '준비됐을 때', 그 밖에는 '발동할 때'(번개 화살처럼). 재사용 대기시간이나 충전이 있는 주문은 그룹 설정을 따릅니다. 또한 보조 재사용 대기시간 그룹의 번쩍임을 직접 정하기 전까지 그것을 켭니다. 해제하면: 직접 정하지 않은 모든 주문이 그룹 설정을 따릅니다."
L["Ticked: these cast bars look as the Default tab says. Unticked: as the settings below say (they start as Default's, and are kept while it's ticked)."] = "체크하면: 이 시전 바는 기본 탭대로 보입니다. 해제하면: 아래 설정대로(기본 값으로 시작하며, 체크된 동안 보관됨)."
L["Ticked: these cast bars take this page's look (the Default tab's, or this tab's own). Unticked: they keep the game's own. Their size stays the game's (yours is sized in Edit Mode)."] = "체크하면: 이 시전 바는 이 페이지의 모양(기본 탭 것 또는 이 탭 고유)을 따릅니다. 해제하면: 게임 자체 모양을 유지합니다. 크기는 게임 것을 유지합니다(내 바 크기는 편집 모드에서 정함)."
L["Ticked: this card shows where its row says. Unticked: never."] = "체크하면: 이 카드는 줄이 정한 곳에 나옵니다. 해제하면: 나오지 않습니다."
L["Ticked: this frame looks as the Default tab says. Unticked: as the settings below say (they start as Default's, and are kept while it's ticked)."] = "체크하면: 이 창은 기본 탭대로 보입니다. 해제하면: 아래 설정대로(기본 값으로 시작하며, 체크된 동안 보관됨)."
L["Ticked: this frame shows the parts the Target grid says. Untick it to give the frame choices of its own."] = "체크하면: 이 창은 대상 격자가 정한 부분을 보여 줍니다. 창에 따로 선택지를 주려면 해제하세요."
L["Ticked: this group looks as the Default tab says. Unticked: as the settings below say (they start as Default's, and are kept while it's ticked)."] = "체크하면: 이 그룹은 기본 탭대로 보입니다. 해제하면: 아래 설정대로(기본 값으로 시작하며, 체크된 동안 보관됨)."
L["Ticked: while no letterbox is up, the card shows in the lower third. Unticked: a bar of its own comes in for it."] = "체크하면: 레터박스가 없을 때 카드가 하단 자막 위치에 나옵니다. 해제하면: 카드를 위한 바가 따로 들어옵니다."
L["Ticked: while you're this role, Heal Vision goes by the Default tab. Unticked: by the settings on this tab."] = "체크하면: 이 역할일 때 Heal Vision이 기본 탭을 따릅니다. 해제하면: 이 탭의 설정을 따릅니다."
L["Tied: rolling again"] = "동점: 다시 굴리는 중"
L["Tighter rows and smaller text, for raids."] = "공격대용으로 더 촘촘한 줄과 작은 글자."
L["Tilt %s° down over %s s"] = "%s° 아래로 기울이기, %s초 동안"
L["Tilt %s° up over %s s"] = "%s° 위로 기울이기, %s초 동안"
L["Tilt 0° (no tilt)"] = "0° 기울이기 (기울이지 않음)"
L["Tilt down to"] = "아래로 기울이는 각도"
L["Tilt to %s° give or take %s/%s over %s s"] = "%s°로 기울이기, 오차 %s/%s, %s초 동안"
L["Tilt up to"] = "위로 기울이는 각도"
L["Time"] = "시간"
L["Time left"] = "남은 시간"
L["Time played"] = "플레이 시간"
L["Times the addon's busy parts as you play, for as long as is picked beside it. It starts when you close the settings (or right away, with Start now), and the results show here. Click it again to stop."] = "플레이하는 동안 옆에서 고른 시간만큼 애드온의 바쁜 부분의 시간을 잽니다. 설정을 닫으면(또는 '지금 시작'이면 바로) 시작하고 결과는 여기 나옵니다. 다시 클릭하면 멈춥니다."
L["Timing and extras"] = "시간과 추가 요소"
L["Title card"] = "타이틀 카드"
L["To fade something else, use the Find frames tab: search by name, pick frames by hovering, or let Smart Find look for them. Or hover over a frame and type |cffffd100/cine add|r. Frames you add are listed under their addon, with the same columns; the X takes one off the list."] = "다른 것을 흐리게 하려면 창 찾기 탭을 쓰세요: 이름으로 검색하거나, 마우스를 올려 창을 고르거나, 스마트 찾기에 맡기세요. 또는 창 위에 마우스를 올리고 |cffffd100/cine add|r를 입력하세요. 추가한 창은 해당 애드온 아래 같은 열로 나열되며, X로 목록에서 뺍니다."
L["Today, %s"] = "오늘, %s"
L["Together (empty: pick it and add steps)"] = "함께 (비어 있음: 골라서 단계를 추가하세요)"
L["Together: these at once"] = "함께: 다음을 동시에"
