L["Toggle Heal Vision"] = "Heal Vision 켜기/끄기"
L["Toggle Quest Vision"] = "Quest Vision 켜기/끄기"
L["Toggle Roll Vision"] = "Roll Vision 켜기/끄기"
L["Toggle Vitals Vision"] = "Vitals Vision 켜기/끄기"
L["Tooltip"] = "툴팁"
L["Tooltip: %s"] = "툴팁: %s"
L["Tooltips show all through CineMode. (The other columns then have nothing to add.)"] = "CineMode 내내 툴팁을 표시합니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["Top"] = "위"
L["Top letterbox bar"] = "위 레터박스 바"
L["Top speed in the middle of a sweep. At 6°/sec with 50% ease, a 30° sweep takes 10 seconds."] = "한 바퀴 도는 도중의 최고 속도. 6°/초에 가감속 50%면 30°를 도는 데 10초 걸립니다."
L["Tracked Bars"] = "추적 바"
L["Tracked Buffs"] = "추적 강화 효과"
L["Tracked buffs and bars: Always, In combat, Out of combat or Hidden (the game keeps your buffs secret in fights, so they go by that alone). Each group has a tab of its own."] = "추적 강화 효과와 바: 항상, 전투 중, 비전투 중 또는 숨김(게임이 전투 중 강화 효과를 비밀로 하므로 그것만 기준으로 함). 그룹마다 탭이 있습니다."
L["Tracking a quest"] = "퀘스트 추적 중"
