L["Trying %s. Close this window to keep it."] = "%s 체험 중. 유지하려면 이 창을 닫으세요."
L["Turn %d°   Tilt %d°   Zoom %s yd   %s / %s s"] = "회전 %d°   기울기 %d°   확대/축소 %sm   %s / %s초"
L["Turn %s° toward where you clicked them over %s s"] = "클릭한 쪽으로 %s° 돌기, %s초 동안"
L["Turn each move"] = "움직일 때마다 회전"
L["Turn it on to see and change its settings."] = "설정을 보고 바꾸려면 켜세요."
L["Turn off"] = "끄기"
L["Turn on"] = "켜기"
L["Turn on %s"] = "%s 켜기"
L["Turn on the Profiler page and record a while of your usual play (a fight too), then click Copy report there and send it with your bug report."] = "프로파일러 페이지를 켜고 평소 플레이(전투 포함)를 잠시 기록한 뒤, 거기서 '보고서 복사'를 클릭해 버그 보고와 함께 보내 주세요."
L["Turn on the loot roll window first."] = "먼저 전리품 주사위 창을 켜세요."
L["Turn around behind you over %s s"] = "뒤쪽으로 돌기, %s초 동안"
L["Turn to face you before the cast ends"] = "시전이 끝나기 전에 나를 마주 보도록 돌기"
L["Turn to face you over %s s"] = "나를 마주 보도록 돌기, %s초 동안"
L["Turning it on, and which rolls it shows."] = "켜기, 그리고 어떤 주사위를 보여 줄지."
L["Turning it on, the moments a card shows for and each one's emotes."] = "켜기, 카드를 띄울 순간과 각 순간의 감정 표현."
L["Turning it on, when it shows and what it counts."] = "켜기, 언제 보일지와 무엇을 셀지."
L["Turns Duel Vision on or off."] = "Duel Vision을 켜거나 끕니다."
L["Turns Heal Vision on or off (its Enable Page switch), in a fight too: off, the party and raid frames all show again."] = "전투 중에도 Heal Vision을 켜거나 끕니다('페이지 사용' 스위치). 끄면 파티와 공격대 창이 다시 모두 보입니다."
L["Turns Quest Vision on or off (its Enable Page switch)."] = "Quest Vision을 켜거나 끕니다('페이지 사용' 스위치)."
L["Turns Roll Vision on or off."] = "Roll Vision을 켜거나 끕니다."
L["Turns Vitals Vision on or off (its Enable Page switch)."] = "Vitals Vision을 켜거나 끕니다('페이지 사용' 스위치)."
L["Turns a minute at full (half that as it starts). Below 0: the other way."] = "가득 찼을 때 분당 회전 수(시작할 때는 그 절반). 0 미만: 반대 방향."
L["Turns the Tooltips page on or off (its Enable Page switch)."] = "툴팁 페이지를 켜거나 끕니다('페이지 사용' 스위치)."
L["Turns the visual effects on or off (their Enable Visual Effects switch): the letterbox, tint, vignette, weather and the rest."] = "화면 효과를 켜거나 끕니다('화면 효과 사용' 스위치): 레터박스, 색조, 비네트, 날씨 등."
L["Turns the whole Atmosphere hub on or off at once: the letterbox, tint, time of day, zone tints, vignette, inn glow, weather, depth of field, Graphics+ and Audio. Each keeps its own settings for when you turn this back on."] = "분위기 허브 전체를 한 번에 켜거나 끕니다: 레터박스, 색조, 시간대, 지역 색조, 비네트, 여관 불빛, 날씨, 피사계 심도, 그래픽+, 소리. 다시 켤 때를 위해 각자의 설정은 유지됩니다."
L["Turns this group on or off. While it's off it's kept as it is, but its frames come up on their own (or with their other groups), and its events don't bring it up."] = "이 그룹을 켜거나 끕니다. 꺼져 있는 동안 그대로 보관되지만, 그 창은 스스로(또는 다른 그룹과 함께) 나타나고, 이벤트가 그룹을 띄우지 않습니다."
L["Twinkling stars"] = "반짝이는 별"
L["Type"] = "종류"
L["Type part of a frame's name or of the addon that made it. Hover over a match to see it marked on screen, click it to put it on the list below, to add. Only other addons' frames that aren't faded yet are listed."] = "창 이름이나 그 창을 만든 애드온 이름의 일부를 입력하세요. 결과에 마우스를 올리면 화면에 표시되고, 클릭하면 아래 목록에 넣어 추가할 수 있습니다. 아직 흐리게 하지 않은 다른 애드온의 창만 나열됩니다."
L["Type part of a name to see the icons it matches: any spell, the items you carry and wear, mounts, or an icon's file name such as INV_Misc_Bag_07. Enter picks the first."] = "이름의 일부를 입력하면 맞는 아이콘이 보입니다: 아무 주문, 가지고 있거나 착용한 아이템, 탈것, 또는 INV_Misc_Bag_07 같은 아이콘 파일 이름. Enter는 첫 번째 것을 고릅니다."
L["Type part of an icon's name to see the ones it matches, such as bang, turnin or speak. Enter picks the first."] = "아이콘 이름의 일부(bang, turnin, speak 등)를 입력하면 맞는 아이콘이 보입니다. Enter는 첫 번째 것을 고릅니다."
L["Typewriter"] = "타자기"
L["Typing brings up the chat window any time. (The other columns then have nothing to add.)"] = "입력하면 언제든 대화창이 나타납니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["Ultra immersive"] = "완전 몰입"
L["Uncommon and up"] = "고급 등급 이상"
L["Under it"] = "그 아래"
L["Under the indicator, while you cast: your mana's numbers on the bar show what you'll have once the cast is done, paler. The amount and the percent, whichever the game shows there (its Status Text setting); with the game's numbers off, the amount in the middle of the bar."] = "시전하는 동안 표시기 아래: 바 위의 마나 숫자가 시전이 끝난 뒤 남을 양을 옅게 보여 줍니다. 게임이 거기 보여 주는 것(상태 문자 설정)에 따라 양과 백분율. 게임 숫자가 꺼져 있으면 바 가운데에 양."
L["Under the name, what the game says of the place: Contested Territory, Sanctuary, Alliance or Horde Territory..."] = "이름 아래, 게임이 알려 주는 장소 정보: 분쟁 지역, 안전 지대, 얼라이언스 또는 호드 영토..."
L["Under the tooltip, where the game puts it."] = "툴팁 아래, 게임이 놓는 자리."
L["Under the words: their color, lighter. Over them: a pale gray."] = "글자 아래: 글자 색을 더 밝게. 위: 옅은 회색."
