L["Warsong Gulch"] = "전쟁노래 협곡"
L["What blows: Auto picks your class and spec's (the same as Vitals Vision's theme), or pick any, or plain wind or motes of light."] = "무엇이 불지: 자동은 내 직업과 전문화의 것(Vitals Vision 테마와 같음)을 고르거나, 아무것이나, 또는 그냥 바람이나 빛 티끌을 고르세요."
L["What cuts the pattern to an edge, so it stays around the screen's sides. None: the pattern over all of the screen (an edge already, like the red one, needs none)."] = "무늬를 가장자리 모양으로 잘라 화면 둘레에 머물게 하는 것. 없음: 화면 전체에 무늬(빨간 것처럼 이미 가장자리인 것은 필요 없음)."
L["What each row of frames is doing right now, and the settings behind it. Click a row for all its reasons. To ask about one frame on the screen, pick it in game (or type /cine why)."] = "각 창 줄이 지금 무엇을 하는지와 그 뒤의 설정. 줄을 클릭하면 모든 이유가 나옵니다. 화면의 창 하나에 대해 물으려면 게임에서 고르세요(또는 /cine why 입력)."
L["What happens when you move the camera, a fight starts, you walk, you zoom or its trigger ends; and its edge haze and Stop button while it runs."] = "카메라를 움직이거나, 전투가 시작되거나, 걷거나, 확대/축소하거나, 발동 조건이 끝날 때 어떻게 할지. 그리고 도는 동안의 가장자리 흐림과 중지 버튼."
L["What it counts"] = "세는 것"
L["What it is: motes of light floating up, stars twinkling, lightning flickering, gas drifting in over the edges, motes spiraling in the way the swirl turns, or stars circling the middle. None: not there."] = "종류: 떠오르는 빛 티끌, 반짝이는 별, 일렁이는 번개, 가장자리로 스며드는 가스, 소용돌이 방향으로 나선을 그리며 들어오는 티끌, 또는 가운데를 도는 별. 없음: 없음."
L["What it is: wispy spiral arms (added on as light), clouds wound into a whirlpool, or a portal's glowing rim closing in around you. None: not there."] = "종류: 가느다란 나선 팔(빛으로 더해짐), 소용돌이로 감긴 구름, 또는 나를 둘러싸며 좁혀 오는 차원문의 빛나는 테두리. 없음: 없음."
L["What picking it does: a slash command, such as /rw Pull in 10, or several, a line each (anything a macro can do). The game cuts a line at 255 letters."] = "고르면 하는 일: /rw Pull in 10 같은 슬래시 명령, 또는 여러 개를 한 줄에 하나씩(매크로가 할 수 있는 모든 것). 게임은 한 줄을 255자에서 자릅니다."
L["What shows of mobs and NPCs you still need for a quest objective (a mob to kill, an NPC to talk to), whatever the Nameplates page's grids say; tick any. Nameplate: their whole nameplates. Name: their names, on their nameplates. Quest mark: a golden ! added to the nameplate or name shown, else the ! alone. These three in CineMode, in fights and out, and need the Nameplates page enabled; once the objective is done, they fade with the rest. Unit frame: the same mark beside your target frame's health bar while your target is one of them, in CineMode and out. None ticked: as the Nameplates page's settings say."] = "이름표 페이지 격자 설정과 관계없이, 퀘스트 목표에 아직 필요한 몹과 NPC(잡아야 할 몹, 대화할 NPC)에 무엇을 보일지. 원하는 대로 체크하세요. 이름표: 이름표 전체. 이름: 이름표 위의 이름. 퀘스트 표시: 보이는 이름표나 이름에 붙는 황금색 !, 없으면 !만. 이 셋은 CineMode에서 전투 안팎으로 적용되며 이름표 페이지를 사용해야 합니다. 목표를 마치면 나머지와 함께 흐려집니다. 유닛 프레임: 대상이 그중 하나일 때 대상 프레임 생명력 바 옆에 같은 표시, CineMode 안팎으로. 아무것도 체크하지 않으면: 이름표 페이지 설정대로."
L["What the addon's timers measured: ms a frame, and its share of the frame."] = "애드온 타이머가 잰 것: 프레임당 ms와 프레임 중 비율."
L["What the bubble and card do while the camera moves: the quest camera's swing, zoom and turn (its drift is Hold the camera still's), or you turning it. Follow: they stay over the NPC's nameplate, sliding with it. Fade out: they fade out, and back in over the NPC once it's still. Dim: they fade down, still readable. Wait to the side: they stay still where Default would put them, and fade over to the NPC once the camera's still."] = "카메라가 움직이는 동안 말풍선과 카드가 하는 일: 퀘스트 카메라의 회전, 확대/축소, 방향 전환(흐름은 '카메라 고정'의 것), 또는 내가 돌릴 때. 따라가기: NPC 이름표 위에 머물며 함께 미끄러짐. 흐리게 사라지기: 사라졌다가 NPC가 멈추면 그 위에 다시 나타남. 흐릿하게: 읽을 수 있을 만큼 흐려짐. 옆에서 대기: 기본 위치에 가만히 있다가 카메라가 멈추면 NPC 쪽으로 흐려지며 옮겨 감."
L["What the game measured for Cinematic meanwhile, the timers' parts and all the rest."] = "그동안 게임이 Cinematic에 대해 잰 것: 타이머 부분과 나머지 전부."
L["What this card does if it comes while you're in a fight, or in the 5 seconds after one."] = "전투 중이나 전투 후 5초 안에 이 카드가 나올 때 하는 일."
L["What this card plays as it shows."] = "이 카드가 나타날 때 재생하는 것."
L["What's new"] = "새 소식"
L["What's new in Cinematic, newest first. Show me opens the page a feature is on. Every change, fixes too, is on the All changes page."] = "Cinematic의 새 소식, 최신순. '보여 주기'는 그 기능이 있는 페이지를 엽니다. 수정을 포함한 모든 변경 사항은 '모든 변경 사항' 페이지에 있습니다."
L["What's this card's alone: when it shows, the lines with its name, its words. How it looks: the Style tab."] = "이 카드만의 것: 언제 보일지, 이름이 든 줄, 글자. 모양: 스타일 탭."
L["Whatever style that event starts from."] = "그 이벤트가 시작하는 스타일이 무엇이든."
L["Wheels"] = "휠"
L["Wheels on it"] = "들어 있는 휠"
L["When"] = "적용 조건"
L["When all a quest giver has to offer or take in is daily or weekly quests, the camera stays as it is."] = "퀘스트 NPC가 주거나 받는 것이 일일이나 주간 퀘스트뿐이면 카메라는 그대로 있습니다."
L["When it blows"] = "부는 때"
L["When it ends"] = "끝날 때"
L["When it ends: nothing, it stays where it is"] = "끝날 때: 아무것도 안 함, 그 자리에 머묾"
L["When it procs"] = "발동할 때"
L["When it's ready"] = "준비됐을 때"
L["When its camera stops. Moving always stops it too, as it does every camera that runs while you stand still. It ends: when the trigger that started it ends (the cast, the buff, leaving the place)."] = "카메라가 멈출 때. 가만히 서 있을 때 도는 모든 카메라처럼 움직이면 항상 멈춥니다. 끝날 때: 시작한 발동 조건이 끝날 때(시전, 강화 효과, 장소를 떠남)."
L["When ready"] = "준비됐을 때"
L["When someone does something for you or at you, a small card shows who it was, with a few emotes to answer in one click. It waits out fights and fades away by itself. Pick the moments and their emotes below. When it shows: the Settings tab. Its style and look: the Look tab."] = "누군가 나를 위해 또는 나에게 무언가를 하면 누구였는지 작은 카드에 보여 주고, 한 번의 클릭으로 답할 감정 표현 몇 개를 붙입니다. 전투가 끝나기를 기다리며 저절로 사라집니다. 아래에서 순간과 감정 표현을 고르세요. 언제 보일지: 설정 탭. 스타일과 모양: 모양 탭."
L["When someone talks out of sight (behind you, say), the camera turns around, a full turn at most, until their chat bubble shows, then frames them. If they're nowhere to be seen, it ends up back where it was."] = "누군가 시야 밖(예: 뒤)에서 말하면 카메라가 최대 한 바퀴까지 돌아 그 사람의 말풍선이 보이면 그를 화면에 담습니다. 어디에도 보이지 않으면 원래 자리로 돌아옵니다."
L["When the cards show and for how long. The moments and their emotes: the Vision tab. Its look: the Look tab."] = "카드가 언제 얼마나 보일지. 순간과 감정 표현: Vision 탭. 모양: 모양 탭."
L["When the cards show, and for how long."] = "카드가 언제 얼마나 보일지."
L["When the edges close in, the health bars and how fast."] = "가장자리가 좁혀 올 때, 생명력 바, 속도."
L["When the release popup offers a way to come back yourself (a soulstone, Reincarnation, an ankh...), there's no death camera: you keep your own view to pick your moment."] = "영혼 해방 창에 스스로 되살아날 방법(영혼석, 윤회, 십자가...)이 있으면 죽음 카메라 없이 내 시점을 유지해 때를 고를 수 있습니다."
L["When this buff's icon or bar shows. The game keeps your buffs secret in fights, so these go by whether you're in one."] = "이 강화 효과의 아이콘이나 바가 언제 보일지. 게임이 전투 중 강화 효과를 비밀로 하므로 전투 중인지 여부로만 판단합니다."
L["When this group works: any time, only out of combat or only in combat. Click to change. The rest of the time its frames come up on their own (or with their other groups), and its events don't bring it up."] = "이 그룹이 작동하는 때: 언제든, 비전투 중에만, 전투 중에만. 클릭해서 바꿉니다. 그 밖의 때에는 그 창이 스스로(또는 다른 그룹과 함께) 나타나고, 이벤트가 그룹을 띄우지 않습니다."
L["When this rule fits. Click to write it in the rule editor; empty: any fight."] = "이 규칙이 맞는 때. 클릭하면 규칙 편집기에서 씁니다. 비우면: 모든 전투."
L["When this rule fits. Click to write it in the rule editor; empty: any time."] = "이 규칙이 맞는 때. 클릭하면 규칙 편집기에서 씁니다. 비우면: 언제든."
L["When this spell's icon shows in the Cooldown Manager."] = "재사용 대기시간 관리자에서 이 주문 아이콘이 언제 보일지."
L["When you die, the camera turns slowly round your body until you release or are resurrected. CineMode stays on (straight away), with the release button (and any soulstone or Reincarnation button) still showing."] = "죽으면 영혼을 해방하거나 부활할 때까지 카메라가 시체 주위를 천천히 돕니다. CineMode는 (곧바로) 유지되며, 영혼 해방 버튼(과 영혼석이나 윤회 버튼)은 계속 보입니다."
L["When you turn left or right, the camera doesn't snap round with you: it carries on as it was (sway and all) until you stop turning, then glides gently around to your new facing, easing in and out. Dragging with either mouse button hands the camera straight back to you."] = "좌우로 돌 때 카메라가 함께 홱 돌지 않고, 돌기를 멈출 때까지 (흔들림까지) 그대로 이어 가다가 새 방향으로 부드럽게 가감속하며 돌아갑니다. 마우스 버튼으로 끌면 곧바로 카메라를 돌려받습니다."
L["Where"] = "장소"
L["Where and when each effect shows in CineMode. Always: everywhere. Combat: In combat, Calm Timer (after a fight, till it's run out), Out of combat (the rest of the time), In a camera mode (flights, AFK, cozy and the rest). Location: the places. Nothing ticked: it's off."] = "CineMode에서 각 효과가 어디서 언제 보일지. 항상: 어디서나. 전투: 전투 중, 진정 타이머(전투 후 끝날 때까지), 비전투 중(나머지 시간), 카메라 모드 중(비행, 자리 비움, 아늑함 등). 장소: 장소들. 아무것도 체크하지 않으면: 꺼짐."
L["Where and when each kind of bubble shows. Always: everywhere. Nothing ticked: never."] = "말풍선 종류별로 어디서 언제 보일지. 항상: 어디서나. 아무것도 체크하지 않으면: 보이지 않음."
L["Where and when music can play in CineMode; anywhere else it fades out (your own game music too) and back in after. Always: everywhere. Out of combat: back once the Calm Timer has run out after a fight (with Calm Timer too: as soon as the fight ends)."] = "CineMode에서 음악이 재생될 수 있는 곳과 때. 그 밖에서는 (내 게임 음악도) 흐려졌다가 나중에 돌아옵니다. 항상: 어디서나. 비전투 중: 전투 후 진정 타이머가 끝나면 돌아옴(진정 타이머도 함께면: 전투가 끝나자마자)."
L["Where chat bubbles show. How they look: the Style hub's Chat bubbles page."] = "말풍선이 보이는 곳. 모양: 스타일 허브의 말풍선 페이지."
L["Where in the letterbox bar the card sits."] = "레터박스 바 안에서 카드의 위치."
L["Where it comes when other scenes are on at the same time: the first one on in this order plays. Going AFK while doing an emote is the AFK scene, say."] = "다른 장면이 동시에 켜질 때의 순서: 이 순서에서 먼저 켜진 것이 재생됩니다. 예를 들어 감정 표현 중에 자리를 비우면 자리 비움 장면입니다."
L["Where the bubble goes. Over the head: over the NPC's nameplate, following them on the screen. Default: above the middle of the screen, or wherever you drag it. Opposite clicked: wherever you drag it, but when you clicked the NPC on that half of the screen, at the same spot on the other half (they stand where you clicked, so that half is clearer), the quest card beside it. With nobody to stand over or no click (a quest from an item, or the interact key), it goes where Default would."] = "말풍선 위치. 머리 위: NPC 이름표 위, 화면에서 NPC를 따라감. 기본: 화면 가운데 위, 또는 끌어 둔 곳. 클릭 반대편: 끌어 둔 곳이지만, 그 화면 절반에서 NPC를 클릭했다면 반대쪽 절반의 같은 자리(NPC는 클릭한 곳에 서 있으니 그쪽 절반이 더 트임)에, 퀘스트 카드를 옆에 두고. 위에 설 사람이 없거나 클릭하지 않았으면(아이템으로 받은 퀘스트, 상호작용 키) 기본 위치로 갑니다."
L["Where the card shows: in the middle of the screen, in a letterbox bar or in the lower third. (A banner goes across the middle.)"] = "카드가 보이는 곳: 화면 가운데, 레터박스 바 안, 또는 하단 자막 위치. (배너는 가운데를 가로지릅니다.)"
L["Where the tail sits along the bubble: 0 at its left end, 50 in the middle, 100 at its right end."] = "말풍선을 따라 꼬리 위치: 0은 왼쪽 끝, 50은 가운데, 100은 오른쪽 끝."
L["Where the zoom ends as the cast does, if you're further out. Closer already, it stays where it is. Arriving, the camera is back at your own distance."] = "내가 더 멀리 있으면 시전이 끝날 때 확대가 끝나는 거리. 이미 더 가까우면 그대로 둡니다. 도착하면 카메라가 내 거리로 돌아옵니다."
L["Where this row's camera may start (Grouped: in a party or raid). Anywhere else the next row of its trigger is tried, and with none the camera doesn't start (or stops if it's running). For flights, Cities means taking off from one, and Open world taking off anywhere else."] = "이 줄의 카메라가 시작해도 되는 곳(파티 중: 파티나 공격대에 있을 때). 그 밖의 곳에서는 발동 조건의 다음 줄을 시도하고, 없으면 카메라가 시작하지 않습니다(돌고 있으면 멈춤). 비행에서 '도시'는 도시에서 출발할 때, '필드'는 그 밖의 곳에서 출발할 때입니다."
L["Where to find Cinematic outside the game. Click a link and press Ctrl+C to copy it, then paste it into your browser."] = "게임 밖에서 Cinematic을 찾는 곳. 링크를 클릭하고 Ctrl+C로 복사한 뒤 브라우저에 붙여 넣으세요."
L["Where your damage came from"] = "내 피해의 출처"
L["Where your extra ability button goes (the extra abilities frame's place in Edit Mode), a big button with the item the nearest tracked quest gives you to use, the one in the quest tracker. Click it or press its key (Keybinds page). Shows near the quest's area, beside the game's own button when that's up. It can't show, hide or move in a fight: it stays as it was until the fight ends."] = "추가 행동 버튼 자리(편집 모드의 추가 능력 창 자리)에, 가장 가까운 추적 퀘스트에서 쓰라고 주는 아이템(퀘스트 추적기에 있는 것)의 큰 버튼. 클릭하거나 그 키를 누르세요(단축키 페이지). 퀘스트 지역 근처에서 보이며, 게임 자체 버튼이 떠 있으면 그 옆에 나옵니다. 전투 중에는 보이거나 숨거나 움직일 수 없습니다: 전투가 끝날 때까지 그대로입니다."
L["Where your healing came from"] = "내 치유의 출처"
L["Whether this row's camera may start in a fight (unticked, one running stops when a fight starts), and whether it waits for things to calm down after one."] = "이 줄의 카메라가 전투 중에 시작해도 되는지(해제하면 돌던 카메라는 전투가 시작되면 멈춤), 그리고 전투 후 잠잠해지기를 기다릴지."
L["Whether you won or lost (or someone fled) as the duel ends."] = "결투가 끝날 때 이겼는지 졌는지(또는 누가 도망쳤는지)."
L["Which Visions follow this page. One with a setting of its own shows which; Use Visions Style puts them all back on this page. The name opens its page."] = "이 페이지를 따르는 Vision. 자체 설정이 있는 것은 무엇인지 보여 줍니다. 'Visions 스타일 사용'은 모두 이 페이지로 되돌립니다. 이름을 누르면 그 페이지가 열립니다."
L["Which addons the table shows: tick the ones to compare, or All addons for every one."] = "표에 보일 애드온: 비교할 것에 체크하거나, 전부라면 '모든 애드온'."
L["Which edge they start from."] = "시작하는 가장자리."
L["Which items"] = "대상 아이템"
L["Which of them, ticks. Aggro: who the enemy's attacking, You or Not you (someone friendly: a group member, a pet or another player), and their role, Tank, Healer or DPS (no role set counts as DPS; a pet only with all three ticked). Units: any of Normal NPC, Elite NPC (elite, rare elite and bosses), Players, and Minions (their pets, totems and guardians); all four, any unit."] = "그중 무엇인지, 체크. 위협: 적이 누구를 공격하는지, 나 또는 내가 아님(아군: 파티원, 소환수, 다른 플레이어), 그리고 그 역할, 방어 전담, 치유 전담, 공격 전담(역할이 없으면 공격 전담으로 침. 소환수는 셋 다 체크했을 때만). 유닛: 일반 NPC, 정예 NPC(정예, 희귀 정예, 우두머리), 플레이어, 하수인(소환수, 토템, 수호물) 중 아무것. 넷 다면 모든 유닛."
L["Which one. Key bindings are set in the game's Key Bindings, under Cinematic."] = "어느 것인지. 단축키는 게임의 단축키 설정에서 Cinematic 아래에 정합니다."
L["Which pages follow General. A page with a setting of its own shows which; Use General puts them all back on General. The page's name opens it."] = "일반을 따르는 페이지. 자체 설정이 있는 페이지는 무엇인지 보여 줍니다. '일반 사용'은 모두 일반으로 되돌립니다. 페이지 이름을 누르면 열립니다."
L["Which parts of the player, target, focus and pet frames show. Keeping a frame up, always or in fights, is on the Game Frames page; your own while you recover, on the Resource Display page."] = "플레이어, 대상, 주시 대상, 소환수 프레임의 어떤 부분을 보일지. 창을 항상 또는 전투 중에 띄워 두는 것은 게임 창 페이지에, 회복하는 동안 내 창은 자원 표시 페이지에 있습니다."
L["Which parts of the unit frames show, CineMode or not: your own frame and your pet's, and the target, focus and target of target frames. Pick a frame's tab to see its grid: the focus and target of target go as the target's grid says until you untick Same as target. Untick parts to keep just the bars. The frame art is the portrait ring, the name box and the bars' borders: the game draws them as one picture. Icons are the rest Zzz, the group leader's crown, role and quest icons, and the raid marker (skull, moon...) on the target and focus frames. Auras are the buffs and debuffs on the target and focus frames. Hit text is the damage and healing numbers on your and your pet's portraits. Threat is the threat percentage and aggro glow on the target and focus frames, for NPCs you can fight."] = "CineMode 여부와 관계없이 유닛 프레임의 어떤 부분을 보일지: 내 프레임과 소환수 프레임, 그리고 대상, 주시 대상, 대상의 대상 프레임. 프레임 탭을 고르면 격자가 보입니다: 주시 대상과 대상의 대상은 '대상과 같게'를 해제하기 전까지 대상 격자를 따릅니다. 바만 남기려면 부분을 해제하세요. 틀 그림은 초상화 고리, 이름 상자, 바 테두리이며 게임이 한 그림으로 그립니다. 아이콘은 휴식 Zzz, 파티장 왕관, 역할과 퀘스트 아이콘, 대상과 주시 대상 프레임의 공격대 징표(해골, 달...)입니다. 효과는 대상과 주시 대상 프레임의 강화/약화 효과입니다. 타격 문자는 내 초상화와 소환수 초상화의 피해와 치유 숫자입니다. 위협 수준은 싸울 수 있는 NPC에 대한 대상과 주시 대상 프레임의 위협 수준 백분율과 위협 빛입니다."
L["Which side the camera comes round to. On your right, the quest giver is on the right of the screen. (The game doesn't tell addons where the quest giver stands, or what's around you, so it can't pick the open side.) \"Where you clicked them\": the side of the screen you clicked the quest giver on, and the camera turns toward it; talking to them with a key instead, the side is picked at random."] = "카메라가 돌아갈 쪽. 내 오른쪽이면 퀘스트 NPC가 화면 오른쪽에 옵니다. (게임은 퀘스트 NPC가 어디 서 있는지, 주위에 무엇이 있는지 애드온에 알려 주지 않아서 트인 쪽을 고를 수 없습니다.) \"클릭한 쪽\": 퀘스트 NPC를 클릭한 화면 쪽으로, 카메라가 그쪽으로 돕니다. 대신 키로 대화하면 무작위로 고릅니다."
L["Which way the lines line up: their left edges, their middles or their right edges. By where it's moved to: by which side of the screen the Move box is on."] = "줄 정렬: 왼쪽 끝, 가운데, 오른쪽 끝. 옮겨 간 곳 기준: '이동' 상자가 화면 어느 쪽에 있는지에 따라."
L["While CineMode is on, the camera comes alive when something happens: an emote, a campfire, going AFK, your Hearthstone, fishing, a flight, a quest giver, auto-walking or dying. The Scenes page says what starts which camera; the Scripts page has each camera's steps and settings. Moving by hand cancels them all, and everything goes back to normal when the UI returns."] = "CineMode가 켜져 있는 동안 무언가 일어나면 카메라가 살아납니다: 감정 표현, 모닥불, 자리 비움, 귀환석, 낚시, 비행, 퀘스트 NPC, 자동 걷기, 죽음. 무엇이 어떤 카메라를 시작하는지는 장면 페이지에, 각 카메라의 단계와 설정은 스크립트 페이지에 있습니다. 직접 움직이면 모두 취소되고, UI가 돌아오면 모든 것이 평소대로 돌아갑니다."
L["While a quest is tracked in the quest tracker, the minimap stays up during CineMode, so you can see where to go. Untrack your quests and it fades again."] = "퀘스트 추적기에서 퀘스트를 추적하는 동안 CineMode에서도 미니맵이 남아 있어 어디로 갈지 볼 수 있습니다. 추적을 풀면 다시 흐려집니다."
L["While a vision is doing something (Heal Vision fading frames, a duel being watched, the roll window up...), the minimap button glows in its color. Its menu and tooltip list that vision, and the camera running, with a link to its page."] = "Vision이 무언가 하는 동안(Heal Vision이 창을 흐리게 함, 결투를 지켜봄, 주사위 창이 떠 있음...) 미니맵 버튼이 그 색으로 빛납니다. 메뉴와 툴팁에 그 Vision과 돌고 있는 카메라가 그 페이지 링크와 함께 나옵니다."
L["While it runs"] = "도는 동안"
L["While recharging"] = "충전 중"
L["While the UI is faded, a new message briefly shows just the chat window it arrived in. Choose which messages below, and what of the window comes up with them under Chat window."] = "UI가 흐려져 있는 동안 새 메시지가 오면 그 메시지가 도착한 대화창만 잠깐 보여 줍니다. 아래에서 어떤 메시지인지, 그리고 '대화창'에서 창의 무엇을 함께 띄울지 고르세요."
L["While the camera moves"] = "카메라가 움직이는 동안"
L["While you cast a spell that costs mana, the mana it will take shows as a pale stretch at the end of your mana: what's left after the cast is the fill to its left."] = "마나를 쓰는 주문을 시전하는 동안 소모될 마나가 마나 끝의 옅은 구간으로 보입니다: 시전 뒤 남는 양은 그 왼쪽 채움입니다."
L["While you're auto-running (the auto-run key). Pressing forward or back, or stopping, ends it; stop and stand, and the AFK camera takes over. Auto-walking counts as RP walk instead."] = "자동 달리기(자동 달리기 키) 중. 앞이나 뒤로 누르거나 멈추면 끝나며, 멈춰 서 있으면 자리 비움 카메라가 넘겨받습니다. 자동 걷기는 대신 RP 걷기로 칩니다."
L["While you're auto-walking (auto-run in walk mode). Walking by hand cancels the camera, as all moving by hand does. Stop and stand, and the AFK camera takes over. Walking is recognized from your speed; /cine walk shows what the addon thinks."] = "자동 걷기(걷기 모드에서 자동 달리기) 중. 직접 걸으면 다른 직접 움직임처럼 카메라가 취소됩니다. 멈춰 서 있으면 자리 비움 카메라가 넘겨받습니다. 걷기는 속도로 알아보며, /cine walk로 애드온이 어떻게 판단하는지 봅니다."
L["While you're in a duel (or have asked for one, or been asked), other players' duels nearby don't show. Off: they show all through yours."] = "결투 중(또는 신청했거나 신청받은 동안)에는 근처 다른 플레이어의 결투를 보여 주지 않습니다. 끄면: 내 결투 내내 보입니다."
L["While you're moving the card waits, and shows once you stop (if that's within 20 seconds)."] = "움직이는 동안 카드는 기다렸다가 멈추면 나타납니다(20초 안이라면)."
L["Whirlpool clouds"] = "소용돌이 구름"
L["White"] = "흰색"
L["Who it's cast at"] = "시전 대상"
L["Whole run"] = "진행 전체"
L["Why Is It Showing?"] = "왜 보이나요?"
L["Why is it showing?"] = "왜 보이나요?"
L["Width"] = "너비"
L["Width:"] = "너비:"
L["Wind Guide"] = "바람 안내"
L["Wind Guide can't tell which way you face here."] = "여기서는 바람 안내가 바라보는 방향을 알 수 없습니다."
L["Wind Guide test done."] = "바람 안내 시험 완료."
L["Wind Guide test: blowing toward your waypoint."] = "바람 안내 시험: 목적지를 향해 부는 중."
L["Wind Guide test: no waypoint, so a pretend one off to your right."] = "바람 안내 시험: 목적지가 없어서 오른쪽에 가짜 목적지."
L["Windows the game opens on the left (quest log, group finder, profession book and the like) open on the right instead, near the top, leaving your character in view. Two open at once still sit side by side. Narrow ones on their own (character, trade, merchant, mail) and quest givers' windows open a little in from the left edge instead, halfway up the screen, leaving the world and the quest giver in view. A window another addon has moved stays where that addon put it."] = "게임이 왼쪽에 여는 창(퀘스트 목록, 파티 찾기, 전문 기술 책 등)을 대신 오른쪽 위쪽에 열어 캐릭터가 보이게 합니다. 두 개를 함께 열면 여전히 나란히 놓입니다. 혼자 열리는 좁은 창(캐릭터, 거래, 상인, 우편)과 퀘스트 NPC 창은 대신 왼쪽 가장자리에서 조금 안쪽, 화면 중간 높이에 열려 세상과 퀘스트 NPC가 보이게 합니다. 다른 애드온이 옮긴 창은 그 애드온이 둔 곳에 머뭅니다."
L["Winner"] = "승자"
L["Winner color:"] = "승자 색:"
L["Winner's row:"] = "승자 줄:"
L["Wipe"] = "전멸"
L["With \"Start in CineMode\" off (Cinematic's main page), its camera starting brings CineMode on, and it ends with the camera."] = "'CineMode로 시작'이 꺼져 있으면(Cinematic 메인 페이지), 이 카메라가 시작될 때 CineMode가 켜지고 카메라와 함께 끝납니다."
L["With Custom dialogue frames unticked, it places the game's own gossip and quest window instead. Default: wherever you drag it (else where the game puts it). Opposite clicked: the same, but on the other half of the screen from where you clicked the NPC. Over the head isn't for a whole window (it would cover them): the game's window is left where the game puts it."] = "'사용자 대화 창'을 해제하면 대신 게임 자체 대화와 퀘스트 창의 위치를 정합니다. 기본: 끌어 둔 곳(없으면 게임이 두는 곳). 클릭 반대편: 같지만 NPC를 클릭한 곳의 반대쪽 화면 절반에. 머리 위는 창 전체에는 맞지 않으므로(NPC를 가림) 게임 창은 게임이 두는 곳에 그대로 둡니다."
L["With Legacy"] = "레거시 포함"
L["With Smart set ticked, until you set a bar's mode, its spells with no cooldown go by what they cost; unticked, by their group's setting."] = "'스마트 설정'에 체크하면 바의 모드를 정하기 전까지 재사용 대기시간 없는 주문은 비용에 따라 가고, 해제하면 그룹 설정을 따릅니다."
L["With no one talking for this long, the camera turns back and zooms back out. Moving ends it at once, leaving the camera where it is."] = "아무도 이만큼 말하지 않으면 카메라가 돌아와 다시 축소합니다. 움직이면 곧바로 끝나며 카메라는 그 자리에 남습니다."
L["With the UI"] = "UI와 함께"
L["Within 11 yards"] = "11m 안"
L["Within 28 yards"] = "28m 안"
L["Within 40 yards"] = "40m 안"
L["Won"] = "획득"
L["Won:"] = "획득:"
L["Words"] = "글자"
L["Words in Russian, Korean or Chinese keep the game's font, so their letters show."] = "러시아어, 한국어, 중국어 글자는 글자가 보이도록 게임 글꼴을 유지합니다."
L["Words that mark a campfire when they're in the name its tooltip shows (\"Campfire\"), separated by commas. Use words in your game language."] = "툴팁에 보이는 이름에 들어 있으면 모닥불로 보는 단어(\"모닥불\"), 쉼표로 구분. 게임 언어의 단어를 쓰세요."
L["Words:"] = "글자:"
L["Worst"] = "최악"
L["Worst frame"] = "최악의 프레임"
L["Worst ms"] = "최악 ms"
L["X"] = "X"
L["XP bars"] = "경험치 바"
L["Y"] = "Y"
L["YOU DIED"] = "YOU DIED"
L["YOU DIED, \"wasted\" (a picture) or words of your own."] = "YOU DIED, \"wasted\"(그림), 또는 직접 정한 글자."
L["Yesterday, %s"] = "어제, %s"
L["You"] = "나"
L["You challenge"] = "내가 신청"
L["You challenge them to a duel"] = "내가 결투를 신청함"
L["You come back to life"] = "되살아남"
L["You earn an achievement"] = "업적 달성"
L["You fled from %s"] = "%s에게서 도망침"
L["You have %d scenes of your own already: delete one to make another."] = "이미 나만의 장면이 %d개 있습니다: 하나를 지워야 새로 만들 수 있습니다."
L["You have %d shots already: delete one to make another."] = "이미 샷이 %d개 있습니다: 하나를 지워야 새로 만들 수 있습니다."
L["You have %d wheels already: delete one to make another."] = "이미 휠이 %d개 있습니다: 하나를 지워야 새로 만들 수 있습니다."
L["You have 30 camera scripts already: delete one to add another."] = "이미 카메라 스크립트가 30개 있습니다: 하나를 지워야 새로 추가할 수 있습니다."
L["You haven't made a wheel yet."] = "아직 휠을 만들지 않았습니다."
L["You leave"] = "떠남"
L["You level up"] = "레벨 업"
L["You move"] = "움직임"
L["You press its key again"] = "그 키를 다시 누름"
L["You set it to always show (Custom frames, Addon Frames page)"] = "항상 표시하도록 설정함(애드온 창 페이지의 사용자 지정 창)"
L["You turn in a quest"] = "퀘스트 완료 보고"
L["You were holding the key that shows tooltips"] = "툴팁을 보여 주는 키를 누르고 있었음"
L["You're challenged"] = "결투 신청받음"
L["You're not on the meter"] = "측정기에 내가 없음"
L["You're not on the meter yet"] = "아직 측정기에 내가 없음"
L["You're typing in chat"] = "대화창에 입력 중"
L["Your camera"] = "내 카메라"
L["Your cast bar fades out over the first 3 seconds of the cast, so you see it start, then the portal closing in is its progress. Other casts show it as usual."] = "시전의 처음 3초 동안 시전 바가 흐려져 시작은 보이고, 그다음 좁혀 오는 차원문이 진행 상황이 됩니다. 다른 시전은 평소처럼 보입니다."
L["Your character looks around as the camera starts turning, as if they'd spotted something. Players nearby see the emote in chat. Fly-bys you start count too."] = "카메라가 돌기 시작할 때 캐릭터가 무언가를 발견한 듯 주위를 둘러봅니다. 근처 플레이어는 대화창에서 감정 표현을 봅니다. 직접 시작한 플라이바이도 해당됩니다."
L["Your class"] = "내 직업"
L["Your class's color, whether you lead or chase."] = "앞서든 쫓든 내 직업 색."
L["Your class's color."] = "내 직업 색."
L["Your face on your dot, their class icon on theirs."] = "내 점에는 내 얼굴, 상대 점에는 그 직업 아이콘."
L["Your focus."] = "주시 대상."
L["Your frame stays up while you recover"] = "회복하는 동안 내 창 유지"
L["Your gear is damaged (durability alert)"] = "장비 손상(내구도 경고)"
L["Your group"] = "내 파티"
L["Your group kills a boss"] = "파티가 우두머리를 처치함"
L["Your health at a glance, without the portrait: as it drops, the screen's edges close in, with your theme's art soaking in from them (blood, smoke, a glow in its color), a heartbeat that quickens as you weaken and a flash on big hits. Auto picks a theme for your class and spec. The death screen takes over if you die."] = "초상화 없이 한눈에 보는 생명력: 줄어들면 화면 가장자리가 좁혀 오고, 테마 그림(피, 연기, 그 색의 빛)이 스며들며, 약해질수록 빨라지는 심장 박동과 큰 타격의 번쩍임이 더해집니다. 자동은 직업과 전문화에 맞는 테마를 고릅니다. 죽으면 죽음 화면이 넘겨받습니다."
L["Your health falls in hits in the preview, and on the screen as the Vitals Vision page's Test says. Close the settings to see it all."] = "미리 보기에서, 그리고 Vitals Vision 페이지의 '시험'대로 화면에서 생명력이 타격마다 줄어듭니다. 전체를 보려면 설정을 닫으세요."
L["Your health the edges are all the way in at (under Starts)."] = "가장자리가 끝까지 들어오는 생명력('시작' 아래)."
L["Your health the edges start creeping in below."] = "가장자리가 스며들기 시작하는 생명력(이 아래에서)."
L["Your health this bar is fully up at (under Starts)."] = "이 바가 완전히 보이는 생명력('시작' 아래)."
L["Your health this bar starts fading in below."] = "이 바가 나타나기 시작하는 생명력(이 아래에서)."
L["Your icons on it"] = "들어 있는 내 아이콘"
L["Your mana under your character when it isn't your power (Elemental Shaman, Shadow Priest...): once it's on, on the Resource Display page."] = "주 자원이 마나가 아닐 때(정기 주술사, 암흑 사제...) 캐릭터 아래의 마나: 켜면 자원 표시 페이지에."
L["Your own"] = "직접 고름"
