L["Your party uses raid-style frames (Edit Mode's party frames setting): they follow the Raid frames page, not this tab."] = "파티가 공격대 방식 창(편집 모드의 파티 창 설정)을 씁니다: 이 탭이 아니라 공격대 창 페이지를 따릅니다."
