-- Options.lua: Reset addon (Reset Settings, Reset EVERYTHING)
L["Reset Settings puts every setting back and keeps what you made: your own profiles, cameras, scripts, themes and backups. Reset EVERYTHING deletes all of it. Either reloads the UI."] = "설정 초기화는 모든 설정을 되돌리고 직접 만든 것은 남깁니다: 내 프로필, 카메라, 스크립트, 테마, 백업. 전부 초기화는 그것까지 모두 지웁니다. 어느 쪽이든 UI를 다시 불러옵니다."
L["Reset Cinematic?\n\nReset Settings: every setting goes back to how it was on install, and you start on the default profile. Nothing you made is deleted: your own profiles, cameras, scripts, themes, rules, wheels and backups stay, and so do flight times and what Cinematic has learned as you played.\n\nReset EVERYTHING: deletes all of it, as on a fresh install.\n\nEither way the UI reloads, and Cinematic's Edit Mode layouts are removed so your own comes back."] = "Cinematic을 초기화할까요?\n\n설정 초기화: 모든 설정이 설치 직후로 돌아가고 기본 프로필로 시작합니다. 직접 만든 것은 지워지지 않습니다: 내 프로필, 카메라, 스크립트, 테마, 규칙, 휠, 백업이 남고, 비행 시간과 플레이하며 Cinematic이 배운 것도 남습니다.\n\n전부 초기화: 새로 설치한 것처럼 모두 지웁니다.\n\n어느 쪽이든 UI를 다시 불러오고, Cinematic의 편집 모드 레이아웃을 지워 내 레이아웃이 돌아옵니다."
L["Delete everything in Cinematic? Your own profiles, cameras, scripts, themes, rules, wheels and backups are deleted for good, along with every setting. This can't be undone."] = "Cinematic의 모든 것을 지울까요? 내 프로필, 카메라, 스크립트, 테마, 규칙, 휠, 백업이 모든 설정과 함께 영구히 지워집니다. 되돌릴 수 없습니다."
L["Reset Settings"] = "설정 초기화"
L["Reset EVERYTHING"] = "전부 초기화"

