L["Over your shoulder wherever you are. (The other columns then have nothing to add.)"] = "어디에 있든 어깨 너머로. (그러면 다른 열은 더할 것이 없습니다.)"
L["Frames follow you"] = "프레임이 따라옴"
L["Your cast bar and Personal Resource Display slide over to where you are on the screen, and glide back as the camera goes behind you. Edit Mode still places them: this moves them from there."] = "시전 바와 개인 자원 표시가 화면에서 내 위치로 미끄러져 가고, 카메라가 뒤로 돌아가면 돌아옵니다. 위치는 여전히 편집 모드가 정하며, 이 기능은 거기서 옮깁니다."
L["Follow strength"] = "따라가는 정도"
L["How far they slide. Where you are on the screen is worked out from the camera, not read: if they land short of you or past you, turn this up or down."] = "얼마나 미끄러질지. 화면 속 내 위치는 읽는 것이 아니라 카메라로 계산합니다: 나보다 덜 가거나 지나치면 이 값을 올리거나 내리세요."
L["The camera sits over your shoulder, with you to one side of the screen."] = "카메라가 어깨 너머에 자리하고, 나는 화면 한쪽에 있습니다."
L["On: the camera moves over your shoulder. This uses one of Blizzard's experimental camera settings: the game shows its experimental camera warning (Accept keeps it working). The game's Keep Character Centered option (Accessibility) stops it, so that's turned off meanwhile. Off: your own settings come back."] = "켜짐: 카메라가 어깨 너머로 옮겨 갑니다. Blizzard의 실험적 카메라 설정 중 하나를 쓰므로, 게임이 실험적 카메라 경고를 띄웁니다(수락하면 계속 작동). 게임의 캐릭터 가운데 유지 옵션(접근성)이 이를 막으므로 그동안 꺼 둡니다. 꺼짐: 내 설정이 돌아옵니다."
L["Shoulder"] = "어깨"
L["Offset"] = "오프셋"
L["How far to the side the camera moves. About 1 is subtle; 1.5 to 2 is a strong over-the-shoulder look."] = "카메라가 옆으로 얼마나 이동할지. 1 정도는 은은하고, 1.5~2는 확실한 어깨 너머 시점입니다."
L["Right shoulder"] = "오른쪽 어깨"
L["Left shoulder"] = "왼쪽 어깨"
L["Which shoulder the camera looks over. The swap key below flips it."] = "카메라가 어느 어깨 너머로 볼지. 아래의 전환 키로 바꿉니다."
L["Swap shoulders key"] = "어깨 전환 키"
L["Not during Cinematic's cameras that frame you"] = "나를 담는 Cinematic 카메라 중에는 끔"
L["On a mount the camera stays straight behind you: a big mount's head fills the shot from the side."] = "탈것에 타면 카메라가 바로 뒤에 머뭅니다: 옆에서 보면 큰 탈것의 머리가 화면을 채웁니다."
L["While the standing-still, AFK, flight, fly-by or death camera runs, the camera goes back behind you, as their shots are built around you in the middle. It comes back as they end. The quest and chat cameras keep it."] = "정지, 자리 비움, 비행, 근접 비행, 죽음 카메라가 도는 동안에는 그 장면들이 나를 가운데 두고 짜여 있어 카메라가 다시 뒤로 갑니다. 끝나면 돌아옵니다. 퀘스트 카메라와 대화 카메라는 유지합니다."
L["Frames"] = "프레임"
L["Pause"] = "일시 정지"

-- TalkingHeads.lua (its option on the Quest Vision page)
L["Talking heads"] = "말하는 얼굴"
L["Hide repeated talking heads"] = "반복되는 말하는 얼굴 숨기기"
L["The game's talking head (the NPC portrait at the top of the screen, with their line and voice) closes at once when it's a line you've already seen. Daily and world quest lines come back every day, so you see them once; the story's lines play only once anyway. Each character remembers its own, ticked or not, so an alt still sees the story's."] = "게임의 말하는 얼굴(화면 위쪽의 NPC 초상화와 대사, 음성)이 이미 본 대사라면 바로 닫힙니다. 일일 퀘스트와 전역 퀘스트 대사는 매일 다시 나오므로 한 번만 보게 되고, 이야기 대사는 어차피 한 번만 나옵니다. 체크 여부와 상관없이 캐릭터마다 따로 기억하므로 부캐는 이야기 대사를 그대로 봅니다."

-- ProfileChoices.lua and Welcome.lua: profile choices
L["Fights and opening windows bring your UI back"] = "전투와 창 열기가 UI를 되돌림"
L["Most of the time"] = "대부분"
L["Between fights, and fights bring back less: no minimap, fewer group nameplates"] = "전투 사이에, 전투 중엔 덜 돌아옴: 미니맵 없음, 파티 이름표 적게"
L["Always show"] = "항상 표시"
L["Action bars (Classic group)"] = "행동 단축바 (클래식 그룹)"
L["Action bars (Retail group)"] = "행동 단축바 (정식 그룹)"
L["General and Trade too"] = "일반과 거래도"
L["Neither NPC speech nor public channels bring chat up"] = "NPC 대사도 공개 채널도 대화창을 띄우지 않음"
L["No NPC chatter; speech from behind you shows low on the screen"] = "NPC 잡담 없음; 뒤쪽 대사는 화면 아래에 표시"
L["A portal opens around you as you hearth or teleport"] = "귀환하거나 순간이동할 때 주위에 차원문이 열림"
L["A card shows who buffed you or emoted at you"] = "나에게 강화 효과나 감정 표현을 한 사람을 카드로 표시"
L["Your race with the top of the meter, in dungeons and raids"] = "던전과 공격대에서 미터기 선두와의 경쟁"
L["NPC speech brings chat up; public channels don't"] = "NPC 대사는 대화창을 띄우고, 공개 채널은 띄우지 않음"
L["NPC speech, and the General and Trade channels"] = "NPC 대사와 일반, 거래 채널"

-- CardMoments.lua, CardsPage.lua, FlightLine.lua: Flight departure
L["Click to target %s"] = "클릭하여 %s 대상 지정"
L["As a flight lands: where it took you, and how long the flight took."] = "비행이 착륙할 때: 어디로 데려왔는지와 비행 시간."
L["Flight departure"] = "비행 출발"
L["As a flight takes off: where it's taking you, and about how long it takes on a route you've flown before. With a line along the top or bottom of the screen filling up on the way, if you like."] = "비행이 이륙할 때: 어디로 가는지, 그리고 전에 날아 본 경로라면 대략 얼마나 걸리는지. 원하면 화면 위나 아래에 가는 동안 채워지는 선도 표시합니다."
L["Flying to"] = "비행 목적지"
L["First time on this route"] = "이 경로는 처음"
L["about %d min"] = "약 %d분"
L["%s flight"] = "%s 비행"
L["Progress line"] = "진행선"
L["Show a line as you fly"] = "비행 중 선 표시"
L["On a route you've flown before, a thin line along a letterbox bar (or that edge of the screen) fills up as you fly, with the time left at its end. It shows while your UI is faded, and goes a moment before you land. A route's first flight has none: it's timed as you fly it."] = "전에 날아 본 경로에서는 레터박스 띠(또는 그쪽 화면 가장자리)를 따라 얇은 선이 비행하는 동안 채워지고, 끝에 남은 시간이 표시됩니다. UI가 흐려진 동안 보이고, 착륙 직전에 사라집니다. 경로의 첫 비행에는 없습니다: 그 비행으로 시간을 잽니다."
L["Flight progress line"] = "비행 진행선"
L["Top bar"] = "위쪽 띠"
L["Only at the start and end"] = "시작과 끝에만"
L["The line shows for this long as the flight starts and before it lands, and is hidden in between: point the mouse at its place to see it. 0: it shows the whole way."] = "선은 비행 시작과 착륙 전에 이만큼 보이고 그 사이에는 숨겨집니다: 그 자리에 마우스를 올리면 보입니다. 0: 내내 보입니다."
L["Bottom bar"] = "아래쪽 띠"
L["The letterbox bar the line and its time go in (no letterbox up: that edge of the screen)."] = "선과 시간이 들어갈 레터박스 띠 (레터박스가 없으면 그쪽 화면 가장자리)."
L["Not on flights"] = "비행 중에는 안 함"
L["No Zone or Subzone card on a flight path: the places you fly over don't bring one after another, and the Flight departure and arrival cards say where you're going."] = "비행 경로에서는 지역/하위 지역 카드 없음: 지나가는 곳마다 카드가 연달아 나오지 않고, 비행 출발·도착 카드가 목적지를 알려 줍니다."
L["Minutes only"] = "분만"
L["\"2 min\", rounded up, then \"under a minute\"."] = "\"2분\", 올림, 그다음 \"1분 미만\"."
L["Minutes and seconds"] = "분과 초"
L["\"1:12\", counting down."] = "\"1:12\", 카운트다운."
L["Don't show"] = "표시 안 함"
L["Just the line."] = "선만."
L["Time left:"] = "남은 시간:"
L["The time left at the line's end."] = "선 끝에 표시할 남은 시간."
L["The Flight departure card's line is on: on a route you've flown before, it fills up as you fly"] = "비행 출발 카드의 선이 켜져 있습니다: 전에 날아 본 경로에서 비행하는 동안 채워집니다"
L["Where:"] = "위치:"

-- Options.lua: the CineMode page's Overview
L["Overview"] = "개요"
L["Everything CineMode can do, page by page, and whether each page is on."] = "CineMode가 할 수 있는 모든 것을 페이지별로, 각 페이지가 켜져 있는지와 함께."
L["How fast the UI fades, the Calm Timer, combat text and error messages."] = "UI가 흐려지는 속도, 진정 타이머, 전투 문자, 오류 메시지."
L["What fades in CineMode, and what brings it back."] = "CineMode에서 무엇이 흐려지고 무엇이 되돌리는지."
L["How the world looks and sounds in CineMode."] = "CineMode에서 세상이 어떻게 보이고 들리는지."
L["The camera coming alive while CineMode is on."] = "CineMode가 켜진 동안 살아 움직이는 카메라."
L["On and off with the General page's switch."] = "일반 페이지의 스위치와 함께 켜지고 꺼집니다."
L["On. Click to turn this page off."] = "켜짐. 클릭하면 이 페이지를 끕니다."
L["Off. Click to turn this page on."] = "꺼짐. 클릭하면 이 페이지를 켭니다."
L["Everything CineMode can do, page by page. Click On or Off to turn a page on or off; Open takes you there."] = "CineMode가 할 수 있는 모든 것을 페이지별로. 켜짐 또는 꺼짐을 클릭하면 페이지를 켜고 끄며, 열기를 누르면 그 페이지로 갑니다."
L["Go to this page."] = "이 페이지로 이동."
L["%d of %d pages on."] = "%d/%d 페이지 켜짐."

-- ShowMe.lua and Welcome.lua: See it first, Show me
L["Nothing to show here."] = "보여 줄 것이 없습니다."
L["Not in a fight: try it once the fight ends."] = "전투 중에는 안 됩니다: 전투가 끝나면 해 보세요."
L["Click the row to turn it on first."] = "먼저 줄을 클릭해 켜세요."
L["See it first"] = "먼저 보기"
L["Click one to see it for a few seconds."] = "하나를 클릭하면 몇 초간 보여 줍니다."
L["Vitals"] = "생명력"
L["Teleport"] = "순간이동"
L["Black bars at the top and bottom of the screen, as in a film."] = "영화처럼 화면 위아래의 검은 띠."
L["A color wash over the world that follows the time of day and the zone, with soft dark edges and weather to match."] = "시간대와 지역을 따라가는 세상 위의 색감, 부드럽고 어두운 가장자리와 어울리는 날씨."
L["The camera moves on its own at quiet moments: on flights, when you go AFK, by a campfire. This shows a half turn around you; move the camera yourself to stop it."] = "조용한 순간에 카메라가 스스로 움직입니다: 비행 중, 자리 비움일 때, 모닥불 곁에서. 여기서는 내 주위를 반 바퀴 돕니다. 직접 카메라를 움직이면 멈춥니다."
L["As your health drops, the screen's edges close in, so you feel a fight without watching your health bar."] = "체력이 떨어지면 화면 가장자리가 좁혀 들어와, 체력 바를 보지 않아도 전투를 느낄 수 있습니다."
L["As you cast your Hearthstone or a teleport, a portal opens around you and the world fades out as you leave."] = "귀환석이나 순간이동을 시전하면 주위에 차원문이 열리고, 떠나면서 세상이 서서히 사라집니다."
